std::string ReplayWindow::GetMatchLoadingBgPath() const
{
    const char* file = GetMapScreenshotFile(m_matchMeta.map_id);

    wchar_t exePath[MAX_PATH];
    if (GetModuleFileNameW(nullptr, exePath, MAX_PATH) == 0)
        return "";
    auto dir = std::filesystem::path(exePath).parent_path();
    for (int i = 0; i < 6; i++)
    {
        if (file)
        {
            auto p = dir / "Textures" / "Loading_Screen" / file;
            if (std::filesystem::exists(p))
                return p.string();
        }
        // Fallback: main splash screen
        auto fb = dir / "Textures" / "Launch_screen" / "GWOBS_Loading_Screen_1.png";
        if (std::filesystem::exists(fb))
            return fb.string();

        if (!dir.has_parent_path() || dir == dir.parent_path())
            break;
        dir = dir.parent_path();
    }
    return "";
}

// ---------------------------------------------------------------------------
// Loading screen overlay (ImGui-based match loading screen)
// ---------------------------------------------------------------------------

namespace
{
    static std::string LsFormatWithCommas(int value)
    {
        if (value < 0) value = 0;
        std::string raw = std::to_string(value);
        std::string result;
        int count = 0;
        for (int i = static_cast<int>(raw.size()) - 1; i >= 0; --i)
        {
            if (count > 0 && count % 3 == 0)
                result.insert(result.begin(), ',');
            result.insert(result.begin(), raw[i]);
            ++count;
        }
        return result;
    }

    static void LsDrawTextWithShadow(ImDrawList* dl, ImVec2 pos, ImU32 col, const char* text)
    {
        ImU32 shadow = IM_COL32(0, 0, 0, 220);
        dl->AddText(ImVec2(pos.x - 1.f, pos.y + 1.f), shadow, text);
        dl->AddText(ImVec2(pos.x + 1.f, pos.y + 1.f), shadow, text);
        dl->AddText(ImVec2(pos.x,       pos.y + 2.f), shadow, text);
        dl->AddText(pos, col, text);
    }

    static void LsDrawTextWithShadowEx(ImDrawList* dl, ImFont* font, float fontSize,
                                        ImVec2 pos, ImU32 col, const char* text)
    {
        ImU32 shadow = IM_COL32(0, 0, 0, 220);
        dl->AddText(font, fontSize, ImVec2(pos.x - 1.f, pos.y + 1.f), shadow, text);
        dl->AddText(font, fontSize, ImVec2(pos.x + 1.f, pos.y + 1.f), shadow, text);
        dl->AddText(font, fontSize, ImVec2(pos.x,       pos.y + 2.f), shadow, text);
        dl->AddText(font, fontSize, pos, col, text);
    }

    static void LsDrawTextCrispShadow(ImDrawList* dl, ImFont* font, float fontSize,
                                       ImVec2 pos, ImU32 col, const char* text)
    {
        ImU32 shadow = IM_COL32(0, 0, 0, 230);
        dl->AddText(font, fontSize, ImVec2(pos.x, pos.y + 1.f), shadow, text);
        dl->AddText(font, fontSize, ImVec2(pos.x + 1.f, pos.y + 1.f), shadow, text);
        dl->AddText(font, fontSize, pos, col, text);
    }

    static std::string GetPartyGuildDisplay(const MatchMeta& m, const std::string& partyId,
                                            std::string& outName, std::string& outTag)
    {
        auto pit = m.parties.find(partyId);
        if (pit == m.parties.end() || pit->second.players.empty())
        {
            // No player data — try guild lookup directly by party ID
            auto git = m.guilds.find(partyId);
            if (git != m.guilds.end() && !git->second.name.empty())
            {
                outName = git->second.name;
                outTag = git->second.tag;
                return outName + " [" + outTag + "]";
            }
            outName = "?";
            outTag = "";
            return "?";
        }

        std::map<int, int> guildCounts;
        for (const auto& p : pit->second.players)
            if (p.guild_id > 0) guildCounts[p.guild_id]++;

        int bestGuildId = 0, bestCount = 0;
        for (const auto& [gid, cnt] : guildCounts)
            if (cnt > bestCount) { bestGuildId = gid; bestCount = cnt; }

        if (bestGuildId == 0)
        {
            // Players exist but no guild_id (cloud-only metadata) — fall back to party ID lookup
            auto git = m.guilds.find(partyId);
            if (git != m.guilds.end() && !git->second.name.empty())
            {
                outName = git->second.name;
                outTag = git->second.tag;
                return outName + " [" + outTag + "]";
            }
            outName = "Unknown";
            outTag = "";
            return "Unknown";
        }

        auto guildIdStr = std::to_string(bestGuildId);
        auto git = m.guilds.find(guildIdStr);
        if (git != m.guilds.end())
        {
            outName = git->second.name;
            outTag = git->second.tag;
            return outName + " [" + outTag + "]";
        }
        outName = "Guild #" + guildIdStr;
        outTag = "";
        return outName;
    }
}

void ReplayWindow::RenderLoadingScreen()
{
    // --- D3D clear ---
    auto* d3dCtx = m_deviceResources->GetD3DDeviceContext();
    auto* rtv = m_deviceResources->GetRenderTargetView();
    auto* dsv = m_deviceResources->GetDepthStencilView();

    float darkBg[4] = { 0.039f, 0.055f, 0.071f, 1.0f };
    d3dCtx->ClearRenderTargetView(rtv, darkBg);
    d3dCtx->ClearDepthStencilView(dsv, D3D11_CLEAR_DEPTH | D3D11_CLEAR_STENCIL, 0.0f, 0);

    auto vp = m_deviceResources->GetScreenViewport();
    d3dCtx->RSSetViewports(1, &vp);
    d3dCtx->OMSetRenderTargets(1, &rtv, nullptr);

    // --- Init ImGui if needed ---
    if (!m_imguiInitialized)
        InitImGui();

    ImGuiContext* prevCtx = ImGui::GetCurrentContext();
    ImGui::SetCurrentContext(m_imguiContext);

    ImGui_ImplDX11_NewFrame();
    ImGui_ImplWin32_NewFrame();
    ImGui::NewFrame();

    ImGuiIO& io = ImGui::GetIO();
    ImVec2 display = io.DisplaySize;

    // --- Init texture cache and background path (once) ---
    if (!m_lsTexCache.IsInitialized())
    {
        m_lsTexCache.Init(m_deviceResources->GetD3DDevice());
        m_lsBgPath = GetMatchLoadingBgPath();
    }

    // --- Timing ---
    if (!m_lsStartTimeSet)
    {
        m_lsStartTime = LsClock::now();
        m_lsStartTimeSet = true;
    }
    float elapsed = std::chrono::duration<float>(LsClock::now() - m_lsStartTime).count();

    constexpr float kFadeInSec         = 0.3f;
    constexpr float kBgFadeInSec       = 0.5f;
    constexpr float kStatusFadeOutSec  = 0.2f;
    constexpr float kReadyLabelSec     = 0.2f;
    constexpr float kReadyHoldSec      = 2.0f;
    constexpr float kFinalFadeOutSec   = 0.4f;

    float screenAlpha = std::clamp(elapsed / kFadeInSec, 0.f, 1.f);
    float bgAlpha     = std::clamp((elapsed - 0.05f) / kBgFadeInSec, 0.f, 1.f);

    // --- Check if "Ready" (FadingOut phase = map load done, fade animation plays) ---
    bool isReady = (m_loadingPhase == LoadingPhase::FadingOut);

    float readyFadeOut = 1.f;
    float readyTextAlpha = 0.f;
    bool shouldTransition = false;

    if (isReady && !m_lsHitReady)
    {
        m_lsHitReady = true;
        m_lsReadyTime = LsClock::now();
    }

    if (m_lsHitReady)
    {
        float re = std::chrono::duration<float>(LsClock::now() - m_lsReadyTime).count();

        // Phase A: status text fades out (0 .. kStatusFadeOutSec)
        float fadeT = std::clamp(re / kStatusFadeOutSec, 0.f, 1.f);
        readyFadeOut = 1.f - fadeT;

        // Phase B: "Ready" label appears (kStatusFadeOutSec .. + kReadyLabelSec)
        float readyStart = kStatusFadeOutSec;
        if (re >= readyStart)
            readyTextAlpha = std::clamp((re - readyStart) / 0.1f, 0.f, 1.f);

        // Phase C: hold on completed screen (kStatusFadeOutSec + kReadyLabelSec .. + kReadyHoldSec)
        float holdEnd = kStatusFadeOutSec + kReadyLabelSec + kReadyHoldSec;

        // Phase D: final fade out to black
        float afterHold = re - holdEnd;
        if (afterHold > 0.f)
        {
            float finalFade = std::clamp(afterHold / kFinalFadeOutSec, 0.f, 1.f);
            screenAlpha = 1.f - finalFade;
            if (finalFade >= 1.f)
                shouldTransition = true;
        }
    }

    // --- Fullscreen ImGui window ---
    ImGui::SetNextWindowPos(ImVec2(0, 0));
    ImGui::SetNextWindowSize(display);
    ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(0, 0));
    ImGui::PushStyleVar(ImGuiStyleVar_WindowBorderSize, 0.f);
    ImGui::PushStyleVar(ImGuiStyleVar_WindowRounding, 0.f);
    ImGui::PushStyleColor(ImGuiCol_WindowBg, ImVec4(0.039f, 0.055f, 0.071f, screenAlpha));

    ImGui::Begin("##MatchLoadingScreen", nullptr,
        ImGuiWindowFlags_NoTitleBar | ImGuiWindowFlags_NoResize | ImGuiWindowFlags_NoMove |
        ImGuiWindowFlags_NoScrollbar | ImGuiWindowFlags_NoScrollWithMouse |
        ImGuiWindowFlags_NoBringToFrontOnFocus | ImGuiWindowFlags_NoNav |
        ImGuiWindowFlags_NoInputs);

    ImDrawList* dl = ImGui::GetWindowDrawList();

    // --- Background image (contain-fit) ---
    ImTextureID bgTex = m_lsBgPath.empty() ? nullptr : m_lsTexCache.GetTexture(m_lsBgPath);
    if (bgTex && screenAlpha > 0.01f)
    {
        // We need the actual image dimensions for contain-fit.
        // TextureCache returns an SRV; query the underlying texture for size.
        ID3D11ShaderResourceView* srv = static_cast<ID3D11ShaderResourceView*>(bgTex);
        Microsoft::WRL::ComPtr<ID3D11Resource> res;
        srv->GetResource(res.GetAddressOf());
        Microsoft::WRL::ComPtr<ID3D11Texture2D> tex2d;
        res.As(&tex2d);

        float imgW = display.x, imgH = display.y;
        if (tex2d)
        {
            D3D11_TEXTURE2D_DESC desc;
            tex2d->GetDesc(&desc);
            imgW = static_cast<float>(desc.Width);
            imgH = static_cast<float>(desc.Height);
        }

        // Contain-fit: scale to fit within window, maintain aspect ratio
        float scaleX = display.x / imgW;
        float scaleY = display.y / imgH;
        float scale = (std::min)(scaleX, scaleY);
        float drawW = imgW * scale;
        float drawH = imgH * scale;
        float offX = (display.x - drawW) * 0.5f;
        float offY = (display.y - drawH) * 0.5f;

        ImU32 imgCol = IM_COL32(255, 255, 255, static_cast<int>(255 * bgAlpha * screenAlpha));
        dl->AddImage(bgTex, ImVec2(offX, offY), ImVec2(offX + drawW, offY + drawH),
                     ImVec2(0, 0), ImVec2(1, 1), imgCol);
    }

    // --- Dark overlay ---
    {
        ImU32 overlayCol = IM_COL32(0, 0, 0, static_cast<int>(115 * screenAlpha));
        dl->AddRectFilled(ImVec2(0, 0), display, overlayCol);
    }

    // --- Match info header (top center, with dark pill) ---
    if (screenAlpha > 0.01f)
    {
        ImFont* font = ImGui::GetFont();

        // --- Build strings ---
        const char* mapName = GetMapNameForLoading(m_matchMeta.map_id);
        char dateLine[128];
        snprintf(dateLine, sizeof(dateLine), "%04d/%02d/%02d",
                 m_matchMeta.year, m_matchMeta.month, m_matchMeta.day);
        std::string line1 = std::string(dateLine) + "  \xC2\xB7  " + (mapName ? mapName : "Unknown Map");

        std::string name1, tag1, name2, tag2;
        GetPartyGuildDisplay(m_matchMeta, "1", name1, tag1);
        GetPartyGuildDisplay(m_matchMeta, "2", name2, tag2);

        std::string team1Name = name1;
        std::string team1Tag  = tag1.empty() ? "" : " [" + tag1 + "]";
        std::string team2Name = name2;
        std::string team2Tag  = tag2.empty() ? "" : " [" + tag2 + "]";

        // --- Sizes ---
        float line1Size = 16.f;
        float line2Size = 26.f;
        float vsSize    = 18.f;
        float tagSize   = 26.f;

        // --- Measure line 1 ---
        ImVec2 line1Sz = font->CalcTextSizeA(line1Size, FLT_MAX, 0.f, line1.c_str());

        // --- Measure line 2 components ---
        ImVec2 t1NameSz = font->CalcTextSizeA(line2Size, FLT_MAX, 0.f, team1Name.c_str());
        ImVec2 t1TagSz  = team1Tag.empty() ? ImVec2(0,0) : font->CalcTextSizeA(tagSize, FLT_MAX, 0.f, team1Tag.c_str());
        std::string vsPad = "  vs  ";
        ImVec2 vsSz = font->CalcTextSizeA(vsSize, FLT_MAX, 0.f, vsPad.c_str());
        ImVec2 t2NameSz = font->CalcTextSizeA(line2Size, FLT_MAX, 0.f, team2Name.c_str());
        ImVec2 t2TagSz  = team2Tag.empty() ? ImVec2(0,0) : font->CalcTextSizeA(tagSize, FLT_MAX, 0.f, team2Tag.c_str());

        float line2TotalW = t1NameSz.x + t1TagSz.x + vsSz.x + t2NameSz.x + t2TagSz.x;
        float line2H = (std::max)(t1NameSz.y, vsSz.y);

        // --- Dark pill background (opaque, no blur) ---
        float pillPadL = 28.f, pillPadR = 28.f, pillPadT = 10.f, pillPadB = 14.f;
        float pillContentW = (std::max)(line1Sz.x, line2TotalW);
        float spacing = 6.f;
        float pillContentH = line1Sz.y + spacing + line2H;
        float pillW = pillContentW + pillPadL + pillPadR;
        float pillH = pillContentH + pillPadT + pillPadB;
        float pillX = (display.x - pillW) * 0.5f;
        float pillY = 48.f;
        float pillR = 10.f;

        ImU32 pillCol    = IM_COL32(8, 12, 16, static_cast<int>(209 * screenAlpha));
        ImU32 pillBorder = IM_COL32(255, 255, 255, static_cast<int>(20 * screenAlpha));
        dl->AddRectFilled(ImVec2(pillX, pillY), ImVec2(pillX + pillW, pillY + pillH), pillCol, pillR);
        dl->AddRect(ImVec2(pillX, pillY), ImVec2(pillX + pillW, pillY + pillH), pillBorder, pillR);

        // --- Line 1 position (centered within pill) ---
        float line1X = pillX + (pillW - line1Sz.x) * 0.5f;
        float line1Y = pillY + pillPadT;
        ImU32 line1Col = IM_COL32(212, 160, 32, static_cast<int>(255 * screenAlpha));
        LsDrawTextCrispShadow(dl, font, line1Size, ImVec2(line1X, line1Y), line1Col, line1.c_str());

        // --- Line 2 position (centered within pill) ---
        float line2Y = line1Y + line1Sz.y + spacing;
        float line2X = pillX + (pillW - line2TotalW) * 0.5f;
        float vsYOff = (line2Size - vsSize) * 0.5f;
        float tagYOff = 0.f;

        // Team names
        ImU32 teamCol = IM_COL32(240, 192, 64, static_cast<int>(255 * screenAlpha));
        ImU32 tagCol  = IM_COL32(240, 192, 64, static_cast<int>(191 * screenAlpha));
        ImU32 vsCol   = IM_COL32(212, 160, 32, static_cast<int>(191 * screenAlpha));

        float cx = line2X;
        LsDrawTextCrispShadow(dl, font, line2Size, ImVec2(cx, line2Y), teamCol, team1Name.c_str());
        cx += t1NameSz.x;
        if (!team1Tag.empty())
        {
            LsDrawTextCrispShadow(dl, font, tagSize, ImVec2(cx, line2Y + tagYOff), tagCol, team1Tag.c_str());
            cx += t1TagSz.x;
        }
        LsDrawTextCrispShadow(dl, font, vsSize, ImVec2(cx, line2Y + vsYOff), vsCol, vsPad.c_str());
        cx += vsSz.x;
        LsDrawTextCrispShadow(dl, font, line2Size, ImVec2(cx, line2Y), teamCol, team2Name.c_str());
        cx += t2NameSz.x;
        if (!team2Tag.empty())
            LsDrawTextCrispShadow(dl, font, tagSize, ImVec2(cx, line2Y + tagYOff), tagCol, team2Tag.c_str());
    }

    // --- Progress bar geometry ---
    float barW = (std::min)(800.f, display.x - 120.f);
    float barH = 6.f;
    float barX = (display.x - barW) * 0.5f;
    float barY = display.y - 40.f - barH;
    float barRight = barX + barW;

    // --- Progress bar ---
    {
        float barAlpha = readyFadeOut * screenAlpha;
        ImU32 bgCol   = IM_COL32(40, 44, 52, static_cast<int>(255 * barAlpha));
        ImU32 fillCol = IM_COL32(74, 144, 216, static_cast<int>(230 * barAlpha));
        float progress = std::clamp(m_loadProgress, 0.f, 1.f);
        dl->AddRectFilled(ImVec2(barX, barY), ImVec2(barX + barW, barY + barH), bgCol, 3.f);
        dl->AddRectFilled(ImVec2(barX, barY), ImVec2(barX + barW * progress, barY + barH), fillCol, 3.f);
    }

    // --- Status text lines (right-aligned above bar) ---
    if (readyFadeOut > 0.01f && screenAlpha > 0.01f && !m_lsHitReady)
    {
        float alpha = readyFadeOut * screenAlpha;
        ImU32 labelCol   = IM_COL32(255, 255, 255, static_cast<int>(210 * alpha));
        ImU32 counterCol = IM_COL32(255, 255, 255, static_cast<int>(250 * alpha));

        float lineH = ImGui::GetFontSize() + 2.f;
        float textY = barY - 8.f;

        auto drawStatusLine = [&](const std::string& label, const std::string& counter)
        {
            std::string full = label + counter;
            ImVec2 fullSz = ImGui::CalcTextSize(full.c_str());
            ImVec2 labelSz = ImGui::CalcTextSize(label.c_str());
            textY -= lineH;
            float lineX = barRight - fullSz.x;
            LsDrawTextWithShadow(dl, ImVec2(lineX, textY), labelCol, label.c_str());
            LsDrawTextWithShadow(dl, ImVec2(lineX + labelSz.x, textY), counterCol, counter.c_str());
        };

        bool showedAny = false;

        // Map loading status
        if (m_loadingPhase == LoadingPhase::Init)
        {
            drawStatusLine("Loading map geometry...", "");
            showedAny = true;
        }
        else if (m_loadingPhase == LoadingPhase::PropModels && m_totalPropFilenames > 0)
        {
            drawStatusLine("Loading map models  ",
                "[" + LsFormatWithCommas(m_propModelLoadIndex) +
                " / " + LsFormatWithCommas(m_totalPropFilenames) + "]");
            showedAny = true;
        }
        else if (m_loadingPhase == LoadingPhase::PlaceProps && m_agentModelsLoading && !m_agentModelsLoaded)
        {
            if (!m_bgLoadDone) {
                int prog = m_bgLoadProgress.load();
                auto subPhase = static_cast<AgentLoadSubPhase>(m_bgLoadSubPhase.load());
                const char* subLabel = "";
                switch (subPhase) {
                    case AgentLoadSubPhase::ParsingModel:         subLabel = "Parsing model geometry..."; break;
                    case AgentLoadSubPhase::LoadingTextures:       subLabel = "Loading textures..."; break;
                    case AgentLoadSubPhase::DiscoveringAnimations: subLabel = "Discovering animations..."; break;
                    case AgentLoadSubPhase::ScanningReferences:    subLabel = "Scanning animation references..."; break;
                    case AgentLoadSubPhase::ScanningMFT:           subLabel = "Scanning DAT file for animations..."; break;
                    case AgentLoadSubPhase::BuildingAnimData:      subLabel = "Building animation data..."; break;
                    default: break;
                }
                ImU32 subCol = IM_COL32(180, 180, 180, static_cast<int>(170 * alpha));
                if (subLabel[0]) {
                    ImVec2 subSz = ImGui::CalcTextSize(subLabel);
                    float subX = barRight - subSz.x;
                    textY -= lineH;
                    LsDrawTextWithShadow(dl, ImVec2(subX, textY), subCol, subLabel);
                }
                int display = std::min(prog + 1, m_bgLoadTotal);
                drawStatusLine("Loading 3D models  ",
                    "[" + std::to_string(display) + " / " + std::to_string(m_bgLoadTotal) + "]");
            } else {
                int total3d = static_cast<int>(m_agentModelCreateOrder.size());
                drawStatusLine("Creating 3D model resources  ",
                    "[" + std::to_string(m_agentModelCreateIndex) + " / " + std::to_string(total3d) + "]");
            }
            showedAny = true;
        }
        else if (m_loadingPhase == LoadingPhase::PlaceProps && m_totalPropInstances > 0)
        {
            drawStatusLine("Placing props  ",
                "[" + LsFormatWithCommas(m_propPlaceIndex) +
                " / " + LsFormatWithCommas(m_totalPropInstances) + "]");
            showedAny = true;
        }

        // Match data parsing (async, can run in parallel with map loading)
        {
            int agentDone = 0, agentTotal = 0, stocDone = 0, stocTotal = 0;
            bool agentActive = false, stocActive = false;
            if (m_replayCtx.agentParseProgress && !m_replayCtx.agentsLoaded)
            {
                agentDone = m_replayCtx.agentParseProgress->files_done.load();
                agentTotal = m_replayCtx.agentParseProgress->files_total.load();
                agentActive = (agentTotal > 0);
            }
            if (m_replayCtx.stocParseProgress && !m_replayCtx.stocLoaded)
            {
                stocDone = m_replayCtx.stocParseProgress->files_done.load();
                stocTotal = m_replayCtx.stocParseProgress->files_total.load();
                stocActive = (stocTotal > 0);
            }

            if (agentActive || stocActive)
            {
                int totalDone = agentDone + stocDone;
                int totalAll = agentTotal + stocTotal;
                drawStatusLine("Loading match data  ",
                    "[" + LsFormatWithCommas(totalDone) +
                    " / " + LsFormatWithCommas(totalAll) + "]");
                showedAny = true;
            }
        }

        if (!showedAny && m_loadingPhase == LoadingPhase::Validate)
        {
            drawStatusLine("Initializing...", "");
        }
    }

    // --- "Ready" text (centered, fades in) ---
    if (readyTextAlpha > 0.01f && screenAlpha > 0.01f)
    {
        const char* readyText = "Ready";
        ImVec2 sz = ImGui::CalcTextSize(readyText);
        float rx = (display.x - sz.x) * 0.5f;
        float ry = barY - 30.f;
        ImU32 readyCol = IM_COL32(255, 255, 255, static_cast<int>(230 * readyTextAlpha * screenAlpha));
        LsDrawTextWithShadow(dl, ImVec2(rx, ry), readyCol, readyText);
    }

    // --- Error text ---
    if (m_loadingPhase == LoadingPhase::Error && !m_errorMsg.empty() && screenAlpha > 0.01f)
    {
        std::string errDisplay = "Error: " + m_errorMsg;
        ImVec2 sz = ImGui::CalcTextSize(errDisplay.c_str());
        float ex = (display.x - sz.x) * 0.5f;
        float ey = display.y * 0.5f;
        ImU32 errCol = IM_COL32(255, 96, 96, static_cast<int>(255 * screenAlpha));
        LsDrawTextWithShadow(dl, ImVec2(ex, ey), errCol, errDisplay.c_str());
    }

    ImGui::End();
    ImGui::PopStyleColor(1);
    ImGui::PopStyleVar(3);

    ImGui::Render();
    ImGui_ImplDX11_RenderDrawData(ImGui::GetDrawData());

    if (prevCtx)
        ImGui::SetCurrentContext(prevCtx);

    m_deviceResources->Present();

    // Transition to Ready phase after all fades complete
    if (shouldTransition) {
        m_loadingPhase = LoadingPhase::Ready;
        InitAudioEngine();
        m_replayCtx.isPlaying = true;
    }
}

// ---------------------------------------------------------------------------
// ImGui overlay: menu bar + debug windows
// ---------------------------------------------------------------------------

void ReplayWindow::DrawImGuiOverlay()
{
    if (!m_imguiInitialized)
        InitImGui();

    ImGuiContext* prevCtx = ImGui::GetCurrentContext();
    ImGui::SetCurrentContext(m_imguiContext);

    ImGui_ImplDX11_NewFrame();
    ImGui_ImplWin32_NewFrame();

    ImGui::NewFrame();

    // Top menu bar
    if (ImGui::BeginMainMenuBar())
    {
        if (ImGui::BeginMenu("File"))
        {
            if (ImGui::BeginMenu("Preferences"))
            {
                if (ImGui::MenuItem("Shortcuts"))
                    m_showShortcutPreferences = true;
                if (ImGui::MenuItem("Interface"))
                    m_showInterfacePrefs = true;
                ImGui::EndMenu();
            }
            if (ImGui::BeginMenu("Rate Match"))
            {
                int cur = MatchRatings::Get().GetRating(m_matchMeta.folder_name);
                for (int i = 1; i <= 5; i++)
                {
                    char label[16];
                    snprintf(label, sizeof(label), "%d Star%s", i, i > 1 ? "s" : "");
                    if (ImGui::MenuItem(label, nullptr, cur == i))
                        MatchRatings::Get().SetRating(m_matchMeta.folder_name, (cur == i) ? 0 : i);
                }
                ImGui::Separator();
                if (ImGui::MenuItem("Clear Rating", nullptr, false, cur > 0))
                    MatchRatings::Get().SetRating(m_matchMeta.folder_name, 0);
                ImGui::EndMenu();
            }
            ImGui::Separator();
            if (ImGui::MenuItem("Close Replay"))
            {
                PostMessage(m_hwnd, WM_CLOSE, 0, 0);
            }
            ImGui::EndMenu();
        }

        if (ImGui::BeginMenu("View"))
        {
            ImGui::MenuItem("Agent Overlay", nullptr, &m_showAgentOverlay);

            if (ImGui::MenuItem("Stylized Agent Icons",
                                nullptr, m_uiLayout.lodEnabled))
            {
                m_uiLayout.lodEnabled = !m_uiLayout.lodEnabled;
                SaveUILayout();
            }

            ImGui::Separator();
            ImGui::MenuItem("Skill Icons", nullptr, &m_showSkillIcons);
            ImGui::MenuItem("Skill Lasers", nullptr, &m_showSkillLasers);

            {
                const auto& hk = ReplayHotkeys::Get();
                auto kn = [](int k) { return ImGui::GetKeyName((ImGuiKey)k); };

                ImGui::MenuItem(std::format("Range Rings ({})", kn(hk.toggleRangeRings)).c_str(), nullptr, &m_showRangeRings);
                {
                    bool fogOn = (m_fogPerspective > 0);
                    if (ImGui::MenuItem(std::format("Fog of War ({})", kn(hk.toggleFogOfWar)).c_str(), nullptr, &fogOn)) {
                        if (fogOn) m_fogPerspective = m_fogLastActive;
                        else { m_fogLastActive = m_fogPerspective; m_fogPerspective = 0; m_fogPlayerAgent = -1; }
                    }
                }
                ImGui::MenuItem(std::format("Morale ({})", kn(hk.toggleMoralePanel)).c_str(), nullptr, &m_showMoralePanel);
                ImGui::MenuItem(std::format("Lord Damage ({})", kn(hk.toggleLordDamage)).c_str(), nullptr, &m_showLordDamagePanel);
                ImGui::MenuItem(std::format("Event Timeline ({})", kn(hk.toggleEventTimeline)).c_str(), nullptr, &m_showEventTimeline);
                ImGui::MenuItem(std::format("Auto Camera ({})", kn(hk.toggleAutoCamera)).c_str(), nullptr, &m_showAutoCameraPanel);
                {
                    bool tvOn = m_topViewActive;
                    if (ImGui::MenuItem(std::format("Top View ({})", kn(hk.toggleTopView)).c_str(), nullptr, &tvOn)) {
                        if (tvOn) EnterTopView(); else ExitTopView();
                    }
                }
                ImGui::MenuItem("Team 1 Party", nullptr, &m_showTeam1Party);
                ImGui::MenuItem("Team 2 Party", nullptr, &m_showTeam2Party);
                ImGui::MenuItem(std::format("Piano Roll ({})", kn(hk.togglePianoRoll)).c_str(), nullptr, &m_showPianoRoll);
                ImGui::Separator();

                ImGui::MenuItem(std::format("Heatmap ({})", kn(hk.toggleHeatmap)).c_str(), nullptr, &m_heatmapSettings.show);
            }

            ImGui::Separator();
            ImGui::MenuItem("Combat Log", nullptr, &m_showCombatLog);
            ImGui::MenuItem("Skill Analytics (BETA)", nullptr, &m_showSkillAnalytics);
            ImGui::MenuItem("Agent Names", nullptr, &m_showNameFilterPanel);
            ImGui::MenuItem("Split Camera", nullptr, &m_pipEnabled);
            ImGui::Separator();
            ImGui::MenuItem("Sound FX (BETA)", nullptr, &m_audioEnabled);
            ImGui::EndMenu();
        }

        if (ImGui::BeginMenu("Debug"))
        {
            if (GuiGlobalConstants::IsDeveloperMode())
            {
                ImGui::MenuItem("Agent Data", nullptr, &m_showAgentDataWindow);
                ImGui::MenuItem("Map Calibration", nullptr, &m_showMapCalibrationWindow);
                ImGui::MenuItem("Interpolation", nullptr, &m_showInterpolationWindow);
                ImGui::MenuItem("StoC Events", nullptr, &m_showStoCWindow);
                ImGui::MenuItem("Auto Camera Debug", nullptr, &m_autoCamShowDebug);
            }
            ImGui::MenuItem("Audio Debug", nullptr, &m_showAudioDebug);
            if (GuiGlobalConstants::IsDeveloperMode())
            {
                ImGui::MenuItem("Flag Timeline", nullptr, &m_showFlagDebugWindow);
                ImGui::MenuItem("Assets", nullptr, &m_showAssetInspector);
                ImGui::MenuItem("Agent 3D Models", nullptr, &m_showAgentModelWindow);
            }
            ImGui::EndMenu();
        }

        if (ImGui::BeginMenu("Tools"))
        {
            ImGui::MenuItem("Drawing toolbar", nullptr, &m_annotationMgr.toolbar_visible);
            ImGui::MenuItem("Bookmarks",       nullptr, &m_annotationMgr.bookmarks_visible);
            ImGui::MenuItem("Notepad",         nullptr, &m_showNotepad);
            ImGui::EndMenu();
        }

        if (m_replayCtx.agentParseProgress && !m_replayCtx.agentsLoaded)
        {
            int done = m_replayCtx.agentParseProgress->files_done.load();
            int total = m_replayCtx.agentParseProgress->files_total.load();
            auto label = std::format("  Parsing agents... {}/{}", done, total);
            ImGui::TextDisabled("%s", label.c_str());
        }
        if (m_replayCtx.stocParseProgress && !m_replayCtx.stocLoaded)
        {
            int done = m_replayCtx.stocParseProgress->files_done.load();
            int total = m_replayCtx.stocParseProgress->files_total.load();
            auto label = std::format("  Parsing StoC... {}/{}", done, total);
            ImGui::TextDisabled("%s", label.c_str());
        }

        ImGui::EndMainMenuBar();
    }

    DrawTimelineController();
    DrawAgentModelLoadingBanner();
    DrawEventTimeline();

    if (m_showAgentDataWindow)
        DrawAgentDataWindow();

    if (m_showMapCalibrationWindow)
        DrawMapCalibrationWindow();

    if (m_showInterpolationWindow)
        DrawInterpolationWindow();

    if (m_showStoCWindow)
        DrawStoCWindow();

    if (m_showFlagDebugWindow)
        DrawFlagDebugWindow();

    if (m_showAssetInspector)
        DrawAssetInspectorWindow();

    if (m_showAgentModelWindow)
    {
        ImGui::SetNextWindowSize(ImVec2(300, 160), ImGuiCond_FirstUseEver);
        if (ImGui::Begin("Agent 3D Models", &m_showAgentModelWindow))
        {
            bool prevToggle = m_useAgentModels;
            ImGui::Checkbox("Enable 3D Agent Models", &m_useAgentModels);
            if (ImGui::IsItemHovered())
                ImGui::SetTooltip("Replace NPC/spirit cylinders with actual GW models");
            if (m_useAgentModels != prevToggle)
                GuiGlobalConstants::use_3d_agent_models = m_useAgentModels;

            if (m_useAgentModels && !m_agentModelsLoaded)
                LoadAgentModels();

            if (m_useAgentModels && !prevToggle && m_agentModelsLoaded)
            {
                // Turning on: meshes will be shown by DrawAgentModels()
            }
            if (!m_useAgentModels && prevToggle && m_agentModelsLoaded)
            {
                // Turning off: hide all agent model meshes
                auto* meshMgr = m_mapRenderer->GetMeshManager();
                for (auto& [agentId, meshIds] : m_agentMeshIds)
                    for (int mid : meshIds)
                        meshMgr->SetMeshShouldRender(mid, false);
            }

            ImGui::SliderFloat("Model Scale", &m_agentModelScale, 0.1f, 5.0f, "%.2f");
            if (ImGui::IsItemHovered())
                ImGui::SetTooltip("Scale factor for agent 3D models");

            ImGui::Separator();
            if (m_agentModelsLoaded) {
                ImGui::Text("Loaded: %d unique models, %d agents",
                    (int)m_agentModelTemplates.size(), (int)m_agentMeshIds.size());

                if (ImGui::TreeNode("Agent Model Diagnostics"))
                {
                    if (ImGui::BeginTable("AgentModelDiag", 7,
                        ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY,
                        ImVec2(0, 300)))
                    {
                        ImGui::TableSetupColumn("ID",      ImGuiTableColumnFlags_WidthFixed, 35);
                        ImGui::TableSetupColumn("Type",    ImGuiTableColumnFlags_WidthFixed, 55);
                        ImGui::TableSetupColumn("Mdl",     ImGuiTableColumnFlags_WidthFixed, 35);
                        ImGui::TableSetupColumn("Tm",      ImGuiTableColumnFlags_WidthFixed, 25);
                        ImGui::TableSetupColumn("Hash",    ImGuiTableColumnFlags_WidthFixed, 65);
                        ImGui::TableSetupColumn("Mesh#",   ImGuiTableColumnFlags_WidthFixed, 40);
                        ImGui::TableSetupColumn("Render Status", ImGuiTableColumnFlags_WidthStretch);
                        ImGui::TableHeadersRow();

                        for (auto& [agentId, ard] : m_replayCtx.agents)
                        {
                            if (ard.type != AgentType::Player && ard.type != AgentType::NPC
                                && ard.type != AgentType::Spirit && ard.type != AgentType::Unknown)
                                continue;
                            ImGui::TableNextRow();
                            ImGui::TableSetColumnIndex(0); ImGui::Text("%d", agentId);
                            ImGui::TableSetColumnIndex(1); ImGui::Text("%s", AgentTypeName(ard.type));
                            ImGui::TableSetColumnIndex(2); ImGui::Text("%u", ard.modelId);
                            ImGui::TableSetColumnIndex(3); ImGui::Text("%u", ard.teamId);
                            auto cacheIt = m_agentFileHashCache.find(agentId);
                            ImGui::TableSetColumnIndex(4);
                            if (cacheIt != m_agentFileHashCache.end())
                                ImGui::Text("0x%X", cacheIt->second);
                            else
                                ImGui::TextDisabled("none");
                            auto meshIt = m_agentMeshIds.find(agentId);
                            ImGui::TableSetColumnIndex(5);
                            if (meshIt != m_agentMeshIds.end())
                                ImGui::Text("%d", (int)meshIt->second.size());
                            else
                                ImGui::TextDisabled("-");
                            ImGui::TableSetColumnIndex(6);
                            auto statusIt = m_agentModelRenderStatus.find(agentId);
                            if (statusIt != m_agentModelRenderStatus.end())
                                ImGui::TextWrapped("%s", statusIt->second.c_str());
                            else
                                ImGui::TextDisabled("n/a");
                        }
                        ImGui::EndTable();
                    }

                    if (ImGui::TreeNode("Model 174 agents (all types)"))
                    {
                        for (auto& [agentId, ard] : m_replayCtx.agents)
                        {
                            if (ard.modelId != 174) continue;
                            ImGui::Text("Agent %d: type=%s team=%u amt=0x%X",
                                        agentId, AgentTypeName(ard.type), ard.teamId, ard.agentModelType);
                        }
                        ImGui::TreePop();
                    }

                    ImGui::TreePop();
                }
            } else if (m_useAgentModels) {
                ImGui::TextDisabled("Loading models...");
            } else {
                ImGui::TextDisabled("Enable to load models from DAT");
            }
        }
        ImGui::End();
    }

    if (m_showShortcutPreferences)
    {
        ImGui::OpenPopup("Shortcut Preferences");
        m_showShortcutPreferences = false;
    }
    DrawShortcutPreferences();

    DrawInterfacePreferences();

    DrawPartyWindows();
    DrawCombatLog();
    DrawSkillAnalyticsPanel();
    DrawSkillAnalyticsPlayerPopups();
    DrawPlayerInfoPanel();
    DrawPianoRollPanel();
    DrawNotepad();
    DrawNameFilterPanel();
    DrawPiPPanel();

    {
        auto lutGetter = [this](HeatmapPalette p) -> ID3D11ShaderResourceView* {
            return m_heatmapRenderer.GetLutSRV(p);
        };

        // Heatmap floating panel
        if (m_heatmapSettings.show)
        {
            std::vector<AgentMenuEntry> hmAgents;
            if (m_agentsClassified)
            {
                auto* dev = m_deviceResources->GetD3DDevice();
                for (int id : m_playerIds)
                {
                    auto it = m_replayCtx.agents.find(id);
                    if (it == m_replayCtx.agents.end()) continue;
                    const auto& ard = it->second;
                    std::string label = ard.playerName.empty()
                        ? ard.categoryName : ard.playerName;
                    ImTextureID icon = (ard.primaryProf > 0)
                        ? LoadProfIcon(dev, ard.primaryProf) : nullptr;
                    hmAgents.push_back({ id, label, ard.teamId, icon });
                }
            }
            size_t prevLayerCount = m_heatmapSettings.layers.size();
            m_panelLayout.ApplyPosition("heatmap");
            bool hmChanged = DrawHeatmapPanel(m_heatmapSettings, hmAgents, lutGetter);
            m_panelLayout.TrackWindowByName("heatmap", "Heatmap");
            if (hmChanged)
            {
                size_t newCount = m_heatmapSettings.layers.size();
                if (newCount != prevLayerCount)
                {
                    m_heatmapAccumulator.EnsureLayerCount(newCount);
                    if (m_heatmapInitialized)
                        m_heatmapRenderer.EnsureLayerTextures(
                            m_deviceResources->GetD3DDevice(), newCount);
                }
                m_heatmapAccumulator.MarkAllLayersDirty();
                ResolveHeatmapLayers();
                SaveHeatmapSettings();
            }
        }

        DrawHeatmapLegend(m_heatmapSettings, lutGetter);
    }

    {
        Camera* cam = m_mapRenderer->GetCamera();
        XMMATRIX annVP = cam->GetView() * cam->GetProj();
        auto annViewport = m_deviceResources->GetScreenViewport();
        m_annotationMgr.Update(m_terrain.get(), annVP,
                               annViewport.Width, annViewport.Height,
                               cam->GetPosition3f(), m_debugTimeline);
    }
    m_annotationMgr.RenderToolbar();
    m_annotationMgr.RenderBookmarkPanel(m_debugTimeline, m_debugTimeline,
                                        m_replayCtx.isPlaying);
    {
        Camera* cam = m_mapRenderer->GetCamera();
        XMMATRIX annVP = cam->GetView() * cam->GetProj();
        auto annViewport = m_deviceResources->GetScreenViewport();
        m_annotationMgr.RenderDrawings(annVP, annViewport.Width,
                                       annViewport.Height, m_debugTimeline);
    }

    // Audio debug panel
    if (m_showAudioDebug && m_audioEngine) {
        ImGui::SetNextWindowSize(ImVec2(360, 0), ImGuiCond_FirstUseEver);
        if (ImGui::Begin("Audio Debug", &m_showAudioDebug)) {
            auto stats = m_audioEngine->GetDebugStats();
            ImGui::Text("Engine initialized: %s", m_audioInitialized ? "YES" : "NO");
            ImGui::Text("Audio enabled:      %s", m_audioEnabled ? "YES" : "NO");
            ImGui::Text("MFT size:           %d", m_datManager ? m_datManager->get_num_files() : -1);
            if (m_datManager) {
                auto wpath = m_datManager->get_filepath();
                std::string path8(wpath.begin(), wpath.end());
                ImGui::TextWrapped("DAT: %s", path8.c_str());
            }
            ImGui::Separator();
            ImGui::Text("Events posted:      %d", stats.eventsPosted);
            ImGui::Text("Sounds played:      %d", stats.soundsPlayed);
            ImGui::Text("Voices active:      %d", stats.voicesActive);
            if (stats.voicesActive > 0) {
                float total = stats.panLeft + stats.panRight;
                float pct = total > 0.001f ? stats.panLeft / total : 0.5f;
                const char* dir = (pct > 0.55f) ? "LEFT" : (pct < 0.45f) ? "RIGHT" : "CENTER";
                ImGui::Text("Pan L:%.2f R:%.2f  [%s]", stats.panLeft, stats.panRight, dir);
            }
            ImGui::Separator();
            ImGui::Text("ID out of range:    %d", stats.hashNotFound);
            ImGui::Text("Not SOUND type:     %d", stats.notSoundType);
            ImGui::Text("Decode failures:    %d", stats.decodeFailures);
            if (auto* sc = m_audioEngine->GetSoundCache()) {
                auto& ll = sc->GetLastLoad();
                ImGui::Separator();
                ImGui::Text("Hash index entries: %d", sc->GetHashIndexSize());
                ImGui::Text("Last fileId (json): %u", ll.fileId);
                ImGui::Text("Resolved MFT idx:   %u", ll.resolvedIndex);
                ImGui::Text("Resolve method:     %s", ll.resolveMethod.c_str());
                ImGui::Text("Data size:          %d", ll.dataSize);
                ImGui::Text("MFT type:           %d", ll.mftType);
                ImGui::Text("Magic bytes:        %02X %02X %02X %02X",
                    ll.magic[0], ll.magic[1], ll.magic[2], ll.magic[3]);
                ImGui::Text("Load ok:            %s", ll.loaded ? "YES" : "NO");
                if (!ll.rejectReason.empty())
                    ImGui::TextColored(ImVec4(1,0.4f,0.4f,1), "Reject: %s", ll.rejectReason.c_str());
            }
            ImGui::Separator();
            ImGui::Text("Last skill: %u '%s'", stats.lastSkillId, stats.lastSkillName.c_str());
            ImGui::Text("Timeline: %.2f  LastAudio: %.2f", m_debugTimeline, m_audioLastTime);
            ImGui::Separator();
            auto& cfg = m_audioEngine->GetConfig();
            ImGui::SliderFloat("Master Vol", &cfg.master_volume, 0.f, 1.f);
            ImGui::SliderFloat("SFX Vol", &cfg.sfx_volume, 0.f, 1.f);
            ImGui::SliderFloat("Dist Scale", &cfg.curve_distance_scaler, 1.f, 50.f);
        }
        ImGui::End();
    }
    else if (m_showAudioDebug && !m_audioEngine) {
        if (ImGui::Begin("Audio Debug", &m_showAudioDebug)) {
            ImGui::Text("Audio engine not created");
            ImGui::Text("Initialized: %s", m_audioInitialized ? "YES" : "NO");
        }
        ImGui::End();
    }

    DrawAgentOverlay();
    DrawFlags();
    DrawBundleItems();
    DrawSkillLasers();
    UpdateIncomingEffects();
    RenderIncomingEffects();
    DrawFollowedAgentHUD();
    DrawRangeRings();
    DrawSpiritRanges();
    DrawWurmsShrineCaptureRadius();
    DrawRangeRingToolbar();
    DrawFogOfWarToolbar();
    DrawMoralePanel();
    DrawLordDamagePanel();
    DrawAutoCameraPanel();
    DrawAutoCameraDebugPanel();

    DrawMatchTimer();
    DrawFlagEventMessages();
    DrawJumboMessages();
    DrawMoraleBoostTimers();

    // Asset selection consumes the left-click before it becomes a pan
    if (m_leftClickPending && m_assetSelectionEnabled && !ImGui::GetIO().WantCaptureMouse)
    {
        m_leftClickPending = false;
        auto it = m_meshIdToPropIndex.find(m_hoveredPropMeshId);
        int newProp = (it != m_meshIdToPropIndex.end())
            ? static_cast<int>(it->second) : -1;
        SetPickedProp(newProp);
    }

    // Commit deferred left-click to pan if no agent was clicked
    if (m_leftClickPending && !m_annotationMgr.draw_mode_active)
    {
        m_leftClickPending = false;
        m_leftMouseDown = true;
        ClosePlayerInfoPanel();
        if (!m_rightMouseDown)
        {
            ShowCursor(FALSE);
            SetCapture(m_hwnd);
        }
        else
        {
            ClipCursor(nullptr);
            ShowCursor(FALSE);
        }
    }

    // Keyboard shortcuts — uses GetAsyncKeyState directly so hotkeys work even
    // without Win32 keyboard focus.  Only active when our process is in the
    // foreground and no text input / annotation mode is active.
    {
        DWORD fgPid = 0;
        GetWindowThreadProcessId(GetForegroundWindow(), &fgPid);
        bool processActive = (fgPid == GetCurrentProcessId());

        if (processActive && !ImGui::GetIO().WantTextInput && !m_clSkillSearchFocused
            && !m_annotationMgr.draw_mode_active)
        {
            const auto& hk = ReplayHotkeys::Get();

            if (HotkeyPressed(hk.exitFollowMode) && m_cameraMode == CameraMode::FollowAgent)
                ExitFollowMode();

            float maxT = std::max(1.f, m_replayCtx.maxReplayTime);

            // Configurable 5s hotkeys (skip if bound to arrow keys — arrows are handled below)
            bool rew5isArrow = (hk.rewind5s  == ImGuiKey_LeftArrow  || hk.rewind5s  == ImGuiKey_RightArrow);
            bool fwd5isArrow = (hk.forward5s == ImGuiKey_LeftArrow  || hk.forward5s == ImGuiKey_RightArrow);
            if (!rew5isArrow && HotkeyPressed(hk.rewind5s))
                m_debugTimeline = std::max(0.f, m_debugTimeline - 5.f);
            if (!fwd5isArrow && HotkeyPressed(hk.forward5s))
                m_debugTimeline = std::min(maxT, m_debugTimeline + 5.f);

            // Arrow keys: tap = ±1s, hold = continuous ±1s at repeat rate
            if (ImGui::IsKeyPressed(ImGuiKey_LeftArrow, true))
                m_debugTimeline = std::max(0.f, m_debugTimeline - 1.f);
            if (ImGui::IsKeyPressed(ImGuiKey_RightArrow, true))
                m_debugTimeline = std::min(maxT, m_debugTimeline + 1.f);

            if (HotkeyPressed(hk.playPause))
                m_replayCtx.isPlaying = !m_replayCtx.isPlaying;

            if (HotkeyPressed(hk.toggleRangeRings))
            {
                m_showRangeRings = !m_showRangeRings;
                if (!m_showRangeRings)
                {
                    m_ringAgentFilter = -1;
                    m_ringHiddenAgents.clear();
                }
            }

            if (HotkeyPressed(hk.toggleMoralePanel))
                m_showMoralePanel = !m_showMoralePanel;

            if (HotkeyPressed(hk.toggleEventTimeline))
                m_showEventTimeline = !m_showEventTimeline;

            if (HotkeyPressed(hk.toggleLordDamage))
                m_showLordDamagePanel = !m_showLordDamagePanel;

            if (HotkeyPressed(hk.toggleAutoCamera))
            {
                m_autoCameraEnabled = !m_autoCameraEnabled;
                if (m_autoCameraEnabled)
                    m_autoCamState = AutoCameraState{};
                else
                    ExitFollowMode();
            }

            if (HotkeyPressed(hk.toggleFogOfWar) && !m_topViewActive)
            {
                if (m_fogPerspective > 0) {
                    m_fogLastActive = m_fogPerspective;
                    m_fogPerspective = 0;
                    m_fogPlayerAgent = -1;
                } else {
                    m_fogPerspective = m_fogLastActive;
                }
            }

            if (HotkeyPressed(hk.toggleTopView))
            {
                if (m_topViewActive)
                    ExitTopView();
                else
                    EnterTopView();
            }

            if (HotkeyPressed(hk.togglePianoRoll))
                m_showPianoRoll = !m_showPianoRoll;

            if (HotkeyPressed(hk.toggleHeatmap))
            {
                m_heatmapSettings.show = !m_heatmapSettings.show;
                SaveHeatmapSettings();
            }
        }
    }

    // Sync panel visibility and auto-save layout if anything changed
    m_panelLayout.SyncVisibilityFromPointers();
    uint64_t stateHash = ComputePanelStateHash();
    bool stateChanged = (stateHash != m_lastPanelStateHash);
    if (stateChanged)
        m_lastPanelStateHash = stateHash;
    if (m_panelLayout.IsDirty() || stateChanged)
        SaveUILayout();

    // Determine cursor mode, then apply drag overrides before committing
    UpdateCursorMode();
    if (m_leftMouseDown)
        g_CurrentCursor = CursorMode::Hidden;
    else if (m_rightMouseDown)
        g_CurrentCursor = CursorMode::Precision;
    ApplyCursor();

    // Cache for next Update() — suppresses WASD camera polling while a text widget is active
    m_imguiWantTextInput = ImGui::GetIO().WantTextInput;

    ImGui::Render();
    ImGui_ImplDX11_RenderDrawData(ImGui::GetDrawData());

    ImGui::SetCurrentContext(prevCtx);
}

// ---------------------------------------------------------------------------
// Map calibration transform: save / load
// ---------------------------------------------------------------------------

static constexpr const char* kCalibrationFile = "map_transforms.txt";

static void SaveMapTransform(int mapId, const MapTransform& t)
{
    std::map<int, MapTransform> all;
    {
        std::ifstream in(kCalibrationFile);
        std::string line;
        while (std::getline(in, line)) {
            if (line.empty() || line[0] == '#') continue;
            int id;
            float ox, oy, oz, sx, sy, sz, rot;
            int fx, fy, fz, syz, sxz, sxy;
            if (sscanf_s(line.c_str(), "%d %f %f %f %f %f %f %f %d %d %d %d %d %d",
                         &id, &ox, &oy, &oz, &sx, &sy, &sz, &rot,
                         &fx, &fy, &fz, &syz, &sxz, &sxy) == 14)
            {
                all[id] = { ox, oy, oz, sx, sy, sz, rot,
                            fx != 0, fy != 0, fz != 0,
                            syz != 0, sxz != 0, sxy != 0 };
            }
        }
    }
    all[mapId] = t;
    {
        std::ofstream out(kCalibrationFile);
        out << "# map_id offX offY offZ scaleX scaleY scaleZ rotation flipX flipY flipZ swapYZ swapXZ swapXY\n";
        for (auto& [id, mt] : all)
        {
            char buf[512];
            snprintf(buf, sizeof(buf),
                     "%d %.4f %.4f %.4f %.6f %.6f %.6f %.4f %d %d %d %d %d %d\n",
                     id, mt.offsetX, mt.offsetY, mt.offsetZ,
                     mt.scaleX, mt.scaleY, mt.scaleZ, mt.rotationDegrees,
                     mt.flipX ? 1 : 0, mt.flipY ? 1 : 0, mt.flipZ ? 1 : 0,
                     mt.swapYZ ? 1 : 0, mt.swapXZ ? 1 : 0, mt.swapXY ? 1 : 0);
            out << buf;
        }
    }
}

static MapTransform LoadMapTransform(int mapId, bool* found)
{
    if (found) *found = false;
    std::ifstream in(kCalibrationFile);
    if (!in.is_open()) return {};
    std::string line;
    while (std::getline(in, line)) {
        if (line.empty() || line[0] == '#') continue;
        int id;
        float ox, oy, oz, sx, sy, sz, rot;
        int fx, fy, fz, syz, sxz, sxy;
        if (sscanf_s(line.c_str(), "%d %f %f %f %f %f %f %f %d %d %d %d %d %d",
                     &id, &ox, &oy, &oz, &sx, &sy, &sz, &rot,
                     &fx, &fy, &fz, &syz, &sxz, &sxy) == 14)
        {
            if (id == mapId) {
                if (found) *found = true;
                return { ox, oy, oz, sx, sy, sz, rot,
                         fx != 0, fy != 0, fz != 0,
                         syz != 0, sxz != 0, sxy != 0 };
            }
        }
    }
    return {};
}

// ---------------------------------------------------------------------------
// Agent Overlay: full calibration transform pipeline + rendering
// ---------------------------------------------------------------------------

static ImU32 GetAgentTeamColor(uint8_t teamId)
{
    switch (teamId) {
    case 1:  return IM_COL32(0x2A, 0x8C, 0xFF, 0xFF);
    case 2:  return IM_COL32(0xFF, 0x4A, 0x4A, 0xFF);
    default: return IM_COL32(0xAA, 0xAA, 0xAA, 0xFF);
    }
}

// Binary search: find index of last snapshot with time <= t
static int FindSnapshotIndex(const std::vector<AgentSnapshot>& snaps, float t)
{
    int lo = 0, hi = static_cast<int>(snaps.size()) - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo + 1) / 2;
        if (snaps[mid].time <= t) lo = mid; else hi = mid - 1;
    }
    return lo;
}

// Snap to the nearest snapshot <= t (no blending). Used for flags and
// when interpolation is disabled.
static void SnapAgentPosition(const AgentReplayData& ard, float t,
                              float& outX, float& outY, float& outZ)
{
    const auto& snaps = ard.snapshots;
    if (snaps.empty()) { outX = outY = outZ = 0.f; return; }
    if (t <= snaps.front().time) {
        outX = snaps.front().x; outY = snaps.front().y; outZ = snaps.front().z; return;
    }
    if (t >= snaps.back().time) {
        outX = snaps.back().x; outY = snaps.back().y; outZ = snaps.back().z; return;
    }
    int idx = FindSnapshotIndex(snaps, t);
    outX = snaps[idx].x; outY = snaps[idx].y; outZ = snaps[idx].z;
}

// Stationary threshold: if both bracketing snapshots are within this distance
// per axis (game units), skip interpolation to avoid micro-jitter from data noise.
// Matches the RAW_COORDINATE_EPSILON from the working website implementation.
static constexpr float kStationaryEpsilon = 1.0f;

// Original linear interpolation (legacy behavior).
static void LinearInterpolatePosition(const AgentReplayData& ard, float t,
                                      float& outX, float& outY, float& outZ)
{
    const auto& snaps = ard.snapshots;
    if (snaps.empty()) { outX = outY = outZ = 0.f; return; }
    if (t <= snaps.front().time) {
        outX = snaps.front().x; outY = snaps.front().y; outZ = snaps.front().z; return;
    }
    if (t >= snaps.back().time) {
        outX = snaps.back().x; outY = snaps.back().y; outZ = snaps.back().z; return;
    }
    int lo = FindSnapshotIndex(snaps, t);
    auto& s0 = snaps[lo];
    if (lo + 1 < static_cast<int>(snaps.size())) {
        auto& s1 = snaps[lo + 1];

        if (fabsf(s1.x - s0.x) <= kStationaryEpsilon &&
            fabsf(s1.y - s0.y) <= kStationaryEpsilon &&
            fabsf(s1.z - s0.z) <= kStationaryEpsilon) {
            outX = s0.x; outY = s0.y; outZ = s0.z;
            return;
        }

        float dt = s1.time - s0.time;
        float a = (dt > 0.001f) ? (t - s0.time) / dt : 0.f;
        outX = s0.x + (s1.x - s0.x) * a;
        outY = s0.y + (s1.y - s0.y) * a;
        outZ = s0.z + (s1.z - s0.z) * a;
    } else {
        outX = s0.x; outY = s0.y; outZ = s0.z;
    }
}

// Find the last MOVE_TO_POINT event at or before time t (binary search).
// Returns -1 if none exists.
static int FindMoveEventIndex(const std::vector<MoveToPointEvent>& moves, float t)
{
    if (moves.empty()) return -1;
    int lo = 0, hi = static_cast<int>(moves.size()) - 1, result = -1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (moves[mid].time <= t) { result = mid; lo = mid + 1; }
        else { hi = mid - 1; }
    }
    return result;
}

// Improved interpolation: MOVE_TO_POINT aware.
//   - For small gaps (<= gapThreshold): pure linear lerp
//   - For large gaps: use MOVE_TO_POINT target as movement direction anchor
//     blended with linear interpolation via velocityInfluence slider.
//   - If no MOVE_TO_POINT exists for the interval, pure linear interpolation.
static void ImprovedInterpolatePosition(const AgentReplayData& ard, float t,
                                        const InterpolationSettings& s,
                                        float& outX, float& outY, float& outZ)
{
    const auto& snaps = ard.snapshots;
    if (snaps.empty()) { outX = outY = outZ = 0.f; return; }
    if (t <= snaps.front().time) {
        outX = snaps.front().x; outY = snaps.front().y; outZ = snaps.front().z; return;
    }
    if (t >= snaps.back().time) {
        outX = snaps.back().x; outY = snaps.back().y; outZ = snaps.back().z; return;
    }

    int lo = FindSnapshotIndex(snaps, t);
    auto& prev = snaps[lo];

    if (lo + 1 >= static_cast<int>(snaps.size())) {
        outX = prev.x; outY = prev.y; outZ = prev.z;
        return;
    }
    auto& next = snaps[lo + 1];

    if (fabsf(next.x - prev.x) <= kStationaryEpsilon &&
        fabsf(next.y - prev.y) <= kStationaryEpsilon &&
        fabsf(next.z - prev.z) <= kStationaryEpsilon) {
        outX = prev.x; outY = prev.y; outZ = prev.z;
        return;
    }

    float gap = next.time - prev.time;
    float alpha = (gap > 0.001f) ? (t - prev.time) / gap : 0.f;

    // Base linear interpolation
    float lx = prev.x + (next.x - prev.x) * alpha;
    float ly = prev.y + (next.y - prev.y) * alpha;
    float lz = prev.z + (next.z - prev.z) * alpha;

    // MOVE_TO_POINT directional prediction for large gaps
    if (gap > s.gapThreshold && s.velocityInfluence > 0.f)
    {
        int moveIdx = FindMoveEventIndex(ard.moveEvents, t);
        if (moveIdx >= 0)
        {
            auto& move = ard.moveEvents[moveIdx];

            // Direction from previous snapshot position toward the MOVE_TO_POINT target
            float dx = move.targetX - prev.x;
            float dy = move.targetY - prev.y;
            float dist = sqrtf(dx * dx + dy * dy);

            if (dist > 1.f)
            {
                // Estimate speed from the distance between the two bracketing snapshots
                float speed = sqrtf((next.x - prev.x) * (next.x - prev.x) +
                                    (next.y - prev.y) * (next.y - prev.y)) / gap;

                float dirX = dx / dist;
                float dirY = dy / dist;
                float dt = t - prev.time;

                float px = prev.x + dirX * speed * dt;
                float py = prev.y + dirY * speed * dt;
                float pz = prev.z;

                float beta = (gap - s.gapThreshold) / 1.0f;
                if (beta > 1.f) beta = 1.f;
                beta *= s.velocityInfluence;

                outX = lx + (px - lx) * beta;
                outY = ly + (py - ly) * beta;
                outZ = lz + (pz - lz) * beta;
                return;
            }
        }
        // No applicable MOVE_TO_POINT — fall through to pure linear
    }

    outX = lx;
    outY = ly;
    outZ = lz;
}

// Internal dispatch: run the active interpolation mode (or snap when disabled).
static void DispatchInterpolation(const AgentReplayData& ard, float t,
                                  const InterpolationSettings& is,
                                  float& outX, float& outY, float& outZ)
{
    if (!is.enabled) {
        SnapAgentPosition(ard, t, outX, outY, outZ);
        return;
    }
    if (is.mode == InterpolationMode::OriginalLinear)
        LinearInterpolatePosition(ard, t, outX, outY, outZ);
    else
        ImprovedInterpolatePosition(ard, t, is, outX, outY, outZ);
}

// Unified entry point: routes through flag snap / disabled snap /
// original linear / improved, based on agent type and settings.
//
// Casting freeze is intentionally NOT applied here.  The snapshot data
// already reflects the game's movement freeze during casts — consecutive
// snapshots during a cast have nearly identical positions, so the
// stationary-detection epsilon in the lerp functions keeps the agent
// still without introducing a position discontinuity at cast boundaries.
//
// Death freeze interpolates to the moment the agent died instead of
// snapping to a raw snapshot, avoiding a teleport at the alive→dead edge.
static void InterpolateAgentPosition(const AgentReplayData& ard, float t,
                                     const InterpolationSettings& is,
                                     float& outX, float& outY, float& outZ)
{
    // Flags and Spirits never interpolate — snap to nearest recorded position
    if (ard.type == AgentType::Flag || ard.type == AgentType::Spirit) {
        SnapAgentPosition(ard, t, outX, outY, outZ);
        return;
    }

    // Death freeze: interpolate to the moment of death so there is no
    // position jump at the alive→dead boundary.
    if (ard.isDeadAtTime(t)) {
        float deathT = ard.deathTransitionTime(t);
        DispatchInterpolation(ard, deathT, is, outX, outY, outZ);
        return;
    }

    DispatchInterpolation(ard, t, is, outX, outY, outZ);
}

static std::string GetAgentLabel(const AgentReplayData& ard)
{
    switch (ard.type) {
    case AgentType::Player: return ard.playerName;
    case AgentType::NPC:    return ard.categoryName;
    case AgentType::Gadget: return ard.categoryName;
    case AgentType::Flag:   return "Flag";
    case AgentType::Spirit: return ard.categoryName;
    case AgentType::Item:   return ard.categoryName;
    default:                return std::format("Agent {}", ard.agent_id);
    }
}

static XMFLOAT3 ApplyMapTransformToPos(float snapX, float snapY, float snapZ,
                                        const MapTransform& t)
{
    // 0. Base axis remap: GWCA (x,y,z_height) → GWMB (x, z_height, y)
    float px = snapX;
    float py = snapZ;
    float pz = snapY;

    // 1. Axis swaps
    if (t.swapYZ) { float tmp = py; py = pz; pz = tmp; }
    if (t.swapXZ) { float tmp = px; px = pz; pz = tmp; }
    if (t.swapXY) { float tmp = px; px = py; py = tmp; }

    // 2. Axis flips
    if (t.flipX) px = -px;
    if (t.flipY) py = -py;
    if (t.flipZ) pz = -pz;

    // 3. Rotation around Y axis
    if (t.rotationDegrees != 0.f) {
        float rad = t.rotationDegrees * (XM_PI / 180.f);
        float c = cosf(rad), s = sinf(rad);
        float rx = px * c - pz * s;
        float rz = px * s + pz * c;
        px = rx;
        pz = rz;
    }

    // 4. Offset
    px += t.offsetX;
    py += t.offsetY;
    pz += t.offsetZ;

    // 5. Scale
    px *= t.scaleX;
    py *= t.scaleY;
    pz *= t.scaleZ;

    return { px, py, pz };
}

static bool ProjectToScreen(XMMATRIX viewProj, float vpW, float vpH,
                             const XMFLOAT3& worldPos, float& scrX, float& scrY)
{
    XMVECTOR clip = XMVector4Transform(
        XMVectorSet(worldPos.x, worldPos.y, worldPos.z, 1.f), viewProj);
    float w = XMVectorGetW(clip);
    if (w <= 0.001f) return false;
    float ndcX = XMVectorGetX(clip) / w;
    float ndcY = XMVectorGetY(clip) / w;
    scrX = (ndcX + 1.f) * 0.5f * vpW;
    scrY = (1.f - ndcY) * 0.5f * vpH;
    return (scrX > -200.f && scrX < vpW + 200.f &&
            scrY > -200.f && scrY < vpH + 200.f);
}

// ---------------------------------------------------------------------------
// Flag Timeline — delegates to FlagTimelineBuilder
// ---------------------------------------------------------------------------

void ReplayWindow::BuildFlagTimeline()
{
    FlagTimelineBuilder::Input input;
    input.flagEvents = &m_replayCtx.stocData.flagEvents;
    input.lifecycle  = &m_replayCtx.stocData.lifecycle;
    input.mapObject  = &m_replayCtx.stocData.mapObject;
    input.agents     = &m_replayCtx.agents;
    input.mapId      = m_replayCtx.mapId;
    m_flagTimeline = FlagTimelineBuilder::Build(input);
    m_flagTimelineBuilt = true;
    BuildFlagMessages();
}

// ---------------------------------------------------------------------------
// Build display messages from flag timeline events
// ---------------------------------------------------------------------------

void ReplayWindow::BuildFlagMessages()
{
    m_flagMessages.clear();
    if (!m_flagTimeline.valid) return;

    for (auto& ev : m_flagTimeline.allEvents)
    {
        if (ev.eventType == FlagTimelineEventType::Spawn ||
            ev.eventType == FlagTimelineEventType::GroundSpawn)
            continue;

        FlagEventMessage msg;
        msg.time      = ev.time;
        msg.flagTeam  = static_cast<int>(ev.flagTeam);
        msg.eventType = ev.eventType;

        int actorId = ev.actorAgentId;
        if (actorId >= 0) {
            auto it = m_replayCtx.agents.find(actorId);
            if (it != m_replayCtx.agents.end()) {
                msg.playerName = it->second.playerName.empty()
                    ? it->second.categoryName : it->second.playerName;
                msg.playerTeam = (it->second.teamId == 2) ? 1 : 0;
            }
        }

        if (msg.playerName.empty() && ev.eventType != FlagTimelineEventType::Return)
            continue;

        m_flagMessages.push_back(std::move(msg));
    }
}

// ---------------------------------------------------------------------------
// Fog of War — full-screen shader overlay
// ---------------------------------------------------------------------------

static const char kFogHLSL[] = R"(
cbuffer FogCB : register(b0)
{
    float4x4 invViewProj;
    float4 playerPos[8];
    float  compassRadius;
    float  fogOpacity;
    float  edgeSoftness;
    float  refHeight;
    float  viewportW;
    float  viewportH;
    int    playerCount;
    float  pad;
};

struct VS_OUT
{
    float4 pos : SV_Position;
    float2 uv  : TEXCOORD0;
};

VS_OUT VSMain(uint id : SV_VertexID)
{
    VS_OUT o;
    float2 uv = float2((id << 1) & 2, id & 2);
    o.pos = float4(uv * float2(2, -2) + float2(-1, 1), 0.5, 1);
    o.uv  = uv;
    return o;
}

float4 PSMain(VS_OUT i) : SV_Target
{
    float2 ndc;
    ndc.x =  (i.pos.x / viewportW) * 2.0 - 1.0;
    ndc.y = 1.0 - (i.pos.y / viewportH) * 2.0;

    float4 nearH = mul(float4(ndc, 0, 1), invViewProj);
    float4 farH  = mul(float4(ndc, 1, 1), invViewProj);

    if (abs(nearH.w) < 1e-6 || abs(farH.w) < 1e-6)
        return float4(0, 0, 0, fogOpacity);

    float3 nearW = nearH.xyz / nearH.w;
    float3 farW  = farH.xyz / farH.w;

    float3 dir = farW - nearW;
    if (abs(dir.y) < 1e-6)
        return float4(0, 0, 0, fogOpacity);

    float t = (refHeight - nearW.y) / dir.y;
    if (t < 0)
        return float4(0, 0, 0, fogOpacity);

    float3 hit = nearW + dir * t;

    float minDist = 1e6;
    [loop] for (int p = 0; p < playerCount; ++p)
    {
        float dx = hit.x - playerPos[p].x;
        float dz = hit.z - playerPos[p].z;
        minDist = min(minDist, sqrt(dx * dx + dz * dz));
    }

    float edge = max(edgeSoftness, 0.1);
    float fog = smoothstep(compassRadius - edge, compassRadius, minDist);
    return float4(0, 0, 0, fogOpacity * saturate(fog));
}
)";

void ReplayWindow::InitFogRenderer()
{
    if (m_fogInitialized) return;
    m_fogInitialized = true;

    ID3D11Device* dev = m_deviceResources->GetD3DDevice();

    Microsoft::WRL::ComPtr<ID3DBlob> vsBlob, psBlob, errBlob;
    UINT flags = D3DCOMPILE_ENABLE_STRICTNESS;
#ifdef _DEBUG
    flags |= D3DCOMPILE_DEBUG;
#endif

    HRESULT hr = D3DCompile(kFogHLSL, sizeof(kFogHLSL), nullptr, nullptr, nullptr,
                            "VSMain", "vs_5_0", flags, 0, vsBlob.GetAddressOf(), errBlob.GetAddressOf());
    if (FAILED(hr)) return;

    hr = D3DCompile(kFogHLSL, sizeof(kFogHLSL), nullptr, nullptr, nullptr,
                    "PSMain", "ps_5_0", flags, 0, psBlob.GetAddressOf(), errBlob.GetAddressOf());
    if (FAILED(hr)) return;

    dev->CreateVertexShader(vsBlob->GetBufferPointer(), vsBlob->GetBufferSize(), nullptr, m_fogVS.GetAddressOf());
    dev->CreatePixelShader(psBlob->GetBufferPointer(), psBlob->GetBufferSize(), nullptr, m_fogPS.GetAddressOf());

    D3D11_BUFFER_DESC cbd = {};
    cbd.ByteWidth = sizeof(FogCBData);
    cbd.Usage = D3D11_USAGE_DYNAMIC;
    cbd.BindFlags = D3D11_BIND_CONSTANT_BUFFER;
    cbd.CPUAccessFlags = D3D11_CPU_ACCESS_WRITE;
    dev->CreateBuffer(&cbd, nullptr, m_fogCB.GetAddressOf());

    D3D11_DEPTH_STENCIL_DESC dsd = {};
    dsd.DepthEnable = FALSE;
    dsd.DepthWriteMask = D3D11_DEPTH_WRITE_MASK_ZERO;
    dev->CreateDepthStencilState(&dsd, m_fogDSS.GetAddressOf());

    D3D11_BLEND_DESC bld = {};
    bld.RenderTarget[0].BlendEnable = TRUE;
    bld.RenderTarget[0].SrcBlend = D3D11_BLEND_SRC_ALPHA;
    bld.RenderTarget[0].DestBlend = D3D11_BLEND_INV_SRC_ALPHA;
    bld.RenderTarget[0].BlendOp = D3D11_BLEND_OP_ADD;
    bld.RenderTarget[0].SrcBlendAlpha = D3D11_BLEND_ZERO;
    bld.RenderTarget[0].DestBlendAlpha = D3D11_BLEND_ONE;
    bld.RenderTarget[0].BlendOpAlpha = D3D11_BLEND_OP_ADD;
    bld.RenderTarget[0].RenderTargetWriteMask = D3D11_COLOR_WRITE_ENABLE_ALL;
    dev->CreateBlendState(&bld, m_fogBS.GetAddressOf());

    D3D11_RASTERIZER_DESC rd = {};
    rd.FillMode = D3D11_FILL_SOLID;
    rd.CullMode = D3D11_CULL_NONE;
    rd.DepthClipEnable = TRUE;
    dev->CreateRasterizerState(&rd, m_fogRS.GetAddressOf());
}

static constexpr float kFogCompassRadius = 5020.f;

void ReplayWindow::DrawFogOfWar()
{
    if (m_fogPerspective == 0) return;
    if (m_topViewActive) return;
    if (!m_agentsClassified || m_replayCtx.agents.empty()) return;

    InitFogRenderer();
    if (!m_fogVS || !m_fogPS) return;

    Camera* cam = m_mapRenderer->GetCamera();
    if (!cam) return;
    XMMATRIX viewProj = cam->GetView() * cam->GetProj();

    auto dvp = m_deviceResources->GetScreenViewport();
    float vpW = dvp.Width;
    float vpH = dvp.Height;

    const MapTransform& mt = m_replayCtx.mapTransform;
    const InterpolationSettings& is = m_replayCtx.interpSettings;
    Terrain* terrain = m_mapRenderer->GetTerrain();

    FogCBData cb = {};

    XMVECTOR det;
    XMMATRIX invVP = XMMatrixInverse(&det, viewProj);
    XMStoreFloat4x4(&cb.invViewProj, XMMatrixTranspose(invVP));

    XMFLOAT3 origin = ApplyMapTransformToPos(0, 0, 0, mt);
    XMFLOAT3 xOff   = ApplyMapTransformToPos(kFogCompassRadius, 0, 0, mt);
    float wdx = xOff.x - origin.x, wdz = xOff.z - origin.z;
    float worldCompassRadius = sqrtf(wdx * wdx + wdz * wdz);

    constexpr float kFogEdgeSoftness = 200.f;
    XMFLOAT3 eOff = ApplyMapTransformToPos(kFogEdgeSoftness, 0, 0, mt);
    float edx = eOff.x - origin.x, edz = eOff.z - origin.z;
    float worldEdgeSoftness = sqrtf(edx * edx + edz * edz);

    float avgHeight = 0.f;
    int playerCount = 0;
    bool isPlayerMode = (m_fogPlayerAgent >= 0);

    if (isPlayerMode)
    {
        auto pit = m_replayCtx.agents.find(m_fogPlayerAgent);
        if (pit != m_replayCtx.agents.end() && !pit->second.snapshots.empty()
            && !pit->second.isDeadAtTime(m_debugTimeline))
        {
            float sx, sy, sz;
            InterpolateAgentPosition(pit->second, m_debugTimeline, is, sx, sy, sz);
            XMFLOAT3 wpos = ApplyMapTransformToPos(sx, sy, sz, mt);
            if (terrain) wpos.y = terrain->get_height_at(wpos.x, wpos.z);
            cb.playerPos[0] = { wpos.x, wpos.y, wpos.z, 0.f };
            avgHeight = wpos.y;
            playerCount = 1;
        }
    }
    else
    {
        for (auto& [agentId, ard] : m_replayCtx.agents)
        {
            if (playerCount >= 8) break;
            if (ard.teamId != m_fogPerspective) continue;
            if (ard.type != AgentType::Player) continue;
            if (ard.snapshots.empty()) continue;
            if (ard.isDeadAtTime(m_debugTimeline)) continue;

            float sx, sy, sz;
            InterpolateAgentPosition(ard, m_debugTimeline, is, sx, sy, sz);
            XMFLOAT3 wpos = ApplyMapTransformToPos(sx, sy, sz, mt);
            if (terrain) wpos.y = terrain->get_height_at(wpos.x, wpos.z);

            cb.playerPos[playerCount] = { wpos.x, wpos.y, wpos.z, 0.f };
            avgHeight += wpos.y;
            playerCount++;
        }
    }

    float fogOpacity = isPlayerMode ? 0.82f : 0.72f;

    cb.playerCount    = playerCount;
    cb.compassRadius  = worldCompassRadius;
    cb.fogOpacity     = (playerCount > 0) ? fogOpacity : 1.0f;
    cb.edgeSoftness   = worldEdgeSoftness;
    cb.refHeight      = (playerCount > 0) ? (avgHeight / playerCount) : 0.f;
    cb.viewportW      = vpW;
    cb.viewportH      = vpH;

    auto* ctx = m_deviceResources->GetD3DDeviceContext();

    Microsoft::WRL::ComPtr<ID3D11RasterizerState>   prevRS;
    Microsoft::WRL::ComPtr<ID3D11DepthStencilState> prevDSS;
    UINT prevStencilRef;
    Microsoft::WRL::ComPtr<ID3D11BlendState>        prevBS;
    FLOAT prevBF[4]; UINT prevSM;
    Microsoft::WRL::ComPtr<ID3D11VertexShader>      prevVS;
    Microsoft::WRL::ComPtr<ID3D11PixelShader>       prevPS;
    Microsoft::WRL::ComPtr<ID3D11InputLayout>       prevIL;
    D3D11_PRIMITIVE_TOPOLOGY prevTopo;
    Microsoft::WRL::ComPtr<ID3D11Buffer> prevPSCB0;
    Microsoft::WRL::ComPtr<ID3D11Buffer> prevVSCB0;

    ctx->RSGetState(prevRS.GetAddressOf());
    ctx->OMGetDepthStencilState(prevDSS.GetAddressOf(), &prevStencilRef);
    ctx->OMGetBlendState(prevBS.GetAddressOf(), prevBF, &prevSM);
    ctx->VSGetShader(prevVS.GetAddressOf(), nullptr, nullptr);
    ctx->PSGetShader(prevPS.GetAddressOf(), nullptr, nullptr);
    ctx->IAGetInputLayout(prevIL.GetAddressOf());
    ctx->IAGetPrimitiveTopology(&prevTopo);
    ctx->PSGetConstantBuffers(0, 1, prevPSCB0.GetAddressOf());
    ctx->VSGetConstantBuffers(0, 1, prevVSCB0.GetAddressOf());

    D3D11_MAPPED_SUBRESOURCE mapped;
    ctx->Map(m_fogCB.Get(), 0, D3D11_MAP_WRITE_DISCARD, 0, &mapped);
    memcpy(mapped.pData, &cb, sizeof(cb));
    ctx->Unmap(m_fogCB.Get(), 0);

    ctx->IASetInputLayout(nullptr);
    ctx->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);

    ctx->VSSetShader(m_fogVS.Get(), nullptr, 0);
    ctx->PSSetShader(m_fogPS.Get(), nullptr, 0);
    ctx->PSSetConstantBuffers(0, 1, m_fogCB.GetAddressOf());

    ctx->RSSetState(m_fogRS.Get());
    ctx->OMSetDepthStencilState(m_fogDSS.Get(), 0);
    float blendFactor[4] = { 0, 0, 0, 0 };
    ctx->OMSetBlendState(m_fogBS.Get(), blendFactor, 0xFFFFFFFF);

    ctx->Draw(3, 0);

    ctx->RSSetState(prevRS.Get());
    ctx->OMSetDepthStencilState(prevDSS.Get(), prevStencilRef);
    ctx->OMSetBlendState(prevBS.Get(), prevBF, prevSM);
    ctx->VSSetShader(prevVS.Get(), nullptr, 0);
    ctx->PSSetShader(prevPS.Get(), nullptr, 0);
    ctx->IASetInputLayout(prevIL.Get());
    ctx->IASetPrimitiveTopology(prevTopo);
    ctx->PSSetConstantBuffers(0, 1, prevPSCB0.GetAddressOf());
    ctx->VSSetConstantBuffers(0, 1, prevVSCB0.GetAddressOf());
}

bool ReplayWindow::IsAgentInFog(int agentId) const
{
    if (m_fogPerspective == 0) return false;

    auto eit = m_replayCtx.agents.find(agentId);
    if (eit == m_replayCtx.agents.end()) return true;
    const auto& enemyArd = eit->second;

    if (m_fogPlayerAgent < 0 && enemyArd.teamId == m_fogPerspective) return false;

    float ex, ey, ez;
    InterpolateAgentPosition(enemyArd, m_debugTimeline, m_replayCtx.interpSettings, ex, ey, ez);

    if (m_fogPlayerAgent >= 0)
    {
        if (agentId == m_fogPlayerAgent) return false;
        auto pit = m_replayCtx.agents.find(m_fogPlayerAgent);
        if (pit == m_replayCtx.agents.end()) return true;
        if (pit->second.snapshots.empty() || pit->second.isDeadAtTime(m_debugTimeline))
            return true;
        float fx, fy, fz;
        InterpolateAgentPosition(pit->second, m_debugTimeline, m_replayCtx.interpSettings, fx, fy, fz);
        float dx = ex - fx, dy = ey - fy;
        return (dx * dx + dy * dy > kFogCompassRadius * kFogCompassRadius);
    }

    for (auto& [fid, fard] : m_replayCtx.agents)
    {
        if (fard.teamId != m_fogPerspective) continue;
        if (fard.type != AgentType::Player) continue;
        if (fard.snapshots.empty()) continue;
        if (fard.isDeadAtTime(m_debugTimeline)) continue;

        float fx, fy, fz;
        InterpolateAgentPosition(fard, m_debugTimeline, m_replayCtx.interpSettings, fx, fy, fz);

        float dx = ex - fx, dy = ey - fy;
        if (dx * dx + dy * dy <= kFogCompassRadius * kFogCompassRadius)
            return false;
    }
    return true;
}

// ---------------------------------------------------------------------------
// Cylinder agent marker — 3D renderer
// ---------------------------------------------------------------------------

static const char kCylinderHLSL[] = R"(
cbuffer CBPerFrame : register(b0)
{
    float4x4 gViewProj;
    float4   gCamPos;
};
cbuffer CBPerInstance : register(b1)
{
    float4x4 gWorld;
    float4   gTeamColor;
};

struct VS_IN  { float3 pos : POSITION; float3 nrm : NORMAL; float height01 : HEIGHT; };
struct VS_OUT { float4 pos : SV_Position; float3 worldPos : TEXCOORD0;
                float3 worldNrm : TEXCOORD1; float  height01 : TEXCOORD2; };

VS_OUT VSMain(VS_IN i)
{
    VS_OUT o;
    float4 wp = mul(float4(i.pos, 1), gWorld);
    o.pos      = mul(wp, gViewProj);
    o.worldPos = wp.xyz;
    o.worldNrm = normalize(mul(float4(i.nrm, 0), gWorld).xyz);
    o.height01 = i.height01;
    return o;
}

float4 PSMain(VS_OUT i) : SV_Target
{
    float3 baseColor = gTeamColor.rgb;

    // Ambient light from above (Y is up in GWMB render space)
    float3 lightDir = normalize(float3(0.2, 1.0, 0.3));
    float ndl = saturate(dot(i.worldNrm, lightDir));

    // View direction for specular on top cap
    float3 viewDir = normalize(gCamPos.xyz - i.worldPos);
    float3 halfVec = normalize(lightDir + viewDir);
    float spec = pow(saturate(dot(i.worldNrm, halfVec)), 32.0);

    // Vertical gradient: darker at bottom, brighter toward top
    float vertBright = lerp(0.55, 1.0, i.height01);

    // Facing camera brightness (body sides brighter at center)
    float facing = saturate(dot(i.worldNrm, viewDir));
    float faceBright = lerp(0.6, 1.0, facing * facing);

    // Top cap gets extra brightness + specular (Y is up)
    float isTop = saturate(i.worldNrm.y * 4.0 - 3.0);
    float topBright = lerp(1.0, 1.3, isTop);

    float3 color = baseColor * (0.35 + 0.65 * ndl) * vertBright * faceBright * topBright;
    color += spec * isTop * 0.4;

    // Base glow: additive team color emission at the very bottom
    float baseGlow = saturate(1.0 - i.height01 * 8.0) * 0.35;
    color += baseColor * baseGlow;

    return float4(saturate(color), gTeamColor.a);
}
)";

void ReplayWindow::InitCylinderRenderer()
{
    if (m_cylInitialized) return;
    m_cylInitialized = true;

    ID3D11Device* dev = m_deviceResources->GetD3DDevice();

    // --- Compile shaders ---
    Microsoft::WRL::ComPtr<ID3DBlob> vsBlob, psBlob, errBlob;
    UINT flags = D3DCOMPILE_ENABLE_STRICTNESS;
#ifdef _DEBUG
    flags |= D3DCOMPILE_DEBUG;
#endif

    HRESULT hr = D3DCompile(kCylinderHLSL, sizeof(kCylinderHLSL), nullptr, nullptr, nullptr,
                            "VSMain", "vs_5_0", flags, 0, vsBlob.GetAddressOf(), errBlob.GetAddressOf());
    if (FAILED(hr)) return;

    hr = D3DCompile(kCylinderHLSL, sizeof(kCylinderHLSL), nullptr, nullptr, nullptr,
                    "PSMain", "ps_5_0", flags, 0, psBlob.GetAddressOf(), errBlob.GetAddressOf());
    if (FAILED(hr)) return;

    dev->CreateVertexShader(vsBlob->GetBufferPointer(), vsBlob->GetBufferSize(), nullptr, m_cylVS.GetAddressOf());
    dev->CreatePixelShader(psBlob->GetBufferPointer(), psBlob->GetBufferSize(), nullptr, m_cylPS.GetAddressOf());

    // --- Input layout ---
    D3D11_INPUT_ELEMENT_DESC layout[] = {
        { "POSITION", 0, DXGI_FORMAT_R32G32B32_FLOAT,    0,  0, D3D11_INPUT_PER_VERTEX_DATA, 0 },
        { "NORMAL",   0, DXGI_FORMAT_R32G32B32_FLOAT,    0, 12, D3D11_INPUT_PER_VERTEX_DATA, 0 },
        { "HEIGHT",   0, DXGI_FORMAT_R32_FLOAT,           0, 24, D3D11_INPUT_PER_VERTEX_DATA, 0 },
    };
    dev->CreateInputLayout(layout, 3, vsBlob->GetBufferPointer(), vsBlob->GetBufferSize(), m_cylIL.GetAddressOf());

    // --- Generate cylinder geometry ---
    constexpr int   SEG = 16;
    constexpr float R   = 30.f;
    constexpr float H   = 120.f;
    constexpr float PI2 = 6.2831853f;

    // Vertices: bottom ring + top ring + bottom center + top center
    // bottom ring: SEG verts, top ring: SEG verts
    // Each side quad uses 2 bottom + 2 top (shared normals per segment)
    // Plus 2 cap centers
    // Total: SEG*2 (body) + 1 (bottom center) + SEG (bottom fan) + 1 (top center) + SEG (top fan)
    // Simplify: body ring duplicated for caps to have different normals

    std::vector<CylVertex> verts;
    std::vector<uint16_t> indices;

    // Body vertices — Y is UP in GWMB render space (ApplyMapTransformToPos already converts)
    int bodyBase = 0;
    for (int i = 0; i <= SEG; ++i)
    {
        float a = (float(i) / SEG) * PI2;
        float cs = cosf(a), sn = sinf(a);
        float nx = cs, nz = sn;
        // Bottom (y=0)
        verts.push_back({ R * cs, 0.f, R * sn,  nx, 0, nz,  0.f });
        // Top (y=H)
        verts.push_back({ R * cs, H,   R * sn,  nx, 0, nz,  1.f });
    }

    // Body indices (triangle strip as quads)
    for (int i = 0; i < SEG; ++i)
    {
        int b0 = bodyBase + i * 2;
        int b1 = bodyBase + i * 2 + 1;
        int b2 = bodyBase + (i + 1) * 2;
        int b3 = bodyBase + (i + 1) * 2 + 1;
        indices.push_back((uint16_t)b0); indices.push_back((uint16_t)b1); indices.push_back((uint16_t)b2);
        indices.push_back((uint16_t)b2); indices.push_back((uint16_t)b1); indices.push_back((uint16_t)b3);
    }

    // Bottom cap (normal pointing down: -Y)
    int botCenter = (int)verts.size();
    verts.push_back({ 0, 0, 0,  0, -1, 0,  0.f });
    int botRing = (int)verts.size();
    for (int i = 0; i < SEG; ++i)
    {
        float a = (float(i) / SEG) * PI2;
        verts.push_back({ R * cosf(a), 0, R * sinf(a),  0, -1, 0,  0.f });
    }
    for (int i = 0; i < SEG; ++i)
    {
        indices.push_back((uint16_t)botCenter);
        indices.push_back((uint16_t)(botRing + (i + 1) % SEG));
        indices.push_back((uint16_t)(botRing + i));
    }

    // Top cap (normal pointing up: +Y)
    int topCenter = (int)verts.size();
    verts.push_back({ 0, H, 0,  0, 1, 0,  1.f });
    int topRing = (int)verts.size();
    for (int i = 0; i < SEG; ++i)
    {
        float a = (float(i) / SEG) * PI2;
        verts.push_back({ R * cosf(a), H, R * sinf(a),  0, 1, 0,  1.f });
    }
    for (int i = 0; i < SEG; ++i)
    {
        indices.push_back((uint16_t)topCenter);
        indices.push_back((uint16_t)(topRing + i));
        indices.push_back((uint16_t)(topRing + (i + 1) % SEG));
    }

    m_cylIndexCount = (UINT)indices.size();

    // Vertex buffer
    D3D11_BUFFER_DESC vbd = {};
    vbd.ByteWidth = (UINT)(verts.size() * sizeof(CylVertex));
    vbd.Usage = D3D11_USAGE_IMMUTABLE;
    vbd.BindFlags = D3D11_BIND_VERTEX_BUFFER;
    D3D11_SUBRESOURCE_DATA vsd = { verts.data(), 0, 0 };
    dev->CreateBuffer(&vbd, &vsd, m_cylVB.GetAddressOf());

    // Index buffer
    D3D11_BUFFER_DESC ibd = {};
    ibd.ByteWidth = (UINT)(indices.size() * sizeof(uint16_t));
    ibd.Usage = D3D11_USAGE_IMMUTABLE;
    ibd.BindFlags = D3D11_BIND_INDEX_BUFFER;
    D3D11_SUBRESOURCE_DATA isd = { indices.data(), 0, 0 };
    dev->CreateBuffer(&ibd, &isd, m_cylIB.GetAddressOf());

    // Constant buffers
    D3D11_BUFFER_DESC cbd = {};
    cbd.Usage = D3D11_USAGE_DYNAMIC;
    cbd.CPUAccessFlags = D3D11_CPU_ACCESS_WRITE;
    cbd.BindFlags = D3D11_BIND_CONSTANT_BUFFER;

    cbd.ByteWidth = sizeof(CylPerFrame);
    dev->CreateBuffer(&cbd, nullptr, m_cylCBFrame.GetAddressOf());

    cbd.ByteWidth = sizeof(CylPerInst);
    dev->CreateBuffer(&cbd, nullptr, m_cylCBInst.GetAddressOf());

    // Rasterizer: solid, no culling (overlay cylinders visible from all angles)
    D3D11_RASTERIZER_DESC rd = {};
    rd.FillMode = D3D11_FILL_SOLID;
    rd.CullMode = D3D11_CULL_NONE;
    rd.FrontCounterClockwise = FALSE;
    rd.DepthBias = 0;
    rd.DepthBiasClamp = 0.f;
    rd.SlopeScaledDepthBias = 0.f;
    rd.DepthClipEnable = TRUE;
    dev->CreateRasterizerState(&rd, m_cylRS.GetAddressOf());

    // Depth-stencil: depth disabled — cylinders render as 3D overlay, always visible
    D3D11_DEPTH_STENCIL_DESC dsd = {};
    dsd.DepthEnable = FALSE;
    dsd.DepthWriteMask = D3D11_DEPTH_WRITE_MASK_ZERO;
    dev->CreateDepthStencilState(&dsd, m_cylDSS.GetAddressOf());

    // Blend: disabled — cylinders are fully opaque
    D3D11_BLEND_DESC bld = {};
    bld.RenderTarget[0].BlendEnable = TRUE;
    bld.RenderTarget[0].SrcBlend = D3D11_BLEND_SRC_ALPHA;
    bld.RenderTarget[0].DestBlend = D3D11_BLEND_INV_SRC_ALPHA;
    bld.RenderTarget[0].BlendOp = D3D11_BLEND_OP_ADD;
    bld.RenderTarget[0].SrcBlendAlpha = D3D11_BLEND_ONE;
    bld.RenderTarget[0].DestBlendAlpha = D3D11_BLEND_ZERO;
    bld.RenderTarget[0].BlendOpAlpha = D3D11_BLEND_OP_ADD;
    bld.RenderTarget[0].RenderTargetWriteMask = D3D11_COLOR_WRITE_ENABLE_ALL;
    dev->CreateBlendState(&bld, m_cylBS.GetAddressOf());

    // --- Generate pillar geometry (thin cylinder for medium LOD) ---
    {
        constexpr int   P_SEG = 8;
        constexpr float P_R   = 6.f;
        constexpr float P_H   = 120.f;

        std::vector<CylVertex> pv;
        std::vector<uint16_t>  pi;

        int pBase = 0;
        for (int i = 0; i <= P_SEG; ++i)
        {
            float a = (float(i) / P_SEG) * PI2;
            float cs = cosf(a), sn = sinf(a);
            pv.push_back({ P_R * cs, 0.f,  P_R * sn,  cs, 0, sn,  0.f });
            pv.push_back({ P_R * cs, P_H,  P_R * sn,  cs, 0, sn,  1.f });
        }
        for (int i = 0; i < P_SEG; ++i)
        {
            int b0 = pBase + i * 2, b1 = b0 + 1, b2 = pBase + (i + 1) * 2, b3 = b2 + 1;
            pi.push_back((uint16_t)b0); pi.push_back((uint16_t)b1); pi.push_back((uint16_t)b2);
            pi.push_back((uint16_t)b2); pi.push_back((uint16_t)b1); pi.push_back((uint16_t)b3);
        }

        int pBotC = (int)pv.size();
        pv.push_back({ 0, 0, 0,  0, -1, 0,  0.f });
        int pBotR = (int)pv.size();
        for (int i = 0; i < P_SEG; ++i) {
            float a = (float(i) / P_SEG) * PI2;
            pv.push_back({ P_R * cosf(a), 0, P_R * sinf(a),  0, -1, 0,  0.f });
        }
        for (int i = 0; i < P_SEG; ++i) {
            pi.push_back((uint16_t)pBotC);
            pi.push_back((uint16_t)(pBotR + (i + 1) % P_SEG));
            pi.push_back((uint16_t)(pBotR + i));
        }

        int pTopC = (int)pv.size();
        pv.push_back({ 0, P_H, 0,  0, 1, 0,  1.f });
        int pTopR = (int)pv.size();
        for (int i = 0; i < P_SEG; ++i) {
            float a = (float(i) / P_SEG) * PI2;
            pv.push_back({ P_R * cosf(a), P_H, P_R * sinf(a),  0, 1, 0,  1.f });
        }
        for (int i = 0; i < P_SEG; ++i) {
            pi.push_back((uint16_t)pTopC);
            pi.push_back((uint16_t)(pTopR + i));
            pi.push_back((uint16_t)(pTopR + (i + 1) % P_SEG));
        }

        m_pillarIndexCount = (UINT)pi.size();

        D3D11_BUFFER_DESC pvbd = {};
        pvbd.ByteWidth = (UINT)(pv.size() * sizeof(CylVertex));
        pvbd.Usage = D3D11_USAGE_IMMUTABLE;
        pvbd.BindFlags = D3D11_BIND_VERTEX_BUFFER;
        D3D11_SUBRESOURCE_DATA pvsd = { pv.data(), 0, 0 };
        dev->CreateBuffer(&pvbd, &pvsd, m_pillarVB.GetAddressOf());

        D3D11_BUFFER_DESC pibd = {};
        pibd.ByteWidth = (UINT)(pi.size() * sizeof(uint16_t));
        pibd.Usage = D3D11_USAGE_IMMUTABLE;
        pibd.BindFlags = D3D11_BIND_INDEX_BUFFER;
        D3D11_SUBRESOURCE_DATA pisd = { pi.data(), 0, 0 };
        dev->CreateBuffer(&pibd, &pisd, m_pillarIB.GetAddressOf());
    }
}

// ---------------------------------------------------------------------------
// Load 3D models from the .dat for known NPC / spirit agent types.
// Creates per-agent mesh instances so each agent can have its own transform.
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Async entry point: collects hashes, launches background IO thread
// ---------------------------------------------------------------------------

void ReplayWindow::LoadAgentModelsAsync()
{
    if (m_agentModelsLoaded || m_agentModelsLoading) return;
    if (!m_agentsClassified || m_replayCtx.agents.empty()) return;
    if (!m_datManager || !m_hashIndex) return;

    // 1. Collect unique file hashes and cache per-agent hash (main thread)
    //    Player variants are shuffled randomly per (profession, gender) group
    //    so that duplicate models are avoided until all variants are exhausted.
    std::unordered_set<uint32_t> uniqueHashes;

    // Count players per (profession, gender) pair
    std::unordered_map<uint64_t, int> profGenderCount;
    for (auto& [agentId, ard] : m_replayCtx.agents) {
        if (ard.type != AgentType::Player) continue;
        uint64_t key = ((uint64_t)ard.primaryProf << 1) | (ard.isFemale ? 1 : 0);
        profGenderCount[key]++;
    }

    // Build shuffled variant-index sequences per group
    std::mt19937 rng(std::random_device{}());
    std::unordered_map<uint64_t, std::vector<int>> profGenderShuffled;
    for (auto& [key, count] : profGenderCount) {
        int prof = static_cast<int>(key >> 1);
        bool isFemale = (key & 1) != 0;
        auto variants = GetPlayerModelVariants(prof, isFemale);
        int numVariants = static_cast<int>(variants.size());
        if (numVariants == 0) continue;

        auto& indices = profGenderShuffled[key];
        while (static_cast<int>(indices.size()) < count) {
            std::vector<int> round(numVariants);
            std::iota(round.begin(), round.end(), 0);
            std::shuffle(round.begin(), round.end(), rng);
            indices.insert(indices.end(), round.begin(), round.end());
        }
    }

    // Assign variants from the shuffled sequences
    std::unordered_map<uint64_t, int> profGenderAssignIdx;
    for (auto& [agentId, ard] : m_replayCtx.agents)
    {
        uint32_t fileHash = 0;
        if (ard.type == AgentType::Player) {
            uint64_t key = ((uint64_t)ard.primaryProf << 1) | (ard.isFemale ? 1 : 0);
            auto it = profGenderShuffled.find(key);
            if (it != profGenderShuffled.end() && !it->second.empty()) {
                int idx = profGenderAssignIdx[key]++;
                fileHash = LookupPlayerFileHash(ard.primaryProf, ard.isFemale,
                                                it->second[idx]);
            }
        } else {
            fileHash = LookupAgentFileHash(ard.type, ard.modelId);
        }
        if (fileHash == 0) continue;
        m_agentFileHashCache[agentId] = fileHash;
        uniqueHashes.insert(fileHash);
    }

    if (uniqueHashes.empty()) { m_agentModelsLoaded = true; return; }

    m_agentModelCreateOrder.assign(uniqueHashes.begin(), uniqueHashes.end());
    m_bgLoadTotal = static_cast<int>(m_agentModelCreateOrder.size());
    m_bgLoadProgress.store(0);
    m_bgLoadDone.store(false);
    m_agentModelCreateIndex = 0;
    m_agentModelsLoading = true;

    m_agentModelLoadThread = std::thread([this]() { LoadAgentModelsIO(); });
}

// ---------------------------------------------------------------------------
// Background thread: DAT reads + CPU parsing, NO D3D calls
// ---------------------------------------------------------------------------

void ReplayWindow::LoadAgentModelsIO()
{
    auto ioStart = LoadClock::now();

    const auto& mft = m_datManager->get_MFT();

    HANDLE datHandle = m_datManager->open_dat_handle();
    if (datHandle == INVALID_HANDLE_VALUE || datHandle == nullptr) {
        m_bgLoadDone.store(true);
        return;
    }

    // Load persistent animation discovery cache
    {
        auto cachePath = GW::Cache::AnimationDiscoveryCache::GetDefaultCachePath();
        auto datPath = m_datManager->get_filepath();
        uintmax_t datSize = 0;
        try { datSize = std::filesystem::file_size(datPath); } catch (...) {}
        m_animDiscoveryCache.SetDatIdentity(datPath, datSize);
        m_animDiscoveryCache.LoadFromFile(cachePath, datPath, datSize);
    }

    struct FoundClipInfo {
        GW::Animation::AnimationClip clip;
        uint32_t sourceFileHash;
    };

    // Per-model geometry needed for bone extraction in Phase C
    struct GeoModelInfo {
        std::vector<uint8_t> extra_data;
        uint32_t u0 = 0, u1 = 0;
        std::vector<std::pair<bool, uint32_t>> vertexGroups;
    };

    struct ModelWorkItem {
        uint32_t fileHash = 0;
        int mftIndex = -1;
        AgentModelInstance tmpl;
        std::vector<FoundClipInfo> foundClips;
        std::vector<GeoModelInfo> geoModels;
        bool needsMftScan = false;
        bool valid = false;
    };

    std::vector<ModelWorkItem> workItems;
    workItems.reserve(m_agentModelCreateOrder.size());

    // ====== Phase A: Parse models, try cache + embedded + references ======
    m_bgLoadSubPhase.store(static_cast<int>(AgentLoadSubPhase::ParsingModel));

    for (uint32_t fileHash : m_agentModelCreateOrder)
    {
        ModelWorkItem wi;
        wi.fileHash = fileHash;

        auto hashIt = m_hashIndex->find(static_cast<int>(fileHash));
        if (hashIt == m_hashIndex->end() || hashIt->second.empty()) {
            workItems.push_back(std::move(wi));
            m_bgLoadProgress.fetch_add(1);
            continue;
        }

        int mftIndex = hashIt->second.at(0);
        wi.mftIndex = mftIndex;
        if (mftIndex < 0 || mftIndex >= (int)mft.size() || mft[mftIndex].type != FFNA_Type2) {
            workItems.push_back(std::move(wi));
            m_bgLoadProgress.fetch_add(1);
            continue;
        }

        bool isOtherFormat = m_datManager->is_other_model_format(mftIndex);
        FFNA_ModelFile modelFile;
        FFNA_ModelFile_Other modelFileOther;

        try {
            if (isOtherFormat)
                modelFileOther = m_datManager->parse_ffna_model_file_other(mftIndex);
            else
                modelFile = m_datManager->parse_ffna_model_file(mftIndex);
        } catch (...) {
            workItems.push_back(std::move(wi));
            m_bgLoadProgress.fetch_add(1);
            continue;
        }

        if (isOtherFormat && !modelFileOther.parsed_correctly) {
            workItems.push_back(std::move(wi));
            m_bgLoadProgress.fetch_add(1);
            continue;
        }
        if (!isOtherFormat && !modelFile.parsed_correctly) {
            workItems.push_back(std::move(wi));
            m_bgLoadProgress.fetch_add(1);
            continue;
        }

        const auto& geoModelsRef = isOtherFormat
            ? modelFileOther.geometry_chunk.models
            : modelFile.geometry_chunk.models;
        const size_t numModels = geoModelsRef.size();

        std::vector<Mesh> propMeshes;
        for (size_t j = 0; j < numModels; j++) {
            AMAT_file amat;
            if (!isOtherFormat && !modelFile.AMAT_filenames_chunk.texture_filenames.empty()) {
                const auto& geom = modelFile.geometry_chunk;
                int subIdx = geom.models[j].unknown;
                if (!geom.tex_and_vertex_shader_struct.uts0.empty())
                    subIdx %= (int)geom.tex_and_vertex_shader_struct.uts0.size();
                const auto& uts1 = geom.uts1[subIdx % geom.uts1.size()];
                int amatIdx = ((uts1.some_flags0 >> 8) & 0xFF)
                    % (int)modelFile.AMAT_filenames_chunk.texture_filenames.size();
                auto amatFn = modelFile.AMAT_filenames_chunk.texture_filenames[amatIdx];
                auto amatHash = decode_filename(amatFn.id0, amatFn.id1);
                auto aIt = m_hashIndex->find(amatHash);
                if (aIt != m_hashIndex->end())
                    amat = m_datManager->parse_amat_file(aIt->second.at(0));
            }
            Mesh mesh = isOtherFormat
                ? modelFileOther.GetMesh((int)j, amat)
                : modelFile.GetMesh((int)j, amat);
            if (mesh.indices.size() % 3 == 0 && !mesh.indices.empty())
                propMeshes.push_back(mesh);
        }
        if (propMeshes.empty()) {
            workItems.push_back(std::move(wi));
            m_bgLoadProgress.fetch_add(1);
            continue;
        }

        // Extract geometry bone data for Phase C (before modelFile goes out of scope)
        for (size_t si = 0; si < geoModelsRef.size() && si < propMeshes.size(); si++) {
            GeoModelInfo gmi;
            gmi.extra_data = geoModelsRef[si].extra_data;
            gmi.u0 = geoModelsRef[si].u0;
            gmi.u1 = geoModelsRef[si].u1;
            gmi.vertexGroups.reserve(geoModelsRef[si].vertices.size());
            for (const auto& mv : geoModelsRef[si].vertices)
                gmi.vertexGroups.push_back({ mv.has_group, mv.group });
            wi.geoModels.push_back(std::move(gmi));
        }

        // Textures
        const bool texOk = isOtherFormat
            ? modelFileOther.textures_parsed_correctly
            : modelFile.textures_parsed_correctly;
        std::vector<int> texFileHashes;
        if (texOk) {
            if (isOtherFormat) {
                for (const auto& tf : modelFileOther.texture_filenames_chunk.texture_filenames)
                    texFileHashes.push_back(decode_filename(tf.id0, tf.id1));
            } else {
                for (const auto& tf : modelFile.texture_filenames_chunk.texture_filenames)
                    texFileHashes.push_back(decode_filename(tf.id0, tf.id1));
            }
        }
        std::vector<ParsedTextureEntry> parsedTextures;
        for (int decoded : texFileHashes) {
            ParsedTextureEntry pt;
            pt.decodedHash = decoded;
            auto mit = m_hashIndex->find(decoded);
            if (mit != m_hashIndex->end()) {
                try {
                    pt.datTex = m_datManager->parse_ffna_texture_file(mit->second.at(0));
                    pt.hasDatTex = (pt.datTex.width > 0 && pt.datTex.height > 0);
                } catch (...) {}
            }
            parsedTextures.push_back(std::move(pt));
        }

        const bool hasNewTexStuff = isOtherFormat
            ? !modelFileOther.geometry_chunk.unknown_tex_stuff1.empty()
            : !modelFile.geometry_chunk.unknown_tex_stuff1.empty();

        // Bounding box
        float bbMinX = FLT_MAX, bbMinY = FLT_MAX, bbMinZ = FLT_MAX;
        float bbMaxX = -FLT_MAX, bbMaxY = -FLT_MAX, bbMaxZ = -FLT_MAX;
        for (const auto& mesh : propMeshes) {
            for (const auto& v : mesh.vertices) {
                bbMinX = std::min(bbMinX, v.position.x);
                bbMinY = std::min(bbMinY, v.position.y);
                bbMinZ = std::min(bbMinZ, v.position.z);
                bbMaxX = std::max(bbMaxX, v.position.x);
                bbMaxY = std::max(bbMaxY, v.position.y);
                bbMaxZ = std::max(bbMaxZ, v.position.z);
            }
        }

        wi.tmpl.nativeHeight = bbMaxY - bbMinY;
        wi.tmpl.nativeMinY = bbMinY;
        wi.tmpl.nativeCenter = { (bbMinX + bbMaxX) * 0.5f, (bbMinY + bbMaxY) * 0.5f, (bbMinZ + bbMaxZ) * 0.5f };
        wi.tmpl.originalMeshes = propMeshes;
        wi.tmpl.parsedTextures_ = std::move(parsedTextures);
        wi.tmpl.pixelShaderType = hasNewTexStuff ? PixelShaderType::NewModel : PixelShaderType::OldModel;
        wi.tmpl.texturesOk = texOk;
        if (isOtherFormat) {
            wi.tmpl.modelHash0 = modelFileOther.geometry_chunk.header.model_hash0;
            wi.tmpl.modelHash1 = modelFileOther.geometry_chunk.header.model_hash1;
        } else {
            wi.tmpl.modelHash0 = modelFile.geometry_chunk.sub_1.f0xC;
            wi.tmpl.modelHash1 = modelFile.geometry_chunk.sub_1.f0x10;
        }
        wi.valid = true;

        // Try animation cache
        const auto* cachedAnimInfo = m_animDiscoveryCache.GetModel(fileHash);
        bool usedCache = false;
        if (cachedAnimInfo && !cachedAnimInfo->animSources.empty() &&
            cachedAnimInfo->modelHash0 == wi.tmpl.modelHash0 &&
            cachedAnimInfo->modelHash1 == wi.tmpl.modelHash1)
        {
            for (const auto& src : cachedAnimInfo->animSources) {
                if (src.mftIndex < 0 || src.mftIndex >= (int)mft.size()) continue;
                try {
                    uint8_t* data = m_datManager->read_file(src.mftIndex, datHandle);
                    if (!data) continue;
                    size_t dataSize = mft[src.mftIndex].uncompressedSize;
                    auto clip = GW::Parsers::ParseAnimationFromFile(data, dataSize);
                    delete[] data;
                    if (clip && clip->IsValid())
                        wi.foundClips.push_back({ std::move(*clip), src.fileHash });
                } catch (...) {}
            }
            usedCache = !wi.foundClips.empty();
        }

        // Try embedded + references if cache missed
        if (!usedCache) {
            try {
                uint8_t* rawData = m_datManager->read_file(mftIndex, datHandle);
                if (rawData) {
                    size_t rawSize = mft[mftIndex].uncompressedSize;
                    auto clipOpt = GW::Parsers::ParseAnimationFromFile(rawData, rawSize);
                    if (clipOpt && clipOpt->IsValid())
                        wi.foundClips.push_back({ std::move(*clipOpt), fileHash });

                    std::vector<uint32_t> animFileIds;
                    size_t scanOffset = 5;
                    while (scanOffset + 8 <= rawSize) {
                        uint32_t chunkId, chunkSize;
                        std::memcpy(&chunkId, &rawData[scanOffset], sizeof(uint32_t));
                        std::memcpy(&chunkSize, &rawData[scanOffset + 4], sizeof(uint32_t));
                        if (chunkId == 0 || chunkSize == 0 || scanOffset + 8 + chunkSize > rawSize) break;
                        const uint8_t* chunkData = &rawData[scanOffset + 8];
                        bool isAnimRef = (chunkId == GW::Parsers::CHUNK_ID_BBD ||
                                          chunkId == GW::Parsers::CHUNK_ID_FA8);
                        if (isAnimRef && chunkSize >= 4) {
                            uint32_t count;
                            size_t entryOffset;
                            if (chunkId == GW::Parsers::CHUNK_ID_FA8) {
                                std::memcpy(&count, &chunkData[0], sizeof(uint32_t));
                                entryOffset = 4;
                            } else {
                                if (chunkSize < 8) { scanOffset += 8 + chunkSize; continue; }
                                std::memcpy(&count, &chunkData[4], sizeof(uint32_t));
                                entryOffset = 8;
                            }
                            size_t maxEntries = (chunkSize - entryOffset) / 6;
                            if (count > maxEntries) count = static_cast<uint32_t>(maxEntries);
                            for (uint32_t i = 0; i < count; i++) {
                                if (entryOffset + 6 > chunkSize) break;
                                uint16_t id0, id1;
                                std::memcpy(&id0, &chunkData[entryOffset], sizeof(uint16_t));
                                std::memcpy(&id1, &chunkData[entryOffset + 2], sizeof(uint16_t));
                                entryOffset += 6;
                                int32_t fid = static_cast<int32_t>(id0) - 0xFF00FF;
                                fid += static_cast<int32_t>(id1) * 0xFF00;
                                animFileIds.push_back(static_cast<uint32_t>(fid));
                            }
                        }
                        scanOffset += 8 + chunkSize;
                    }

                    for (uint32_t animFileId : animFileIds) {
                        auto refIt = m_hashIndex->find(static_cast<int>(animFileId));
                        if (refIt == m_hashIndex->end() || refIt->second.empty()) continue;
                        int refMftIdx = refIt->second.at(0);
                        if (refMftIdx < 0 || refMftIdx >= (int)mft.size()) continue;
                        uint8_t* refData = m_datManager->read_file(refMftIdx, datHandle);
                        if (!refData) continue;
                        size_t refSize = mft[refMftIdx].uncompressedSize;
                        auto refClip = GW::Parsers::ParseAnimationFromFile(refData, refSize);
                        delete[] refData;
                        if (refClip && refClip->IsValid())
                            wi.foundClips.push_back({ std::move(*refClip), animFileId });
                    }

                    delete[] rawData;
                }
            } catch (...) {}

            if (wi.foundClips.empty() && wi.tmpl.modelHash0 != 0)
                wi.needsMftScan = true;
        }

        workItems.push_back(std::move(wi));
        m_bgLoadProgress.fetch_add(1);
    }

    // ====== Phase B: Single MFT scan for ALL models needing discovery ======
    // Build lookup: (modelHash0, modelHash1) → work item indices
    std::unordered_map<uint64_t, std::vector<size_t>> hashToWorkIndices;
    std::unordered_set<int> skipMftIndices;

    for (size_t idx = 0; idx < workItems.size(); idx++) {
        if (!workItems[idx].needsMftScan) continue;
        uint64_t key = (uint64_t(workItems[idx].tmpl.modelHash0) << 32) | workItems[idx].tmpl.modelHash1;
        hashToWorkIndices[key].push_back(idx);
        skipMftIndices.insert(workItems[idx].mftIndex);
    }

    if (!hashToWorkIndices.empty()) {
        m_bgLoadSubPhase.store(static_cast<int>(AgentLoadSubPhase::ScanningMFT));
        OutputDebugStringA(std::format("[ReplayLoad] MFT scan: {} models need discovery\n",
                                       hashToWorkIndices.size()).c_str());

        for (size_t mi = 0; mi < mft.size(); mi++) {
            if (mft[mi].type != FFNA_Type2) continue;
            if (mft[mi].uncompressedSize < 5 + 8 + 44) continue;
            if (skipMftIndices.count(static_cast<int>(mi))) continue;

            uint8_t* scanData = m_datManager->read_file(static_cast<int>(mi), datHandle);
            if (!scanData) continue;
            size_t scanSize = mft[mi].uncompressedSize;

            if (scanSize < 5 || scanData[0] != 'f' || scanData[1] != 'f' ||
                scanData[2] != 'n' || scanData[3] != 'a') {
                delete[] scanData;
                continue;
            }

            // Extract all BB9/FA1 hash pairs and check against needed models
            bool anyMatch = false;
            size_t off = 5;
            while (off + 8 <= scanSize) {
                uint32_t cid, csz;
                std::memcpy(&cid, &scanData[off], sizeof(uint32_t));
                std::memcpy(&csz, &scanData[off + 4], sizeof(uint32_t));
                if (cid == 0 || csz == 0 || off + 8 + csz > scanSize) break;
                size_t cDataOff = off + 8;

                uint32_t h0 = 0, h1 = 0;
                bool gotHash = false;
                if (cid == GW::Parsers::CHUNK_ID_BB9 &&
                    cDataOff + sizeof(GW::Parsers::BB9Header) <= scanSize) {
                    GW::Parsers::BB9Header hdr;
                    std::memcpy(&hdr, &scanData[cDataOff], sizeof(hdr));
                    h0 = hdr.modelHash0;
                    h1 = hdr.modelHash1;
                    gotHash = true;
                } else if (cid == GW::Parsers::CHUNK_ID_FA1 &&
                           cDataOff + sizeof(GW::Parsers::FA1Header) <= scanSize) {
                    GW::Parsers::FA1Header hdr;
                    std::memcpy(&hdr, &scanData[cDataOff], sizeof(hdr));
                    h0 = hdr.boundingBoxId;
                    h1 = hdr.collisionMeshId;
                    gotHash = true;
                }

                if (gotHash) {
                    uint64_t key = (uint64_t(h0) << 32) | h1;
                    auto it = hashToWorkIndices.find(key);
                    if (it != hashToWorkIndices.end()) {
                        anyMatch = true;
                        break;
                    }
                }
                off += 8 + csz;
            }

            if (anyMatch) {
                auto scanClip = GW::Parsers::ParseAnimationFromFile(scanData, scanSize);
                if (scanClip && scanClip->IsValid()) {
                    uint32_t fHash = static_cast<uint32_t>(mft[mi].Hash);
                    off = 5;
                    while (off + 8 <= scanSize) {
                        uint32_t cid, csz;
                        std::memcpy(&cid, &scanData[off], sizeof(uint32_t));
                        std::memcpy(&csz, &scanData[off + 4], sizeof(uint32_t));
                        if (cid == 0 || csz == 0 || off + 8 + csz > scanSize) break;
                        size_t cDataOff = off + 8;

                        uint32_t h0 = 0, h1 = 0;
                        bool gotHash = false;
                        if (cid == GW::Parsers::CHUNK_ID_BB9 &&
                            cDataOff + sizeof(GW::Parsers::BB9Header) <= scanSize) {
                            GW::Parsers::BB9Header hdr;
                            std::memcpy(&hdr, &scanData[cDataOff], sizeof(hdr));
                            h0 = hdr.modelHash0; h1 = hdr.modelHash1; gotHash = true;
                        } else if (cid == GW::Parsers::CHUNK_ID_FA1 &&
                                   cDataOff + sizeof(GW::Parsers::FA1Header) <= scanSize) {
                            GW::Parsers::FA1Header hdr;
                            std::memcpy(&hdr, &scanData[cDataOff], sizeof(hdr));
                            h0 = hdr.boundingBoxId; h1 = hdr.collisionMeshId; gotHash = true;
                        }
                        if (gotHash) {
                            uint64_t key = (uint64_t(h0) << 32) | h1;
                            auto it = hashToWorkIndices.find(key);
                            if (it != hashToWorkIndices.end()) {
                                for (size_t wiIdx : it->second)
                                    workItems[wiIdx].foundClips.push_back({ *scanClip, fHash });
                            }
                        }
                        off += 8 + csz;
                    }
                }
            }
            delete[] scanData;
        }
    }

    // ====== Phase C: Build animation data + finalize templates ======
    m_bgLoadSubPhase.store(static_cast<int>(AgentLoadSubPhase::BuildingAnimData));

    for (auto& wi : workItems) {
        if (!wi.valid) {
            m_agentModelTemplates[wi.fileHash] = std::move(wi.tmpl);
            continue;
        }

        // Update discovery cache for models that did fresh discovery
        if (wi.needsMftScan && !wi.foundClips.empty()) {
            GW::Cache::CachedModelAnimInfo cacheEntry;
            cacheEntry.modelHash0 = wi.tmpl.modelHash0;
            cacheEntry.modelHash1 = wi.tmpl.modelHash1;
            for (const auto& fc : wi.foundClips) {
                GW::Cache::AnimSourceEntry src;
                src.fileHash = fc.sourceFileHash;
                auto srcIt = m_hashIndex->find(static_cast<int>(fc.sourceFileHash));
                if (srcIt != m_hashIndex->end() && !srcIt->second.empty())
                    src.mftIndex = srcIt->second.at(0);
                else
                    src.mftIndex = wi.mftIndex;
                cacheEntry.animSources.push_back(src);
            }
            m_animDiscoveryCache.SetModel(wi.fileHash, std::move(cacheEntry));
        }
        // Also cache models resolved via embedded/refs (not from cache hit, not needing MFT scan)
        if (!wi.needsMftScan && !wi.foundClips.empty()) {
            const auto* existing = m_animDiscoveryCache.GetModel(wi.fileHash);
            if (!existing) {
                GW::Cache::CachedModelAnimInfo cacheEntry;
                cacheEntry.modelHash0 = wi.tmpl.modelHash0;
                cacheEntry.modelHash1 = wi.tmpl.modelHash1;
                for (const auto& fc : wi.foundClips) {
                    GW::Cache::AnimSourceEntry src;
                    src.fileHash = fc.sourceFileHash;
                    auto srcIt = m_hashIndex->find(static_cast<int>(fc.sourceFileHash));
                    if (srcIt != m_hashIndex->end() && !srcIt->second.empty())
                        src.mftIndex = srcIt->second.at(0);
                    else
                        src.mftIndex = wi.mftIndex;
                    cacheEntry.animSources.push_back(src);
                }
                m_animDiscoveryCache.SetModel(wi.fileHash, std::move(cacheEntry));
            }
        }

        if (!wi.foundClips.empty()) {
            for (size_t ci = 0; ci < wi.foundClips.size(); ci++) {
                AnimClipEntry entry;
                entry.clip = std::make_shared<GW::Animation::AnimationClip>(std::move(wi.foundClips[ci].clip));
                entry.clip->BuildAnimationGroups();
                entry.skeleton = std::make_shared<GW::Animation::Skeleton>(
                    GW::Parsers::BB9AnimationParser::CreateSkeleton(*entry.clip));
                entry.sourceFileHash = wi.foundClips[ci].sourceFileHash;
                wi.tmpl.allClips.push_back(std::move(entry));
            }
            wi.tmpl.clip = wi.tmpl.allClips[0].clip;
            wi.tmpl.skeleton = wi.tmpl.allClips[0].skeleton;

            for (size_t si = 0; si < wi.geoModels.size(); si++) {
                auto boneData = AnimationPanelState::ExtractBoneData(
                    wi.geoModels[si].extra_data, wi.geoModels[si].u0, wi.geoModels[si].u1);
                wi.tmpl.submeshBoneData.push_back(std::move(boneData));
                std::vector<uint32_t> vbg;
                vbg.reserve(wi.geoModels[si].vertexGroups.size());
                for (const auto& [hasGroup, group] : wi.geoModels[si].vertexGroups)
                    vbg.push_back(hasGroup ? group : 0);
                wi.tmpl.perVertexBoneGroups.push_back(std::move(vbg));
            }

            std::unordered_map<uint32_t, SegmentRef> segHashToRef;
            for (int ci = 0; ci < static_cast<int>(wi.tmpl.allClips.size()); ci++) {
                const auto& clipEntry = wi.tmpl.allClips[ci];
                for (size_t si = 0; si < clipEntry.clip->animationSegments.size(); si++) {
                    uint32_t segHash = clipEntry.clip->animationSegments[si].hash;
                    SegmentRef ref{ ci, static_cast<int>(si) };
                    if (!segHashToRef.count(segHash)) segHashToRef[segHash] = ref;
                    if (!wi.tmpl.animCodeToSegment.count(segHash)) wi.tmpl.animCodeToSegment[segHash] = ref;
                    auto& lookup = GW::Animation::AnimationHashLookup::Instance();
                    int stateIdx = lookup.GetStateIndex(segHash);
                    if (stateIdx >= 0 && stateIdx < (int)GW::Animation::g_animationStateCount) {
                        uint32_t primary = GW::Animation::g_animationStateTable[stateIdx].primaryHash;
                        if (!wi.tmpl.animCodeToSegment.count(primary))
                            wi.tmpl.animCodeToSegment[primary] = ref;
                    }
                    for (size_t bs = 0; bs < GW::Animation::g_boneSlotCount; bs++) {
                        uint32_t fallback = GW::Animation::ReverseSegmentHash(
                            segHash, GW::Animation::g_boneSlotChars[bs]);
                        if (fallback != 0 && !wi.tmpl.animCodeToSegment.count(fallback))
                            wi.tmpl.animCodeToSegment[fallback] = ref;
                    }
                }
            }
            for (size_t i = 0; i < GW::Animation::g_animationStateCount; i++) {
                uint32_t primary = GW::Animation::g_animationStateTable[i].primaryHash;
                if (wi.tmpl.animCodeToSegment.count(primary)) continue;
                for (size_t bs = 0; bs < GW::Animation::g_boneSlotCount; bs++) {
                    uint32_t candidate = GW::Animation::ComputeSegmentHash(
                        primary, GW::Animation::g_boneSlotChars[bs]);
                    auto it = segHashToRef.find(candidate);
                    if (it != segHashToRef.end()) {
                        wi.tmpl.animCodeToSegment[primary] = it->second;
                        break;
                    }
                }
            }
            wi.tmpl.hasAnimation = true;
        }

        m_agentModelTemplates[wi.fileHash] = std::move(wi.tmpl);
    }

    CloseHandle(datHandle);

    if (m_animDiscoveryCache.IsDirty()) {
        auto cachePath = GW::Cache::AnimationDiscoveryCache::GetDefaultCachePath();
        m_animDiscoveryCache.SaveToFile(cachePath);
    }

    m_loadTiming.agentIOSec = std::chrono::duration<double>(LoadClock::now() - ioStart).count();
    OutputDebugStringA(std::format("[ReplayLoad] AgentIO: {:.3f}s\n", m_loadTiming.agentIOSec).c_str());

    m_bgLoadDone.store(true);
}

// ---------------------------------------------------------------------------
// Main thread: create GPU resources in batches (called per frame)
// Uses the EXACT same texture creation → remap → AddProp flow as the
// working synchronous LoadAgentModels to avoid the color regression.
// ---------------------------------------------------------------------------

static constexpr int kAgentModelBatchSize = 2;

void ReplayWindow::StepCreateAgentModelResources()
{
    if (!m_bgLoadDone || m_agentModelsLoaded) return;

    auto* map_renderer = m_mapRenderer.get();
    if (!map_renderer) return;
    auto* device = m_deviceResources->GetD3DDevice();
    if (!device) return;

    auto frameStart = LoadClock::now();
    int processed = 0;
    while (m_agentModelCreateIndex < static_cast<int>(m_agentModelCreateOrder.size()))
    {
        uint32_t fileHash = m_agentModelCreateOrder[m_agentModelCreateIndex];
        m_agentModelCreateIndex++;
        processed++;

        auto tmplIt = m_agentModelTemplates.find(fileHash);
        if (tmplIt == m_agentModelTemplates.end()) continue;

        auto& tmpl = tmplIt->second;
        auto& propMeshes = tmpl.originalMeshes;
        if (propMeshes.empty()) continue;

        // ---- GPU texture creation (same flow as working LoadAgentModels) ----
        std::vector<int> textureIds;
        for (const auto& pt : tmpl.parsedTextures_) {
            int texId = map_renderer->GetTextureManager()->GetTextureIdByHash(pt.decodedHash);
            if (texId >= 0) { textureIds.push_back(texId); continue; }
            if (pt.hasDatTex) {
                map_renderer->GetTextureManager()->CreateTextureFromRGBA(
                    pt.datTex.width, pt.datTex.height, pt.datTex.rgba_data.data(), &texId, pt.decodedHash);
            }
            textureIds.push_back(texId);
        }

        // ---- Remap per-mesh texture indices (same flow as working code) ----
        std::vector<std::vector<int>> perMeshTexIds(propMeshes.size());
        for (size_t k = 0; k < propMeshes.size(); k++) {
            std::vector<uint8_t> remappedIndices;
            for (size_t ti = 0; ti < propMeshes[k].tex_indices.size(); ti++) {
                int idx = std::min((int)propMeshes[k].tex_indices[ti], (int)textureIds.size() - 1);
                if (idx >= 0 && idx < (int)textureIds.size()) {
                    perMeshTexIds[k].push_back(textureIds[idx]);
                    remappedIndices.push_back((uint8_t)ti);
                }
            }
            propMeshes[k].tex_indices = remappedIndices;
        }

        // ---- Build template PerObjectCBs (after tex_indices remapping) ----
        std::vector<PerObjectCB> templateCBs(propMeshes.size());
        for (size_t j = 0; j < propMeshes.size(); j++) {
            XMStoreFloat4x4(&templateCBs[j].world, XMMatrixIdentity());
            auto& mesh = propMeshes[j];
            if (mesh.uv_coord_indices.size() == mesh.tex_indices.size() &&
                mesh.uv_coord_indices.size() < MAX_NUM_TEX_INDICES && tmpl.texturesOk) {
                templateCBs[j].num_uv_texture_pairs = (uint32_t)mesh.uv_coord_indices.size();
                for (size_t k = 0; k < mesh.uv_coord_indices.size(); k++) {
                    templateCBs[j].uv_indices[k / 4][k % 4] = (uint32_t)mesh.uv_coord_indices[k];
                    templateCBs[j].texture_indices[k / 4][k % 4] = (uint32_t)mesh.tex_indices[k];
                    templateCBs[j].blend_flags[k / 4][k % 4] = (uint32_t)mesh.blend_flags[k];
                    templateCBs[j].texture_types[k / 4][k % 4] = (uint32_t)mesh.texture_types[k];
                }
            }
        }
        tmpl.templateCBs = templateCBs;

        // ---- Create props and skinned meshes per agent ----
        for (auto& [agentId, cachedHash] : m_agentFileHashCache)
        {
            if (cachedHash != fileHash) continue;

            std::vector<PerObjectCB> agentCBs = templateCBs;
            auto meshIds = map_renderer->AddProp(propMeshes, agentCBs, 0x80000000u | (uint32_t)agentId, tmpl.pixelShaderType);

            if (tmpl.texturesOk) {
                for (size_t l = 0; l < meshIds.size() && l < perMeshTexIds.size(); l++) {
                    map_renderer->GetMeshManager()->SetTexturesForMesh(
                        meshIds[l], map_renderer->GetTextureManager()->GetTextures(perMeshTexIds[l]), 3);
                }
            }

            for (int mid : meshIds)
                map_renderer->GetMeshManager()->SetMeshShouldRender(mid, false);

            m_agentMeshIds[agentId] = meshIds;

            if (tmpl.hasAnimation && tmpl.clip && device) {
                AgentAnimState animState;
                auto hierarchyMode = tmpl.clip->hierarchyMode;
                size_t boneCount = tmpl.clip->boneTracks.size();

                for (size_t si = 0; si < tmpl.originalMeshes.size(); si++) {
                    const auto& mesh = tmpl.originalMeshes[si];
                    const auto& boneData = (si < tmpl.submeshBoneData.size())
                        ? tmpl.submeshBoneData[si]
                        : AnimationPanelState::SubmeshBoneData();
                    const auto& vbg = (si < tmpl.perVertexBoneGroups.size())
                        ? tmpl.perVertexBoneGroups[si]
                        : std::vector<uint32_t>();

                    auto skinnedVerts = AnimationPanelState::CreateSkinnedVertices(
                        mesh, boneData, vbg, boneCount, hierarchyMode, si);

                    auto animMesh = std::make_shared<AnimatedMeshInstance>(
                        device, skinnedVerts, mesh.indices, static_cast<int>(si));
                    animState.animMeshes.push_back(std::move(animMesh));
                }

                animState.perMeshCBs = templateCBs;
                animState.perMeshTextureIds = perMeshTexIds;
                animState.pixelShaderType = tmpl.pixelShaderType;

                animState.controller = std::make_unique<GW::Animation::AnimationController>();
                animState.controller->Initialize(tmpl.clip);
                animState.controller->SetPlaybackMode(GW::Animation::PlaybackMode::SegmentLoop);
                animState.controller->SetLooping(true);
                if (!tmpl.clip->animationSegments.empty())
                    animState.controller->SetSegment(0);
                animState.controller->Play();

                animState.hasSkinning = !animState.animMeshes.empty();
                m_agentAnimStates[agentId] = std::move(animState);
            }
        }

        tmpl.parsedTextures_.clear();
        tmpl.parsedTextures_.shrink_to_fit();

        if (processed >= kAgentModelBatchSize) {
            auto elapsed = std::chrono::duration<float, std::milli>(LoadClock::now() - frameStart).count();
            if (elapsed > kLoadFrameBudgetMs)
                break;
        }
    }

    if (m_agentModelCreateIndex >= static_cast<int>(m_agentModelCreateOrder.size())) {
        m_loadTiming.agentGPUSec += std::chrono::duration<double>(LoadClock::now() - m_phaseStartTime).count();
        OutputDebugStringA(std::format("[ReplayLoad] AgentGPU: {:.3f}s\n", m_loadTiming.agentGPUSec).c_str());

        m_agentModelsLoaded = true;
        m_agentModelsLoading = false;
    }
}

// Keep synchronous LoadAgentModels as fallback (calls async + blocks)
void ReplayWindow::LoadAgentModels()
{
    if (m_agentModelsLoaded) return;
    if (!m_agentsClassified || m_replayCtx.agents.empty()) return;
    if (!m_datManager || !m_hashIndex) return;

    auto* map_renderer = m_mapRenderer.get();
    if (!map_renderer) return;

    LoadAgentModelsAsync();

    // Block until IO is done, then create all resources at once
    if (m_agentModelLoadThread.joinable())
        m_agentModelLoadThread.join();

    while (!m_agentModelsLoaded)
        StepCreateAgentModelResources();
}

// ---------------------------------------------------------------------------
// Per-frame: update agent model world transforms and visibility
// ---------------------------------------------------------------------------

void ReplayWindow::DrawAgentModels()
{
    if (!m_useAgentModels) return;
    if (!m_showAgentOverlay) return;
    if (!m_agentsClassified || m_replayCtx.agents.empty()) return;

    auto* meshMgr = m_mapRenderer->GetMeshManager();
    if (!meshMgr) return;

    auto* context = m_deviceResources->GetD3DDeviceContext();
    float frameDt = static_cast<float>(m_timer.GetElapsedSeconds());

    const MapTransform& mt = m_replayCtx.mapTransform;
    const InterpolationSettings& is = m_replayCtx.interpSettings;
    Terrain* terrain = m_mapRenderer->GetTerrain();

    Camera* cam = m_mapRenderer->GetCamera();
    XMFLOAT3 camP = cam->GetPosition3f();
    const bool lodOn = m_uiLayout.lodEnabled;
    const float lodDot = m_uiLayout.lodDotDist;

    bool hasBounds = (terrain != nullptr);
    float bMinX = 0, bMaxX = 0, bMinZ = 0, bMaxZ = 0;
    if (hasBounds) {
        bMinX = terrain->m_bounds.map_min_x;
        bMaxX = terrain->m_bounds.map_max_x;
        bMinZ = terrain->m_bounds.map_min_z;
        bMaxZ = terrain->m_bounds.map_max_z;
    }

    for (auto& [agentId, meshIds] : m_agentMeshIds)
    {
        auto agentIt = m_replayCtx.agents.find(agentId);
        if (agentIt == m_replayCtx.agents.end()) {
            for (int mid : meshIds) meshMgr->SetMeshShouldRender(mid, false);
            m_agentModelRenderStatus[agentId] = std::format("hidden: not in agents (meshes={})", meshIds.size());
            continue;
        }

        auto& ard = agentIt->second;
        if (ard.snapshots.empty()) {
            for (int mid : meshIds) meshMgr->SetMeshShouldRender(mid, false);
            m_agentModelRenderStatus[agentId] = "hidden: no snapshots";
            continue;
        }

        // Spirits: only visible within their snapshot time range
        if (ard.type == AgentType::Spirit) {
            if (m_debugTimeline < ard.snapshots.front().time ||
                m_debugTimeline > ard.snapshots.back().time ||
                ard.overlapHidden ||
                ard.isDeadAtTime(m_debugTimeline) ||
                !ard.isAliveAtTime(m_debugTimeline)) {
                for (int mid : meshIds) meshMgr->SetMeshShouldRender(mid, false);
                m_agentModelRenderStatus[agentId] = "hidden: spirit not active";
                continue;
            }
        }

        // Dead state: keep rendering with fade (don't hide)
        bool dead = (ard.type == AgentType::NPC || ard.type == AgentType::Player)
                     && ard.isDeadAtTime(m_debugTimeline);

        float deadAlpha = 1.0f;
        if (dead) {
            float deathTime = ard.deathTransitionTime(m_debugTimeline);
            float fadeIn = std::clamp((m_debugTimeline - deathTime) / 0.5f, 0.f, 1.f);
            fadeIn = fadeIn * fadeIn * (3.f - 2.f * fadeIn);
            deadAlpha = 1.0f - 0.3f * fadeIn;
        }

        // Fog check
        bool inFog = (m_fogPerspective > 0 && ard.teamId != m_fogPerspective && IsAgentInFog(agentId));
        if (inFog && !m_fogGhostMode) {
            for (int mid : meshIds) meshMgr->SetMeshShouldRender(mid, false);
            m_agentModelRenderStatus[agentId] = "hidden: fog";
            continue;
        }

        // Get interpolated position — use agent's own height (includes plane elevation)
        float sx, sy, sz;
        InterpolateAgentPosition(ard, m_debugTimeline, is, sx, sy, sz);
        XMFLOAT3 pos = ApplyMapTransformToPos(sx, sy, sz, mt);

        if (hasBounds) {
            pos.x = std::clamp(pos.x, bMinX, bMaxX);
            pos.z = std::clamp(pos.z, bMinZ, bMaxZ);
        }

        // LOD: beyond lodDotDist → hide 3D model, show stylized icon instead
        if (lodOn) {
            float dx = pos.x - camP.x, dy = pos.y - camP.y, dz = pos.z - camP.z;
            float dist = sqrtf(dx * dx + dy * dy + dz * dz);
            if (dist > lodDot) {
                for (int mid : meshIds) meshMgr->SetMeshShouldRender(mid, false);
                ard.currentLOD = 0;
                m_agentModelRenderStatus[agentId] = std::format("hidden: LOD icon (dist={:.0f})", dist);
                continue;
            }
        }
        ard.currentLOD = 2;

        // Get rotation from nearest snapshot
        int snapIdx = FindSnapshotIndex(ard.snapshots, m_debugTimeline);
        float rotRad = ard.snapshots[snapIdx].rotation;

        // Scale: FFNA models are already in game units; only apply the GW NPC adjustment
        auto hashIt = m_agentFileHashCache.find(agentId);
        uint32_t cachedHash = (hashIt != m_agentFileHashCache.end()) ? hashIt->second : 0;
        auto tmplIt = m_agentModelTemplates.find(cachedHash);

        AgentModelInfo info = LookupAgentModelInfo(ard.type, ard.modelId,
                                                     ard.primaryProf, ard.isFemale);
        float scale = info.npcAdjustment * m_agentModelScale;
        XMMATRIX centering = XMMatrixIdentity();

        if (tmplIt != m_agentModelTemplates.end()) {
            const auto& tmpl = tmplIt->second;
            centering = XMMatrixTranslation(
                -tmpl.nativeCenter.x, -tmpl.nativeMinY, -tmpl.nativeCenter.z);
        }

        XMMATRIX worldMat = centering
            * XMMatrixRotationY(XM_PIDIV2)
            * XMMatrixScaling(scale, scale, scale)
            * XMMatrixRotationY(-rotRad)
            * XMMatrixTranslation(pos.x, pos.y, pos.z);

        // Decide skinned vs. rigid rendering
        auto animIt = m_agentAnimStates.find(agentId);
        bool useSkinned = (animIt != m_agentAnimStates.end() && animIt->second.hasSkinning);

        if (useSkinned) {
            // Hide the rigid props — skinned draw will handle this agent
            for (int mid : meshIds)
                meshMgr->SetMeshShouldRender(mid, false);

            auto& animState = animIt->second;

            // Compute velocity from interpolated position deltas (game coordinates)
            float moveDx = 0.f, moveDy = 0.f;
            float frameVelocity = 0.f;
            {
                float dt = m_debugTimeline - animState.prevTime;
                if (animState.prevTime >= 0.f && dt > 0.001f && dt < 1.0f) {
                    moveDx = sx - animState.prevPosX;
                    moveDy = sy - animState.prevPosY;
                    frameVelocity = std::sqrtf(moveDx * moveDx + moveDy * moveDy) / dt;
                }
                constexpr float kSmoothAlpha = 0.3f;
                animState.smoothVelocity = kSmoothAlpha * frameVelocity
                                         + (1.f - kSmoothAlpha) * animState.smoothVelocity;
                animState.prevPosX = sx;
                animState.prevPosY = sy;
                animState.prevTime = m_debugTimeline;
            }

            // Drive animation from gameplay state
            auto& ctrl = animState.controller;
            const auto& snap = ard.snapshots[snapIdx];

            if (tmplIt != m_agentModelTemplates.end() && ctrl) {
                uint32_t animCode = snap.animation_code;
                if (animCode != animState.lastAnimCode && animCode != 0) {
                    auto& codeMap = tmplIt->second.animCodeToSegment;
                    bool resolved = false;
                    SegmentRef resolvedRef{};

                    // Strategy 1: direct lookup in pre-built map
                    auto segIt = codeMap.find(animCode);
                    if (segIt != codeMap.end()) {
                        resolvedRef = segIt->second;
                        resolved = true;
                    }

                    // Strategy 2: treat animCode as primaryHash, compute segment hash per bone slot
                    if (!resolved) {
                        for (size_t bs = 0; bs < GW::Animation::g_boneSlotCount; bs++) {
                            uint32_t candidate = GW::Animation::ComputeSegmentHash(
                                animCode, GW::Animation::g_boneSlotChars[bs]);
                            auto segIt2 = codeMap.find(candidate);
                            if (segIt2 != codeMap.end()) {
                                resolvedRef = segIt2->second;
                                codeMap[animCode] = resolvedRef;
                                resolved = true;
                                break;
                            }
                        }
                    }

                    // Strategy 3: reverse animCode, compute hash, match against all clip segments
                    if (!resolved) {
                        for (int ci = 0; ci < static_cast<int>(tmplIt->second.allClips.size()) && !resolved; ci++) {
                            const auto& segments = tmplIt->second.allClips[ci].clip->animationSegments;
                            for (size_t bsA = 0; bsA < GW::Animation::g_boneSlotCount && !resolved; bsA++) {
                                uint32_t animPrimary = GW::Animation::ReverseSegmentHash(
                                    animCode, GW::Animation::g_boneSlotChars[bsA]);
                                if (animPrimary == 0) continue;
                                for (size_t bsB = 0; bsB < GW::Animation::g_boneSlotCount && !resolved; bsB++) {
                                    uint32_t candidate = GW::Animation::ComputeSegmentHash(
                                        animPrimary, GW::Animation::g_boneSlotChars[bsB]);
                                    for (size_t si = 0; si < segments.size(); si++) {
                                        if (segments[si].hash == candidate) {
                                            resolvedRef = { ci, static_cast<int>(si) };
                                            codeMap[animCode] = resolvedRef;
                                            resolved = true;
                                            break;
                                        }
                                    }
                                }
                            }
                        }
                    }

                    // Strategy 4: reverse both animCode and segment hash, compare primaries
                    if (!resolved) {
                        for (int ci = 0; ci < static_cast<int>(tmplIt->second.allClips.size()) && !resolved; ci++) {
                            const auto& segments = tmplIt->second.allClips[ci].clip->animationSegments;
                            for (size_t si = 0; si < segments.size() && !resolved; si++) {
                                uint32_t segHash = segments[si].hash;
                                for (size_t bs = 0; bs < GW::Animation::g_boneSlotCount && !resolved; bs++) {
                                    uint32_t animPrimary = GW::Animation::ReverseSegmentHash(
                                        animCode, GW::Animation::g_boneSlotChars[bs]);
                                    uint32_t segPrimary = GW::Animation::ReverseSegmentHash(
                                        segHash, GW::Animation::g_boneSlotChars[bs]);
                                    if (animPrimary != 0 && animPrimary == segPrimary) {
                                        resolvedRef = { ci, static_cast<int>(si) };
                                        codeMap[animCode] = resolvedRef;
                                        resolved = true;
                                    }
                                }
                            }
                        }
                    }

                    if (resolved) {
                        if (resolvedRef.clipIndex != animState.currentClipIndex &&
                            resolvedRef.clipIndex >= 0 &&
                            resolvedRef.clipIndex < static_cast<int>(tmplIt->second.allClips.size())) {
                            const auto& newClip = tmplIt->second.allClips[resolvedRef.clipIndex].clip;
                            ctrl->Initialize(newClip);
                            ctrl->SetPlaybackMode(GW::Animation::PlaybackMode::SegmentLoop);
                            animState.currentClipIndex = resolvedRef.clipIndex;
                        }
                        animState.wasCasting = false;
                        bool stillKD = snap.is_knocked;
                        animState.postKdGetUp = animState.wasKnockedDown && !stillKD;
                        animState.wasKnockedDown = false;
                        ctrl->SetSegment(resolvedRef.segmentIndex);
                        bool playOnce = dead || (snap.is_casting && !stillKD) || animState.postKdGetUp;
                        ctrl->SetLooping(!playOnce);
                        ctrl->Play();
                    }

                    animState.lastLookupFailed = !resolved;
                    animState.lastAnimCode = animCode;
                    animState.isPlayingMovementAnim = false;
                    animState.isPlayingIdleAnim = false;
                }

                // Movement / idle animation when server sends no animation code
                constexpr float kMovingThreshold = 15.f;
                if (animCode == 0 && !dead && !snap.is_casting && !animState.wasCasting
                    && !animState.postKdGetUp && !ard.isKnockedDownAtTime(m_debugTimeline))
                {
                    bool isMoving = animState.smoothVelocity > kMovingThreshold;
                    auto& codeMap = tmplIt->second.animCodeToSegment;

                    if (isMoving) {
                        // Compute movement heading from position delta
                        float moveHeading = std::atan2(moveDx, moveDy);
                        float relAngle = moveHeading - rotRad;
                        // Normalize to [-PI, PI]
                        while (relAngle > XM_PI)  relAngle -= XM_2PI;
                        while (relAngle < -XM_PI) relAngle += XM_2PI;

                        // Quantize to 8 compass sectors (each 45 deg)
                        int dirIndex = (static_cast<int>(std::round(relAngle / (XM_PI / 4.f))) + 8) % 8;

                        if (dirIndex != animState.currentMovementDirIndex || !animState.isPlayingMovementAnim) {
                            // Use "Running" movement table (index 2)
                            constexpr int kRunningTableIdx = 2;
                            uint8_t stateIdx = GW::Animation::g_movementTables[kRunningTableIdx].indices[dirIndex];
                            if (stateIdx < GW::Animation::g_animationStateCount) {
                                uint32_t primaryHash = GW::Animation::g_animationStateTable[stateIdx].primaryHash;
                                auto segIt = codeMap.find(primaryHash);
                                if (segIt != codeMap.end()) {
                                    SegmentRef ref = segIt->second;
                                    if (ref.clipIndex != animState.currentClipIndex &&
                                        ref.clipIndex >= 0 &&
                                        ref.clipIndex < static_cast<int>(tmplIt->second.allClips.size())) {
                                        ctrl->Initialize(tmplIt->second.allClips[ref.clipIndex].clip);
                                        ctrl->SetPlaybackMode(GW::Animation::PlaybackMode::SegmentLoop);
                                        animState.currentClipIndex = ref.clipIndex;
                                    }
                                    ctrl->SetSegment(ref.segmentIndex);
                                    ctrl->SetLooping(true);
                                    ctrl->Play();
                                }
                            }
                            animState.currentMovementDirIndex = dirIndex;
                            animState.isPlayingMovementAnim = true;
                            animState.isPlayingIdleAnim = false;
                        }
                    } else if (!animState.isPlayingIdleAnim) {
                        // Switch to idle when stopped
                        constexpr uint32_t kIdlePrimaryHash = 0x365C0E24u;
                        auto segIt = codeMap.find(kIdlePrimaryHash);
                        if (segIt != codeMap.end()) {
                            SegmentRef ref = segIt->second;
                            if (ref.clipIndex != animState.currentClipIndex &&
                                ref.clipIndex >= 0 &&
                                ref.clipIndex < static_cast<int>(tmplIt->second.allClips.size())) {
                                ctrl->Initialize(tmplIt->second.allClips[ref.clipIndex].clip);
                                ctrl->SetPlaybackMode(GW::Animation::PlaybackMode::SegmentLoop);
                                animState.currentClipIndex = ref.clipIndex;
                            }
                            ctrl->SetSegment(ref.segmentIndex);
                            ctrl->SetLooping(true);
                            ctrl->Play();
                        }
                        animState.isPlayingIdleAnim = true;
                        animState.isPlayingMovementAnim = false;
                        animState.currentMovementDirIndex = -1;
                    }
                }

                // Detect resurrection
                if (!dead && animState.wasDead)
                    ctrl->Play();
                animState.wasDead = dead;

                // Track casting/KD state
                bool isKD = ard.isKnockedDownAtTime(m_debugTimeline);
                if (snap.is_casting)
                    animState.wasCasting = true;
                if (snap.is_knocked) {
                    animState.wasKnockedDown = true;
                    animState.wasCasting = false;
                }

                // Update looping dynamically
                bool playOnce = dead || isKD || (snap.is_casting && !isKD) || (animState.wasCasting && !isKD) || animState.postKdGetUp;
                ctrl->SetLooping(!playOnce);

                // Playback speed — use the game's animation_speed when available.
                // NPC/hero agents always have animation_speed > 0 in snapshot data.
                // Player agents have animation_speed = 0 (sparse observer data),
                // so we fall back to duration-based or velocity-based formulas.
                float speedMult = 1.0f;
                if (dead) {
                    speedMult = 0.8f;
                } else if (snap.is_casting && ctrl) {
                    const CastInterval* ci = ard.castIntervalAtTime(m_debugTimeline);
                    if (ci) {
                        float castDur = ci->end - ci->start;
                        float segStart = ctrl->GetSequenceStartTime();
                        float segEnd   = ctrl->GetSequenceEndTime();
                        float segDurSec = (segEnd - segStart) / 100000.f;
                        if (castDur > 0.001f && segDurSec > 0.001f)
                            speedMult = segDurSec / castDur;
                    }
                } else if (snap.animation_speed > 0.f) {
                    speedMult = snap.animation_speed;
                    // Use timing-based formula for attack animations when weapon data
                    // is available.  This fits the segment to the real attack window,
                    // just like the casting formula above.
                    if (!animState.isPlayingMovementAnim && !animState.isPlayingIdleAnim
                        && snap.weapon_attack_speed > 0.f && snap.attack_speed_modifier > 0.f && ctrl) {
                        float effectiveAttackTime = snap.weapon_attack_speed * snap.attack_speed_modifier;
                        float segStart = ctrl->GetSequenceStartTime();
                        float segEnd   = ctrl->GetSequenceEndTime();
                        float segDurSec = (segEnd - segStart) / 100000.f;
                        if (effectiveAttackTime > 0.001f && segDurSec > 0.001f)
                            speedMult = segDurSec / effectiveAttackTime;
                    }
                    // The server sends a fixed animation_speed for running (typically
                    // 0.667) regardless of actual velocity.  When the character has a
                    // speed buff the legs need to move faster to match, just like the
                    // real game client does locally.  Use the higher of the two speeds
                    // so attack/cast anims (which have speed > 1) are never reduced.
                    if (animState.smoothVelocity > 15.f) {
                        constexpr float kBaseRunAnimSpeedNPC = 432.f;
                        float velSpeed = animState.smoothVelocity / kBaseRunAnimSpeedNPC;
                        if (velSpeed > speedMult)
                            speedMult = velSpeed;
                    }
                } else if (isKD && ctrl) {
                    const auto* kd = ard.knockdownIntervalAtTime(m_debugTimeline);
                    if (kd) {
                        float kdDur = kd->end - kd->start;
                        float segStart = ctrl->GetSequenceStartTime();
                        float segEnd   = ctrl->GetSequenceEndTime();
                        float segDurSec = (segEnd - segStart) / 100000.f;
                        if (kdDur > 0.001f && segDurSec > 0.001f)
                            speedMult = segDurSec / kdDur;
                    }
                } else if (animState.postKdGetUp && ctrl) {
                    float segStart = ctrl->GetSequenceStartTime();
                    float segEnd   = ctrl->GetSequenceEndTime();
                    float segDurSec = (segEnd - segStart) / 100000.f;
                    float codeStart = snap.time;
                    for (int si2 = snapIdx - 1; si2 >= 0; si2--) {
                        if (ard.snapshots[si2].animation_code != snap.animation_code) break;
                        codeStart = ard.snapshots[si2].time;
                    }
                    float codeEnd = snap.time;
                    for (int si2 = snapIdx + 1; si2 < static_cast<int>(ard.snapshots.size()); si2++) {
                        if (ard.snapshots[si2].animation_code != snap.animation_code) {
                            codeEnd = ard.snapshots[si2].time;
                            break;
                        }
                        codeEnd = ard.snapshots[si2].time;
                    }
                    float getUpDur = codeEnd - codeStart;
                    if (getUpDur > 0.001f && segDurSec > 0.001f)
                        speedMult = segDurSec / getUpDur;
                } else {
                    if (animState.isPlayingMovementAnim) {
                        constexpr float kBaseRunAnimSpeed = 432.f;
                        speedMult = animState.smoothVelocity / kBaseRunAnimSpeed;
                        speedMult = std::clamp(speedMult, 0.1f, 4.0f);
                    } else if (!animState.isPlayingIdleAnim
                               && snap.weapon_attack_speed > 0.f && snap.attack_speed_modifier > 0.f && ctrl) {
                        float effectiveAttackTime = snap.weapon_attack_speed * snap.attack_speed_modifier;
                        float segStart = ctrl->GetSequenceStartTime();
                        float segEnd   = ctrl->GetSequenceEndTime();
                        float segDurSec = (segEnd - segStart) / 100000.f;
                        if (effectiveAttackTime > 0.001f && segDurSec > 0.001f)
                            speedMult = segDurSec / effectiveAttackTime;
                    }
                }

                animState.effectiveSpeedMult = speedMult;
                ctrl->SetPlaybackSpeed(speedMult * 100000.f);

                // Advance animation
                bool deathFrozen = dead && ctrl->GetState() == GW::Animation::AnimationController::PlaybackState::Stopped;
                if (m_replayCtx.isPlaying && !deathFrozen)
                    ctrl->Update(frameDt * m_replayCtx.playbackSpeed);

                if (context) {
                    for (auto& am : animState.animMeshes)
                        if (am) am->UpdateBoneMatrices(context, *ctrl);
                }
            }

            // Update world transforms and alpha on per-mesh CBs
            float baseAlpha = inFog ? 0.3f : 1.0f;
            if (dead) baseAlpha = deadAlpha;
            bool hovered = (agentId == m_hoveredAgentId);
            for (size_t si2 = 0; si2 < animState.perMeshCBs.size(); si2++) {
                XMStoreFloat4x4(&animState.perMeshCBs[si2].world, worldMat);
                animState.perMeshCBs[si2].mesh_alpha = baseAlpha;
                animState.perMeshCBs[si2].highlight_state = hovered ? 5 : 0;
            }

            m_agentModelRenderStatus[agentId] = std::format(
                "skinned{}: submeshes={} pos=({:.0f},{:.0f},{:.0f}) anim=0x{:X}",
                dead ? " (dead)" : "", animState.animMeshes.size(),
                pos.x, pos.y, pos.z, snap.animation_code);
        } else {
            // Rigid prop rendering
            float rigidAlpha = inFog ? 0.3f : 1.0f;
            if (dead) rigidAlpha = deadAlpha;
            bool rigidHovered = (agentId == m_hoveredAgentId);
            int renderedCount = 0;
            for (int mid : meshIds) {
                meshMgr->SetMeshShouldRender(mid, true);
                auto cbOpt = meshMgr->GetMeshPerObjectData(mid);
                if (cbOpt.has_value()) {
                    auto cb = cbOpt.value();
                    XMStoreFloat4x4(&cb.world, worldMat);
                    cb.mesh_alpha = rigidAlpha;
                    cb.highlight_state = rigidHovered ? 5 : 0;
                    meshMgr->UpdateMeshPerObjectData(mid, cb);
                    renderedCount++;
                }
            }
            m_agentModelRenderStatus[agentId] = std::format(
                "shown: meshes={}/{} pos=({:.0f},{:.0f},{:.0f}) scale={:.3f}",
                renderedCount, meshIds.size(), pos.x, pos.y, pos.z, scale);
        }
    }
}

// ---------------------------------------------------------------------------
// Skinned render pass for animated agent models.
// Called after DrawAgentModels() which updates bone matrices and world CBs.
// ---------------------------------------------------------------------------

void ReplayWindow::DrawSkinnedAgentModels()
{
    if (!m_useAgentModels || !m_agentModelsLoaded) return;
    if (m_agentAnimStates.empty()) return;

    auto* context = m_deviceResources->GetD3DDeviceContext();
    auto* meshManager = m_mapRenderer->GetMeshManager();
    auto* textureManager = m_mapRenderer->GetTextureManager();
    if (!context || !meshManager || !textureManager) return;

    bool anyVisible = false;
    for (auto& [agentId, animState] : m_agentAnimStates) {
        if (!animState.hasSkinning) continue;
        auto statusIt = m_agentModelRenderStatus.find(agentId);
        if (statusIt == m_agentModelRenderStatus.end()) continue;
        if (statusIt->second.starts_with("skinned")) { anyVisible = true; break; }
    }
    if (!anyVisible) return;

    m_mapRenderer->BindSkinnedVertexShader();
    context->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);
    m_mapRenderer->BindModelPixelShader(false);

    for (auto& [agentId, animState] : m_agentAnimStates)
    {
        if (!animState.hasSkinning) continue;

        auto statusIt = m_agentModelRenderStatus.find(agentId);
        if (statusIt == m_agentModelRenderStatus.end() || !statusIt->second.starts_with("skinned"))
            continue;

        for (size_t si = 0; si < animState.animMeshes.size(); si++)
        {
            auto& animMesh = animState.animMeshes[si];
            if (!animMesh) continue;

            if (si < animState.perMeshCBs.size()) {
                PerObjectCB transposedData = animState.perMeshCBs[si];
                XMMATRIX worldMatrix = XMLoadFloat4x4(&transposedData.world);
                worldMatrix = XMMatrixTranspose(worldMatrix);
                XMStoreFloat4x4(&transposedData.world, worldMatrix);
                meshManager->SetPerObjectCB(transposedData);
            }

            if (si < animState.perMeshTextureIds.size()) {
                const auto& texIds = animState.perMeshTextureIds[si];
                if (!texIds.empty()) {
                    auto textures = textureManager->GetTextures(texIds);
                    if (!textures.empty())
                        animMesh->SetTextures(textures, 3);
                }
            }

            animMesh->Draw(context, m_mapRenderer->GetLODQuality());
        }
    }

    m_mapRenderer->BindRegularVertexShader();
}

void ReplayWindow::DrawAgentCylinders()
{
    if (!m_showAgentOverlay) return;
    if (!m_agentsClassified || m_replayCtx.agents.empty()) return;

    InitCylinderRenderer();
    if (!m_cylVS || !m_cylPS) return;

    ID3D11DeviceContext* ctx = m_deviceResources->GetD3DDeviceContext();

    // ---- Save ALL D3D11 state so we don't corrupt MapRenderer / ImGui ----
    Microsoft::WRL::ComPtr<ID3D11VertexShader>   oldVS;
    Microsoft::WRL::ComPtr<ID3D11PixelShader>    oldPS;
    Microsoft::WRL::ComPtr<ID3D11InputLayout>    oldIL;
    Microsoft::WRL::ComPtr<ID3D11Buffer>         oldVB;
    Microsoft::WRL::ComPtr<ID3D11Buffer>         oldIB;
    Microsoft::WRL::ComPtr<ID3D11RasterizerState> oldRS;
    Microsoft::WRL::ComPtr<ID3D11DepthStencilState> oldDSS;
    Microsoft::WRL::ComPtr<ID3D11BlendState>     oldBS;
    UINT oldStencilRef = 0;
    float oldBlendFactor[4]; UINT oldSampleMask = 0;
    UINT oldVBStride = 0, oldVBOffset = 0;
    DXGI_FORMAT oldIBFormat = DXGI_FORMAT_UNKNOWN; UINT oldIBOffset = 0;
    D3D11_PRIMITIVE_TOPOLOGY oldTopo = D3D11_PRIMITIVE_TOPOLOGY_UNDEFINED;
    Microsoft::WRL::ComPtr<ID3D11Buffer> oldVSCB0, oldVSCB1, oldPSCB0, oldPSCB1;

    ctx->VSGetShader(oldVS.GetAddressOf(), nullptr, nullptr);
    ctx->PSGetShader(oldPS.GetAddressOf(), nullptr, nullptr);
    ctx->IAGetInputLayout(oldIL.GetAddressOf());
    ctx->IAGetVertexBuffers(0, 1, oldVB.GetAddressOf(), &oldVBStride, &oldVBOffset);
    ctx->IAGetIndexBuffer(oldIB.GetAddressOf(), &oldIBFormat, &oldIBOffset);
    ctx->IAGetPrimitiveTopology(&oldTopo);
    ctx->RSGetState(oldRS.GetAddressOf());
    ctx->OMGetDepthStencilState(oldDSS.GetAddressOf(), &oldStencilRef);
    ctx->OMGetBlendState(oldBS.GetAddressOf(), oldBlendFactor, &oldSampleMask);
    ctx->VSGetConstantBuffers(0, 1, oldVSCB0.GetAddressOf());
    ctx->VSGetConstantBuffers(1, 1, oldVSCB1.GetAddressOf());
    ctx->PSGetConstantBuffers(0, 1, oldPSCB0.GetAddressOf());
    ctx->PSGetConstantBuffers(1, 1, oldPSCB1.GetAddressOf());

    // ---- Set up cylinder pipeline ----
    Camera* cam = m_mapRenderer->GetCamera();
    const MapTransform& t = m_replayCtx.mapTransform;
    const InterpolationSettings& is = m_replayCtx.interpSettings;

    XMMATRIX vp = cam->GetView() * cam->GetProj();
    XMFLOAT3 camP = cam->GetPosition3f();

    {
        D3D11_MAPPED_SUBRESOURCE mapped;
        ctx->Map(m_cylCBFrame.Get(), 0, D3D11_MAP_WRITE_DISCARD, 0, &mapped);
        CylPerFrame* cb = (CylPerFrame*)mapped.pData;
        XMStoreFloat4x4(&cb->viewProj, XMMatrixTranspose(vp));
        cb->camPos = { camP.x, camP.y, camP.z, 1.f };
        ctx->Unmap(m_cylCBFrame.Get(), 0);
    }

    UINT stride = sizeof(CylVertex), offset = 0;
    ctx->IASetVertexBuffers(0, 1, m_cylVB.GetAddressOf(), &stride, &offset);
    ctx->IASetIndexBuffer(m_cylIB.Get(), DXGI_FORMAT_R16_UINT, 0);
    ctx->IASetInputLayout(m_cylIL.Get());
    ctx->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);

    ctx->VSSetShader(m_cylVS.Get(), nullptr, 0);
    ctx->PSSetShader(m_cylPS.Get(), nullptr, 0);

    ID3D11Buffer* cbs[] = { m_cylCBFrame.Get(), m_cylCBInst.Get() };
    ctx->VSSetConstantBuffers(0, 2, cbs);
    ctx->PSSetConstantBuffers(0, 2, cbs);

    ctx->RSSetState(m_cylRS.Get());
    ctx->OMSetDepthStencilState(m_cylDSS.Get(), 0);
    float blendFactor[4] = { 0, 0, 0, 0 };
    ctx->OMSetBlendState(m_cylBS.Get(), blendFactor, 0xFFFFFFFF);

    Terrain* terrain = m_mapRenderer->GetTerrain();
    bool hasBounds = (terrain != nullptr);
    float bMinX = 0, bMaxX = 0, bMinZ = 0, bMaxZ = 0;
    if (hasBounds) {
        bMinX = terrain->m_bounds.map_min_x;
        bMaxX = terrain->m_bounds.map_max_x;
        bMinZ = terrain->m_bounds.map_min_z;
        bMaxZ = terrain->m_bounds.map_max_z;
    }

    const bool lodOn = m_uiLayout.lodEnabled;
    const float lodDot = m_uiLayout.lodDotDist;

    for (auto& [agentId, ard] : m_replayCtx.agents)
    {
        if (ard.snapshots.empty()) continue;
        if (ard.type != AgentType::Player && ard.type != AgentType::NPC) continue;

        // Skip cylinder for agents that already have a 3D model loaded.
        if (m_useAgentModels && m_agentMeshIds.count(agentId))
            continue;

        float sx, sy, sz;
        InterpolateAgentPosition(ard, m_debugTimeline, is, sx, sy, sz);
        XMFLOAT3 pos = ApplyMapTransformToPos(sx, sy, sz, t);

        if (hasBounds) {
            pos.x = std::clamp(pos.x, bMinX, bMaxX);
            pos.z = std::clamp(pos.z, bMinZ, bMaxZ);
        }

        // LOD: beyond lodDot distance → dot only (skip 3D draw)
        bool isDot = false;
        if (lodOn) {
            float dx = pos.x - camP.x, dy = pos.y - camP.y, dz = pos.z - camP.z;
            float dist = sqrtf(dx * dx + dy * dy + dz * dz);
            isDot = (dist > lodDot);
        }
        ard.currentLOD = isDot ? 0 : 2;  // 0=Dot, 2=Cylinder

        if (isDot) continue;

        bool inFog = (m_fogPerspective > 0 && ard.teamId != m_fogPerspective && IsAgentInFog(agentId));
        if (inFog && !m_fogGhostMode) continue;

        bool dead = ard.isDeadAtTime(m_debugTimeline);

        float tiltDeg = dead ? 90.f : ard.knockdownTiltAtTime(m_debugTimeline);
        XMMATRIX world;
        if (tiltDeg > 0.01f)
        {
            float tiltRad = XMConvertToRadians(tiltDeg);
            world = XMMatrixRotationZ(tiltRad) * XMMatrixTranslation(pos.x, pos.y, pos.z);
        }
        else
        {
            world = XMMatrixTranslation(pos.x, pos.y, pos.z);
        }

        XMFLOAT4 color;
        if (inFog)
        {
            color = { 0.4f, 0.4f, 0.4f, 0.30f };
        }
        else if (ard.teamId == 1)  color = { 0.290f, 0.565f, 0.847f, 1.f };
        else if (ard.teamId == 2)  color = { 0.816f, 0.282f, 0.282f, 1.f };
        else                       color = { 0.7f, 0.7f, 0.7f, 1.f };

        if (dead)
        {
            float deathTime = ard.deathTransitionTime(m_debugTimeline);
            float fadeIn = std::clamp((m_debugTimeline - deathTime) / 0.25f, 0.f, 1.f);
            fadeIn = fadeIn * fadeIn * (3.f - 2.f * fadeIn);
            float lum = color.x * 0.299f + color.y * 0.587f + color.z * 0.114f;
            float desatR = lum + (color.x - lum) * 0.35f;
            float desatG = lum + (color.y - lum) * 0.35f;
            float desatB = lum + (color.z - lum) * 0.35f;
            color = { desatR * 0.45f, desatG * 0.45f, desatB * 0.45f, 0.6f * fadeIn };
        }

        if (agentId == m_hoveredAgentId)
        {
            color.x = std::min(color.x * 1.25f, 1.0f);
            color.y = std::min(color.y * 1.25f, 1.0f);
            color.z = std::min(color.z * 1.25f, 1.0f);
        }

        {
            D3D11_MAPPED_SUBRESOURCE mapped;
            ctx->Map(m_cylCBInst.Get(), 0, D3D11_MAP_WRITE_DISCARD, 0, &mapped);
            CylPerInst* cb = (CylPerInst*)mapped.pData;
            XMStoreFloat4x4(&cb->world, XMMatrixTranspose(world));
            cb->teamColor = color;
            ctx->Unmap(m_cylCBInst.Get(), 0);
        }
        ctx->DrawIndexed(m_cylIndexCount, 0, 0);
    }

    // ---- Restore ALL saved D3D11 state ----
    ctx->VSSetShader(oldVS.Get(), nullptr, 0);
    ctx->PSSetShader(oldPS.Get(), nullptr, 0);
    ctx->IASetInputLayout(oldIL.Get());
    ctx->IASetVertexBuffers(0, 1, oldVB.GetAddressOf(), &oldVBStride, &oldVBOffset);
    ctx->IASetIndexBuffer(oldIB.Get(), oldIBFormat, oldIBOffset);
    ctx->IASetPrimitiveTopology(oldTopo);
    ctx->RSSetState(oldRS.Get());
    ctx->OMSetDepthStencilState(oldDSS.Get(), oldStencilRef);
    ctx->OMSetBlendState(oldBS.Get(), oldBlendFactor, oldSampleMask);
    ID3D11Buffer* restoreVSCBs[] = { oldVSCB0.Get(), oldVSCB1.Get() };
    ctx->VSSetConstantBuffers(0, 2, restoreVSCBs);
    ID3D11Buffer* restorePSCBs[] = { oldPSCB0.Get(), oldPSCB1.Get() };
    ctx->PSSetConstantBuffers(0, 2, restorePSCBs);
}

// Forward declarations for icon loaders (defined later)
static ImTextureID LoadProfIcon(ID3D11Device* device, int profId);
enum class AgentIconState { Alive, Dead, Knockdown };
static ImTextureID LoadProfStylized(ID3D11Device* device, int profId,
                                     int teamId = 0,
                                     AgentIconState state = AgentIconState::Alive);
static ImTextureID LoadSkillIcon(ReplayWindow* rw, ID3D11Device* device,
                                 int skillId,
                                 std::unordered_map<int, std::string>& index,
                                 std::unordered_map<int, ComPtr<ID3D11ShaderResourceView>>& cache);
static ImTextureID LoadFlagIcon(ID3D11Device* device, const char* filename);
static ImTextureID LoadPartyIcon(ID3D11Device* device, const char* filename);
static ImTextureID LoadEffectIcon(ID3D11Device* device, const char* filename);
static std::string GetSkillDisplayName(int skillId);

// Gradient helpers (used by cast bar rendering + texture building)
struct GradStop { float pos; uint8_t r, g, b; };
static float LerpGradChannel(float a, float b, float t) { return a + (b - a) * t; }
static void SampleGradient(const GradStop* stops, int n, float t,
                            float& outR, float& outG, float& outB)
{
    const GradStop* a = &stops[0];
    const GradStop* b = &stops[n - 1];
    for (int i = 0; i < n - 1; ++i)
    {
        if (t >= stops[i].pos && t <= stops[i + 1].pos)
        { a = &stops[i]; b = &stops[i + 1]; break; }
    }
    float lt = (b->pos - a->pos > 0.0001f) ? (t - a->pos) / (b->pos - a->pos) : 0.f;
    outR = LerpGradChannel(a->r, b->r, lt);
    outG = LerpGradChannel(a->g, b->g, lt);
    outB = LerpGradChannel(a->b, b->b, lt);
}

void ReplayWindow::DrawAgentOverlay()
{
    if (!m_showAgentOverlay) return;
    if (!m_agentsClassified || m_replayCtx.agents.empty()) return;

    Camera* cam = m_mapRenderer->GetCamera();
    XMMATRIX viewProj = cam->GetView() * cam->GetProj();
    auto vp = m_deviceResources->GetScreenViewport();
    float vpW = vp.Width, vpH = vp.Height;

    ImDrawList* dl = ImGui::GetBackgroundDrawList();
    ImFont* font = ImGui::GetFont();
    const float dotRadius = 6.f;
    const float labelOffY = 8.f;
    const MapTransform& t = m_replayCtx.mapTransform;

    const bool canClickAgents = !ImGui::GetIO().WantCaptureMouse
                                && !m_rightMouseDown
                                && !m_annotationMgr.draw_mode_active;
    const ImVec2 mousePos = ImGui::GetIO().MousePos;
    const float clickRadius = 14.f;
    m_hoveredAgentId = -1;

    struct TopViewTooltipCandidate { float rectMinX, rectMinY, rectMaxX, rectMaxY; std::string name; float dist; };
    std::vector<TopViewTooltipCandidate> topViewTooltipCandidates;

    // Map boundary clamping: use terrain bounds if available.
    // Bounds are in GWMB mesh coordinates (post-transform), so we clamp after
    // applying the map transform.
    Terrain* terrain = m_mapRenderer->GetTerrain();
    bool hasBounds = (terrain != nullptr);
    float bMinX = 0, bMaxX = 0, bMinZ = 0, bMaxZ = 0;
    if (hasBounds) {
        bMinX = terrain->m_bounds.map_min_x;
        bMaxX = terrain->m_bounds.map_max_x;
        bMinZ = terrain->m_bounds.map_min_z;
        bMaxZ = terrain->m_bounds.map_max_z;
    }

    // Optional: draw origin axes
    if (m_showMapOriginAxes)
    {
        const float axisLen = 2000.f;
        struct { XMFLOAT3 end; ImU32 col; } axes[] = {
            { { axisLen, 0, 0 }, IM_COL32(255, 60, 60, 200) },
            { { 0, axisLen, 0 }, IM_COL32(60, 255, 60, 200) },
            { { 0, 0, axisLen }, IM_COL32(60, 100, 255, 200) },
        };
        float ox, oy;
        if (ProjectToScreen(viewProj, vpW, vpH, { 0, 0, 0 }, ox, oy))
        {
            for (auto& a : axes) {
                float ax, ay;
                if (ProjectToScreen(viewProj, vpW, vpH, a.end, ax, ay))
                    dl->AddLine(ImVec2(ox, oy), ImVec2(ax, ay), a.col, 2.f);
            }
        }
    }

    const InterpolationSettings& is = m_replayCtx.interpSettings;

    // --- Spirit overlap pass: determine which spirits are hidden ---
    // Group spirits by (team, model_id). Within each group, only the newest
    // spirit is unconditionally visible; older ones are hidden if they are
    // within 2.7 × the spirit's danger-zone radius of the newest.
    {
        struct SpiritEntry { int agentId; float spawnTime; float px, py; };
        // Key: (teamId << 32) | modelId
        std::unordered_map<uint64_t, std::vector<SpiritEntry>> groups;

        for (int id : m_spiritIds)
        {
            auto& ard = m_replayCtx.agents[id];
            ard.overlapHidden     = false;
            ard.overlapIsNewest   = false;
            ard.overlapDistNewest = 0.f;
            ard.overlapThreshold  = 0.f;

            if (ard.snapshots.empty()) continue;
            if (m_debugTimeline < ard.snapshots.front().time ||
                m_debugTimeline > ard.snapshots.back().time)
                continue;

            float sx, sy, sz;
            SnapAgentPosition(ard, m_debugTimeline, sx, sy, sz);

            uint64_t key = (static_cast<uint64_t>(ard.teamId) << 32) | ard.modelId;
            groups[key].push_back({ id, ard.snapshots.front().time, sx, sy });
        }

        for (auto& [key, entries] : groups)
        {
            if (entries.size() <= 1) {
                if (!entries.empty()) {
                    auto& a = m_replayCtx.agents[entries[0].agentId];
                    a.overlapIsNewest  = true;
                    a.overlapThreshold = GetSpiritOverwriteDist(a.modelId);
                }
                continue;
            }

            // Sort newest first (highest spawnTime)
            std::sort(entries.begin(), entries.end(),
                      [](const SpiritEntry& a, const SpiritEntry& b) {
                          return a.spawnTime > b.spawnTime;
                      });

            auto& newest = entries[0];
            auto& newestArd = m_replayCtx.agents[newest.agentId];
            float threshold = GetSpiritOverwriteDist(newestArd.modelId);

            newestArd.overlapIsNewest  = true;
            newestArd.overlapThreshold = threshold;

            for (size_t i = 1; i < entries.size(); ++i)
            {
                auto& e = entries[i];
                auto& a = m_replayCtx.agents[e.agentId];
                float dx = e.px - newest.px;
                float dy = e.py - newest.py;
                float dist = sqrtf(dx * dx + dy * dy);

                a.overlapThreshold  = threshold;
                a.overlapDistNewest = dist;
                a.overlapHidden     = (dist < threshold);
            }
        }
    }

    for (auto& [agentId, ard] : m_replayCtx.agents)
    {
        if (ard.snapshots.empty()) continue;

        if (ard.type == AgentType::Flag) continue;

        // Skip empty agents (no model, no gadget) and bodyguard model 166
        {
            const auto& fs = ard.snapshots.front();
            if (fs.model_id == 0 && fs.gadget_id == 0) continue;
            if (fs.model_id == 166) continue;
        }

        if (m_fogPerspective > 0 && ard.teamId != m_fogPerspective && IsAgentInFog(agentId))
        {
            if (!m_fogGhostMode) continue;
        }

        // Spirits only exist within their snapshot time range
        if (ard.type == AgentType::Spirit)
        {
            if (m_debugTimeline < ard.snapshots.front().time ||
                m_debugTimeline > ard.snapshots.back().time)
                continue;
        }

        // Items: use lifecycle AGENT_REMOVE time for precise visibility cutoff
        if (ard.type == AgentType::Item)
        {
            if (m_debugTimeline < ard.snapshots.front().time)
                continue;
            auto rmIt = m_itemRemoveTime.find(agentId);
            float removeT;
            if (rmIt != m_itemRemoveTime.end())
                removeT = rmIt->second;
            else if (m_replayCtx.stocLoaded)
                removeT = FLT_MAX;
            else
                removeT = ard.snapshots.back().time;
            if (m_debugTimeline > removeT)
                continue;
        }

        // Spirit visibility: hide overwritten, dead, or not-alive spirits immediately
        if (ard.type == AgentType::Spirit)
        {
            if (ard.overlapHidden) continue;
            if (ard.isDeadAtTime(m_debugTimeline) || !ard.isAliveAtTime(m_debugTimeline))
                continue;
        }

        float sx, sy, sz;
        InterpolateAgentPosition(ard, m_debugTimeline, is, sx, sy, sz);

        // Optional: show raw axis-remapped position (no transform) — from calibration panel
        if (m_showRawPositions) {
            XMFLOAT3 rawPos = { sx, sz, sy };
            float rsx, rsy;
            if (ProjectToScreen(viewProj, vpW, vpH, rawPos, rsx, rsy))
                dl->AddCircle(ImVec2(rsx, rsy), 3.f, IM_COL32(255, 255, 0, 120), 0, 1.f);
        }

        // Optional: show raw snapshot position as grey dot (from interp panel)
        float rawScrX = 0.f, rawScrY = 0.f;
        bool rawOnScreen = false;
        if (is.showRawSnapshots && ard.type != AgentType::Flag && ard.type != AgentType::Spirit)
        {
            float rx, ry, rz;
            SnapAgentPosition(ard, m_debugTimeline, rx, ry, rz);
            XMFLOAT3 rawPos = ApplyMapTransformToPos(rx, ry, rz, t);
            rawOnScreen = ProjectToScreen(viewProj, vpW, vpH, rawPos, rawScrX, rawScrY);
            if (rawOnScreen)
                dl->AddCircleFilled(ImVec2(rawScrX, rawScrY), 3.f, IM_COL32(160, 160, 160, 180));
        }

        // Optional: draw MOVE_TO_POINT anchors (yellow diamond + line from snap)
        if (is.showMoveAnchors && !ard.moveEvents.empty() &&
            ard.type != AgentType::Flag && ard.type != AgentType::Spirit)
        {
            int moveIdx = FindMoveEventIndex(ard.moveEvents, m_debugTimeline);
            if (moveIdx >= 0) {
                auto& move = ard.moveEvents[moveIdx];
                XMFLOAT3 mpos = ApplyMapTransformToPos(move.targetX, move.targetY, 0.f, t);
                float msx, msy;
                if (ProjectToScreen(viewProj, vpW, vpH, mpos, msx, msy)) {
                    dl->AddCircleFilled(ImVec2(msx, msy), 4.f, IM_COL32(255, 255, 0, 200));
                    float snapScrX, snapScrY;
                    float rx, ry, rz;
                    SnapAgentPosition(ard, m_debugTimeline, rx, ry, rz);
                    XMFLOAT3 spos = ApplyMapTransformToPos(rx, ry, rz, t);
                    if (ProjectToScreen(viewProj, vpW, vpH, spos, snapScrX, snapScrY))
                        dl->AddLine(ImVec2(snapScrX, snapScrY), ImVec2(msx, msy),
                                    IM_COL32(255, 255, 0, 100), 1.f);
                }
            }
        }

        XMFLOAT3 pos = ApplyMapTransformToPos(sx, sy, sz, t);

        // Clamp to map boundaries to prevent out-of-bounds drift
        if (hasBounds) {
            if (pos.x < bMinX) pos.x = bMinX;
            if (pos.x > bMaxX) pos.x = bMaxX;
            if (pos.z < bMinZ) pos.z = bMinZ;
            if (pos.z > bMaxZ) pos.z = bMaxZ;
        }

        float scrX, scrY;
        if (!ProjectToScreen(viewProj, vpW, vpH, pos, scrX, scrY)) continue;

        // Debug line between raw snapshot and interpolated position
        if (is.showInterpolatedLine && rawOnScreen &&
            ard.type != AgentType::Flag && ard.type != AgentType::Spirit)
            dl->AddLine(ImVec2(rawScrX, rawScrY), ImVec2(scrX, scrY),
                        IM_COL32(255, 255, 255, 80), 1.f);

        bool casting = ard.isCastingAtTime(m_debugTimeline);
        bool dead    = ard.isDeadAtTime(m_debugTimeline);

        // Determine if this agent has a 3D representation or needs a 2D dot
        bool is3DAgent = (ard.type == AgentType::Player || ard.type == AgentType::NPC);
        bool showDot = !is3DAgent;

        // Agents with 3D models don't need dots
        if (m_useAgentModels && m_agentMeshIds.count(agentId))
            showDot = false;

        // For players/NPCs, check LOD: if Dot mode, use stylized profession icon for players
        if (is3DAgent && ard.currentLOD == 0)
            showDot = true;

        // For players with 3D representation (not dot LOD), draw profession icon just above model head
        if (ard.type == AgentType::Player && !showDot && ard.primaryProf >= 1)
        {
            float modelTopY = pos.y;
            if (m_useAgentModels && m_agentModelsLoaded) {
                auto hashIt = m_agentFileHashCache.find(agentId);
                if (hashIt != m_agentFileHashCache.end()) {
                    auto tmplIt = m_agentModelTemplates.find(hashIt->second);
                    if (tmplIt != m_agentModelTemplates.end()) {
                        AgentModelInfo minfo = LookupAgentModelInfo(
                            ard.type, ard.modelId, ard.primaryProf, ard.isFemale);
                        float scale = minfo.npcAdjustment * m_agentModelScale;
                        modelTopY += tmplIt->second.nativeHeight * scale;
                    }
                }
            }
            if (modelTopY <= pos.y)
                modelTopY = pos.y + 120.f;

            XMFLOAT3 topPos = { pos.x, modelTopY, pos.z };
            float topScrX, topScrY;
            if (ProjectToScreen(viewProj, vpW, vpH, topPos, topScrX, topScrY))
            {
                ID3D11Device* dev = m_deviceResources->GetD3DDevice();
                ImTextureID profTex = LoadProfIcon(dev, ard.primaryProf);
                if (profTex)
                {
                    float iconSz = std::clamp(vpH * 0.020f, 12.f, 20.f);
                    constexpr float kScreenPad = 4.f;
                    float iconBottom = topScrY - kScreenPad;
                    ImVec2 iconTL(topScrX - iconSz * 0.5f, iconBottom - iconSz);
                    ImVec2 iconBR(topScrX + iconSz * 0.5f, iconBottom);
                    dl->AddImage(profTex, iconTL, iconBR);
                }
            }
        }

        // Floating skill icon + cast bar above agent (players/NPCs, alive only)
        if (m_showSkillIcons && !dead && (ard.type == AgentType::Player || ard.type == AgentType::NPC))
        {
            auto sv = ard.skillVisualAtTime(m_debugTimeline);
            if (sv.skillId > 0 && sv.alpha > 0.f)
            {
                EnsureSkillIconIndex();
                ID3D11Device* dev = m_deviceResources->GetD3DDevice();
                ImTextureID skillTex = LoadSkillIcon(this, dev, sv.skillId,
                                                     m_skillIconIndex, m_skillIconCache);
                constexpr float SKILL_SIDE_OFFSET = 55.f;
                constexpr float SKILL_UP_OFFSET   = 40.f;
                XMFLOAT3 skillPos = { pos.x + SKILL_SIDE_OFFSET, pos.y + SKILL_UP_OFFSET, pos.z };
                float skX, skY;
                if (ProjectToScreen(viewProj, vpW, vpH, skillPos, skX, skY))
                {
                    float dpiScale = std::max(1.f, vpH / 1080.f);
                    ImU8 alpha = (ImU8)(sv.alpha * 255.f);
                    float iconSz = std::clamp(vpH * 0.028f, 20.f, 32.f);

                    // Skill icon
                    if (skillTex)
                    {
                        ImVec2 iconTL(skX - iconSz * 0.5f, skY - iconSz * 0.5f);
                        ImVec2 iconBR(skX + iconSz * 0.5f, skY + iconSz * 0.5f);
                        dl->AddImage(skillTex, iconTL, iconBR,
                                     ImVec2(0, 0), ImVec2(1, 1),
                                     IM_COL32(255, 255, 255, alpha));
                    }

                    // Cast bar (non-instant skills: casting, cancelled, interrupted, or just completed)
                    bool showBar = sv.isCasting || sv.cancelled || sv.interrupted;
                    if (showBar)
                    {
                        float barW = iconSz * 1.6f;
                        float barH = 6.f  * dpiScale;
                        float gap  = 2.f  * dpiScale;

                        ImVec2 barMin(skX - barW * 0.5f, skY + iconSz * 0.5f + gap);
                        ImVec2 barMax(barMin.x + barW, barMin.y + barH);
                        float pct   = sv.progress;
                        float midY  = barMin.y + barH * 0.5f;

                        // Background: procedural vertical gradient (black→gray→black)
                        {
                            ImU32 bgD = IM_COL32(0, 0, 0, alpha);
                            ImU32 bgM = IM_COL32(36, 36, 36, alpha);
                            dl->AddRectFilledMultiColor(barMin, ImVec2(barMax.x, midY),
                                bgD, bgD, bgM, bgM);
                            dl->AddRectFilledMultiColor(ImVec2(barMin.x, midY), barMax,
                                bgM, bgM, bgD, bgD);
                        }

                        // Fill: procedural horizontal gradient + vertical vignette
                        // Green = success, Yellow/orange = cancelled, Purple = interrupted
                        float fillW = barW * pct;
                        if (pct > 0.005f)
                        {
                            static const GradStop sGreenH[] = {
                                { 0.000f,  10, 10, 10 }, { 0.200f,  26, 58, 10 },
                                { 0.400f,  64,176, 32 }, { 0.600f, 168,240, 80 },
                                { 0.800f, 200,255,112 }, { 1.000f, 144,224, 64 }
                            };
                            static const GradStop sOrangeH[] = {
                                { 0.000f,  10,  8,  0 }, { 0.143f,  58, 30,  0 },
                                { 0.286f, 122, 58,  0 }, { 0.429f, 192, 96,  0 },
                                { 0.571f, 232,144, 16 }, { 0.714f, 255,184, 32 },
                                { 0.857f, 255,208, 64 }, { 1.000f, 232,160, 16 }
                            };
                            static const GradStop sPurpleH[] = {
                                { 0.000f,  10, 10, 10 }, { 0.300f, 120, 32,192 },
                                { 0.600f, 224,160,255 }, { 1.000f, 160, 80,224 }
                            };
                            const GradStop* hS;
                            int nH;
                            float topV, botV;
                            if (sv.interrupted) {
                                hS = sPurpleH; nH = 4; topV = 0.58f; botV = 0.52f;
                            } else if (sv.cancelled) {
                                hS = sOrangeH; nH = 8; topV = 0.58f; botV = 0.52f;
                            } else {
                                hS = sGreenH; nH = 6; topV = 0.55f; botV = 0.50f;
                            }

                            int nSegs = std::clamp((int)(fillW / 3.f), 4, 24);
                            for (int si = 0; si < nSegs; ++si)
                            {
                                float u0 = (float)si / nSegs;
                                float u1 = (float)(si + 1) / nSegs;
                                float r0, g0, b0, r1, g1, b1;
                                SampleGradient(hS, nH, u0 * pct, r0, g0, b0);
                                SampleGradient(hS, nH, u1 * pct, r1, g1, b1);

                                float x0 = barMin.x + fillW * u0;
                                float x1 = barMin.x + fillW * u1;

                                auto vig = [&](float r, float g, float b, float d) -> ImU32 {
                                    float m = 1.f - d;
                                    return IM_COL32((ImU8)(r * m), (ImU8)(g * m), (ImU8)(b * m), alpha);
                                };
                                ImU32 tl = vig(r0,g0,b0, topV);
                                ImU32 tr = vig(r1,g1,b1, topV);
                                ImU32 ml = IM_COL32((ImU8)r0,(ImU8)g0,(ImU8)b0, alpha);
                                ImU32 mr = IM_COL32((ImU8)r1,(ImU8)g1,(ImU8)b1, alpha);
                                ImU32 bl = vig(r0,g0,b0, botV);
                                ImU32 br = vig(r1,g1,b1, botV);

                                dl->AddRectFilledMultiColor(
                                    ImVec2(x0, barMin.y), ImVec2(x1, midY),
                                    tl, tr, mr, ml);
                                dl->AddRectFilledMultiColor(
                                    ImVec2(x0, midY), ImVec2(x1, barMax.y),
                                    ml, mr, br, bl);
                            }
                        }

                        // Outer glow at leading edge
                        float fillX = barMin.x + fillW;
                        if (pct > 0.01f)
                        {
                            float gw = 6.f * dpiScale;
                            ImU8 glA1 = (ImU8)(140 * sv.alpha);
                            ImU8 glA2 = (ImU8)( 60 * sv.alpha);
                            ImU32 gc1, gc2;
                            if (sv.interrupted)
                            {
                                gc1 = IM_COL32(128, 48,192, glA1);
                                gc2 = IM_COL32(128, 48,192, glA2);
                            }
                            else if (sv.cancelled)
                            {
                                gc1 = IM_COL32(192,120,  0, glA1);
                                gc2 = IM_COL32(192,120,  0, glA2);
                            }
                            else
                            {
                                gc1 = IM_COL32( 96,208, 32, glA1);
                                gc2 = IM_COL32( 96,208, 32, glA2);
                            }
                            dl->AddRectFilled(
                                ImVec2(fillX - gw * 0.5f, barMin.y),
                                ImVec2(fillX + gw * 0.5f, barMax.y), gc1);
                            dl->AddRectFilled(
                                ImVec2(fillX - gw, barMin.y - 1.f * dpiScale),
                                ImVec2(fillX + gw, barMax.y + 1.f * dpiScale), gc2);
                        }
                    }
                }
            }
        }


        bool usedProfIcon = false;
        if (showDot)
        {
            if (ard.type == AgentType::Player && ard.primaryProf >= 1)
            {
                ID3D11Device* dev = m_deviceResources->GetD3DDevice();
                AgentIconState iconState = AgentIconState::Alive;
                if (dead)
                    iconState = AgentIconState::Dead;
                else if (ard.knockdownTiltAtTime(m_debugTimeline) > 0.f)
                    iconState = AgentIconState::Knockdown;

                ImTextureID stylTex = LoadProfStylized(dev, ard.primaryProf,
                                                       ard.teamId, iconState);
                if (stylTex)
                {
                    float iconSz = std::clamp(vpH * 0.020f, 12.f, 22.f);
                    ImVec2 iconTL(scrX - iconSz * 0.5f, scrY - iconSz * 0.5f);
                    ImVec2 iconBR(scrX + iconSz * 0.5f, scrY + iconSz * 0.5f);
                    dl->AddImage(stylTex, iconTL, iconBR);
                    usedProfIcon = true;
                }
            }
            if (!usedProfIcon)
            {
                bool isSpecialGadget = (ard.categoryName == "Repair Kit" ||
                                        ard.categoryName == "Tower Flag Stand" ||
                                        ard.categoryName == "Obelisk Flag Stand" ||
                                        ard.categoryName == "Resurrection Shrine" ||
                                        ard.categoryName == "Dwarven Resurrection Shrine" ||
                                        ard.categoryName == "Southern Health Shrine" ||
                                        ard.categoryName == "Lever");
                ImU32 dotColor;
                if (isSpecialGadget)
                    dotColor = IM_COL32(220, 200, 120, 255);
                else if (ard.type == AgentType::Spirit)
                    dotColor = IsNatureRitual(ard.modelId)
                        ? IM_COL32(0x80, 0xFF, 0x80, 0xFF)
                        : GetAgentTeamColor(ard.teamId);
                else if (ard.type == AgentType::Item)
                    dotColor = IM_COL32(0xFF, 0xA5, 0x00, 0xFF);
                else
                    dotColor = GetAgentTeamColor(ard.teamId);
                dl->AddCircleFilled(ImVec2(scrX, scrY), dotRadius, dotColor);
                dl->AddCircle(ImVec2(scrX, scrY), dotRadius, IM_COL32(0, 0, 0, 180), 0, 1.5f);
            }
        }

        // Dead freeze indicator: black X over the dot (dot-mode agents only, skip if prof icon used)
        if (showDot && !usedProfIcon && is.showDeadFreeze && dead &&
            ard.type != AgentType::Flag && ard.type != AgentType::Spirit)
        {
            float r = dotRadius + 2.f;
            dl->AddLine(ImVec2(scrX - r, scrY - r), ImVec2(scrX + r, scrY + r),
                        IM_COL32(0, 0, 0, 240), 2.f);
            dl->AddLine(ImVec2(scrX + r, scrY - r), ImVec2(scrX - r, scrY + r),
                        IM_COL32(0, 0, 0, 240), 2.f);
        }

        // Casting freeze indicator: purple ring (dot-mode agents only)
        if (showDot && is.showCastingFreeze && casting && !dead &&
            ard.type != AgentType::Flag && ard.type != AgentType::Spirit)
        {
            dl->AddCircle(ImVec2(scrX, scrY), dotRadius + 3.f,
                          IM_COL32(180, 60, 255, 220), 0, 2.f);
        }

        // Neon-green dashed ring + glow at cylinder base for followed agent (counter-clockwise spin)
        if (m_cameraMode == CameraMode::FollowAgent && agentId == m_followedAgentId)
        {
            constexpr int   NUM_DASHES = 16;
            constexpr float DASH_FRAC  = 0.70f;   // 70% visible, 30% gap
            constexpr float CYL_R      = 30.f;
            constexpr float RING_R     = CYL_R + 4.f;
            constexpr float PI2        = 6.2831853f;
            constexpr int   PTS_PER_DASH = 8;      // smooth arc per dash
            const ImU32 ringCol = IM_COL32(0, 255, 120, 255);
            const ImU32 glowCol = IM_COL32(0, 255, 120, 80);

            float baseY = pos.y + 0.05f;
            float spinOffset = -fmodf((float)ImGui::GetTime() / 15.f, 1.f) * PI2;
            float pulse = 0.5f + 0.5f * sinf((float)ImGui::GetTime() * 2.5f);
            float pulseR = RING_R + pulse * 3.f;
            ImU8  pulseA = (ImU8)(200 + (int)(55.f * pulse));

            auto projectRingPt = [&](float angle, float r, float& ox, float& oy) -> bool {
                XMFLOAT3 wp = { pos.x + r * cosf(angle), baseY, pos.z + r * sinf(angle) };
                return ProjectToScreen(viewProj, vpW, vpH, wp, ox, oy);
            };

            // Glow layers (pulsating)
            for (int g = 1; g <= 3; ++g)
            {
                float gr = pulseR + g * 3.f;
                ImU32 gc = IM_COL32(0, 255, 120, (ImU8)((int)(80 * (0.5f + 0.5f * pulse)) / g));
                float prevX, prevY;
                bool first = true;
                for (int i = 0; i <= 64; ++i)
                {
                    float a = (float(i) / 64) * PI2;
                    float rx, ry;
                    if (!projectRingPt(a, gr, rx, ry)) { first = true; continue; }
                    if (!first)
                        dl->AddLine(ImVec2(prevX, prevY), ImVec2(rx, ry), gc, 2.f);
                    prevX = rx; prevY = ry;
                    first = false;
                }
            }

            // Dashed ring with counter-clockwise rotation (pulsating)
            ImU32 pulseRingCol = IM_COL32(0, 255, 120, pulseA);
            float dashArc = (PI2 / NUM_DASHES) * DASH_FRAC;
            float segStep = PI2 / NUM_DASHES;
            for (int d = 0; d < NUM_DASHES; ++d)
            {
                float dashStart = spinOffset + d * segStep;
                float prevX, prevY;
                bool first = true;
                for (int p = 0; p <= PTS_PER_DASH; ++p)
                {
                    float a = dashStart + (float(p) / PTS_PER_DASH) * dashArc;
                    float rx, ry;
                    if (!projectRingPt(a, pulseR, rx, ry)) { first = true; continue; }
                    if (!first)
                        dl->AddLine(ImVec2(prevX, prevY), ImVec2(rx, ry), pulseRingCol, 2.5f);
                    prevX = rx; prevY = ry;
                    first = false;
                }
            }
        }

        // Hover detection + click-to-follow
        if (canClickAgents)
        {
            bool hit = false;

            if (!showDot && is3DAgent)
            {
                constexpr float HOVER_H = 120.f;
                XMFLOAT3 topPos = { pos.x, pos.y + HOVER_H, pos.z };
                float topScrX, topScrY;
                if (ProjectToScreen(viewProj, vpW, vpH, topPos, topScrX, topScrY))
                {
                    float minY = std::min(topScrY, scrY);
                    float maxY = std::max(topScrY, scrY);
                    float height = maxY - minY;
                    float halfW = std::max(height * 0.35f, clickRadius);
                    hit = (mousePos.x >= scrX - halfW && mousePos.x <= scrX + halfW &&
                           mousePos.y >= minY - 4.f   && mousePos.y <= maxY + 4.f);
                }
            }
            else
            {
                float dx = mousePos.x - scrX;
                float dy = mousePos.y - scrY;
                hit = (dx * dx + dy * dy <= clickRadius * clickRadius);
            }

            if (hit)
            {
                m_hoveredAgentId = agentId;

                if (ImGui::IsMouseClicked(ImGuiMouseButton_Left))
                {
                    EnterFollowMode(agentId);
                    OpenPlayerInfoPanel(agentId);
                    if (m_showRangeRings)
                        m_ringAgentFilter = (m_ringAgentFilter == agentId) ? -1 : agentId;
                    if (m_fogPerspective > 0)
                        m_fogPlayerAgent = (m_fogPlayerAgent == agentId) ? -1 : agentId;
                }
            }
        }

        if (m_show3DLabels && !m_hiddenNameAgents.count(agentId))
        {
            std::string label = GetAgentLabel(ard);
            ImVec2 textSize = font->CalcTextSizeA(font->FontSize, FLT_MAX, 0.f, label.c_str());
            float lx = scrX - textSize.x * 0.5f;
            float ly = scrY + dotRadius + labelOffY;

            bool isSpecialLabel = (ard.categoryName == "Repair Kit" ||
                                   ard.categoryName == "Tower Flag Stand" ||
                                   ard.categoryName == "Obelisk Flag Stand" ||
                                   ard.categoryName == "Resurrection Shrine" ||
                                   ard.categoryName == "Dwarven Resurrection Shrine" ||
                                   ard.categoryName == "Southern Health Shrine" ||
                                   ard.categoryName == "Lever");
            float pad = 2.f;
            if (isSpecialLabel)
            {
                dl->AddRectFilled(ImVec2(lx - pad, ly - pad),
                                  ImVec2(lx + textSize.x + pad, ly + textSize.y + pad),
                                  IM_COL32(0, 0, 0, 13), 3.f);
                dl->AddText(ImVec2(lx, ly), IM_COL32(245, 228, 180, 255), label.c_str());
            }
            else
            {
                dl->AddRectFilled(ImVec2(lx - pad, ly - pad),
                                  ImVec2(lx + textSize.x + pad, ly + textSize.y + pad),
                                  IM_COL32(0, 0, 0, 25), 3.f);
                ImU32 labelCol;
                if (ard.teamId == 1)      labelCol = IM_COL32(0x99, 0xCB, 0xFD, 0xE6);
                else if (ard.teamId == 2) labelCol = IM_COL32(0xFF, 0x99, 0x9A, 0xE6);
                else                      labelCol = IM_COL32(255, 255, 255, 230);
                dl->AddText(ImVec2(lx + 1.f, ly + 1.f), IM_COL32(0, 0, 0, 200), label.c_str());
                dl->AddText(ImVec2(lx, ly), labelCol, label.c_str());

                if (agentId == m_hoveredAgentId)
                {
                    float ulY = ly + textSize.y - 2.f;
                    dl->AddLine(ImVec2(lx, ulY), ImVec2(lx + textSize.x, ulY), labelCol, 1.f);
                }
            }
        }

        // Top View: collect tooltip hit candidates (skip when names already visible)
        if (m_topViewActive && !m_show3DLabels)
        {
            const float pad = 4.f;
            float hitSz = showDot ? std::clamp(vpH * 0.020f, 12.f, 22.f) : 24.f;
            float rMinX = scrX - hitSz * 0.5f - pad;
            float rMinY = scrY - hitSz * 0.5f - pad;
            float rMaxX = scrX + hitSz * 0.5f + pad;
            float rMaxY = scrY + hitSz * 0.5f + pad;
            XMFLOAT3 camP = cam->GetPosition3f();
            float dx = pos.x - camP.x, dy = pos.y - camP.y, dz = pos.z - camP.z;
            float dist = sqrtf(dx * dx + dy * dy + dz * dz);
            topViewTooltipCandidates.push_back({ rMinX, rMinY, rMaxX, rMaxY, GetAgentLabel(ard), dist });
        }
    }

    // Top View: draw agent name tooltip on hover (skip when names already visible)
    if (m_topViewActive && !m_show3DLabels && !topViewTooltipCandidates.empty())
    {
        const float mx = mousePos.x, my = mousePos.y;
        int bestIdx = -1;
        float bestDist = FLT_MAX;
        for (size_t i = 0; i < topViewTooltipCandidates.size(); ++i)
        {
            const auto& c = topViewTooltipCandidates[i];
            if (mx >= c.rectMinX && mx <= c.rectMaxX && my >= c.rectMinY && my <= c.rectMaxY
                && c.dist < bestDist)
            {
                bestDist = c.dist;
                bestIdx = (int)i;
            }
        }
        if (bestIdx >= 0)
        {
            const auto& c = topViewTooltipCandidates[bestIdx];
            float iconCx = (c.rectMinX + c.rectMaxX) * 0.5f;
            float iconCy = (c.rectMinY + c.rectMaxY) * 0.5f;
            const float hitPad = 4.f;
            float iconTop = c.rectMinY + hitPad;
            float iconBottom = c.rectMaxY - hitPad;

            ImDrawList* fg = ImGui::GetForegroundDrawList();
            const char* text = c.name.c_str();
            ImVec2 textSize = font->CalcTextSizeA(11.f, FLT_MAX, 0.f, text);
            const float tPadH = 4.f, tPadV = 3.f;
            float tw = textSize.x + tPadH * 2.f;
            float th = textSize.y + tPadV * 2.f;
            const float gap = 8.f;

            float tx = iconCx - tw * 0.5f;
            float ty;
            if (iconTop - gap - th >= 0.f)
                ty = iconTop - gap - th;
            else
                ty = iconBottom + gap;
            if (tx + tw > vpW) tx = vpW - tw;
            if (tx < 0.f) tx = 0.f;
            if (ty + th > vpH) ty = vpH - th;
            if (ty < 0.f) ty = 0.f;

            ImVec2 tMin(tx, ty);
            ImVec2 tMax(tx + tw, ty + th);
            fg->AddRectFilled(tMin, tMax, IM_COL32(14, 20, 26, (int)(0.88f * 255)));
            fg->AddRect(tMin, tMax, IM_COL32(255, 255, 255, (int)(0.12f * 255)), 4.f);
            fg->AddText(font, 11.f, ImVec2(tx + tPadH, ty + tPadV), IM_COL32(0xf0, 0xf0, 0xf0, 255), text);
        }
    }
}

// Forward declarations for functions defined later in this file
static ImTextureID LoadFlagIcon(ID3D11Device* device, const char* filename);
static ImTextureID LoadNPCIcon(ID3D11Device* device, const char* filename);
static const AgentSnapshot* FindSnapshotAtTime(const AgentReplayData& ard, float t);

// ---------------------------------------------------------------------------
// Flag rendering — draw team-colored flag icons from FlagTimeline
// ---------------------------------------------------------------------------

void ReplayWindow::DrawFlags()
{
    if (!m_flagTimelineBuilt || !m_flagTimeline.valid) return;
    if (!m_agentsClassified) return;

    Camera* cam = m_mapRenderer->GetCamera();
    if (!cam) return;

    XMMATRIX viewProj = cam->GetView() * cam->GetProj();
    auto* vp = ImGui::GetMainViewport();
    float vpW = vp->Size.x;
    float vpH = vp->Size.y;
    const MapTransform& t = m_replayCtx.mapTransform;

    ImDrawList* dl = ImGui::GetForegroundDrawList();
    ID3D11Device* dev = m_deviceResources->GetD3DDevice();
    ImTextureID texBlue = LoadFlagIcon(dev, "Blue_flag_waving.svg.png");
    ImTextureID texRed  = LoadFlagIcon(dev, "Red_flag_waving.svg.png");
    const float iconSz = std::clamp(vpH * 0.035f, 18.f, 32.f);

    auto DrawFlagAt = [&](float worldX, float worldY, float worldZ,
                          ImTextureID tex, int teamIdx, const char* label)
    {
        XMFLOAT3 pos = ApplyMapTransformToPos(worldX, worldY, worldZ, t);
        float scrX, scrY;
        if (!ProjectToScreen(viewProj, vpW, vpH, pos, scrX, scrY)) return;

        constexpr float kFlagDotRadius = 5.f;
        ImU32 dotColor = (teamIdx == 0) ? IM_COL32(100, 160, 255, 200)
                                        : IM_COL32(255, 100, 90, 200);
        dl->AddCircleFilled(ImVec2(scrX, scrY), kFlagDotRadius, dotColor);
        dl->AddCircle(ImVec2(scrX, scrY), kFlagDotRadius, IM_COL32(0, 0, 0, 180), 0, 1.5f);

        if (tex)
        {
            float offsetY = iconSz * 0.8f;
            ImVec2 iconTL(scrX - iconSz * 0.5f, scrY - offsetY - iconSz);
            ImVec2 iconBR(iconTL.x + iconSz, iconTL.y + iconSz);
            dl->AddImage(tex, iconTL, iconBR);
        }

        if (label)
        {
            ImFont* font = ImGui::GetFont();
            float fontSize = font->FontSize;
            ImVec2 textSz = font->CalcTextSizeA(fontSize, FLT_MAX, 0.f, label);
            float tx = scrX - textSz.x * 0.5f;
            float offsetY = iconSz * 0.8f;
            float ty = scrY - offsetY - iconSz - fontSize - 2.f;
            dl->AddText(ImVec2(tx + 1.f, ty + 1.f), IM_COL32(0, 0, 0, 200), label);
            dl->AddText(ImVec2(tx, ty), IM_COL32(255, 255, 255, 230), label);
        }
    };

    // --- Captured flag on stand (pulsing glow + icon) ---
    StandOwner standOwner = m_flagTimeline.stand.ownerAtTime(m_debugTimeline);
    if (standOwner != StandOwner::Neutral)
    {
        int standTi = (standOwner == StandOwner::Blue) ? 0 : 1;
        ImTextureID standTex = (standTi == 0) ? texBlue : texRed;
        float sx = m_flagTimeline.stand.standX;
        float sy = m_flagTimeline.stand.standY;
        float sz = m_flagTimeline.stand.standZ;

        XMFLOAT3 standPos = ApplyMapTransformToPos(sx, sy, sz, t);
        float standScrX, standScrY;
        if (ProjectToScreen(viewProj, vpW, vpH, standPos, standScrX, standScrY) && standTex)
        {
            float offsetY = iconSz * 0.8f;
            ImVec2 iconTL(standScrX - iconSz * 0.5f, standScrY - offsetY - iconSz);
            ImVec2 iconBR(iconTL.x + iconSz, iconTL.y + iconSz);

            ImVec2 center((iconTL.x + iconBR.x) * 0.5f, (iconTL.y + iconBR.y) * 0.5f);
            float glowRadius = iconSz * 0.75f;
            float pulse = 0.6f + 0.4f * sinf((float)ImGui::GetTime() * 1.8f);
            ImU32 glowCol = (standTi == 0)
                ? IM_COL32(60, 130, 255, (int)(50 * pulse))
                : IM_COL32(255, 60, 50,  (int)(50 * pulse));
            dl->AddCircleFilled(center, glowRadius, glowCol, 32);
            dl->AddImage(standTex, iconTL, iconBR);
        }
    }

    // --- Active flag per team ---
    for (int ti = 0; ti < 2; ti++)
    {
        auto& ft = m_flagTimeline.teams[ti];
        if (ft.events.empty()) continue;

        ImTextureID tex = (ti == 0) ? texBlue : texRed;
        FlagLocation loc = ft.locationAtTime(m_debugTimeline);

        if (loc == FlagLocation::Stand) continue;

        float worldX = 0, worldY = 0, worldZ = 0;
        const char* label = nullptr;

        if (loc == FlagLocation::Carried)
        {
            int carrierId = ft.carrierAtTime(m_debugTimeline);
            if (carrierId >= 0)
            {
                auto it = m_replayCtx.agents.find(carrierId);
                if (it != m_replayCtx.agents.end() && !it->second.snapshots.empty())
                {
                    InterpolateAgentPosition(it->second, m_debugTimeline,
                                             m_replayCtx.interpSettings, worldX, worldY, worldZ);
                }
                else
                {
                    ft.positionAtTime(m_debugTimeline, worldX, worldY, worldZ);
                }
            }
            else
            {
                ft.positionAtTime(m_debugTimeline, worldX, worldY, worldZ);
            }
            label = "Flag (Carried)";
        }
        else
        {
            ft.positionAtTime(m_debugTimeline, worldX, worldY, worldZ);
            if (loc == FlagLocation::Ground)
                label = "Flag (Dropped)";
        }

        DrawFlagAt(worldX, worldY, worldZ, tex, ti, label);
    }
}

// ---------------------------------------------------------------------------
// Flag Debug Window — shows reconstructed FlagTimeline
// ---------------------------------------------------------------------------

static const char* FlagLocationName(FlagLocation loc)
{
    switch (loc) {
    case FlagLocation::Base:    return "Base";
    case FlagLocation::Carried: return "Carried";
    case FlagLocation::Ground:  return "Ground";
    case FlagLocation::Stand:   return "Stand";
    }
    return "?";
}

static const char* FlagEventTypeName(FlagTimelineEventType t)
{
    switch (t) {
    case FlagTimelineEventType::Spawn:       return "Spawn";
    case FlagTimelineEventType::Pickup:      return "Pickup";
    case FlagTimelineEventType::Drop:        return "Drop";
    case FlagTimelineEventType::Stick:       return "Stick";
    case FlagTimelineEventType::Return:      return "Return";
    case FlagTimelineEventType::GroundSpawn: return "GroundSpawn";
    }
    return "?";
}

static const char* StandOwnerName(StandOwner o)
{
    switch (o) {
    case StandOwner::Neutral: return "Neutral";
    case StandOwner::Blue:    return "Blue";
    case StandOwner::Red:     return "Red";
    }
    return "?";
}

void ReplayWindow::DrawFlagDebugWindow()
{
    ImGui::SetNextWindowSize(ImVec2(950, 650), ImGuiCond_FirstUseEver);
    if (!ImGui::Begin("Flag Timeline", &m_showFlagDebugWindow))
    {
        ImGui::End();
        return;
    }

    if (!m_flagTimelineBuilt || !m_flagTimeline.valid)
    {
        if (!m_replayCtx.stocLoaded)
            ImGui::TextWrapped("Waiting for StoC data to load...");
        else if (!m_agentsClassified)
            ImGui::TextWrapped("Waiting for agent classification...");
        else if (m_replayCtx.stocData.flagEvents.empty())
            ImGui::TextWrapped("No flag_events.txt data in this replay.");
        else
            ImGui::TextWrapped("Flag timeline not yet built.");
        ImGui::End();
        return;
    }

    float t = m_debugTimeline;
    char timeBuf[32];
    int sec = static_cast<int>(t);
    int ms  = static_cast<int>((t - sec) * 1000.f);
    snprintf(timeBuf, sizeof(timeBuf), "%02d:%02d.%03d", sec / 60, sec % 60, ms);

    // Current State Summary
    ImGui::SeparatorText("Current State");
    ImGui::Text("Playback: %s", timeBuf);

    for (int ti = 0; ti < 2; ti++)
    {
        const char* teamLabel = (ti == 0) ? "Blue" : "Red";
        auto& ft = m_flagTimeline.teams[ti];
        if (ft.events.empty()) {
            ImGui::Text("%s Flag: [no data]", teamLabel);
            continue;
        }
        FlagLocation loc = ft.locationAtTime(t);
        int carrierId = ft.carrierAtTime(t);
        float fx, fy, fz;
        ft.positionAtTime(t, fx, fy, fz);

        ImGui::Text("%s Flag: [%s] at (%.0f, %.0f, %.0f) | carrier %d | base (%.0f, %.0f)",
                    teamLabel, FlagLocationName(loc), fx, fy, fz, carrierId,
                    ft.spawnX, ft.spawnY);
    }

    StandOwner standOwner = m_flagTimeline.stand.ownerAtTime(t);
    ImGui::Text("Stand: %s (at %.0f, %.0f)", StandOwnerName(standOwner),
                m_flagTimeline.stand.standX, m_flagTimeline.stand.standY);
    ImGui::Spacing();

    // Merged Event Timeline
    if (ImGui::CollapsingHeader("All Events (chronological)", ImGuiTreeNodeFlags_DefaultOpen))
    {
        if (ImGui::BeginTable("##flag_tl_all", 8,
                ImGuiTableFlags_Borders | ImGuiTableFlags_RowBg |
                ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable,
                ImVec2(0, 250)))
        {
            ImGui::TableSetupScrollFreeze(0, 1);
            ImGui::TableSetupColumn("Time",     ImGuiTableColumnFlags_WidthFixed, 80.f);
            ImGui::TableSetupColumn("Team",     ImGuiTableColumnFlags_WidthFixed, 45.f);
            ImGui::TableSetupColumn("Event",    ImGuiTableColumnFlags_WidthFixed, 80.f);
            ImGui::TableSetupColumn("Location", ImGuiTableColumnFlags_WidthFixed, 65.f);
            ImGui::TableSetupColumn("Actor",    ImGuiTableColumnFlags_WidthFixed, 55.f);
            ImGui::TableSetupColumn("Carrier",  ImGuiTableColumnFlags_WidthFixed, 55.f);
            ImGui::TableSetupColumn("Position", ImGuiTableColumnFlags_WidthFixed, 150.f);
            ImGui::TableSetupColumn("Flag Agent", ImGuiTableColumnFlags_WidthStretch);
            ImGui::TableHeadersRow();

            ImGuiListClipper clipper;
            clipper.Begin(static_cast<int>(m_flagTimeline.allEvents.size()));
            while (clipper.Step())
            {
                for (int row = clipper.DisplayStart; row < clipper.DisplayEnd; row++)
                {
                    auto& ev = m_flagTimeline.allEvents[row];
                    ImGui::TableNextRow();

                    bool nearCurrent = (ev.time >= t - 1.f && ev.time <= t + 1.f);
                    if (nearCurrent)
                        ImGui::TableSetBgColor(ImGuiTableBgTarget_RowBg1, IM_COL32(80, 80, 40, 100));

                    int s = static_cast<int>(ev.time);
                    int m = static_cast<int>((ev.time - s) * 1000.f);

                    ImGui::TableNextColumn();
                    if (ImGui::Selectable(std::format("{:02d}:{:02d}.{:03d}##ftl{}", s/60, s%60, m, row).c_str(),
                                          false, ImGuiSelectableFlags_SpanAllColumns))
                        m_debugTimeline = ev.time;
                    ImGui::TableNextColumn();
                    ImGui::TextUnformatted(ev.flagTeam == FlagTeam::Blue ? "Blue" : "Red");
                    ImGui::TableNextColumn();
                    ImGui::TextUnformatted(FlagEventTypeName(ev.eventType));
                    ImGui::TableNextColumn();
                    ImGui::TextUnformatted(FlagLocationName(ev.newLocation));
                    ImGui::TableNextColumn();
                    if (ev.actorAgentId >= 0) ImGui::Text("%d", ev.actorAgentId);
                    else ImGui::TextUnformatted("-");
                    ImGui::TableNextColumn();
                    if (ev.carrierAgentId >= 0) ImGui::Text("%d", ev.carrierAgentId);
                    else ImGui::TextUnformatted("-");
                    ImGui::TableNextColumn();
                    ImGui::Text("%.0f, %.0f, %.0f", ev.x, ev.y, ev.z);
                    ImGui::TableNextColumn();
                    if (ev.flagWorldAgentId >= 0) ImGui::Text("%d", ev.flagWorldAgentId);
                    else if (ev.standAgentId >= 0) ImGui::Text("stand:%d", ev.standAgentId);
                    else ImGui::TextUnformatted("-");
                }
            }
            ImGui::EndTable();
        }
        ImGui::Spacing();
    }

    // Stand Control Timeline
    if (ImGui::CollapsingHeader("Stand Control Timeline", ImGuiTreeNodeFlags_DefaultOpen))
    {
        ImGui::Text("Stand Agent: %d  Position: (%.0f, %.0f, %.0f)",
                    m_flagTimeline.stand.standAgentId,
                    m_flagTimeline.stand.standX, m_flagTimeline.stand.standY, m_flagTimeline.stand.standZ);

        if (ImGui::BeginTable("##stand_tl", 4,
                ImGuiTableFlags_Borders | ImGuiTableFlags_RowBg |
                ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable,
                ImVec2(0, 150)))
        {
            ImGui::TableSetupScrollFreeze(0, 1);
            ImGui::TableSetupColumn("Time",          ImGuiTableColumnFlags_WidthFixed, 80.f);
            ImGui::TableSetupColumn("Owner",         ImGuiTableColumnFlags_WidthFixed, 60.f);
            ImGui::TableSetupColumn("Morale Expiry", ImGuiTableColumnFlags_WidthFixed, 100.f);
            ImGui::TableSetupColumn("Stand Agent",   ImGuiTableColumnFlags_WidthStretch);
            ImGui::TableHeadersRow();

            for (int i = 0; i < static_cast<int>(m_flagTimeline.stand.events.size()); i++)
            {
                auto& sc = m_flagTimeline.stand.events[i];
                ImGui::TableNextRow();

                bool nearCurrent = (sc.time >= t - 1.f && sc.time <= t + 1.f);
                if (nearCurrent)
                    ImGui::TableSetBgColor(ImGuiTableBgTarget_RowBg1, IM_COL32(80, 80, 40, 100));

                int s = static_cast<int>(sc.time);
                int m = static_cast<int>((sc.time - s) * 1000.f);

                ImGui::TableNextColumn();
                ImGui::Text("%02d:%02d.%03d", s/60, s%60, m);
                ImGui::TableNextColumn();
                ImGui::TextUnformatted(StandOwnerName(sc.owner));
                ImGui::TableNextColumn();
                if (sc.moraleExpiry > 0) {
                    int es = static_cast<int>(sc.moraleExpiry);
                    ImGui::Text("%02d:%02d", es/60, es%60);
                } else ImGui::TextUnformatted("-");
                ImGui::TableNextColumn();
                ImGui::Text("%d", sc.standAgentId);
            }
            ImGui::EndTable();
        }
        ImGui::Spacing();
    }

    // Per-Team Event Timelines
    for (int ti = 0; ti < 2; ti++)
    {
        const char* label = (ti == 0) ? "Blue Team Timeline" : "Red Team Timeline";
        if (!ImGui::CollapsingHeader(label, ImGuiTreeNodeFlags_DefaultOpen))
            continue;

        auto& ft = m_flagTimeline.teams[ti];
        ImGui::Text("  Base: (%.0f, %.0f, %.0f) | Events: %d",
                    ft.spawnX, ft.spawnY, ft.spawnZ, static_cast<int>(ft.events.size()));

        if (ImGui::BeginTable(std::format("##team_tl_{}", ti).c_str(), 7,
                ImGuiTableFlags_Borders | ImGuiTableFlags_RowBg |
                ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable,
                ImVec2(0, 180)))
        {
            ImGui::TableSetupScrollFreeze(0, 1);
            ImGui::TableSetupColumn("Time",     ImGuiTableColumnFlags_WidthFixed, 80.f);
            ImGui::TableSetupColumn("Event",    ImGuiTableColumnFlags_WidthFixed, 80.f);
            ImGui::TableSetupColumn("Location", ImGuiTableColumnFlags_WidthFixed, 65.f);
            ImGui::TableSetupColumn("Actor",    ImGuiTableColumnFlags_WidthFixed, 55.f);
            ImGui::TableSetupColumn("Carrier",  ImGuiTableColumnFlags_WidthFixed, 55.f);
            ImGui::TableSetupColumn("Position", ImGuiTableColumnFlags_WidthFixed, 150.f);
            ImGui::TableSetupColumn("Flag Agent", ImGuiTableColumnFlags_WidthStretch);
            ImGui::TableHeadersRow();

            for (int row = 0; row < static_cast<int>(ft.events.size()); row++)
            {
                auto& ev = ft.events[row];
                ImGui::TableNextRow();

                bool nearCurrent = (ev.time >= t - 1.f && ev.time <= t + 1.f);
                if (nearCurrent)
                    ImGui::TableSetBgColor(ImGuiTableBgTarget_RowBg1, IM_COL32(80, 80, 40, 100));

                int s = static_cast<int>(ev.time);
                int m = static_cast<int>((ev.time - s) * 1000.f);

                ImGui::TableNextColumn();
                if (ImGui::Selectable(std::format("{:02d}:{:02d}.{:03d}##ttl{}_{}", s/60, s%60, m, ti, row).c_str(),
                                      false, ImGuiSelectableFlags_SpanAllColumns))
                    m_debugTimeline = ev.time;
                ImGui::TableNextColumn();
                ImGui::TextUnformatted(FlagEventTypeName(ev.eventType));
                ImGui::TableNextColumn();
                ImGui::TextUnformatted(FlagLocationName(ev.newLocation));
                ImGui::TableNextColumn();
                if (ev.actorAgentId >= 0) ImGui::Text("%d", ev.actorAgentId);
                else ImGui::TextUnformatted("-");
                ImGui::TableNextColumn();
                if (ev.carrierAgentId >= 0) ImGui::Text("%d", ev.carrierAgentId);
                else ImGui::TextUnformatted("-");
                ImGui::TableNextColumn();
                ImGui::Text("%.0f, %.0f, %.0f", ev.x, ev.y, ev.z);
                ImGui::TableNextColumn();
                if (ev.flagWorldAgentId >= 0) ImGui::Text("%d", ev.flagWorldAgentId);
                else if (ev.standAgentId >= 0) ImGui::Text("stand:%d", ev.standAgentId);
                else ImGui::TextUnformatted("-");
            }
            ImGui::EndTable();
        }
        ImGui::Spacing();
    }

    ImGui::End();
}

// ---------------------------------------------------------------------------
// Asset Inspector / Blacklist debug panel
// ---------------------------------------------------------------------------

void ReplayWindow::SetPropHighlight(int propIndex, uint32_t state)
{
    if (propIndex < 0) return;
    auto meshIt = m_mapRenderer->GetPropsMeshIds().find(static_cast<uint32_t>(propIndex));
    if (meshIt == m_mapRenderer->GetPropsMeshIds().end()) return;
    for (int mid : meshIt->second)
    {
        auto data = m_mapRenderer->GetMeshManager()->GetMeshPerObjectData(mid);
        if (data.has_value()) {
            auto updated = data.value();
            updated.highlight_state = state;
            m_mapRenderer->GetMeshManager()->UpdateMeshPerObjectData(mid, updated);
        }
    }
}

void ReplayWindow::SetPickedProp(int newPropIndex)
{
    if (newPropIndex == m_pickedPropIndex) return;
    SetPropHighlight(m_pickedPropIndex, 0);
    m_pickedPropIndex = newPropIndex;
    SetPropHighlight(m_pickedPropIndex, 1);
}

void ReplayWindow::SetPropAlpha(int propIndex, float alpha)
{
    if (propIndex < 0) return;
    auto meshIt = m_mapRenderer->GetPropsMeshIds().find(static_cast<uint32_t>(propIndex));
    if (meshIt == m_mapRenderer->GetPropsMeshIds().end()) return;
    for (int mid : meshIt->second)
    {
        auto data = m_mapRenderer->GetMeshManager()->GetMeshPerObjectData(mid);
        if (data.has_value()) {
            auto updated = data.value();
            updated.mesh_alpha = alpha;
            m_mapRenderer->GetMeshManager()->UpdateMeshPerObjectData(mid, updated);
        }
    }
}

void ReplayWindow::DrawAssetInspectorWindow()
{
    ImGui::SetNextWindowSize(ImVec2(420, 520), ImGuiCond_FirstUseEver);
    if (!ImGui::Begin("Asset Inspector / Blacklist", &m_showAssetInspector))
    {
        if (!m_showAssetInspector) {
            SetPickedProp(-1);
            m_assetSelectionEnabled = false;
        }
        ImGui::End();
        return;
    }

    bool wasEnabled = m_assetSelectionEnabled;
    ImGui::Checkbox("Enable Asset Selection", &m_assetSelectionEnabled);
    if (wasEnabled && !m_assetSelectionEnabled)
        SetPickedProp(-1);
    if (m_assetSelectionEnabled)
        ImGui::TextDisabled("Left-click on the map to select an asset");

    ImGui::Separator();

    const auto& propsInfo = m_mapFile.props_info_chunk.prop_array.props_info;
    const auto& propFN = m_mapFile.prop_filenames_chunk.array;
    const auto& moreFN = m_mapFile.more_filnames_chunk.array;

    // --- Selected asset info ---
    if (m_pickedPropIndex >= 0 && m_pickedPropIndex < static_cast<int>(propsInfo.size()))
    {
        ImGui::SeparatorText("Selected Asset");

        const auto& prop = propsInfo[m_pickedPropIndex];
        ImGui::Text("Prop Index: %d", m_pickedPropIndex);
        ImGui::Text("Filename Index: %u", static_cast<unsigned>(prop.filename_index));
        ImGui::Text("Position: (%.1f, %.1f, %.1f)", prop.x, prop.y, prop.z);
        ImGui::Text("Scale: %.3f", prop.scaling_factor);

        int fnIdx = static_cast<int>(prop.filename_index);
        int totalFN = static_cast<int>(propFN.size() + moreFN.size());
        if (fnIdx >= 0 && fnIdx < totalFN)
        {
            const auto& fn = (fnIdx < static_cast<int>(propFN.size()))
                ? propFN[fnIdx] : moreFN[fnIdx - static_cast<int>(propFN.size())];
            auto datHash = decode_filename(fn.filename.id0, fn.filename.id1);
            ImGui::Text("DAT Hash: 0x%X", datHash);
        }

        auto& blacklist = AssetBlacklist::Get();
        uint32_t selIdx = static_cast<uint32_t>(m_pickedPropIndex);
        bool alreadyBlacklisted = blacklist.HasEntry(selIdx);
        if (alreadyBlacklisted)
        {
            ImGui::TextColored(ImVec4(1.f, 0.6f, 0.2f, 1.f), "Already blacklisted");
        }
        else
        {
            bool hasAlpha = blacklist.HasAlphaOverride(selIdx);
            if (ImGui::Button("Blacklist Asset"))
            {
                blacklist.SetEntry(selIdx, true);
                auto meshIt = m_mapRenderer->GetPropsMeshIds().find(selIdx);
                if (meshIt != m_mapRenderer->GetPropsMeshIds().end())
                {
                    for (int mid : meshIt->second)
                        m_mapRenderer->GetMeshManager()->SetMeshShouldRender(mid, false);
                }
            }
            ImGui::SameLine();
            if (!hasAlpha)
            {
                if (ImGui::Button("Make Transparent"))
                {
                    blacklist.SetAlpha(selIdx, 0.3f);
                    SetPropAlpha(m_pickedPropIndex, 0.3f);
                }
            }
            else
            {
                if (ImGui::SmallButton("Reset Opacity"))
                {
                    blacklist.RemoveAlpha(selIdx);
                    SetPropAlpha(m_pickedPropIndex, 1.0f);
                }
            }

            if (hasAlpha)
            {
                float alpha = blacklist.GetAlpha(selIdx);
                ImGui::SetNextItemWidth(-1);
                if (ImGui::SliderFloat("##opacity", &alpha, 0.0f, 1.0f, "Opacity: %.2f"))
                {
                    blacklist.SetAlpha(selIdx, alpha);
                    SetPropAlpha(m_pickedPropIndex, alpha);
                }
            }
        }
    }
    else
    {
        ImGui::TextDisabled("No asset selected");
    }

    ImGui::Separator();

    // --- Blacklisted assets list ---
    ImGui::SeparatorText("Blacklisted Assets");
    ImGui::Text("Map ID: %d", m_replayCtx.mapId);

    auto& blacklist = AssetBlacklist::Get();
    const auto& entries = blacklist.GetEntries();

    if (entries.empty())
    {
        ImGui::TextDisabled("No blacklisted assets for this map");
    }
    else
    {
        // Sort entries by prop index for stable display order
        std::vector<uint32_t> sortedKeys;
        sortedKeys.reserve(entries.size());
        for (auto& [k, _] : entries)
            sortedKeys.push_back(k);
        std::sort(sortedKeys.begin(), sortedKeys.end());

        for (uint32_t propIdx : sortedKeys)
        {
            auto entryIt = entries.find(propIdx);
            if (entryIt == entries.end()) continue;

            ImGui::PushID(static_cast<int>(propIdx));

            bool hidden = entryIt->second;
            if (ImGui::Checkbox("##hidden", &hidden))
            {
                blacklist.SetEntry(propIdx, hidden);
                auto meshIt = m_mapRenderer->GetPropsMeshIds().find(propIdx);
                if (meshIt != m_mapRenderer->GetPropsMeshIds().end())
                {
                    for (int mid : meshIt->second)
                        m_mapRenderer->GetMeshManager()->SetMeshShouldRender(mid, !hidden);
                }
            }
            ImGui::SameLine();
            ImGui::Text("#%u", propIdx);

            if (propIdx < propsInfo.size())
            {
                const auto& prop = propsInfo[propIdx];
                ImGui::SameLine();
                ImGui::TextDisabled("(%.0f, %.0f, %.0f)", prop.x, prop.y, prop.z);
            }

            ImGui::SameLine();
            if (ImGui::SmallButton("Remove"))
            {
                blacklist.RemoveEntry(propIdx);
                auto meshIt = m_mapRenderer->GetPropsMeshIds().find(propIdx);
                if (meshIt != m_mapRenderer->GetPropsMeshIds().end())
                {
                    for (int mid : meshIt->second)
                        m_mapRenderer->GetMeshManager()->SetMeshShouldRender(mid, true);
                }
                ImGui::PopID();
                break;
            }

            ImGui::PopID();
        }
    }

    ImGui::Separator();

    // --- Transparent assets list ---
    ImGui::SeparatorText("Transparent Assets");

    const auto& alphaEntries = blacklist.GetAlphaEntries();

    if (alphaEntries.empty())
    {
        ImGui::TextDisabled("No transparency overrides for this map");
    }
    else
    {
        std::vector<uint32_t> alphaSortedKeys;
        alphaSortedKeys.reserve(alphaEntries.size());
        for (auto& [k, _] : alphaEntries)
            alphaSortedKeys.push_back(k);
        std::sort(alphaSortedKeys.begin(), alphaSortedKeys.end());

        for (uint32_t propIdx : alphaSortedKeys)
        {
            auto alphaIt = alphaEntries.find(propIdx);
            if (alphaIt == alphaEntries.end()) continue;

            ImGui::PushID(static_cast<int>(propIdx) + 100000);

            float alpha = alphaIt->second;
            ImGui::Text("#%u", propIdx);
            if (propIdx < propsInfo.size())
            {
                ImGui::SameLine();
                ImGui::TextDisabled("(%.0f, %.0f, %.0f)",
                    propsInfo[propIdx].x, propsInfo[propIdx].y, propsInfo[propIdx].z);
            }
            ImGui::SetNextItemWidth(200.f);
            if (ImGui::SliderFloat("##alpha", &alpha, 0.0f, 1.0f, "%.2f"))
            {
                blacklist.SetAlpha(propIdx, alpha);
                SetPropAlpha(static_cast<int>(propIdx), alpha);
            }
            ImGui::SameLine();
            if (ImGui::SmallButton("Remove"))
            {
                blacklist.RemoveAlpha(propIdx);
                SetPropAlpha(static_cast<int>(propIdx), 1.0f);
                ImGui::PopID();
                break;
            }

            ImGui::PopID();
        }
    }

    ImGui::End();
}

// ---------------------------------------------------------------------------
// ResolveAgentAtTime — find the correct incarnation entry for a given agent_id
// and timestamp, accounting for agent ID recycling.
// ---------------------------------------------------------------------------

int ReplayWindow::ResolveAgentAtTime(int agentId, float time) const
{
    constexpr float kTol = 0.5f;

    auto it = m_replayCtx.agents.find(agentId);
    if (it != m_replayCtx.agents.end())
    {
        const auto& ard = it->second;
        if (ard.lifecycleStart >= 0)
        {
            float t0 = ard.lifecycleStart - kTol;
            float t1 = (ard.lifecycleEnd >= 0) ? ard.lifecycleEnd + kTol : FLT_MAX;
            if (time >= t0 && time <= t1)
                return agentId;
        }
        else if (!ard.snapshots.empty())
        {
            float t0 = ard.snapshots.front().time - kTol;
            float t1 = ard.snapshots.back().time + kTol;
            if (time >= t0 && time <= t1)
                return agentId;
        }
    }

    auto incIt = m_incarnationMap.find(agentId);
    if (incIt != m_incarnationMap.end())
    {
        for (int sid : incIt->second)
        {
            auto sit = m_replayCtx.agents.find(sid);
            if (sit == m_replayCtx.agents.end()) continue;
            const auto& sard = sit->second;
            if (sard.lifecycleStart >= 0)
            {
                float t0 = sard.lifecycleStart - kTol;
                float t1 = (sard.lifecycleEnd >= 0) ? sard.lifecycleEnd + kTol : FLT_MAX;
                if (time >= t0 && time <= t1)
                    return sid;
            }
            else if (!sard.snapshots.empty())
            {
                float t0 = sard.snapshots.front().time - kTol;
                float t1 = sard.snapshots.back().time + kTol;
                if (time >= t0 && time <= t1)
                    return sid;
            }
        }
    }

    return agentId;
}

// ---------------------------------------------------------------------------
// Bundle carry timeline — correlate lifecycle events with weapon_type transitions
// to build per-player intervals of what bundle they are holding.
// ---------------------------------------------------------------------------

void ReplayWindow::BuildBundleCarryTimeline()
{
    m_bundleCarryBuilt = true;
    m_bundleCarry.clear();
    m_itemRemoveTime.clear();
    m_leverCaps.clear();
    m_vineBridgeEvents.clear();

    const int mapId = m_replayCtx.mapId;

    // Index lifecycle AGENT_REMOVE events by agent_id for quick lookup.
    // When an item agent is removed, it was picked up by a nearby player.
    // We also track AGENT_ADD events to know item spawn/respawn positions.
    struct ItemLifecycle {
        float addTime    = -1.f;
        float removeTime = -1.f;
        float addX = 0, addY = 0;
        uint32_t agentType = 0;
        int      typeCode  = 0;
    };
    // agent_id -> list of incarnations (add/remove pairs)
    std::unordered_map<int, std::vector<ItemLifecycle>> itemLifecycles;

    for (auto& ev : m_replayCtx.stocData.lifecycle)
    {
        if (ev.isAdd)
        {
            ItemLifecycle il;
            il.addTime   = ev.time;
            il.addX      = ev.x;
            il.addY      = ev.y;
            il.agentType = ev.agent_type;
            il.typeCode  = ev.type_code;
            itemLifecycles[ev.agent_id].push_back(il);
        }
        else
        {
            auto& vec = itemLifecycles[ev.agent_id];
            if (!vec.empty() && vec.back().removeTime < 0)
                vec.back().removeTime = ev.time;
        }
    }

    // Build m_itemRemoveTime from lifecycle AGENT_REMOVE events for item agents
    for (auto& [agentId, lifecycles] : itemLifecycles)
    {
        for (auto& lc : lifecycles)
        {
            if (lc.removeTime >= 0)
                m_itemRemoveTime[agentId] = lc.removeTime;
        }
    }

    // Build item_id -> BundleType map from known item agents
    std::unordered_map<uint32_t, BundleType> itemIdBundleType;
    for (auto& [id, ard] : m_replayCtx.agents)
    {
        if (ard.type != AgentType::Flag && ard.type != AgentType::Item) continue;
        if (ard.snapshots.empty()) continue;
        uint32_t iid = ard.snapshots.front().item_id;
        if (iid == 0) continue;
        BundleType bt = LookupBundleType(mapId, iid);
        if (bt != BundleType::Unknown)
            itemIdBundleType[iid] = bt;
    }

    // Scan all players for weapon_type transitions: non-0 -> 0 = pickup, 0 -> non-0 = drop/consume
    auto allPlayers = m_team1PlayerIds;
    allPlayers.insert(allPlayers.end(), m_team2PlayerIds.begin(), m_team2PlayerIds.end());

    for (int pid : allPlayers)
    {
        auto it = m_replayCtx.agents.find(pid);
        if (it == m_replayCtx.agents.end()) continue;
        const auto& ard = it->second;
        const auto& snaps = ard.snapshots;
        if (snaps.size() < 2) continue;

        for (size_t si = 1; si < snaps.size(); si++)
        {
            const auto& prev = snaps[si - 1];
            const auto& cur  = snaps[si];

            // Pickup: weapon_type was non-0, now 0 (and weapon_item_type == 46)
            if (prev.weapon_type != 0 && cur.weapon_type == 0 && cur.weapon_item_type == 46)
            {
                BundleCarryInterval bci;
                bci.startTime = cur.time;

                // Try to classify: look at which item agent disappeared around this time
                BundleType classified = BundleType::Unknown;
                float bestDist = FLT_MAX;
                int bestItemAgent = -1;

                for (auto& [itemAgentId, lifecycles] : itemLifecycles)
                {
                    for (auto& lc : lifecycles)
                    {
                        if (lc.removeTime < 0) continue;
                        if (std::abs(lc.removeTime - cur.time) > 2.f) continue;
                        float dx = lc.addX - cur.x;
                        float dy = lc.addY - cur.y;
                        float dsq = dx * dx + dy * dy;
                        if (dsq < bestDist)
                        {
                            bestDist = dsq;
                            bestItemAgent = itemAgentId;
                        }
                    }
                }

                // If we found a lifecycle match, look up the item_id from snapshot data
                if (bestItemAgent >= 0)
                {
                    auto ait = m_replayCtx.agents.find(bestItemAgent);
                    if (ait != m_replayCtx.agents.end() && !ait->second.snapshots.empty())
                    {
                        uint32_t iid = ait->second.snapshots.front().item_id;
                        auto btIt = itemIdBundleType.find(iid);
                        if (btIt != itemIdBundleType.end())
                            classified = btIt->second;
                    }
                    bci.itemAgentId = bestItemAgent;
                }

                // Fallback: if we're on a map with no vine seeds and no repair kits, it's a flag
                if (classified == BundleType::Unknown)
                    classified = BundleType::Flag;

                bci.type = classified;

                // Find the end: scan forward for weapon_type going back to non-0
                for (size_t ej = si + 1; ej < snaps.size(); ej++)
                {
                    if (snaps[ej].weapon_type != 0)
                    {
                        bci.endTime = snaps[ej].time;
                        break;
                    }
                }

                m_bundleCarry[pid].push_back(bci);
            }
        }
    }

    // Process MAP_OBJECT events for lever caps and vine bridge activations
    for (auto& moe : m_replayCtx.stocData.mapObject)
    {
        if (moe.isState) continue;

        // Lever cap: animation_type=2, animation_stage=2
        if (moe.animation_type == 2 && moe.animation_stage == 2)
        {
            LeverCapEvent lce;
            lce.time     = moe.time;
            lce.objectId = moe.object_id;

            // Find the player who just dropped the repair kit at this time
            for (int pid : allPlayers)
            {
                auto& intervals = m_bundleCarry[pid];
                for (auto& bci : intervals)
                {
                    if (bci.type != BundleType::RepairKit) continue;
                    if (std::abs(bci.endTime - moe.time) > 2.f) continue;
                    auto pit = m_replayCtx.agents.find(pid);
                    if (pit == m_replayCtx.agents.end()) continue;
                    const auto& psnap = *FindSnapshotAtTime(pit->second, bci.endTime);
                    lce.x = psnap.x;
                    lce.y = psnap.y;
                    lce.z = psnap.z;
                    lce.teamIdx = (pit->second.teamId == 1) ? 0 : 1;
                    break;
                }
                if (lce.teamIdx >= 0) break;
            }

            m_leverCaps.push_back(lce);
        }

        // Vine bridge activation: animation_type=16, animation_stage=2
        if (moe.animation_type == 16 && moe.animation_stage == 2)
        {
            VineBridgeEvent vbe;
            vbe.time     = moe.time;
            vbe.objectId = moe.object_id;

            for (int pid : allPlayers)
            {
                auto& intervals = m_bundleCarry[pid];
                for (auto& bci : intervals)
                {
                    if (bci.type != BundleType::VineSeed) continue;
                    if (std::abs(bci.endTime - moe.time) > 2.f) continue;
                    auto pit = m_replayCtx.agents.find(pid);
                    if (pit == m_replayCtx.agents.end()) continue;
                    const auto& psnap = *FindSnapshotAtTime(pit->second, bci.endTime);
                    vbe.x = psnap.x;
                    vbe.y = psnap.y;
                    vbe.z = psnap.z;
                    vbe.teamIdx = (pit->second.teamId == 1) ? 0 : 1;
                    break;
                }
                if (vbe.teamIdx >= 0) break;
            }

            m_vineBridgeEvents.push_back(vbe);
        }
    }

    // Build catapult lever state machines (Warrior's Isle only)
    m_catapultStates.clear();
    if (m_replayCtx.mapId == kWarriorsIsleMapId)
    {
        for (auto& moe : m_replayCtx.stocData.mapObject)
        {
            if (moe.isState) continue;
            if (moe.animation_stage != 2) continue;

            CatapultState cs = CatapultState::Unknown;
            if (moe.animation_type == 2)
                cs = CatapultState::Repaired;
            else if (moe.animation_type == 17)
                cs = CatapultState::Loaded;
            else if (moe.animation_type == 12)
                cs = CatapultState::Fired;

            if (cs != CatapultState::Unknown)
                m_catapultStates[moe.object_id].AddEvent(moe.time, cs);
        }

        for (auto& [objId, state] : m_catapultStates)
            state.Finalize();
    }
}

// ---------------------------------------------------------------------------
// Query the bundle type a player is carrying at a given time
// ---------------------------------------------------------------------------

BundleType ReplayWindow::GetPlayerBundleType(int agentId, float time) const
{
    auto it = m_bundleCarry.find(agentId);
    if (it == m_bundleCarry.end()) return BundleType::Unknown;

    for (auto& bci : it->second)
    {
        if (time >= bci.startTime && time < bci.endTime)
            return bci.type;
    }
    return BundleType::Unknown;
}

// ---------------------------------------------------------------------------
// Render carried bundle items (repair kits, vine seeds) and capped indicators
// ---------------------------------------------------------------------------

void ReplayWindow::DrawBundleItems()
{
    if (!m_bundleCarryBuilt) return;
    if (!m_agentsClassified) return;

    const auto& t = m_replayCtx.mapTransform;
    Camera* cam = m_mapRenderer->GetCamera();
    if (!cam) return;

    auto* vp = ImGui::GetMainViewport();
    float vpW = vp->Size.x;
    float vpH = vp->Size.y;

    XMMATRIX viewProj = cam->GetView() * cam->GetProj();
    ImDrawList* dl = ImGui::GetForegroundDrawList();
    ID3D11Device* dev = m_deviceResources->GetD3DDevice();

    const float iconSz = std::clamp(vpH * 0.035f, 18.f, 32.f);

    // 1. Draw carried repair kits and vine seeds above the carrier
    auto allPlayers = m_team1PlayerIds;
    allPlayers.insert(allPlayers.end(), m_team2PlayerIds.begin(), m_team2PlayerIds.end());

    for (int pid : allPlayers)
    {
        BundleType bt = GetPlayerBundleType(pid, m_debugTimeline);
        if (bt != BundleType::RepairKit && bt != BundleType::VineSeed) continue;

        auto it = m_replayCtx.agents.find(pid);
        if (it == m_replayCtx.agents.end() || it->second.snapshots.empty()) continue;

        float cx, cy, cz;
        InterpolateAgentPosition(it->second, m_debugTimeline, m_replayCtx.interpSettings, cx, cy, cz);

        XMFLOAT3 pos = ApplyMapTransformToPos(cx, cy, cz, t);
        float scrX, scrY;
        if (!ProjectToScreen(viewProj, vpW, vpH, pos, scrX, scrY)) continue;

        const char* iconFile = (bt == BundleType::RepairKit) ? "RepairKit.png" : "Vine Seed.png";
        ImTextureID tex = LoadNPCIcon(dev, iconFile);
        if (!tex) continue;

        float offsetY = iconSz * 0.8f;
        ImVec2 iconTL(scrX - iconSz * 0.5f, scrY - offsetY - iconSz);
        ImVec2 iconBR(iconTL.x + iconSz, iconTL.y + iconSz);
        dl->AddImage(tex, iconTL, iconBR);

        const char* label = (bt == BundleType::RepairKit) ? "Repair Kit" : "Vine Seed";
        ImFont* font = ImGui::GetFont();
        ImVec2 textSz = font->CalcTextSizeA(font->FontSize, FLT_MAX, 0.f, label);
        float tx = scrX - textSz.x * 0.5f;
        float ty = iconBR.y + 2.f;
        dl->AddText(ImVec2(tx + 1.f, ty + 1.f), IM_COL32(0, 0, 0, 200), label);
        dl->AddText(ImVec2(tx, ty), IM_COL32(255, 255, 255, 230), label);
    }

    // 2. Draw capped lever indicators (permanent after capping)
    for (auto& lc : m_leverCaps)
    {
        if (m_debugTimeline < lc.time) continue;
        if (lc.x == 0 && lc.y == 0) continue;

        ImTextureID tex = LoadNPCIcon(dev, "Lever.png");
        if (!tex) continue;

        XMFLOAT3 pos = ApplyMapTransformToPos(lc.x, lc.y, lc.z, t);
        float scrX, scrY;
        if (!ProjectToScreen(viewProj, vpW, vpH, pos, scrX, scrY)) continue;

        float leverSz = iconSz * 1.2f;
        ImVec2 iconTL(scrX - leverSz * 0.5f, scrY - leverSz);
        ImVec2 iconBR(iconTL.x + leverSz, iconTL.y + leverSz);
        dl->AddImage(tex, iconTL, iconBR);

        auto csIt = m_catapultStates.find(lc.objectId);
        if (csIt != m_catapultStates.end() && m_replayCtx.mapId == kWarriorsIsleMapId)
        {
            const CatapultLeverState& cls = csIt->second;
            std::string labelStr = cls.GetLabelText(m_debugTimeline);
            ImU32 labelCol       = cls.GetLabelColor(m_debugTimeline);
            float glowOpacity    = cls.GetGlowOpacity(m_debugTimeline);
            ImU32 glowCol        = cls.GetGlowColor(m_debugTimeline);
            CatapultState cState = cls.GetState(m_debugTimeline);

            // Glow rings (concentric circles around the icon center)
            if (glowOpacity > 0.01f)
            {
                float cx = (iconTL.x + iconBR.x) * 0.5f;
                float cy = (iconTL.y + iconBR.y) * 0.5f;
                uint8_t gr = (glowCol >> IM_COL32_R_SHIFT) & 0xFF;
                uint8_t gg = (glowCol >> IM_COL32_G_SHIFT) & 0xFF;
                uint8_t gb = (glowCol >> IM_COL32_B_SHIFT) & 0xFF;

                float r1 = leverSz * 0.6f;
                float r2 = leverSz * 0.9f;
                float r3 = leverSz * 1.2f;
                dl->AddCircle(ImVec2(cx, cy), r1,
                    IM_COL32(gr, gg, gb, (uint8_t)(glowOpacity * 255)), 0, 2.0f);
                dl->AddCircle(ImVec2(cx, cy), r2,
                    IM_COL32(gr, gg, gb, (uint8_t)(glowOpacity * 0.5f * 255)), 0, 1.5f);
                dl->AddCircle(ImVec2(cx, cy), r3,
                    IM_COL32(gr, gg, gb, (uint8_t)(glowOpacity * 0.25f * 255)), 0, 1.0f);
            }

            ImFont* font = ImGui::GetFont();
            float fontSize = font->FontSize;
            if (cState == CatapultState::Impact)
                fontSize += 2.f;

            ImVec2 textSz = font->CalcTextSizeA(fontSize, FLT_MAX, 0.f, labelStr.c_str());
            float tx = scrX - textSz.x * 0.5f;
            float ty = iconBR.y + 2.f;
            dl->AddText(font, fontSize, ImVec2(tx + 1.f, ty + 1.f),
                        IM_COL32(0, 0, 0, 200), labelStr.c_str());
            dl->AddText(font, fontSize, ImVec2(tx, ty), labelCol, labelStr.c_str());
        }
        else
        {
            const char* label = "Lever (Capped)";
            ImFont* font = ImGui::GetFont();
            ImVec2 textSz = font->CalcTextSizeA(font->FontSize, FLT_MAX, 0.f, label);
            float tx = scrX - textSz.x * 0.5f;
            float ty = iconBR.y + 2.f;
            dl->AddText(ImVec2(tx + 1.f, ty + 1.f), IM_COL32(0, 0, 0, 200), label);
            dl->AddText(ImVec2(tx, ty), IM_COL32(255, 255, 255, 230), label);
        }
    }

    // 3. Draw activated vine bridge indicators
    for (auto& vb : m_vineBridgeEvents)
    {
        if (m_debugTimeline < vb.time) continue;
        if (vb.x == 0 && vb.y == 0) continue;

        ImTextureID tex = LoadNPCIcon(dev, "Vine Seed.png");
        if (!tex) continue;

        XMFLOAT3 pos = ApplyMapTransformToPos(vb.x, vb.y, vb.z, t);
        float scrX, scrY;
        if (!ProjectToScreen(viewProj, vpW, vpH, pos, scrX, scrY)) continue;

        float bridgeSz = iconSz * 1.2f;
        ImVec2 iconTL(scrX - bridgeSz * 0.5f, scrY - bridgeSz);
        ImVec2 iconBR(iconTL.x + bridgeSz, iconTL.y + bridgeSz);
        dl->AddImage(tex, iconTL, iconBR);

        const char* label = "Bridge (Grown)";
        ImFont* font = ImGui::GetFont();
        ImVec2 textSz = font->CalcTextSizeA(font->FontSize, FLT_MAX, 0.f, label);
        float tx = scrX - textSz.x * 0.5f;
        float ty = iconBR.y + 2.f;
        dl->AddText(ImVec2(tx + 1.f, ty + 1.f), IM_COL32(0, 0, 0, 200), label);
        dl->AddText(ImVec2(tx, ty), IM_COL32(255, 255, 255, 230), label);
    }
}

// ---------------------------------------------------------------------------
// Skill Lasers: animated dashed line from caster → target
// ---------------------------------------------------------------------------

void ReplayWindow::DrawSkillLasers()
{
    if (!m_showSkillLasers) return;
    if (!m_skillUseTimelineBuilt) return;
    if (!m_agentsClassified || m_replayCtx.agents.empty()) return;

    Camera* cam = m_mapRenderer->GetCamera();
    XMMATRIX viewProj = cam->GetView() * cam->GetProj();
    auto vp = m_deviceResources->GetScreenViewport();
    float vpW = vp.Width, vpH = vp.Height;
    const auto& t = m_replayCtx.mapTransform;

    const InterpolationSettings& is = m_replayCtx.interpSettings;

    ImDrawList* dl = ImGui::GetForegroundDrawList();
    float dpi = std::max(1.f, vpH / 1080.f);
    float curTime = (float)ImGui::GetTime();

    for (auto& [agentId, ard] : m_replayCtx.agents)
    {
        if (ard.type != AgentType::Player && ard.type != AgentType::NPC) continue;
        if (ard.isDeadAtTime(m_debugTimeline)) continue;

        auto laser = ard.skillLaserAtTime(m_debugTimeline);
        if (laser.targetId <= 0 || laser.alpha <= 0.f) continue;

        auto tit = m_replayCtx.agents.find(laser.targetId);
        if (tit == m_replayCtx.agents.end()) continue;
        auto& targ = tit->second;

        // Caster position
        float cx, cy, cz;
        InterpolateAgentPosition(ard, m_debugTimeline, is, cx, cy, cz);
        XMFLOAT3 casterWorld = ApplyMapTransformToPos(cx, cy, cz, t);
        casterWorld.y += 60.f;

        float cScrX, cScrY;
        if (!ProjectToScreen(viewProj, vpW, vpH, casterWorld, cScrX, cScrY)) continue;

        // Target position
        float txp, typ, tzp;
        InterpolateAgentPosition(targ, m_debugTimeline, is, txp, typ, tzp);
        XMFLOAT3 targetWorld = ApplyMapTransformToPos(txp, typ, tzp, t);
        targetWorld.y += 60.f;

        float tScrX, tScrY;
        if (!ProjectToScreen(viewProj, vpW, vpH, targetWorld, tScrX, tScrY)) continue;

        // LOD check: skip if caster is far and in dot LOD
        if (m_uiLayout.lodEnabled && ard.currentLOD == 0)
        {
            XMFLOAT3 camPos;
            XMStoreFloat3(&camPos, cam->GetPosition());
            float dx = casterWorld.x - camPos.x;
            float dy = casterWorld.y - camPos.y;
            float dz2 = casterWorld.z - camPos.z;
            float dist = sqrtf(dx * dx + dy * dy + dz2 * dz2);
            if (dist > m_uiLayout.lodDotDist * 1.5f) continue;
        }

        // Determine ally vs enemy
        bool isEnemy = (ard.teamId != targ.teamId);
        ImU32 laserCol, glowCol;
        int lR, lG, lB;
        if (isEnemy)
        {
            lR = 255; lG = 60; lB = 60;
            laserCol = IM_COL32(255, 60, 60, (ImU8)(255 * laser.alpha));
            glowCol  = IM_COL32(255, 60, 60, (ImU8)(120 * laser.alpha));
        }
        else
        {
            lR = 60; lG = 255; lB = 120;
            laserCol = IM_COL32(60, 255, 120, (ImU8)(255 * laser.alpha));
            glowCol  = IM_COL32(60, 255, 120, (ImU8)(120 * laser.alpha));
        }

        ImVec2 A(cScrX, cScrY), B(tScrX, tScrY);
        float lineLen = sqrtf((B.x - A.x) * (B.x - A.x) + (B.y - A.y) * (B.y - A.y));
        if (lineLen < 2.f) continue;

        ImVec2 dir((B.x - A.x) / lineLen, (B.y - A.y) / lineLen);

        // Glow layers (continuous line behind dashes)
        for (int g = 1; g <= 3; ++g)
        {
            float thick = (1.0f + g * 0.8f) * dpi;
            ImU32 gc = IM_COL32(lR, lG, lB, (ImU8)(std::max(0.f, 30.f / g * laser.alpha)));
            dl->AddLine(A, B, gc, thick);
        }

        // Flowing dashes (caster → target direction)
        float dashLen = 14.f * dpi;
        float gapLen  = 8.f * dpi;
        float period  = dashLen + gapLen;
        float anim    = fmodf(curTime * 0.8f, 1.f);
        float offset  = anim * period;

        for (float d = offset - period; d < lineLen; d += period)
        {
            float s0 = std::clamp(d, 0.f, lineLen);
            float s1 = std::clamp(d + dashLen, 0.f, lineLen);
            if (s1 - s0 < 1.f) continue;
            ImVec2 p0(A.x + dir.x * s0, A.y + dir.y * s0);
            ImVec2 p1(A.x + dir.x * s1, A.y + dir.y * s1);
            dl->AddLine(p0, p1, laserCol, 1.2f * dpi);
        }

        // Arrowhead at target
        float arrowSz = 10.f * dpi;
        ImVec2 perp(-dir.y, dir.x);
        ImVec2 tip = B;
        ImVec2 left(B.x - dir.x * arrowSz + perp.x * arrowSz * 0.6f,
                     B.y - dir.y * arrowSz + perp.y * arrowSz * 0.6f);
        ImVec2 right(B.x - dir.x * arrowSz - perp.x * arrowSz * 0.6f,
                      B.y - dir.y * arrowSz - perp.y * arrowSz * 0.6f);
        dl->AddTriangleFilled(tip, left, right, laserCol);

        // Breathing target highlight ring at cylinder base (3D projected)
        constexpr float CYL_R       = 30.f;
        constexpr float RING_R      = CYL_R + 5.f;
        constexpr int   RING_SEGS   = 48;
        constexpr float DASH_RATIO  = 0.35f;
        constexpr float PI2         = 6.2831853f;

        float pulse = 0.5f + 0.5f * sinf(curTime * 4.f);
        ImU32 ringCol = IM_COL32(
            (int)(lR * (0.7f + 0.3f * pulse)),
            (int)(lG * (0.7f + 0.3f * pulse)),
            (int)(lB * (0.7f + 0.3f * pulse)),
            (ImU8)(220 * laser.alpha));

        // Base of the cylinder (targetWorld.y was offset +60, remove it and add small lift)
        float baseY = targetWorld.y - 60.f + 0.05f;

        for (int i = 0; i < RING_SEGS; ++i)
        {
            float a0 = (float(i) / RING_SEGS) * PI2;
            float a1 = (float(i + 1) / RING_SEGS) * PI2;
            float mid = (a0 + a1) * 0.5f;
            float sa = a0 + (mid - a0) * (1.f - DASH_RATIO);
            float ea = mid + (a1 - mid) * DASH_RATIO;

            XMFLOAT3 wp0 = { targetWorld.x + RING_R * cosf(sa), baseY, targetWorld.z + RING_R * sinf(sa) };
            XMFLOAT3 wp1 = { targetWorld.x + RING_R * cosf(ea), baseY, targetWorld.z + RING_R * sinf(ea) };
            float sx0, sy0, sx1, sy1;
            if (ProjectToScreen(viewProj, vpW, vpH, wp0, sx0, sy0) &&
                ProjectToScreen(viewProj, vpW, vpH, wp1, sx1, sy1))
            {
                dl->AddLine(ImVec2(sx0, sy0), ImVec2(sx1, sy1), ringCol, 1.5f * dpi);
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Range Ring Rendering
// ---------------------------------------------------------------------------

static const ReplayWindow::RingDef kRingDefs[ReplayWindow::kRingTypeCount] = {
    //                                                    thick  solid  dash       fillA
    { "Touch",      144.f,  IM_COL32(255, 64, 64, 255),  1.5f, true,  0,0,       0.15f },
    { "Adjacent",   166.f,  IM_COL32(255,112, 32, 255),  1.5f, true,  0,0,       0.15f },
    { "Nearby",     240.f,  IM_COL32(255,176, 32, 255),  1.0f, true,  0,0,       0.12f },
    { "In Area",    322.f,  IM_COL32(255,255, 64, 255),  1.0f, true,  0,0,       0.10f },
    { "Earshot",   1000.f,  IM_COL32( 64,255,128, 255),  1.0f, true,  0,0,       0.06f },
    { "Cast Range",1248.f,  IM_COL32( 64,192,255, 255),  2.0f, true,  0,0,       0.05f },
    { "Passive",   2512.f,  IM_COL32(192, 64,255, 255),  1.0f, true,  0,0,       0.03f },
    { "Compass",   5020.f,  IM_COL32(128,128,128, 255),  0.5f, false, 8,4,       0.02f },
};

static constexpr float kRingFillAlpha    = 0.15f;
static constexpr float kRingSelectFill   = 0.22f;
static constexpr float kRingDimFactor    = 0.50f;
static const ImU32 kRingSelectEdge = IM_COL32(128, 255, 128, 255);

static ImU32 ScaleAlpha(ImU32 col, float factor)
{
    ImU8 a = (ImU8)((col >> 24) & 0xFF);
    a = (ImU8)(a * factor);
    return (col & 0x00FFFFFF) | ((ImU32)a << 24);
}

void ReplayWindow::DrawRangeRings()
{
    if (!m_showRangeRings) return;
    if (!m_agentsClassified || m_replayCtx.agents.empty()) return;

    Camera* cam = m_mapRenderer->GetCamera();
    if (!cam) return;
    XMMATRIX viewProj = cam->GetView() * cam->GetProj();

    auto* vp = ImGui::GetMainViewport();
    float vpW = vp->Size.x;
    float vpH = vp->Size.y;

    ImDrawList* dl = ImGui::GetBackgroundDrawList();
    const MapTransform& t = m_replayCtx.mapTransform;
    const InterpolationSettings& is = m_replayCtx.interpSettings;
    Terrain* terrain = m_mapRenderer->GetTerrain();

    constexpr int kSamples = 64;
    constexpr float kPI2 = 6.28318530718f;
    constexpr float kZOffset = 2.f;

    bool hasSelection = (m_ringAgentFilter >= 0);

    for (auto& [agentId, ard] : m_replayCtx.agents)
    {
        if (ard.type != AgentType::Player) continue;
        if (ard.snapshots.empty()) continue;
        if (ard.isDeadAtTime(m_debugTimeline)) continue;

        if (m_fogPerspective > 0 && ard.teamId != m_fogPerspective && IsAgentInFog(agentId))
            continue;

        if (m_ringHiddenAgents.count(agentId)) continue;

        bool isSelected = (m_ringAgentFilter == agentId);

        if (!isSelected)
        {
            if (hasSelection)
            {
                bool teamEnabled = (ard.teamId == 1 && m_ringShowBlue)
                                || (ard.teamId == 2 && m_ringShowRed);
                if (!teamEnabled) continue;
            }
            else
            {
                if (ard.teamId == 1 && !m_ringShowBlue) continue;
                if (ard.teamId == 2 && !m_ringShowRed)  continue;
            }
        }

        float sx, sy, sz;
        InterpolateAgentPosition(ard, m_debugTimeline, is, sx, sy, sz);

        ImU32 teamCol = GetAgentTeamColor(ard.teamId);

        for (int ri = 0; ri < kRingTypeCount; ++ri)
        {
            bool showRing = m_ringType[ri];
            bool isHoverPreview = (!showRing && m_ringHoveredType == ri);
            if (!showRing && !isHoverPreview) continue;

            const auto& def = kRingDefs[ri];
            float radius = def.radius;

            float dimFactor = (!isSelected && hasSelection) ? 0.25f : 1.f;
            float thickMul  = (isSelected && hasSelection) ? 1.6f : 1.f;
            ImU32 edgeCol = teamCol;
            if (dimFactor < 1.f) edgeCol = ScaleAlpha(edgeCol, dimFactor);
            if (isHoverPreview) edgeCol = ScaleAlpha(teamCol, 0.40f);

            ImVec2 pts[kSamples];
            bool vis[kSamples];
            int visCount = 0;

            for (int i = 0; i < kSamples; ++i)
            {
                float angle = (float(i) / kSamples) * kPI2;
                float wx = sx + cosf(angle) * radius;
                float wy = sy + sinf(angle) * radius;

                XMFLOAT3 mp = ApplyMapTransformToPos(wx, wy, sz, t);

                if (terrain)
                    mp.y = terrain->get_height_at(mp.x, mp.z) + kZOffset;

                float scrX, scrY;
                vis[i] = ProjectToScreen(viewProj, vpW, vpH, mp, scrX, scrY);
                pts[i] = ImVec2(scrX, scrY);
                if (vis[i]) visCount++;
            }

            if (visCount < 3) continue;

            // Fill pass (brighter when selected, heavily dimmed for teammates)
            {
                float fa = isHoverPreview ? 0.10f : (isSelected ? def.fillAlpha * 2.0f : def.fillAlpha);
                if (dimFactor < 1.f) fa *= dimFactor;
                ImU32 baseRGB = teamCol;
                ImU32 fillCol = (baseRGB & 0x00FFFFFF) | ((ImU32)(fa * 255.f) << 24);
                ImVector<ImVec2> polyPts;
                for (int i = 0; i < kSamples; ++i)
                    if (vis[i]) polyPts.push_back(pts[i]);
                if (polyPts.Size >= 3)
                    dl->AddConvexPolyFilled(polyPts.Data, polyPts.Size, fillCol);
            }

            // Ring edge pass
            float thick = def.thickness * thickMul;
            if (def.solid)
            {
                for (int i = 0; i < kSamples; ++i)
                {
                    int j = (i + 1) % kSamples;
                    if (vis[i] && vis[j])
                        dl->AddLine(pts[i], pts[j], edgeCol, thick);
                }
            }
            else
            {
                float dashOn  = def.dashOn;
                float dashOff = def.dashOff;
                float cycle = dashOn + dashOff;
                float accum = 0.f;
                for (int i = 0; i < kSamples; ++i)
                {
                    int j = (i + 1) % kSamples;
                    float dx = pts[j].x - pts[i].x;
                    float dy = pts[j].y - pts[i].y;
                    float segLen = sqrtf(dx * dx + dy * dy);

                    if (vis[i] && vis[j])
                    {
                        float pos = fmodf(accum, cycle);
                        if (pos < dashOn)
                            dl->AddLine(pts[i], pts[j], edgeCol, thick);
                    }
                    accum += segLen;
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Spirit Range Circles — drawn for hovered or selected spirits
// ---------------------------------------------------------------------------

void ReplayWindow::DrawSpiritRanges()
{
    if (!m_agentsClassified || m_replayCtx.agents.empty()) return;
    if (m_hoveredAgentId < 0 && m_followedAgentId < 0) return;

    Camera* cam = m_mapRenderer->GetCamera();
    if (!cam) return;
    XMMATRIX viewProj = cam->GetView() * cam->GetProj();

    auto* vp = ImGui::GetMainViewport();
    float vpW = vp->Size.x;
    float vpH = vp->Size.y;

    ImDrawList* dl = ImGui::GetBackgroundDrawList();
    const MapTransform& t = m_replayCtx.mapTransform;
    Terrain* terrain = m_mapRenderer->GetTerrain();

    constexpr int kSamples = 48;
    constexpr float kPI2 = 6.28318530718f;
    constexpr float kZOffset = 2.f;
    constexpr float kFillAlpha = 0.12f;
    constexpr float kEdgeThickness = 1.5f;

    for (int sid : m_spiritIds)
    {
        if (sid != m_hoveredAgentId && sid != m_followedAgentId) continue;

        auto it = m_replayCtx.agents.find(sid);
        if (it == m_replayCtx.agents.end()) continue;
        const auto& ard = it->second;
        if (ard.type != AgentType::Spirit) continue;
        if (ard.snapshots.empty()) continue;

        if (m_debugTimeline < ard.snapshots.front().time ||
            m_debugTimeline > ard.snapshots.back().time)
            continue;
        if (ard.overlapHidden) continue;
        if (ard.isDeadAtTime(m_debugTimeline) || !ard.isAliveAtTime(m_debugTimeline))
            continue;

        float radius = GetSpiritRange(ard.modelId);
        if (radius <= 0.f) continue;

        ImU32 baseColor = IsNatureRitual(ard.modelId)
            ? IM_COL32(0x80, 0xFF, 0x80, 0xFF)
            : GetAgentTeamColor(ard.teamId);

        float sx, sy, sz;
        SnapAgentPosition(ard, m_debugTimeline, sx, sy, sz);

        ImVec2 pts[kSamples];
        bool vis[kSamples];
        int visCount = 0;

        for (int i = 0; i < kSamples; ++i)
        {
            float angle = (float(i) / kSamples) * kPI2;
            float wx = sx + cosf(angle) * radius;
            float wy = sy + sinf(angle) * radius;

            XMFLOAT3 mp = ApplyMapTransformToPos(wx, wy, sz, t);
            if (terrain)
                mp.y = terrain->get_height_at(mp.x, mp.z) + kZOffset;

            float scrX, scrY;
            vis[i] = ProjectToScreen(viewProj, vpW, vpH, mp, scrX, scrY);
            pts[i] = ImVec2(scrX, scrY);
            if (vis[i]) visCount++;
        }

        if (visCount < 3) continue;

        // Fill pass
        {
            ImU32 fillCol = (baseColor & 0x00FFFFFF) | ((ImU32)(kFillAlpha * 255.f) << 24);
            ImVector<ImVec2> polyPts;
            for (int i = 0; i < kSamples; ++i)
                if (vis[i]) polyPts.push_back(pts[i]);
            if (polyPts.Size >= 3)
                dl->AddConvexPolyFilled(polyPts.Data, polyPts.Size, fillCol);
        }

        // Edge pass
        ImU32 edgeCol = (baseColor & 0x00FFFFFF) | (0xC0u << 24);
        for (int i = 0; i < kSamples; ++i)
        {
            int j = (i + 1) % kSamples;
            if (vis[i] && vis[j])
                dl->AddLine(pts[i], pts[j], edgeCol, kEdgeThickness);
        }
    }
}

// ---------------------------------------------------------------------------
// Isle of Wurms — South Health Shrine capture radius (1010u)
// ---------------------------------------------------------------------------

namespace {

static float ShrineCaptureTime(int effectivePips)
{
    switch (effectivePips) {
    case 1: return 12.f;
    case 2: return 12.f;
    case 3: return 9.f;
    case 4: return 7.f;
    default: return 0.f;
    }
}

static float ShrinePipRate(int effectivePips)
{
    const float t = ShrineCaptureTime(effectivePips);
    return (t > 0.f) ? 1.f / t : 0.f;
}

} // namespace

void ReplayWindow::PrecomputeShrineTimeline()
{
    m_wurmsShrineSamples.clear();
    m_wurmsShrineCurrentSample = {};

    if (m_wurmsSouthShrineAgentId < 0) return;

    const auto& agents = m_replayCtx.agents;
    auto shrineIt = agents.find(m_wurmsSouthShrineAgentId);
    if (shrineIt == agents.end()) return;
    const AgentReplayData& shrine = shrineIt->second;
    if (shrine.snapshots.empty()) return;

    const float R2 = kWurmsShrineCaptureRadius * kWurmsShrineCaptureRadius;
    const InterpolationSettings& interp = m_replayCtx.interpSettings;
    const float matchEnd = std::max(1.f, m_replayCtx.maxReplayTime);
    constexpr float DT = 0.1f;

    auto countPlayers = [&](float tp, float& shX, float& shY, float& shZ)
        -> std::pair<int, int>
    {
        InterpolateAgentPosition(shrine, tp, interp, shX, shY, shZ);
        int b = 0, r = 0;
        for (int pid : m_playerIds)
        {
            auto pit = agents.find(pid);
            if (pit == agents.end()) continue;
            const AgentReplayData& ard = pit->second;
            if (ard.teamId != 1 && ard.teamId != 2) continue;
            if (ard.isDeadAtTime(tp) || !ard.isAliveAtTime(tp)) continue;
            float px, py, pz;
            InterpolateAgentPosition(ard, tp, interp, px, py, pz);
            const float dx = px - shX, dy = py - shY;
            if (dx * dx + dy * dy <= R2)
            {
                if (ard.teamId == 1) ++b; else ++r;
            }
        }
        return { b, r };
    };

    // ---- Forward simulation ----
    const int sampleCount = static_cast<int>(matchEnd / DT) + 2;
    m_wurmsShrineSamples.resize(sampleCount);

    int    owner        = 0;
    float  progress     = 0.f;
    uint8_t progressTeam = 0;
    bool   decapping    = false;
    size_t nextEvent    = 0;

    while (nextEvent < m_wurmsShrineCaptureEvents.size()
           && m_wurmsShrineCaptureEvents[nextEvent].first <= 1e-5f)
    {
        owner = m_wurmsShrineCaptureEvents[nextEvent].second;
        progress = 0.f; progressTeam = 0; decapping = false;
        ++nextEvent;
    }

    for (int si = 0; si < sampleCount; ++si)
    {
        const float t = si * DT;

        float shX, shY, shZ;
        auto [bRaw, rRaw] = countPlayers(t, shX, shY, shZ);
        const int bp  = std::min(bRaw, 4);
        const int rp  = std::min(rRaw, 4);
        const int eff = std::abs(bp - rp);
        const int dom = (bp > rp) ? 1 : (rp > bp) ? 2 : 0;
        const bool contested = (bp > 0 && rp > 0 && eff == 0);

        const float rate = ShrinePipRate(eff) * DT;

        if (eff > 0 && dom > 0)
        {
            if (owner == 0)
            {
                decapping = false;
                if (progressTeam == 0 || progress < 1e-5f)
                {
                    progressTeam = static_cast<uint8_t>(dom);
                    progress += rate;
                }
                else if (progressTeam == static_cast<uint8_t>(dom))
                {
                    progress += rate;
                }
                else
                {
                    progress -= rate;
                    if (progress <= 0.f)
                    {
                        progress = -progress;
                        progressTeam = static_cast<uint8_t>(dom);
                    }
                }
            }
            else
            {
                if (dom != owner)
                {
                    decapping = true;
                    progressTeam = static_cast<uint8_t>(owner);
                    progress += rate;
                }
                else if (decapping && progress > 1e-5f)
                {
                    progress -= rate;
                    if (progress <= 0.f)
                    {
                        progress = 0.f;
                        decapping = false;
                        progressTeam = 0;
                    }
                }
            }
        }

        ShrineState state;
        if (contested)
        {
            state = ShrineState::Contested;
        }
        else if (owner == 0)
        {
            if (progressTeam == 1 && progress > 0.001f)
                state = ShrineState::CapturingBlue;
            else if (progressTeam == 2 && progress > 0.001f)
                state = ShrineState::CapturingRed;
            else
                state = ShrineState::Neutral;
        }
        else
        {
            if (decapping && progress > 0.001f)
            {
                const int attacker = (owner == 1) ? 2 : 1;
                state = (attacker == 1) ? ShrineState::DecappingBlue
                                        : ShrineState::DecappingRed;
            }
            else
            {
                state = (owner == 1) ? ShrineState::OwnedByBlue
                                     : ShrineState::OwnedByRed;
            }
        }

        ShrineSample& s = m_wurmsShrineSamples[si];
        s.state         = state;
        s.ownerTeam     = static_cast<uint8_t>(owner);
        s.progressTeam  = progressTeam;
        s.bluePips      = bp;
        s.redPips       = rp;
        s.effectivePips = eff;
        s.progress      = progress;

        while (nextEvent < m_wurmsShrineCaptureEvents.size()
               && m_wurmsShrineCaptureEvents[nextEvent].first <= t + DT + 1e-5f)
        {
            owner = m_wurmsShrineCaptureEvents[nextEvent].second;
            progress = 0.f; progressTeam = 0; decapping = false;
            ++nextEvent;
        }
    }

    // ---- Normalization pass ----
    // Scale progress within each jumbo-bounded phase so it reaches 1.0
    // exactly at the jumbo timestamp.
    size_t phaseStartIdx = 0;
    for (const auto& [evTime, evTeam] : m_wurmsShrineCaptureEvents)
    {
        int evIdx = static_cast<int>(evTime / DT);
        if (evIdx >= sampleCount) evIdx = sampleCount - 1;
        if (evIdx < 0) evIdx = 0;

        const float rawAtEnd = m_wurmsShrineSamples[evIdx].progress;
        if (rawAtEnd > 0.001f)
        {
            for (size_t i = phaseStartIdx; i <= static_cast<size_t>(evIdx); ++i)
                m_wurmsShrineSamples[i].progress =
                    std::clamp(m_wurmsShrineSamples[i].progress / rawAtEnd, 0.f, 1.f);
        }
        phaseStartIdx = static_cast<size_t>(evIdx) + 1;
    }
    for (size_t i = phaseStartIdx; i < static_cast<size_t>(sampleCount); ++i)
        m_wurmsShrineSamples[i].progress = std::clamp(m_wurmsShrineSamples[i].progress, 0.f, 1.f);
}

void ReplayWindow::DrawWurmsShrineCaptureRadius()
{
    if (!m_agentsClassified || m_replayCtx.agents.empty()) return;
    if (!IsIsleOfWurmsMap(m_replayCtx.mapId)) return;
    if (m_wurmsSouthShrineAgentId < 0) return;
    if (m_wurmsShrineSamples.empty()) return;

    const int lastIdx = static_cast<int>(m_wurmsShrineSamples.size()) - 1;
    const float fIdx  = m_debugTimeline / m_wurmsShrineSampleDt;
    const int   idx0  = std::clamp(static_cast<int>(fIdx), 0, lastIdx);
    const int   idx1  = std::min(idx0 + 1, lastIdx);
    const float frac  = fIdx - static_cast<float>(idx0);

    m_wurmsShrineCurrentSample = m_wurmsShrineSamples[idx0];
    const float p0 = m_wurmsShrineSamples[idx0].progress;
    const float p1 = m_wurmsShrineSamples[idx1].progress;
    // Interpolate progress for smooth animation; skip across phase resets
    if (m_wurmsShrineSamples[idx0].ownerTeam == m_wurmsShrineSamples[idx1].ownerTeam
        && p1 >= p0 - 0.15f)
    {
        m_wurmsShrineCurrentSample.progress = p0 + (p1 - p0) * frac;
    }
    const ShrineSample& s = m_wurmsShrineCurrentSample;

    const int shrineId = m_wurmsSouthShrineAgentId;

    const bool showByFocus  = (m_hoveredAgentId == shrineId)
                           || (m_followedAgentId == shrineId);
    const bool showByOwned  = (s.state == ShrineState::OwnedByBlue)
                           || (s.state == ShrineState::OwnedByRed);
    const bool showByActive = (s.state == ShrineState::CapturingBlue)
                           || (s.state == ShrineState::CapturingRed)
                           || (s.state == ShrineState::DecappingBlue)
                           || (s.state == ShrineState::DecappingRed)
                           || (s.state == ShrineState::Contested);
    if (!showByFocus && !showByOwned && !showByActive) return;

    Camera* cam = m_mapRenderer->GetCamera();
    if (!cam) return;
    XMMATRIX viewProj = cam->GetView() * cam->GetProj();

    auto* vp = ImGui::GetMainViewport();
    const float vpW = vp->Size.x;
    const float vpH = vp->Size.y;

    ImDrawList* dl = ImGui::GetBackgroundDrawList();
    const MapTransform& mt = m_replayCtx.mapTransform;
    Terrain* terrain = m_mapRenderer->GetTerrain();

    constexpr int kSeg = 48;
    constexpr float kPI2 = 6.28318530718f;
    constexpr float kZOff = 2.f;
    constexpr float kFillAlpha = 0.14f;

    auto it = m_replayCtx.agents.find(shrineId);
    if (it == m_replayCtx.agents.end()) return;
    const AgentReplayData& srd = it->second;
    if (srd.snapshots.empty()) return;

    float sx, sy, sz;
    InterpolateAgentPosition(srd, m_debugTimeline, m_replayCtx.interpSettings,
                             sx, sy, sz);
    const float radius = kWurmsShrineCaptureRadius;

    auto projectPt = [&](float wx, float wy, ImVec2& out, bool& vis) {
        XMFLOAT3 mp = ApplyMapTransformToPos(wx, wy, sz, mt);
        if (terrain) mp.y = terrain->get_height_at(mp.x, mp.z) + kZOff;
        float scX, scY;
        vis = ProjectToScreen(viewProj, vpW, vpH, mp, scX, scY);
        out = ImVec2(scX, scY);
    };

    ImVec2 outerPts[kSeg];
    bool   outerVis[kSeg];
    int    outerCount = 0;
    for (int i = 0; i < kSeg; ++i)
    {
        const float ang = (float(i) / kSeg) * kPI2;
        projectPt(sx + cosf(ang) * radius, sy + sinf(ang) * radius,
                  outerPts[i], outerVis[i]);
        if (outerVis[i]) ++outerCount;
    }
    if (outerCount < 3) return;

    // ---- Drawing helpers ----
    auto drawFullFill = [&](ImU32 col) {
        ImVector<ImVec2> poly;
        for (int i = 0; i < kSeg; ++i)
            if (outerVis[i]) poly.push_back(outerPts[i]);
        if (poly.Size >= 3)
            dl->AddConvexPolyFilled(poly.Data, poly.Size, col);
    };

    auto drawPartialDisc = [&](float prog, ImU32 col) {
        const float rFill = radius * std::clamp(prog, 0.f, 1.f);
        ImVec2 cScr{};  bool cVis = false;
        {
            XMFLOAT3 mp = ApplyMapTransformToPos(sx, sy, sz, mt);
            if (terrain) mp.y = terrain->get_height_at(mp.x, mp.z) + kZOff;
            float cx, cy;
            cVis = ProjectToScreen(viewProj, vpW, vpH, mp, cx, cy);
            cScr = ImVec2(cx, cy);
        }
        ImVec2 fp[kSeg]; bool fv[kSeg];
        for (int i = 0; i < kSeg; ++i)
        {
            const float ang = (float(i) / kSeg) * kPI2;
            projectPt(sx + cosf(ang) * rFill, sy + sinf(ang) * rFill,
                      fp[i], fv[i]);
        }
        if (cVis)
        {
            for (int i = 0; i < kSeg; ++i)
            {
                const int j = (i + 1) % kSeg;
                if (fv[i] && fv[j])
                {
                    const ImVec2 tri[3] = { cScr, fp[i], fp[j] };
                    dl->AddConvexPolyFilled(tri, 3, col);
                }
            }
        }
        else
        {
            ImVector<ImVec2> poly;
            for (int i = 0; i < kSeg; ++i)
                if (fv[i]) poly.push_back(fp[i]);
            if (poly.Size >= 3)
                dl->AddConvexPolyFilled(poly.Data, poly.Size, col);
        }
    };

    auto drawAnnulus = [&](float prog, ImU32 col) {
        const float rIn = radius * std::clamp(prog, 0.f, 1.f);
        if (rIn < 1.f) { drawFullFill(col); return; }
        ImVec2 ip[kSeg]; bool iv[kSeg];
        for (int i = 0; i < kSeg; ++i)
        {
            const float ang = (float(i) / kSeg) * kPI2;
            projectPt(sx + cosf(ang) * rIn, sy + sinf(ang) * rIn,
                      ip[i], iv[i]);
        }
        for (int i = 0; i < kSeg; ++i)
        {
            const int j = (i + 1) % kSeg;
            if (!outerVis[i] || !outerVis[j] || !iv[i] || !iv[j]) continue;
            const ImVec2 q[4] = { ip[i], ip[j], outerPts[j], outerPts[i] };
            dl->AddConvexPolyFilled(q, 4, col);
        }
    };

    auto drawEdge = [&](ImU32 col, float thick = 1.6f) {
        for (int i = 0; i < kSeg; ++i)
        {
            const int j = (i + 1) % kSeg;
            if (outerVis[i] && outerVis[j])
                dl->AddLine(outerPts[i], outerPts[j], col, thick);
        }
    };

    auto drawContestedEdge = [&]() {
        const float pulse = 0.45f + 0.55f * sinf((float)ImGui::GetTime() * 3.2f);
        const ImU32 amber = IM_COL32(255, 200, 80, (ImU8)(pulse * 200.f));
        constexpr float dashOn = 10.f, dashOff = 8.f;
        const float cycle = dashOn + dashOff;
        float accum = 0.f;
        for (int i = 0; i < kSeg; ++i)
        {
            const int j = (i + 1) % kSeg;
            if (!outerVis[i] || !outerVis[j]) { accum = 0.f; continue; }
            const float dx = outerPts[j].x - outerPts[i].x;
            const float dy = outerPts[j].y - outerPts[i].y;
            if (fmodf(accum, cycle) < dashOn)
                dl->AddLine(outerPts[i], outerPts[j], amber, 2.2f);
            accum += sqrtf(dx * dx + dy * dy);
        }
    };

    // ---- Render by state ----
    const ImU32 greyEdge = IM_COL32(160, 160, 160, 220);
    const ImU32 greyFill = IM_COL32(140, 140, 140, 55);

    switch (s.state)
    {
    case ShrineState::Neutral:
        drawFullFill(greyFill);
        drawEdge(greyEdge, 1.5f);
        break;

    case ShrineState::OwnedByBlue:
    case ShrineState::OwnedByRed: {
        const ImU32 rgb  = GetAgentTeamColor(s.ownerTeam);
        const ImU32 fill = (rgb & 0x00FFFFFF) | ((ImU32)(kFillAlpha * 255.f) << 24);
        const ImU32 edge = (rgb & 0x00FFFFFF) | (0xD0u << 24);
        drawFullFill(fill);
        drawEdge(edge);
        break;
    }

    case ShrineState::CapturingBlue:
    case ShrineState::CapturingRed: {
        const int   capTeam = (s.state == ShrineState::CapturingBlue) ? 1 : 2;
        const ImU32 rgb  = GetAgentTeamColor(capTeam);
        const ImU32 fill = (rgb & 0x00FFFFFF) | ((ImU32)(kFillAlpha * 255.f) << 24);
        const ImU32 edge = (rgb & 0x00FFFFFF) | (0xD0u << 24);
        if (s.progress > 0.001f)
            drawPartialDisc(s.progress, fill);
        drawEdge(edge);
        break;
    }

    case ShrineState::DecappingBlue:
    case ShrineState::DecappingRed: {
        const int   actTeam = (s.state == ShrineState::DecappingBlue) ? 1 : 2;
        const ImU32 ownerRgb  = GetAgentTeamColor(s.ownerTeam);
        const ImU32 actRgb    = GetAgentTeamColor(actTeam);
        const ImU32 fill = (ownerRgb & 0x00FFFFFF) | ((ImU32)(kFillAlpha * 255.f) << 24);
        const ImU32 edge = (actRgb   & 0x00FFFFFF) | (0xD0u << 24);
        drawAnnulus(s.progress, fill);
        drawEdge(edge);
        break;
    }

    case ShrineState::Contested: {
        if (s.ownerTeam == 0 && s.progressTeam > 0 && s.progress > 0.001f)
        {
            const ImU32 rgb = GetAgentTeamColor(s.progressTeam);
            drawPartialDisc(s.progress,
                            (rgb & 0x00FFFFFF) | ((ImU32)(kFillAlpha * 255.f) << 24));
        }
        else if (s.ownerTeam > 0)
        {
            const ImU32 rgb = GetAgentTeamColor(s.ownerTeam);
            const ImU32 fill = (rgb & 0x00FFFFFF) | ((ImU32)(kFillAlpha * 255.f) << 24);
            if (s.progress > 0.001f)
                drawAnnulus(s.progress, fill);
            else
                drawFullFill(fill);
        }
        else
        {
            drawFullFill(IM_COL32(90, 85, 70, 45));
        }
        drawContestedEdge();
        break;
    }
    }

    // Ownership beam: visible when shrine is owned (persists during decap)
    if (s.ownerTeam > 0)
        DrawShrineBeam(s.ownerTeam, sx, sy, sz);
}

// ---------------------------------------------------------------------------
// Isle of Wurms — Shrine ownership beam
// ---------------------------------------------------------------------------

namespace {

struct AdditiveBlendCBData {
    ID3D11DeviceContext* ctx;
    ID3D11BlendState*    bs;
};

static void BeamSetAdditiveBlend(const ImDrawList*, const ImDrawCmd* cmd)
{
    auto* d = static_cast<AdditiveBlendCBData*>(cmd->UserCallbackData);
    const float f[4] = { 0, 0, 0, 0 };
    d->ctx->OMSetBlendState(d->bs, f, 0xFFFFFFFF);
}

constexpr float kBeamBaseHalfWidth = 30.f;
constexpr float kBeamTopHalfWidth  = 6.f;
constexpr float kBeamHeight        = 1100.f;
constexpr int   kBeamSubdivisions  = 12;
constexpr float kHaloRadius        = 35.f;
constexpr int   kHaloSegments      = 24;

struct BeamLayerDef {
    float widthScale;
    ImU32 edgeColor;
    ImU32 centerColor;
};

} // namespace

void ReplayWindow::DrawShrineBeam(uint8_t ownerTeam, float sx, float sy, float sz)
{
    Camera* cam = m_mapRenderer->GetCamera();
    if (!cam) return;
    XMMATRIX viewProj = cam->GetView() * cam->GetProj();

    auto* vp = ImGui::GetMainViewport();
    const float vpW = vp->Size.x;
    const float vpH = vp->Size.y;

    ImDrawList* dl = ImGui::GetBackgroundDrawList();
    const MapTransform& mt = m_replayCtx.mapTransform;
    Terrain* terrain = m_mapRenderer->GetTerrain();

    XMFLOAT3 baseWorld = ApplyMapTransformToPos(sx, sy, sz, mt);
    if (terrain)
        baseWorld.y = terrain->get_height_at(baseWorld.x, baseWorld.z);

    XMFLOAT3 look = cam->GetLook3f();
    float rxz = sqrtf(look.x * look.x + look.z * look.z);
    XMFLOAT3 right;
    if (rxz > 0.001f)
    {
        right = { -look.z / rxz, 0.f, look.x / rxz };
    }
    else
    {
        XMFLOAT3 r3 = cam->GetRight3f();
        float rlen = sqrtf(r3.x * r3.x + r3.z * r3.z);
        right = (rlen > 0.001f)
            ? XMFLOAT3{ r3.x / rlen, 0.f, r3.z / rlen }
            : XMFLOAT3{ 1.f, 0.f, 0.f };
    }

    float baseHW = kBeamBaseHalfWidth * mt.scaleX;
    float topHW  = kBeamTopHalfWidth  * mt.scaleX;
    float height = kBeamHeight        * mt.scaleY;

    XMFLOAT3 topWorld = { baseWorld.x, baseWorld.y + height, baseWorld.z };

    auto projectWorld = [&](XMFLOAT3 w, ImVec2& out) -> bool {
        float scX, scY;
        bool vis = ProjectToScreen(viewProj, vpW, vpH, w, scX, scY);
        out = ImVec2(scX, scY);
        return vis;
    };

    BeamLayerDef layers[3];
    if (ownerTeam == 1) // Blue
    {
        layers[0] = { 1.00f, IM_COL32(0x20, 0x60, 0xC0, 166), IM_COL32(0x40, 0x90, 0xF0, 166) };
        layers[1] = { 0.75f, IM_COL32(0x6A, 0xB8, 0xFF, 230), IM_COL32(0x88, 0xCC, 0xFF, 230) };
        layers[2] = { 0.35f, IM_COL32(0xDD, 0xF0, 0xFF, 255), IM_COL32(0xFF, 0xFF, 0xFF, 255) };
    }
    else // Red
    {
        layers[0] = { 1.00f, IM_COL32(0xB0, 0x20, 0x20, 166), IM_COL32(0xE0, 0x30, 0x30, 166) };
        layers[1] = { 0.75f, IM_COL32(0xF0, 0x60, 0x40, 230), IM_COL32(0xFF, 0x80, 0x60, 230) };
        layers[2] = { 0.35f, IM_COL32(0xFF, 0xDD, 0xD0, 255), IM_COL32(0xFF, 0xFF, 0xFF, 255) };
    }

    // ---- Switch to additive blending ----
    static AdditiveBlendCBData cbData;
    cbData.ctx = m_deviceResources->GetD3DDeviceContext();
    cbData.bs  = m_additiveBS.Get();
    dl->AddCallback(BeamSetAdditiveBlend, &cbData);

    // ---- Floor halo (ellipse at shrine base) ----
    {
        float haloR = kHaloRadius * mt.scaleX;
        ImU32 haloCenterCol = (ownerTeam == 1)
            ? IM_COL32(0x3A, 0x80, 0xE0, 140)
            : IM_COL32(0xE0, 0x30, 0x20, 140);
        ImU32 haloEdgeCol = (ownerTeam == 1)
            ? IM_COL32(0x3A, 0x80, 0xE0, 0)
            : IM_COL32(0xE0, 0x30, 0x20, 0);

        ImVec2 centerScr;
        bool centerVis = projectWorld(baseWorld, centerScr);

        if (centerVis)
        {
            constexpr float kPI2 = 6.28318530718f;
            ImVec2 ringPts[kHaloSegments];
            bool   ringVis[kHaloSegments];
            for (int i = 0; i < kHaloSegments; ++i)
            {
                float ang = (float(i) / kHaloSegments) * kPI2;
                XMFLOAT3 hp = {
                    baseWorld.x + cosf(ang) * haloR * right.x + sinf(ang) * haloR * 0.25f * 0.f,
                    baseWorld.y,
                    baseWorld.z + cosf(ang) * haloR * right.z + sinf(ang) * haloR * 0.25f * 0.f
                };
                float fwdX = look.x, fwdZ = look.z;
                if (rxz > 0.001f) { fwdX /= rxz; fwdZ /= rxz; }
                hp.x = baseWorld.x + cosf(ang) * haloR * right.x + sinf(ang) * haloR * 0.25f * fwdX;
                hp.z = baseWorld.z + cosf(ang) * haloR * right.z + sinf(ang) * haloR * 0.25f * fwdZ;
                ringVis[i] = projectWorld(hp, ringPts[i]);
            }
            for (int i = 0; i < kHaloSegments; ++i)
            {
                int j = (i + 1) % kHaloSegments;
                if (!ringVis[i] || !ringVis[j]) continue;
                dl->AddTriangleFilled(centerScr, ringPts[i], ringPts[j], haloCenterCol);
            }
            for (int i = 0; i < kHaloSegments; ++i)
            {
                int j = (i + 1) % kHaloSegments;
                if (!ringVis[i] || !ringVis[j]) continue;
                ImVec2 midI = ImVec2((centerScr.x + ringPts[i].x) * 0.5f,
                                     (centerScr.y + ringPts[i].y) * 0.5f);
                ImVec2 midJ = ImVec2((centerScr.x + ringPts[j].x) * 0.5f,
                                     (centerScr.y + ringPts[j].y) * 0.5f);
                const ImVec2 outerQ[4] = { midI, midJ, ringPts[j], ringPts[i] };
                dl->AddConvexPolyFilled(outerQ, 4, haloEdgeCol);
            }
        }
    }

    // ---- Beam layers ----
    for (int li = 0; li < 3; ++li)
    {
        const BeamLayerDef& L = layers[li];
        float bHW = baseHW * L.widthScale;
        float tHW = topHW  * L.widthScale;
        const int N = kBeamSubdivisions;

        for (int i = 0; i < N; ++i)
        {
            float t0 = (float(i) / N) * 2.f - 1.f;
            float t1 = (float(i + 1) / N) * 2.f - 1.f;

            XMFLOAT3 bl = {
                baseWorld.x + right.x * bHW * t0,
                baseWorld.y,
                baseWorld.z + right.z * bHW * t0
            };
            XMFLOAT3 br = {
                baseWorld.x + right.x * bHW * t1,
                baseWorld.y,
                baseWorld.z + right.z * bHW * t1
            };
            XMFLOAT3 tl = {
                topWorld.x + right.x * tHW * t0,
                topWorld.y,
                topWorld.z + right.z * tHW * t0
            };
            XMFLOAT3 tr = {
                topWorld.x + right.x * tHW * t1,
                topWorld.y,
                topWorld.z + right.z * tHW * t1
            };

            ImVec2 sbl, sbr, stl, str;
            bool vbl = projectWorld(bl, sbl);
            bool vbr = projectWorld(br, sbr);
            bool vtl = projectWorld(tl, stl);
            bool vtr = projectWorld(tr, str);
            if (!vbl && !vbr && !vtl && !vtr) continue;

            float d0 = fabsf(t0);
            float d1 = fabsf(t1);
            auto lerpCol = [](ImU32 edge, ImU32 center, float dist) -> ImU32 {
                float f = 1.f - dist;
                int re = (edge >> 0) & 0xFF,  ge = (edge >> 8) & 0xFF,  be = (edge >> 16) & 0xFF,  ae = (edge >> 24) & 0xFF;
                int rc = (center >> 0) & 0xFF, gc = (center >> 8) & 0xFF, bc = (center >> 16) & 0xFF, ac = (center >> 24) & 0xFF;
                int ro = re + (int)((rc - re) * f);
                int go = ge + (int)((gc - ge) * f);
                int bo = be + (int)((bc - be) * f);
                int ao = ae + (int)((ac - ae) * f);
                return IM_COL32(ro, go, bo, ao);
            };

            ImU32 c0 = lerpCol(L.edgeColor, L.centerColor, d0);
            ImU32 c1 = lerpCol(L.edgeColor, L.centerColor, d1);

            ImVec2 uv = dl->_Data->TexUvWhitePixel;
            dl->PrimReserve(6, 4);
            ImDrawIdx idx = (ImDrawIdx)dl->_VtxCurrentIdx;
            dl->_VtxWritePtr[0] = { stl, uv, c0 };
            dl->_VtxWritePtr[1] = { str, uv, c1 };
            dl->_VtxWritePtr[2] = { sbr, uv, c1 };
            dl->_VtxWritePtr[3] = { sbl, uv, c0 };
            dl->_VtxWritePtr += 4;
            dl->_IdxWritePtr[0] = idx;     dl->_IdxWritePtr[1] = (ImDrawIdx)(idx + 1); dl->_IdxWritePtr[2] = (ImDrawIdx)(idx + 2);
            dl->_IdxWritePtr[3] = idx;     dl->_IdxWritePtr[4] = (ImDrawIdx)(idx + 2); dl->_IdxWritePtr[5] = (ImDrawIdx)(idx + 3);
            dl->_IdxWritePtr += 6;
            dl->_VtxCurrentIdx += 4;
        }
    }

    // ---- Restore normal blend state ----
    dl->AddCallback(ImDrawCallback_ResetRenderState, nullptr);
}

// ---------------------------------------------------------------------------
// Range Ring Toolbar UI
// ---------------------------------------------------------------------------

void ReplayWindow::DrawRangeRingToolbar()
{
    if (!m_showRangeRings) return;

    ImGui::PushStyleColor(ImGuiCol_WindowBg,       ImVec4(0.055f, 0.063f, 0.078f, 0.94f));
    ImGui::PushStyleColor(ImGuiCol_TitleBg,        ImVec4(0.07f, 0.08f, 0.10f, 1.f));
    ImGui::PushStyleColor(ImGuiCol_TitleBgActive,  ImVec4(0.10f, 0.09f, 0.06f, 1.f));
    ImGui::PushStyleColor(ImGuiCol_Border,         ImVec4(0.16f, 0.12f, 0.06f, 0.85f));
    ImGui::PushStyleColor(ImGuiCol_Separator,      ImVec4(0.40f, 0.33f, 0.15f, 0.40f));
    ImGui::PushStyleVar(ImGuiStyleVar_WindowRounding, 6.f);
    ImGui::PushStyleVar(ImGuiStyleVar_WindowBorderSize, 1.f);

    auto* vp = ImGui::GetMainViewport();
    ImGui::SetNextWindowSizeConstraints(ImVec2(300.f, 0.f), ImVec2(vp->Size.x, vp->Size.y));
    ImGui::SetNextWindowSize(ImVec2(0, 0), ImGuiCond_Always);
    m_panelLayout.ApplyPosition("range_rings");
    if (ImGui::Begin("Range Rings", &m_showRangeRings,
        ImGuiWindowFlags_AlwaysAutoResize))
    {
        m_panelLayout.TrackWindow("range_rings");
        ImVec2 pos = ImGui::GetWindowPos();
        ImVec2 sz  = ImGui::GetWindowSize();
        float cx = std::clamp(pos.x, vp->Pos.x, vp->Pos.x + vp->Size.x - sz.x);
        float cy = std::clamp(pos.y, vp->Pos.y, vp->Pos.y + vp->Size.y - sz.y);
        if (cx != pos.x || cy != pos.y)
            ImGui::SetWindowPos(ImVec2(cx, cy));
        auto RingPill = [](const char* label, bool active, ImU32 accent = 0) -> bool {
            ImVec4 bg, tx, hov, bdr;
            if (active) {
                bg  = ImVec4(0.18f, 0.14f, 0.05f, 1.f);
                tx  = ImVec4(1.f, 0.91f, 0.69f, 1.f);
                hov = ImVec4(0.23f, 0.19f, 0.08f, 1.f);
                bdr = ImVec4(1.f, 0.84f, 0.39f, 0.85f);
            } else {
                bg  = ImVec4(1.f, 1.f, 1.f, 0.05f);
                tx  = ImVec4(0.60f, 0.64f, 0.69f, 1.f);
                hov = ImVec4(1.f, 1.f, 1.f, 0.12f);
                bdr = ImVec4(1.f, 1.f, 1.f, 0.08f);
            }
            ImGui::PushStyleColor(ImGuiCol_Button, bg);
            ImGui::PushStyleColor(ImGuiCol_Text, tx);
            ImGui::PushStyleColor(ImGuiCol_ButtonHovered, hov);
            ImGui::PushStyleColor(ImGuiCol_ButtonActive,
                ImVec4(bg.x * 0.85f, bg.y * 0.85f, bg.z * 0.85f, 1.f));
            ImGui::PushStyleColor(ImGuiCol_Border, bdr);
            ImGui::PushStyleVar(ImGuiStyleVar_FrameRounding, 10.f);
            ImGui::PushStyleVar(ImGuiStyleVar_FramePadding, ImVec2(6, 3));
            ImGui::PushStyleVar(ImGuiStyleVar_FrameBorderSize, 1.f);
            bool clicked = ImGui::Button(label);
            ImGui::PopStyleVar(3);
            ImGui::PopStyleColor(5);
            return clicked;
        };

        auto TeamPill = [](const char* label, bool active, int team) -> bool {
            ImVec4 bg, tx, hov, bdr;
            if (active) {
                if (team == 1) {
                    bg  = ImVec4(0.05f, 0.12f, 0.25f, 1.f);
                    tx  = ImVec4(0.29f, 0.78f, 1.f, 1.f);
                    hov = ImVec4(0.08f, 0.16f, 0.30f, 1.f);
                    bdr = ImVec4(0.29f, 0.78f, 1.f, 0.85f);
                } else if (team == 2) {
                    bg  = ImVec4(0.25f, 0.06f, 0.06f, 1.f);
                    tx  = ImVec4(1.f, 0.42f, 0.42f, 1.f);
                    hov = ImVec4(0.30f, 0.10f, 0.10f, 1.f);
                    bdr = ImVec4(1.f, 0.42f, 0.42f, 0.85f);
                } else {
                    bg  = ImVec4(0.18f, 0.14f, 0.05f, 1.f);
                    tx  = ImVec4(1.f, 0.91f, 0.69f, 1.f);
                    hov = ImVec4(0.23f, 0.19f, 0.08f, 1.f);
                    bdr = ImVec4(1.f, 0.84f, 0.39f, 0.85f);
                }
            } else {
                bg  = ImVec4(1.f, 1.f, 1.f, 0.05f);
                tx  = ImVec4(0.60f, 0.64f, 0.69f, 1.f);
                hov = ImVec4(1.f, 1.f, 1.f, 0.12f);
                bdr = ImVec4(1.f, 1.f, 1.f, 0.08f);
            }
            ImGui::PushStyleColor(ImGuiCol_Button, bg);
            ImGui::PushStyleColor(ImGuiCol_Text, tx);
            ImGui::PushStyleColor(ImGuiCol_ButtonHovered, hov);
            ImGui::PushStyleColor(ImGuiCol_ButtonActive,
                ImVec4(bg.x * 0.85f, bg.y * 0.85f, bg.z * 0.85f, 1.f));
            ImGui::PushStyleColor(ImGuiCol_Border, bdr);
            ImGui::PushStyleVar(ImGuiStyleVar_FrameRounding, 10.f);
            ImGui::PushStyleVar(ImGuiStyleVar_FramePadding, ImVec2(6, 3));
            ImGui::PushStyleVar(ImGuiStyleVar_FrameBorderSize, 1.f);
            bool clicked = ImGui::Button(label);
            ImGui::PopStyleVar(3);
            ImGui::PopStyleColor(5);
            return clicked;
        };

        // None / All buttons
        if (RingPill("None", false))
            for (int i = 0; i < kRingTypeCount; ++i) m_ringType[i] = false;
        ImGui::SameLine();
        if (RingPill("All", false))
            for (int i = 0; i < kRingTypeCount; ++i) m_ringType[i] = true;

        ImGui::Separator();

        // Ring type pills (two rows: 4 + 4)
        m_ringHoveredType = -1;
        for (int i = 0; i < kRingTypeCount; ++i)
        {
            if (i == 4) {} // new line
            else if (i > 0) ImGui::SameLine();

            ImGui::PushID(i);
            bool clicked = RingPill(kRingDefs[i].name, m_ringType[i], kRingDefs[i].color);

            if (ImGui::IsItemHovered())
            {
                m_ringHoveredType = i;
                ImGui::SetTooltip("%s \xe2\x80\x94 %.0f units", kRingDefs[i].name, kRingDefs[i].radius);
            }

            if (clicked)
            {
                if (ImGui::GetIO().MouseDoubleClicked[0])
                {
                    if (m_ringSoloActive && m_ringType[i])
                    {
                        for (int k = 0; k < kRingTypeCount; ++k)
                            m_ringType[k] = m_ringSoloPrev[k];
                        m_ringSoloActive = false;
                    }
                    else
                    {
                        for (int k = 0; k < kRingTypeCount; ++k)
                            m_ringSoloPrev[k] = m_ringType[k];
                        for (int k = 0; k < kRingTypeCount; ++k)
                            m_ringType[k] = (k == i);
                        m_ringSoloActive = true;
                    }
                }
                else
                {
                    m_ringType[i] = !m_ringType[i];
                    m_ringSoloActive = false;
                }
            }
            ImGui::PopID();
        }

        ImGui::Separator();

        // Team filter (independent toggles)
        if (TeamPill("Blue", m_ringShowBlue, 1))
            m_ringShowBlue = !m_ringShowBlue;
        ImGui::SameLine();
        if (TeamPill("Red", m_ringShowRed, 2))
            m_ringShowRed = !m_ringShowRed;

        if (m_ringAgentFilter >= 0)
        {
            ImGui::SameLine();
            auto it = m_replayCtx.agents.find(m_ringAgentFilter);
            ImVec4 agentCol(1.f, 0.91f, 0.69f, 1.f);
            if (it != m_replayCtx.agents.end()) {
                if (it->second.teamId == 1) agentCol = ImVec4(0.29f, 0.78f, 1.f, 1.f);
                else if (it->second.teamId == 2) agentCol = ImVec4(1.f, 0.42f, 0.42f, 1.f);
            }
            ImGui::PushStyleColor(ImGuiCol_Text, agentCol);
            std::string lbl = (it != m_replayCtx.agents.end())
                ? std::format("Agent: {} [x]", it->second.playerName)
                : std::format("Agent: #{} [x]", m_ringAgentFilter);
            if (ImGui::SmallButton(lbl.c_str()))
                m_ringAgentFilter = -1;
            ImGui::PopStyleColor();
        }

        // Per-character ring visibility
        ImGui::Separator();

        if (ImGui::SmallButton("Show All##Rings"))
            m_ringHiddenAgents.clear();
        ImGui::SameLine();
        if (ImGui::SmallButton("Hide All##Rings"))
        {
            for (int id : m_playerIds)
                m_ringHiddenAgents.insert(id);
        }

        ID3D11Device* dev = m_deviceResources->GetD3DDevice();
        const float iconSz = 16.f;

        auto DrawTeamRings = [&](const char* header, const std::vector<int>& ids, bool teamEnabled)
        {
            if (!teamEnabled) ImGui::BeginDisabled();
            if (ImGui::TreeNodeEx(header, ImGuiTreeNodeFlags_DefaultOpen))
            {
                for (int id : ids)
                {
                    auto it = m_replayCtx.agents.find(id);
                    if (it == m_replayCtx.agents.end()) continue;
                    const auto& ard = it->second;

                    bool visible = !m_ringHiddenAgents.count(id);

                    ImTextureID profTex = (ard.primaryProf > 0)
                        ? LoadProfIcon(dev, ard.primaryProf) : nullptr;
                    if (profTex)
                    {
                        ImGui::Image(profTex, ImVec2(iconSz, iconSz));
                        ImGui::SameLine(0, 4);
                    }

                    if (ImGui::Checkbox(("##ring_" + std::to_string(id)).c_str(), &visible))
                    {
                        if (visible)
                            m_ringHiddenAgents.erase(id);
                        else
                            m_ringHiddenAgents.insert(id);
                    }
                    ImGui::SameLine(0, 4);
                    std::string label = ard.playerName.empty()
                        ? ard.categoryName : ard.playerName;
                    ImGui::TextUnformatted(label.c_str());
                }
                ImGui::TreePop();
            }
            if (!teamEnabled) ImGui::EndDisabled();
        };

        DrawTeamRings("Blue Team", m_team1PlayerIds, m_ringShowBlue);
        DrawTeamRings("Red Team", m_team2PlayerIds, m_ringShowRed);
    }
    ImGui::End();
    ImGui::PopStyleVar(2);
    ImGui::PopStyleColor(5);
}

// ---------------------------------------------------------------------------
// Fog of War Toolbar UI
// ---------------------------------------------------------------------------

void ReplayWindow::DrawFogOfWarToolbar()
{
    if (m_fogPerspective == 0) return;

    ImGui::PushStyleColor(ImGuiCol_WindowBg,       ImVec4(0.055f, 0.063f, 0.078f, 0.94f));
    ImGui::PushStyleColor(ImGuiCol_TitleBg,        ImVec4(0.07f, 0.08f, 0.10f, 1.f));
    ImGui::PushStyleColor(ImGuiCol_TitleBgActive,  ImVec4(0.10f, 0.09f, 0.06f, 1.f));
    ImGui::PushStyleColor(ImGuiCol_Border,         ImVec4(0.16f, 0.12f, 0.06f, 0.85f));
    ImGui::PushStyleColor(ImGuiCol_Separator,      ImVec4(0.40f, 0.33f, 0.15f, 0.40f));
    ImGui::PushStyleVar(ImGuiStyleVar_WindowRounding, 6.f);
    ImGui::PushStyleVar(ImGuiStyleVar_WindowBorderSize, 1.f);
    ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(10, 8));

    auto* vp = ImGui::GetMainViewport();
    ImGui::SetNextWindowSizeConstraints(ImVec2(240.f, 0.f), ImVec2(240.f, vp->Size.y));
    static bool fogFirstOpen = true;
    if (fogFirstOpen) {
        ImGui::SetNextWindowPos(ImVec2(vp->Pos.x + 8.f, vp->Pos.y + 8.f), ImGuiCond_Once);
        fogFirstOpen = false;
    }

    bool fogOpen = true;
    if (ImGui::Begin("Fog of War", &fogOpen,
        ImGuiWindowFlags_AlwaysAutoResize | ImGuiWindowFlags_NoResize))
    {
        ImVec2 pos = ImGui::GetWindowPos();
        ImVec2 sz  = ImGui::GetWindowSize();
        float cx = std::clamp(pos.x, vp->Pos.x, vp->Pos.x + vp->Size.x - sz.x);
        float cy = std::clamp(pos.y, vp->Pos.y, vp->Pos.y + vp->Size.y - sz.y);
        if (cx != pos.x || cy != pos.y)
            ImGui::SetWindowPos(ImVec2(cx, cy));

        auto FogPill = [](const char* label, bool active, int team) -> bool {
            ImVec4 bg, tx, hov, bdr;
            if (active) {
                if (team == 1) {
                    bg  = ImVec4(0.05f, 0.12f, 0.25f, 1.f);
                    tx  = ImVec4(0.29f, 0.78f, 1.f, 1.f);
                    hov = ImVec4(0.08f, 0.16f, 0.30f, 1.f);
                    bdr = ImVec4(0.29f, 0.78f, 1.f, 0.85f);
                } else if (team == 2) {
                    bg  = ImVec4(0.25f, 0.06f, 0.06f, 1.f);
                    tx  = ImVec4(1.f, 0.42f, 0.42f, 1.f);
                    hov = ImVec4(0.30f, 0.10f, 0.10f, 1.f);
                    bdr = ImVec4(1.f, 0.42f, 0.42f, 0.85f);
                } else {
                    bg  = ImVec4(0.18f, 0.14f, 0.05f, 1.f);
                    tx  = ImVec4(1.f, 0.91f, 0.69f, 1.f);
                    hov = ImVec4(0.23f, 0.19f, 0.08f, 1.f);
                    bdr = ImVec4(1.f, 0.84f, 0.39f, 0.85f);
                }
            } else {
                bg  = ImVec4(1.f, 1.f, 1.f, 0.05f);
                tx  = ImVec4(0.60f, 0.64f, 0.69f, 1.f);
                hov = ImVec4(1.f, 1.f, 1.f, 0.12f);
                bdr = ImVec4(1.f, 1.f, 1.f, 0.08f);
            }
            ImGui::PushStyleColor(ImGuiCol_Button, bg);
            ImGui::PushStyleColor(ImGuiCol_Text, tx);
            ImGui::PushStyleColor(ImGuiCol_ButtonHovered, hov);
            ImGui::PushStyleColor(ImGuiCol_ButtonActive,
                ImVec4(bg.x * 0.85f, bg.y * 0.85f, bg.z * 0.85f, 1.f));
            ImGui::PushStyleColor(ImGuiCol_Border, bdr);
            ImGui::PushStyleVar(ImGuiStyleVar_FrameRounding, 10.f);
            ImGui::PushStyleVar(ImGuiStyleVar_FramePadding, ImVec2(6, 3));
            ImGui::PushStyleVar(ImGuiStyleVar_FrameBorderSize, 1.f);
            bool clicked = ImGui::Button(label);
            ImGui::PopStyleVar(3);
            ImGui::PopStyleColor(5);
            return clicked;
        };

        ImGui::TextColored(ImVec4(0.78f, 0.72f, 0.55f, 1.f), "Perspective");
        ImGui::SameLine();
        if (FogPill("Off", m_fogPerspective == 0 && m_fogPlayerAgent < 0, 0))
        { m_fogPerspective = 0; m_fogPlayerAgent = -1; }
        ImGui::SameLine();
        if (FogPill("Blue", m_fogPerspective == 1 && m_fogPlayerAgent < 0, 1))
        { m_fogPerspective = (m_fogPerspective == 1 && m_fogPlayerAgent < 0) ? 0 : 1; m_fogPlayerAgent = -1; }
        ImGui::SameLine();
        if (FogPill("Red", m_fogPerspective == 2 && m_fogPlayerAgent < 0, 2))
        { m_fogPerspective = (m_fogPerspective == 2 && m_fogPlayerAgent < 0) ? 0 : 2; m_fogPlayerAgent = -1; }

        if (m_fogPlayerAgent >= 0)
        {
            auto pit = m_replayCtx.agents.find(m_fogPlayerAgent);
            std::string pname = (pit != m_replayCtx.agents.end())
                ? pit->second.partyBarLabel : std::format("#{}", m_fogPlayerAgent);
            std::string pillLabel = pname + "  \xc3\x97";
            if (FogPill(pillLabel.c_str(), true, 0))
                m_fogPlayerAgent = -1;
        }

        ImGui::Separator();

        ImGui::TextColored(ImVec4(0.78f, 0.72f, 0.55f, 1.f), "Enemies");
        ImGui::SameLine();
        ImGui::PushStyleColor(ImGuiCol_FrameBg, ImVec4(0.10f, 0.10f, 0.12f, 1.f));
        ImGui::PushStyleColor(ImGuiCol_FrameBgHovered, ImVec4(0.15f, 0.14f, 0.10f, 1.f));
        ImGui::PushStyleColor(ImGuiCol_CheckMark, ImVec4(1.f, 0.84f, 0.39f, 1.f));
        if (ImGui::RadioButton("Hide", !m_fogGhostMode)) m_fogGhostMode = false;
        ImGui::SameLine();
        if (ImGui::RadioButton("Ghost", m_fogGhostMode)) m_fogGhostMode = true;
        ImGui::PopStyleColor(3);

        ImGui::Separator();

        bool inPlayerMode = (m_fogPlayerAgent >= 0);
        int sourceCount = 0;
        bool playerDead = false;
        std::string playerDeadName;

        if (inPlayerMode)
        {
            auto pit = m_replayCtx.agents.find(m_fogPlayerAgent);
            if (pit != m_replayCtx.agents.end() && !pit->second.snapshots.empty())
            {
                if (pit->second.isDeadAtTime(m_debugTimeline))
                {
                    playerDead = true;
                    playerDeadName = pit->second.partyBarLabel;
                }
                else
                    sourceCount = 1;
            }
        }
        else
        {
            for (auto& [aid, ard] : m_replayCtx.agents) {
                if (ard.teamId != m_fogPerspective) continue;
                if (ard.type != AgentType::Player) continue;
                if (ard.snapshots.empty()) continue;
                if (!ard.isDeadAtTime(m_debugTimeline)) sourceCount++;
            }
        }

        ImU32 dotCol;
        if (playerDead || sourceCount == 0)
            dotCol = IM_COL32(220, 60, 60, 255);
        else if (inPlayerMode)
            dotCol = IM_COL32(64, 220, 80, 255);
        else if (sourceCount >= 8)
            dotCol = IM_COL32(64, 220, 80, 255);
        else if (sourceCount >= 5)
            dotCol = IM_COL32(230, 180, 40, 255);
        else
            dotCol = IM_COL32(220, 60, 60, 255);

        ImVec2 cur = ImGui::GetCursorScreenPos();
        ImDrawList* dl = ImGui::GetWindowDrawList();
        float dotR = 4.f;
        float textH = ImGui::GetTextLineHeight();
        dl->AddCircleFilled(ImVec2(cur.x + dotR, cur.y + textH * 0.5f), dotR, dotCol);
        ImGui::Dummy(ImVec2(dotR * 2.f + 4.f, 0));
        ImGui::SameLine();

        if (playerDead)
            ImGui::Text("0 / 8 -- %s is dead", playerDeadName.c_str());
        else if (inPlayerMode)
            ImGui::Text("1 / 8 players as source");
        else
            ImGui::Text("%d / 8 players visible", sourceCount);
    }
    ImGui::End();
    ImGui::PopStyleVar(3);
    ImGui::PopStyleColor(5);

    if (!fogOpen)
        m_fogPerspective = 0;

    if (m_fogPerspective > 0 && m_fogPlayerAgent >= 0)
    {
        auto pit = m_replayCtx.agents.find(m_fogPlayerAgent);
        if (pit != m_replayCtx.agents.end() && !pit->second.snapshots.empty()
            && pit->second.isDeadAtTime(m_debugTimeline))
        {
            std::string msg = pit->second.partyBarLabel + " \xe2\x80\x94 No vision";
            ImVec2 txtSz = ImGui::CalcTextSize(msg.c_str());
            auto* fgDl = ImGui::GetForegroundDrawList();
            auto* mvp  = ImGui::GetMainViewport();
            ImVec2 center(mvp->Pos.x + mvp->Size.x * 0.5f, mvp->Pos.y + mvp->Size.y * 0.5f);
            fgDl->AddText(nullptr, 13.f,
                ImVec2(center.x - txtSz.x * 0.5f, center.y - txtSz.y * 0.5f),
                IM_COL32(255, 255, 255, 102), msg.c_str());
        }
    }
}

// ---------------------------------------------------------------------------
// Morale Panel
// ---------------------------------------------------------------------------

void ReplayWindow::DrawMoralePanel()
{
    if (!m_showMoralePanel) return;

    const float curTime = m_debugTimeline;
    const auto* vp = ImGui::GetMainViewport();

    struct PlayerMorale {
        int    agentId = 0;
        std::string name;
        int    primaryProf = 0;
        int    secondaryProf = 0;
        int    morale = 0;
        int    deathCount = 0;
        bool   dead = false;
    };

    std::vector<PlayerMorale> blueTeam, redTeam;

    // --- Death Pact Signet link tracking ---
    // DPS (5413/8059) links caster to target for 120s; if the target dies
    // during that window the caster also dies — that death is NOT penalised.
    constexpr int kDPS_Normal = 5413;
    constexpr int kDPS_PvP    = 8059;

    struct DPSLink { int casterId; int targetId; float linkStart; float linkEnd; };
    std::vector<DPSLink> dpsLinks;
    for (auto& [aid, ard] : m_replayCtx.agents) {
        if (ard.type != AgentType::Player) continue;
        for (auto& ev : ard.skillUseHistory) {
            if (ev.skillId != kDPS_Normal && ev.skillId != kDPS_PvP) continue;
            if (ev.wasCancelled || ev.wasInterrupted) continue;
            if (ev.endTime > curTime || ev.targetId <= 0) continue;
            dpsLinks.push_back({ aid, ev.targetId, ev.endTime, ev.endTime + 120.f });
        }
    }

    auto isDPSLinkedDeath = [&](int agentId, float deathTime) -> bool {
        for (auto& link : dpsLinks) {
            if (link.casterId != agentId) continue;
            if (deathTime < link.linkStart || deathTime > link.linkEnd) continue;
            auto tit = m_replayCtx.agents.find(link.targetId);
            if (tit == m_replayCtx.agents.end()) continue;
            const auto& trd = tit->second;
            for (size_t i = 1; i < trd.snapshots.size(); ++i) {
                if (trd.snapshots[i].time > deathTime + 1.5f) break;
                if (trd.snapshots[i].is_dead && !trd.snapshots[i - 1].is_dead) {
                    if (std::abs(trd.snapshots[i].time - deathTime) < 1.5f) return true;
                }
            }
        }
        return false;
    };

    // Collect per-player death times (with grace period + DPS exclusion).
    auto collectDeathTimes = [&](const AgentReplayData& ard) {
        std::vector<float> deaths;
        float lastResTime = -999.f;
        for (size_t i = 1; i < ard.snapshots.size(); ++i) {
            if (ard.snapshots[i].time > curTime) break;
            if (!ard.snapshots[i].is_dead && ard.snapshots[i - 1].is_dead)
                lastResTime = ard.snapshots[i].time;
            if (ard.snapshots[i].is_dead && !ard.snapshots[i - 1].is_dead) {
                float dt = ard.snapshots[i].time;
                if (dt - lastResTime < 5.f) continue;
                if (isDPSLinkedDeath(ard.agent_id, dt)) continue;
                deaths.push_back(dt);
            }
        }
        return deaths;
    };

    // Collect timestamps when enemy players died.
    auto collectEnemyKillTimes = [&](const std::vector<int>& enemyIds) {
        std::vector<float> times;
        for (int id : enemyIds) {
            auto it = m_replayCtx.agents.find(id);
            if (it == m_replayCtx.agents.end()) continue;
            if (it->second.type != AgentType::Player) continue;
            const auto& snaps = it->second.snapshots;
            for (size_t i = 1; i < snaps.size(); ++i) {
                if (snaps[i].time > curTime) break;
                if (snaps[i].is_dead && !snaps[i - 1].is_dead)
                    times.push_back(snaps[i].time);
            }
        }
        std::sort(times.begin(), times.end());
        return times;
    };

    // Collect timestamps when morale boosts fired for this team.
    auto collectBoostTimes = [&](int partyValue) {
        std::vector<float> times;
        for (auto& ev : m_replayCtx.stocData.jumbo) {
            if (ev.time > curTime) break;
            if (ev.message == "MORALE_BOOST" && ev.party_value == partyValue)
                times.push_back(ev.time);
        }
        return times;
    };

    auto blueBoostTimes = collectBoostTimes(1635021873);
    auto redBoostTimes  = collectBoostTimes(1635021874);
    auto blueEnemyKills = collectEnemyKillTimes(m_team2PlayerIds);
    auto redEnemyKills  = collectEnemyKillTimes(m_team1PlayerIds);

    // Compute morale chronologically so kill-based DP reduction is applied
    // only when the player actually has DP at the moment the enemy dies.
    // Events: own death (-15), team morale boost (+10), enemy kill (+2 if DP<0 and alive).
    // Kill reduction can never push morale above 0%.
    enum class MoraleEventType : uint8_t { Death, Boost, EnemyKill };
    struct MoraleEvent { float time; MoraleEventType type; };

    auto computeMorale = [&](const AgentReplayData& ard,
                             const std::vector<float>& boostTimes,
                             const std::vector<float>& enemyKillTimes,
                             int& outDeathCount) -> int {
        auto deathTimes = collectDeathTimes(ard);

        std::vector<MoraleEvent> events;
        events.reserve(deathTimes.size() + boostTimes.size() + enemyKillTimes.size());
        for (float t : deathTimes)      events.push_back({ t, MoraleEventType::Death });
        for (float t : boostTimes)      events.push_back({ t, MoraleEventType::Boost });
        for (float t : enemyKillTimes)  events.push_back({ t, MoraleEventType::EnemyKill });
        std::sort(events.begin(), events.end(),
                  [](const MoraleEvent& a, const MoraleEvent& b) { return a.time < b.time; });

        int morale = 0;
        int deaths = 0;
        for (auto& ev : events) {
            switch (ev.type) {
            case MoraleEventType::Death:
                morale = std::max(morale - 15, -60);
                ++deaths;
                break;
            case MoraleEventType::Boost:
                morale = std::min(morale + 10, 10);
                break;
            case MoraleEventType::EnemyKill:
                if (morale < 0 && ard.isAliveAtTime(ev.time))
                    morale = std::min(morale + 2, 0);
                break;
            }
        }
        outDeathCount = deaths;
        return std::clamp(morale, -60, 10);
    };

    auto buildTeam = [&](const std::vector<int>& ids,
                         const std::vector<float>& boostTimes,
                         const std::vector<float>& enemyKillTimes) {
        std::vector<PlayerMorale> result;
        for (int id : ids) {
            auto it = m_replayCtx.agents.find(id);
            if (it == m_replayCtx.agents.end()) continue;
            const auto& ard = it->second;
            if (ard.type != AgentType::Player) continue;

            PlayerMorale pm;
            pm.agentId = id;
            pm.name = ard.playerName;
            pm.primaryProf = ard.primaryProf;
            pm.secondaryProf = ard.secondaryProf;
            pm.morale = computeMorale(ard, boostTimes, enemyKillTimes, pm.deathCount);
            pm.dead = ard.isDeadAtTime(curTime);
            result.push_back(std::move(pm));
        }
        return result;
    };

    blueTeam = buildTeam(m_team1PlayerIds, blueBoostTimes, blueEnemyKills);
    redTeam  = buildTeam(m_team2PlayerIds, redBoostTimes, redEnemyKills);

    auto getGuildLabel = [&](const std::string& partyId) -> std::string {
        auto pit = m_matchMeta.parties.find(partyId);
        if (pit == m_matchMeta.parties.end()) return "?";
        std::map<int, int> guildCounts;
        for (const auto& p : pit->second.players)
            if (p.guild_id > 0) guildCounts[p.guild_id]++;
        int bestId = 0, bestCnt = 0;
        for (const auto& [gid, cnt] : guildCounts)
            if (cnt > bestCnt) { bestId = gid; bestCnt = cnt; }
        if (bestId == 0) return "?";
        auto git = m_matchMeta.guilds.find(std::to_string(bestId));
        if (git != m_matchMeta.guilds.end())
            return git->second.name + " [" + git->second.tag + "]";
        return "?";
    };

    std::string blueLabel = getGuildLabel("1");
    std::string redLabel  = getGuildLabel("2");

    constexpr float kPanelW = 520.f;
    constexpr float kRowH = 22.f;
    constexpr float kIconSz = 16.f;

    ImGui::PushStyleColor(ImGuiCol_WindowBg,       ImVec4(0.055f, 0.063f, 0.078f, 0.94f));
    ImGui::PushStyleColor(ImGuiCol_TitleBg,        ImVec4(0.07f, 0.08f, 0.10f, 1.f));
    ImGui::PushStyleColor(ImGuiCol_TitleBgActive,  ImVec4(0.10f, 0.09f, 0.06f, 1.f));
    ImGui::PushStyleColor(ImGuiCol_Border,         ImVec4(0.16f, 0.12f, 0.06f, 0.85f));
    ImGui::PushStyleColor(ImGuiCol_Separator,      ImVec4(0.40f, 0.33f, 0.15f, 0.40f));
    ImGui::PushStyleVar(ImGuiStyleVar_WindowRounding, 6.f);
    ImGui::PushStyleVar(ImGuiStyleVar_WindowBorderSize, 1.f);
    ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(10, 8));

    if (m_panelLayout.HasSavedPosition("morale"))
        m_panelLayout.ApplyPosition("morale");
    else
        ImGui::SetNextWindowPos(
            ImVec2(vp->Pos.x + (vp->Size.x - kPanelW) * 0.5f,
                   vp->Pos.y + vp->Size.y - 300.f),
            ImGuiCond_Once);
    ImGui::SetNextWindowSizeConstraints(ImVec2(kPanelW, 0.f), ImVec2(kPanelW, vp->Size.y));

    if (!ImGui::Begin("Morale##morale_panel", &m_showMoralePanel,
        ImGuiWindowFlags_AlwaysAutoResize | ImGuiWindowFlags_NoResize))
    {
        m_panelLayout.TrackWindow("morale");
        ImGui::End();
        ImGui::PopStyleVar(3);
        ImGui::PopStyleColor(5);
        return;
    }

    m_panelLayout.TrackWindow("morale");

    {
        ImVec2 wPos = ImGui::GetWindowPos();
        ImVec2 wSz  = ImGui::GetWindowSize();
        float cx = std::clamp(wPos.x, vp->Pos.x, vp->Pos.x + vp->Size.x - wSz.x);
        float cy = std::clamp(wPos.y, vp->Pos.y, vp->Pos.y + vp->Size.y - wSz.y);
        if (cx != wPos.x || cy != wPos.y)
            ImGui::SetWindowPos(ImVec2(cx, cy));
    }

    ImDrawList* dl = ImGui::GetWindowDrawList();
    const float fontSize = ImGui::GetFontSize();
    ID3D11Device* dev = m_deviceResources ? m_deviceResources->GetD3DDevice() : nullptr;

    constexpr ImU32 kBlueTeam = IM_COL32(0x4A, 0xC8, 0xFF, 0xFF);
    constexpr ImU32 kRedTeam  = IM_COL32(0xFF, 0x6B, 0x6B, 0xFF);
    constexpr ImU32 kGreen    = IM_COL32(0x40, 0xE0, 0x80, 0xFF);
    constexpr ImU32 kMuted    = IM_COL32(0x70, 0x7D, 0x88, 0xFF);
    constexpr ImU32 kAmber    = IM_COL32(0xFF, 0xA0, 0x30, 0xFF);
    constexpr ImU32 kRed      = IM_COL32(0xFF, 0x50, 0x50, 0xFF);
    constexpr ImU32 kText     = IM_COL32(0xE8, 0xEC, 0xF2, 0xFF);
    constexpr ImU32 kTextDead = IM_COL32(0x60, 0x60, 0x60, 0xFF);

    auto moraleColor = [&](int m) -> ImU32 {
        if (m > 0)    return kGreen;
        if (m == 0)   return kMuted;
        if (m >= -15) return kAmber;
        if (m >= -30) return IM_COL32(0xFF, 0x80, 0x30, 0xFF);
        return kRed;
    };

    auto avgColor = [&](float avg) -> ImU32 {
        if (avg > 0.f)    return kGreen;
        if (avg >= -5.f)  return kMuted;
        if (avg >= -15.f) return kAmber;
        return kRed;
    };

    const float contentW = kPanelW - 20.f;
    const float colW = (contentW - 1.f) * 0.5f;
    const float startX = ImGui::GetCursorScreenPos().x;
    const float startY = ImGui::GetCursorScreenPos().y;

    size_t maxRows = std::max(blueTeam.size(), redTeam.size());

    // Column headers: guild name [tag] in team color, standard font
    {
        ImVec2 p(startX, startY);
        dl->AddText(ImVec2(p.x + 2.f, p.y), kBlueTeam, blueLabel.c_str());
        dl->AddText(ImVec2(p.x + colW + 1.f + 2.f, p.y), kRedTeam, redLabel.c_str());
        ImGui::Dummy(ImVec2(0.f, fontSize + 4.f));
    }

    float rowStartY = ImGui::GetCursorScreenPos().y;

    auto drawPlayerRow = [&](const PlayerMorale& pm, float x, float y) {
        float cx = x;

        // Primary profession icon
        if (dev && pm.primaryProf >= 1) {
            ImTextureID tex = LoadProfIcon(dev, pm.primaryProf);
            if (tex) {
                float iy = y + (kRowH - kIconSz) * 0.5f;
                dl->AddImage(tex, ImVec2(cx, iy), ImVec2(cx + kIconSz, iy + kIconSz));
            }
        }
        cx += kIconSz + 1.f;

        // Secondary profession icon
        if (dev && pm.secondaryProf >= 1) {
            ImTextureID tex = LoadProfIcon(dev, pm.secondaryProf);
            if (tex) {
                float iy = y + (kRowH - kIconSz) * 0.5f;
                dl->AddImage(tex, ImVec2(cx, iy), ImVec2(cx + kIconSz, iy + kIconSz));
            }
        }
        cx += kIconSz + 3.f;

        // Player name in standard white/grey
        ImU32 nameCol = pm.dead ? kTextDead : kText;
        dl->AddText(ImVec2(cx, y + (kRowH - fontSize) * 0.5f), nameCol, pm.name.c_str());

        // Right side: morale value + dots or star
        float rightEdge = x + colW;
        char valBuf[16];

        if (pm.morale > 0) {
            snprintf(valBuf, sizeof(valBuf), "+%d%%", pm.morale);
            ImVec2 valSz = ImGui::CalcTextSize(valBuf);
            float valX = rightEdge - valSz.x - 2.f;
            dl->AddText(ImVec2(valX, y + (kRowH - fontSize) * 0.5f), kGreen, valBuf);
            float starX = valX - fontSize;
            dl->AddText(ImVec2(starX, y + (kRowH - fontSize) * 0.5f), kGreen, "\xe2\x98\x85");
        }
        else if (pm.morale == 0) {
            ImVec2 zSz = ImGui::CalcTextSize("0%");
            dl->AddText(ImVec2(rightEdge - zSz.x - 2.f, y + (kRowH - fontSize) * 0.5f), kMuted, "0%");
        }
        else {
            snprintf(valBuf, sizeof(valBuf), "%d%%", pm.morale);
            ImU32 valCol = moraleColor(pm.morale);
            ImVec2 valSz = ImGui::CalcTextSize(valBuf);

            int dots = std::min(4, pm.deathCount);
            float dotSpacing = 10.f;
            float dotsWidth = dots > 0 ? (dots * dotSpacing) : 0.f;

            float totalW = valSz.x + 4.f + dotsWidth + 2.f;
            float vx = rightEdge - totalW;

            dl->AddText(ImVec2(vx, y + (kRowH - fontSize) * 0.5f), valCol, valBuf);
            vx += valSz.x + 4.f;

            for (int d = 0; d < dots; ++d) {
                dl->AddCircleFilled(
                    ImVec2(vx + d * dotSpacing + 3.f, y + kRowH * 0.5f),
                    3.f, valCol);
            }
        }
    };

    for (size_t i = 0; i < maxRows; ++i) {
        float rowY = rowStartY + i * kRowH;
        if (i < blueTeam.size())
            drawPlayerRow(blueTeam[i], startX, rowY);
        if (i < redTeam.size())
            drawPlayerRow(redTeam[i], startX + colW + 1.f, rowY);
    }

    float divX = startX + colW;
    float divTop = rowStartY;
    float divBot = rowStartY + maxRows * kRowH;
    dl->AddLine(ImVec2(divX, divTop), ImVec2(divX, divBot),
                IM_COL32(0xFF, 0xD7, 0x64, 0x30), 1.f);

    ImGui::Dummy(ImVec2(0.f, maxRows * kRowH + 4.f));

    // Footer divider
    {
        ImVec2 p = ImGui::GetCursorScreenPos();
        dl->AddLine(ImVec2(p.x, p.y), ImVec2(p.x + contentW, p.y),
                    IM_COL32(0xFF, 0xD7, 0x64, 0x20), 1.f);
        ImGui::Dummy(ImVec2(0.f, 4.f));
    }

    auto computeAvg = [](const std::vector<PlayerMorale>& team) -> float {
        if (team.empty()) return 0.f;
        float sum = 0.f;
        for (auto& pm : team) sum += static_cast<float>(pm.morale);
        return sum / static_cast<float>(team.size());
    };

    float blueAvg = computeAvg(blueTeam);
    float redAvg  = computeAvg(redTeam);

    // Footer: team averages
    {
        ImVec2 p = ImGui::GetCursorScreenPos();
        char buf[32];

        snprintf(buf, sizeof(buf), "Avg  %.0f%%", blueAvg);
        dl->AddText(ImVec2(p.x + 2.f, p.y), avgColor(blueAvg), buf);

        snprintf(buf, sizeof(buf), "Avg  %.0f%%", redAvg);
        dl->AddText(ImVec2(p.x + colW + 1.f + 2.f, p.y), avgColor(redAvg), buf);

        ImGui::Dummy(ImVec2(0.f, fontSize + 4.f));
    }

    // Bottom bar
    {
        ImVec2 p = ImGui::GetCursorScreenPos();
        float barW = contentW;
        float barH = 8.f;
        float halfW = barW * 0.5f;

        dl->AddRectFilled(ImVec2(p.x, p.y), ImVec2(p.x + barW, p.y + barH),
                          IM_COL32(255, 255, 255, 15), 3.f);

        float blueLen = std::min(1.f, std::abs(blueAvg) / 60.f) * halfW;
        if (blueLen > 1.f) {
            dl->AddRectFilled(
                ImVec2(p.x + halfW - blueLen, p.y),
                ImVec2(p.x + halfW, p.y + barH),
                IM_COL32(0x4A, 0xC8, 0xFF, 0xB3), 2.f);
        }

        float redLen = std::min(1.f, std::abs(redAvg) / 60.f) * halfW;
        if (redLen > 1.f) {
            dl->AddRectFilled(
                ImVec2(p.x + halfW, p.y),
                ImVec2(p.x + halfW + redLen, p.y + barH),
                IM_COL32(0xFF, 0x6B, 0x6B, 0xB3), 2.f);
        }

        dl->AddLine(ImVec2(p.x + halfW, p.y), ImVec2(p.x + halfW, p.y + barH),
                    IM_COL32(0xFF, 0xD7, 0x64, 0x60), 1.f);

        char buf[16];
        snprintf(buf, sizeof(buf), "%.0f%%", blueAvg);
        dl->AddText(ImVec2(p.x + 2.f, p.y + barH + 2.f), avgColor(blueAvg), buf);

        snprintf(buf, sizeof(buf), "%.0f%%", redAvg);
        ImVec2 rSz = ImGui::CalcTextSize(buf);
        dl->AddText(ImVec2(p.x + barW - rSz.x - 2.f, p.y + barH + 2.f), avgColor(redAvg), buf);

        ImGui::Dummy(ImVec2(0.f, barH + fontSize + 4.f));
    }

    ImGui::End();
    ImGui::PopStyleVar(3);
    ImGui::PopStyleColor(5);
}

// ---------------------------------------------------------------------------
// Scene overlays: Match Timer, Jumbo Messages, Morale Boost Timers
// ---------------------------------------------------------------------------

static float sVw(float pct) { return ImGui::GetMainViewport()->Size.x * pct; }
static float sVh(float pct) { return ImGui::GetMainViewport()->Size.y * pct; }

static void FormatMMSS(char* buf, size_t bufSz, float seconds)
{
    int s = std::max(0, static_cast<int>(seconds));
    int m = s / 60;
    int ss = s % 60;
    snprintf(buf, bufSz, "%02d:%02d", m, ss);
}

static int JumboPartyToTeam(int partyValue)
{
    if (partyValue == 1635021873) return 1;
    if (partyValue == 1635021874) return 2;
    return 0;
}

static const char* JumboMessageDisplayText(const std::string& msgType, int team)
{
    const char* side = (team == 1) ? "Blue" : "Red";
    static char buf[128];
    if      (msgType == "BASE_UNDER_ATTACK")       snprintf(buf, sizeof(buf), "%s Base Under Attack",       side);
    else if (msgType == "GUILD_LORD_UNDER_ATTACK")  snprintf(buf, sizeof(buf), "%s Guild Lord Under Attack",  side);
    else if (msgType == "CAPTURED_SHRINE")          snprintf(buf, sizeof(buf), "%s Captured Shrine",          side);
    else if (msgType == "NEUTRALIZED_SHRINE")       snprintf(buf, sizeof(buf), "%s neutralized Health Shrine", side);
    else if (msgType == "CAPTURED_TOWER")           snprintf(buf, sizeof(buf), "%s Captured Tower",           side);
    else if (msgType == "PARTY_DEFEATED")           snprintf(buf, sizeof(buf), "%s Party Defeated",           side);
    else if (msgType == "MORALE_BOOST")             snprintf(buf, sizeof(buf), "%s Morale Boost",             side);
    else if (msgType == "VICTORY")                  snprintf(buf, sizeof(buf), "%s Victory!",                 side);
    else if (msgType == "FLAWLESS_VICTORY")         snprintf(buf, sizeof(buf), "%s Flawless Victory!",        side);
    else                                            snprintf(buf, sizeof(buf), "%s %s",                       side, msgType.c_str());
    return buf;
}

// Helper: handle drag mode for an overlay element.
// Returns true if currently being dragged; updates the fraction-based position.
bool ReplayWindow::HandleOverlayDrag(int elementIdx, float* fracX, float* fracY,
                                      ImVec2 boxTL, ImVec2 boxBR)
{
    if (m_draggingUIElement != elementIdx) return false;

    ImDrawList* dl = ImGui::GetForegroundDrawList();
    dl->AddRect(ImVec2(boxTL.x - 2, boxTL.y - 2), ImVec2(boxBR.x + 2, boxBR.y + 2),
                IM_COL32(0xF5, 0xE4, 0x5A, 180), 4.f, 0, 2.f);
    dl->AddRectFilled(boxTL, boxBR, IM_COL32(0xF5, 0xE4, 0x5A, 30), 4.f);

    const ImGuiViewport* vp = ImGui::GetMainViewport();

    if (ImGui::IsMouseDragging(ImGuiMouseButton_Left))
    {
        ImVec2 delta = ImGui::GetIO().MouseDelta;
        *fracX += delta.x / vp->Size.x;
        *fracY += delta.y / vp->Size.y;
        *fracX = std::clamp(*fracX, 0.f, 1.f);
        *fracY = std::clamp(*fracY, 0.f, 1.f);
    }

    if (ImGui::IsMouseReleased(ImGuiMouseButton_Left))
    {
        m_draggingUIElement = -1;
        SaveUILayout();
    }
    return true;
}

// ---------------------------------------------------------------------------
// DrawLordDamagePanel — guild lord damage stats floating panel
// ---------------------------------------------------------------------------
void ReplayWindow::DrawLordDamagePanel()
{
    if (!m_showLordDamagePanel || !m_lordDamageBuilt) return;

    ID3D11Device* dev = m_deviceResources->GetD3DDevice();
    ImFont* font = ImGui::GetFont();
    float maxT = std::max(1.f, m_replayCtx.maxReplayTime);

    if (std::isnan(m_debugTimeline) || std::isinf(m_debugTimeline))
        m_debugTimeline = 0.f;
    float curTime = std::clamp(m_debugTimeline, 0.f, maxT);

    // Party-style gradient definitions (matching DrawPartyHealthBar)
    struct LordGrad5 { ImU32 c[5]; };
    static constexpr LordGrad5 gAliveBlue = {{ IM_COL32(0x4A,0x6B,0xA3,0xFF), IM_COL32(0x3D,0x5F,0x98,0xFF), IM_COL32(0x30,0x5A,0x90,0xFF), IM_COL32(0x29,0x4E,0x7A,0xFF), IM_COL32(0x22,0x42,0x65,0xFF) }};
    static constexpr LordGrad5 gDeadBlue  = {{ IM_COL32(0x3A,0x4A,0x66,0xFF), IM_COL32(0x33,0x42,0x59,0xFF), IM_COL32(0x2C,0x3A,0x4D,0xFF), IM_COL32(0x25,0x32,0x40,0xFF), IM_COL32(0x1E,0x29,0x33,0xFF) }};
    static constexpr LordGrad5 gAliveRed  = {{ IM_COL32(0xCE,0x0C,0x0C,0xFF), IM_COL32(0xD6,0x34,0x34,0xFF), IM_COL32(0xD9,0x43,0x43,0xFF), IM_COL32(0xB2,0x00,0x00,0xFF), IM_COL32(0x7E,0x00,0x00,0xFF) }};
    static constexpr LordGrad5 gDeadRed   = {{ IM_COL32(0x47,0x1C,0x17,0xFF), IM_COL32(0x53,0x24,0x1B,0xFF), IM_COL32(0x52,0x24,0x1C,0xFF), IM_COL32(0x3C,0x19,0x14,0xFF), IM_COL32(0x2F,0x13,0x0F,0xFF) }};
    static constexpr LordGrad5 gDegenHex  = {{ IM_COL32(0xC9,0x47,0x9E,0xFF), IM_COL32(0xCE,0x5A,0xA8,0xFF), IM_COL32(0xD3,0x6C,0xB1,0xFF), IM_COL32(0xB5,0x33,0x8A,0xFF), IM_COL32(0x86,0x26,0x66,0xFF) }};
    static constexpr LordGrad5 gPoison    = {{ IM_COL32(0x7F,0x7F,0x3F,0xFF), IM_COL32(0x8B,0x8B,0x50,0xFF), IM_COL32(0x94,0x94,0x5F,0xFF), IM_COL32(0x66,0x66,0x2B,0xFF), IM_COL32(0x4E,0x4E,0x1D,0xFF) }};
    static constexpr LordGrad5 gBleeding  = {{ IM_COL32(0xDF,0x71,0x70,0xFF), IM_COL32(0xE1,0x7B,0x7B,0xFF), IM_COL32(0xE2,0x7E,0x7E,0xFF), IM_COL32(0xBC,0x59,0x59,0xFF), IM_COL32(0xA9,0x4F,0x50,0xFF) }};
    static constexpr LordGrad5 gDeepWound = {{ IM_COL32(0x92,0x92,0x92,0xFF), IM_COL32(0x9F,0x9F,0x9F,0xFF), IM_COL32(0xAB,0xAB,0xAB,0xFF), IM_COL32(0x84,0x84,0x84,0xFF), IM_COL32(0x73,0x73,0x73,0xFF) }};

    auto DrawLordGradRect = [](ImDrawList* dl, ImVec2 tl, ImVec2 br, const LordGrad5& g) {
        float w = br.x - tl.x;
        float h = br.y - tl.y;
        if (w < 1.f || h < 1.f) return;
        float bandH = h / 5.f;
        for (int i = 0; i < 5; ++i) {
            float y0 = tl.y + i * bandH;
            float y1 = (i == 4) ? br.y : y0 + bandH;
            ImU32 cTop = g.c[i];
            ImU32 cBot = (i < 4) ? g.c[i + 1] : g.c[i];
            dl->AddRectFilledMultiColor(ImVec2(tl.x, y0), ImVec2(br.x, y1), cTop, cTop, cBot, cBot);
        }
    };

    // Load status icons every frame through the cached loaders
    // (the loaders themselves cache by device+filename, so this is cheap)
    // Do NOT store raw pointers in statics — they can dangle if the
    // internal cache is invalidated on device change.
    ImTextureID sIconWeaponSpell = LoadEffectIcon(dev, "WeaponSpell.png");
    ImTextureID sIconEnchanted   = LoadPartyIcon(dev, "Enchanted.png");
    ImTextureID sIconCondition   = LoadPartyIcon(dev, "Condition.png");
    ImTextureID sIconHexed       = LoadPartyIcon(dev, "Hexed.png");

    ImGui::PushStyleColor(ImGuiCol_WindowBg,      ImVec4(0.055f, 0.063f, 0.078f, 0.94f));
    ImGui::PushStyleColor(ImGuiCol_TitleBg,       ImVec4(0.07f, 0.08f, 0.10f, 1.f));
    ImGui::PushStyleColor(ImGuiCol_TitleBgActive, ImVec4(0.10f, 0.09f, 0.06f, 1.f));
    ImGui::PushStyleColor(ImGuiCol_Border,        ImVec4(0.16f, 0.12f, 0.06f, 0.85f));
    ImGui::PushStyleColor(ImGuiCol_Separator,     ImVec4(0.40f, 0.33f, 0.15f, 0.40f));
    ImGui::PushStyleVar(ImGuiStyleVar_WindowRounding, 6.f);
    ImGui::PushStyleVar(ImGuiStyleVar_WindowBorderSize, 1.f);
    ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(10, 8));

    ImGui::SetNextWindowSizeConstraints(ImVec2(600, 100), ImVec2(900, FLT_MAX));
    m_panelLayout.ApplyPosition("lord_damage");

    if (!ImGui::Begin("Lord Damage##lord_dmg", &m_showLordDamagePanel,
            ImGuiWindowFlags_AlwaysAutoResize))
    {
        m_panelLayout.TrackWindow("lord_damage");
        ImGui::End();
        ImGui::PopStyleVar(3);
        ImGui::PopStyleColor(5);
        return;
    }

    m_panelLayout.TrackWindow("lord_damage");

    // Viewport clamping
    {
        ImVec2 vpSz = ImGui::GetMainViewport()->Size;
        ImVec2 wPos = ImGui::GetWindowPos();
        ImVec2 wSz  = ImGui::GetWindowSize();
        wPos.x = std::clamp(wPos.x, 0.f, std::max(0.f, vpSz.x - wSz.x));
        wPos.y = std::clamp(wPos.y, 0.f, std::max(0.f, vpSz.y - wSz.y));
        ImGui::SetWindowPos(wPos);
    }

    const ImU32 cLabel   = IM_COL32(0x70, 0x7d, 0x88, 255);
    const ImU32 cWhite   = IM_COL32(0xe2, 0xe3, 0xe4, 255);
    const ImU32 cBlue    = IM_COL32(74, 144, 216, 255);
    const ImU32 cRed     = IM_COL32(208, 72, 72, 255);
    const ImU32 cGreen   = IM_COL32(80, 200, 80, 255);
    const ImU32 cAmber   = IM_COL32(220, 180, 40, 255);
    const ImU32 cDanger  = IM_COL32(220, 60, 50, 255);

    auto hpColor = [&](float pct) -> ImU32 {
        if (pct > 0.6f) return cGreen;
        if (pct > 0.3f) return cAmber;
        return cDanger;
    };

    auto formatDmg = [](int v) -> std::string {
        if (v < 1000) return std::to_string(v);
        std::string s = std::to_string(v);
        int insertPos = (int)s.length() - 3;
        while (insertPos > 0) { s.insert(insertPos, ","); insertPos -= 3; }
        return s;
    };

    float colW = std::max(50.f, (ImGui::GetContentRegionAvail().x - 10.f) * 0.5f);

    // ---- PART 1: Lord header (icon, name, HP bar, stats) per column ----
    auto DrawLordHeader = [&](int idx, float startX) {
        auto& ld = m_lordDmg[idx];
        bool isRed = (idx == 1);
        const char* teamLabel = isRed ? "Red" : "Blue";
        const char* iconFile = isRed ? "redguildlord.png" : "blueguildlord.png";
        const std::string& guildHeader = isRed ? m_team2GuildHeader : m_team1GuildHeader;

        ImGui::SetCursorPosX(startX);
        float cursorY = ImGui::GetCursorPosY();

        ImTextureID lordTex = LoadFlagIcon(dev, iconFile);
        if (lordTex)
        {
            ImVec2 p = ImGui::GetCursorScreenPos();
            ImGui::GetWindowDrawList()->AddImage(lordTex,
                ImVec2(p.x, p.y), ImVec2(p.x + 32, p.y + 32));
        }

        const ImU32 cGuildHeader = IM_COL32(245, 227, 181, 255);
        float textX = startX + 36.f;
        ImGui::SetCursorPos(ImVec2(textX, cursorY + 1.f));
        ImGui::GetWindowDrawList()->AddText(font, font->FontSize,
            ImGui::GetCursorScreenPos(), cGuildHeader,
            guildHeader.empty() ? teamLabel : guildHeader.c_str());
        ImGui::SetCursorPos(ImVec2(textX, cursorY + 17.f));
        ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(1, 1, 1, 1));
        ImGui::TextUnformatted(std::format("{} Guild Lord", teamLabel).c_str());
        ImGui::PopStyleColor();

        ImGui::SetCursorPosX(startX);
        ImGui::SetCursorPosY(cursorY + 36.f);

        if (ld.lordAgentId < 0)
        {
            ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.33f, 0.34f, 0.35f, 1.f));
            ImGui::TextUnformatted("No lord found");
            ImGui::PopStyleColor();
            return;
        }

        const AgentSnapshot* snap = nullptr;
        float hpPct = 1.f;
        bool isDead = false;
        uint8_t teamId = isRed ? 2 : 1;
        auto lordIt = m_replayCtx.agents.find(ld.lordAgentId);
        if (lordIt != m_replayCtx.agents.end())
        {
            snap = FindSnapshotAtTime(lordIt->second, curTime);
            if (snap) { hpPct = std::clamp(snap->health_pct, 0.f, 1.f); isDead = snap->is_dead; }
        }

        // Party-window-style HP bar
        {
            constexpr float barH = 20.f;
            float barW = std::max(4.f, colW);
            ImVec2 barTL = ImGui::GetCursorScreenPos();
            ImVec2 barBR(barTL.x + barW, barTL.y + barH);
            ImDrawList* dl = ImGui::GetWindowDrawList();

            dl->AddRect(barTL, barBR, IM_COL32(0x4E, 0x4D, 0x48, 0xFF), 0.f, 0, 1.0f);
            ImVec2 innerTL(barTL.x + 1, barTL.y + 1);
            ImVec2 innerBR(barBR.x - 1, barBR.y - 1);
            float innerW = innerBR.x - innerTL.x;
            float innerH = innerBR.y - innerTL.y;

            const LordGrad5* fillGrad = nullptr;
            if (isDead)
                fillGrad = (teamId == 1) ? &gDeadBlue : &gDeadRed;
            else if (snap && snap->has_degen_hex)
                fillGrad = &gDegenHex;
            else if (snap && snap->has_poison)
                fillGrad = &gPoison;
            else if (snap && snap->has_bleeding)
                fillGrad = &gBleeding;
            else
                fillGrad = (teamId == 1) ? &gAliveBlue : &gAliveRed;

            if (isDead)
            {
                DrawLordGradRect(dl, innerTL, innerBR, *fillGrad);
            }
            else
            {
                const LordGrad5* deadGrad = (teamId == 1) ? &gDeadBlue : &gDeadRed;
                DrawLordGradRect(dl, innerTL, innerBR, *deadGrad);
                bool hasDeepWound = snap && snap->has_deep_wound && !isDead;
                float fillPct = hasDeepWound ? std::min(hpPct, 0.80f) : hpPct;
                if (fillPct > 0.f)
                    DrawLordGradRect(dl, innerTL, ImVec2(innerTL.x + innerW * fillPct, innerBR.y), *fillGrad);
                if (hasDeepWound)
                    DrawLordGradRect(dl, ImVec2(innerTL.x + innerW * 0.80f, innerTL.y), innerBR, gDeepWound);
            }

            char hpText[32];
            snprintf(hpText, sizeof(hpText), "%d%%", (int)(hpPct * 100.f));
            ImVec2 hpSz = ImGui::CalcTextSize(hpText);
            ImVec2 hpPos(innerTL.x + 4.f, innerTL.y + (innerH - hpSz.y) * 0.5f);
            dl->AddText(ImVec2(hpPos.x + 1, hpPos.y + 1), IM_COL32(0, 0, 0, 0xCC), hpText);
            dl->AddText(hpPos, isDead ? IM_COL32(0x80, 0x80, 0x80, 0xFF) : cWhite, hpText);

            if (snap && !isDead)
            {
                const float icoSz = std::min(innerH - 2.f, 16.f);
                float iconX = innerBR.x - 2.f;
                float iconY = innerTL.y + (innerH - icoSz) * 0.5f;
                if (snap->has_weapon_spell && sIconWeaponSpell)
                    { iconX -= icoSz; dl->AddImage(sIconWeaponSpell, ImVec2(iconX, iconY), ImVec2(iconX + icoSz, iconY + icoSz)); iconX -= 1.f; }
                if (snap->has_enchantment && sIconEnchanted)
                    { iconX -= icoSz; dl->AddImage(sIconEnchanted, ImVec2(iconX, iconY), ImVec2(iconX + icoSz, iconY + icoSz)); iconX -= 1.f; }
                if ((snap->has_condition || snap->has_deep_wound || snap->has_bleeding || snap->has_poison) && sIconCondition)
                    { iconX -= icoSz; dl->AddImage(sIconCondition, ImVec2(iconX, iconY), ImVec2(iconX + icoSz, iconY + icoSz)); iconX -= 1.f; }
                if (snap->has_hex && sIconHexed)
                    { iconX -= icoSz; dl->AddImage(sIconHexed, ImVec2(iconX, iconY), ImVec2(iconX + icoSz, iconY + icoSz)); }
            }
            ImGui::Dummy(ImVec2(barW, barH));
        }
        ImGui::SetCursorPosX(startX);

        // Compute live stats up to current timestamp
        int liveTotalDmg = 0;
        float liveLowHp = 1.f;
        for (const auto& h : ld.hits)
        {
            if (h.time > curTime) break;
            liveTotalDmg += h.rawDmg;
        }
        if (lordIt != m_replayCtx.agents.end())
        {
            for (const auto& s : lordIt->second.snapshots)
            {
                if (s.time > curTime) break;
                if (s.health_pct < liveLowHp && s.health_pct >= 0.f)
                    liveLowHp = s.health_pct;
            }
        }

        if (liveTotalDmg > 0)
        {
            ImU32 lpCol = hpColor(liveLowHp);
            ImGui::GetWindowDrawList()->AddText(font, font->FontSize,
                ImGui::GetCursorScreenPos(), lpCol,
                std::format("Low point: {:.0f}%", liveLowHp * 100.f).c_str());
            ImGui::Dummy(ImVec2(colW, font->FontSize + 2.f));
            ImGui::SetCursorPosX(startX);

            ImVec2 p = ImGui::GetCursorScreenPos();
            ImGui::GetWindowDrawList()->AddText(font, font->FontSize, p, cLabel, "Dmg taken: ");
            ImVec2 valSz = font->CalcTextSizeA(font->FontSize, FLT_MAX, 0.f, "Dmg taken: ");
            ImGui::GetWindowDrawList()->AddText(font, font->FontSize,
                ImVec2(p.x + valSz.x, p.y), cWhite, formatDmg(liveTotalDmg).c_str());
            ImGui::Dummy(ImVec2(colW, font->FontSize + 2.f));
        }
        else
        {
            ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.33f, 0.34f, 0.35f, 1.f));
            ImGui::TextUnformatted("Never attacked");
            ImGui::PopStyleColor();
        }
    };

    // ---- PART 2: Attacker breakdown per column ----
    auto DrawLordAttackers = [&](int idx, float startX) {
        auto& ld = m_lordDmg[idx];
        if (ld.lordAgentId < 0) return;

        int liveTotalDmg = 0;
        std::unordered_map<int, int> liveAttackerDmg;
        for (const auto& h : ld.hits)
        {
            if (h.time > curTime) break;
            liveTotalDmg += h.rawDmg;
            liveAttackerDmg[h.casterId] += h.rawDmg;
        }
        if (liveTotalDmg <= 0) return;

        ImGui::SetCursorPosX(startX);
        {
            float fs10 = 10.f;
            ImGui::GetWindowDrawList()->AddText(font, fs10,
                ImGui::GetCursorScreenPos(), cLabel, "ATTACKERS");
            ImGui::Dummy(ImVec2(colW, fs10 + 3.f));
        }

        std::vector<LordAttackerRow> liveRows;
        liveRows.reserve(liveAttackerDmg.size());
        for (auto& [aid, dmg] : liveAttackerDmg)
        {
            LordAttackerRow row;
            row.agentId = aid;
            row.totalDmg = dmg;
            row.pct = (liveTotalDmg > 0) ? (float)dmg / (float)liveTotalDmg : 0.f;
            auto ait = m_replayCtx.agents.find(aid);
            if (ait != m_replayCtx.agents.end())
            {
                row.name = ait->second.partyBarLabel.empty()
                    ? ait->second.playerName : ait->second.partyBarLabel;
                row.professionId = ait->second.primaryProf;
                row.teamId = ait->second.teamId;
            }
            liveRows.push_back(std::move(row));
        }
        std::sort(liveRows.begin(), liveRows.end(),
            [](const LordAttackerRow& a, const LordAttackerRow& b) { return a.totalDmg > b.totalDmg; });
        if (liveRows.size() > 8) liveRows.resize(8);

        const float atkFontSz = font->FontSize;
        const float rowH = std::max(20.f, atkFontSz + 6.f);
        const float iconSz = 16.f;

        for (const auto& atk : liveRows)
        {
            ImGui::SetCursorPosX(startX);
            ImVec2 rowP = ImGui::GetCursorScreenPos();
            ImDrawList* dl = ImGui::GetWindowDrawList();

            float iconY = rowP.y + (rowH - iconSz) * 0.5f;
            ImTextureID profTex = LoadProfIcon(dev, atk.professionId);
            if (profTex)
                dl->AddImage(profTex, ImVec2(rowP.x, iconY), ImVec2(rowP.x + iconSz, iconY + iconSz));

            float textY = rowP.y + (rowH - atkFontSz) * 0.5f;
            float nameW = std::max(40.f, colW * 0.45f);
            float nameX = rowP.x + iconSz + 4.f;
            dl->PushClipRect(ImVec2(nameX, rowP.y),
                ImVec2(nameX + nameW, rowP.y + rowH), true);
            dl->AddText(font, atkFontSz, ImVec2(nameX, textY),
                cWhite, atk.name.c_str());
            dl->PopClipRect();

            char pctBuf[16];
            snprintf(pctBuf, sizeof(pctBuf), "%d%%", (int)(atk.pct * 100.f));
            ImVec2 pctSz = font->CalcTextSizeA(atkFontSz, FLT_MAX, 0.f, pctBuf);
            float pctX = nameX + nameW + 4 + 30 - pctSz.x;
            dl->AddText(font, atkFontSz, ImVec2(pctX, textY), cWhite, pctBuf);

            float barX = nameX + nameW + 4 + 32;
            float barW = std::max(0.f, colW - (iconSz + 4 + nameW + 4 + 32));
            ImU32 barBg = IM_COL32(255, 255, 255, 15);
            ImU32 barFg = (atk.teamId == 2)
                ? IM_COL32(208, 72, 72, 178)
                : IM_COL32(74, 144, 216, 178);
            dl->AddRectFilled(ImVec2(barX, rowP.y + 3),
                ImVec2(barX + barW, rowP.y + rowH - 3), barBg, 2.f);
            dl->AddRectFilled(ImVec2(barX, rowP.y + 3),
                ImVec2(barX + barW * atk.pct, rowP.y + rowH - 3), barFg, 2.f);

            std::string absLabel = formatDmg(atk.totalDmg);
            ImVec2 absSz = font->CalcTextSizeA(atkFontSz, FLT_MAX, 0.f, absLabel.c_str());
            const float barPad = 4.f;
            float absTextY = rowP.y + (rowH - absSz.y) * 0.5f;
            float absTextX;
            if (barW >= absSz.x + barPad * 2.f)
                absTextX = barX + barW - barPad - absSz.x;
            else
                absTextX = barX + barW + barPad;
            dl->AddText(font, atkFontSz, ImVec2(absTextX + 1.f, absTextY + 1.f),
                IM_COL32(0, 0, 0, 0xCC), absLabel.c_str());
            dl->AddText(font, atkFontSz, ImVec2(absTextX, absTextY), cWhite, absLabel.c_str());

            ImGui::Dummy(ImVec2(colW, rowH));
        }
    };

    // ===== LAYOUT =====

    // Row 1: Lord headers (two columns)
    float col0X = ImGui::GetCursorPosX();
    float col1X = col0X + colW + 10.f;
    float savedY = ImGui::GetCursorPosY();

    DrawLordHeader(0, col0X);
    float afterHdr0Y = ImGui::GetCursorPosY();

    ImGui::SetCursorPosY(savedY);
    DrawLordHeader(1, col1X);
    float afterHdr1Y = ImGui::GetCursorPosY();

    ImGui::SetCursorPosY(std::max(afterHdr0Y, afterHdr1Y) + 4.f);
    ImGui::Separator();

    // Row 2: Timeline strip (full width, stable position)
    {
        float stripH = 24.f;
        float stripW = std::max(1.f, ImGui::GetContentRegionAvail().x);
        ImVec2 stripP = ImGui::GetCursorScreenPos();
        ImDrawList* dl = ImGui::GetWindowDrawList();

        ImGui::InvisibleButton("##LordTimeline", ImVec2(stripW, stripH));
        if (ImGui::IsItemActive() && stripW > 1.f)
        {
            float mx = ImGui::GetIO().MousePos.x - stripP.x;
            float ratio = std::clamp(mx / stripW, 0.f, 1.f);
            m_debugTimeline = ratio * maxT;
        }

        int nBuckets = (int)std::max(m_lordDmg[0].damageBuckets.size(),
                                      m_lordDmg[1].damageBuckets.size());
        if (nBuckets < 1) nBuckets = 1;
        float bw = stripW / (float)nBuckets;

        for (int b = 0; b < (int)m_lordDmg[1].damageBuckets.size(); ++b)
        {
            ImVec2 bMin(stripP.x + b * bw, stripP.y);
            ImVec2 bMax(stripP.x + (b + 1) * bw, stripP.y + 12.f);
            ImU32 col = m_lordDmg[1].damageBuckets[b]
                ? IM_COL32(74, 144, 216, 204)
                : IM_COL32(255, 255, 255, 10);
            dl->AddRectFilled(bMin, bMax, col);
        }

        for (int b = 0; b < (int)m_lordDmg[0].damageBuckets.size(); ++b)
        {
            ImVec2 bMin(stripP.x + b * bw, stripP.y + 12.f);
            ImVec2 bMax(stripP.x + (b + 1) * bw, stripP.y + 24.f);
            ImU32 col = m_lordDmg[0].damageBuckets[b]
                ? IM_COL32(208, 72, 72, 204)
                : IM_COL32(255, 255, 255, 10);
            dl->AddRectFilled(bMin, bMax, col);
        }

        dl->AddLine(ImVec2(stripP.x, stripP.y + 12.f),
                    ImVec2(stripP.x + stripW, stripP.y + 12.f),
                    IM_COL32(255, 255, 255, 25));

        float phX = stripP.x + (m_debugTimeline / maxT) * stripW;
        dl->AddLine(ImVec2(phX, stripP.y), ImVec2(phX, stripP.y + stripH),
            IM_COL32(200, 168, 75, 220), 1.5f);
    }

    ImGui::Separator();

    // Row 3: Attacker lists (two columns, grows with content)
    float atkSavedY = ImGui::GetCursorPosY();

    DrawLordAttackers(0, col0X);
    float afterAtk0Y = ImGui::GetCursorPosY();

    ImGui::SetCursorPosY(atkSavedY);
    DrawLordAttackers(1, col1X);
    float afterAtk1Y = ImGui::GetCursorPosY();

    ImGui::SetCursorPosY(std::max(afterAtk0Y, afterAtk1Y));

    ImGui::End();
    ImGui::PopStyleVar(3);
    ImGui::PopStyleColor(5);
}

// ---------------------------------------------------------------------------
// BuildTimelineData — precompute health curves + collect events
// ---------------------------------------------------------------------------
// ---------------------------------------------------------------------------
// BuildLordDamageData — one-time aggregation of guild lord combat stats
// ---------------------------------------------------------------------------
void ReplayWindow::BuildLordDamageData()
{
    if (m_lordDamageBuilt) return;
    m_lordDamageBuilt = true;

    m_lordDmg[0] = {};
    m_lordDmg[1] = {};

    // Find guild lord agent IDs
    for (int nid : m_npcIds)
    {
        auto it = m_replayCtx.agents.find(nid);
        if (it == m_replayCtx.agents.end()) continue;
        if (it->second.categoryName != "Guild Lord") continue;
        int idx = (it->second.teamId == 2) ? 1 : 0;
        m_lordDmg[idx].lordAgentId = nid;
    }

    float maxT = m_replayCtx.maxReplayTime;
    int bucketCount = std::max(1, (int)std::ceil(maxT / 5.f));

    for (int li = 0; li < 2; ++li)
    {
        auto& ld = m_lordDmg[li];
        if (ld.lordAgentId < 0) continue;

        ld.damageBuckets.resize(bucketCount, false);

        auto lordIt = m_replayCtx.agents.find(ld.lordAgentId);
        if (lordIt == m_replayCtx.agents.end()) continue;
        const auto& lordArd = lordIt->second;

        // Resolve base max HP for HP-bar rendering
        uint32_t baseMaxHp = 0;
        for (const auto& s : lordArd.snapshots)
            if (s.max_hp > 0) { baseMaxHp = s.max_hp; break; }
        if (baseMaxHp == 0)
            for (auto rit = lordArd.snapshots.rbegin(); rit != lordArd.snapshots.rend(); ++rit)
                if (rit->max_hp > 0) { baseMaxHp = rit->max_hp; break; }
        ld.lordMaxHp = baseMaxHp;

        // Low point from snapshots
        for (const auto& s : lordArd.snapshots)
            if (s.health_pct < ld.lowPointHp && s.health_pct >= 0.f)
                ld.lowPointHp = s.health_pct;

        // Use lord_events.txt data (server-computed integer damage)
        std::unordered_map<int, int> attackerDmg;
        std::vector<float> hitTimes;

        for (const auto& le : m_replayCtx.stocData.lordDamage)
        {
            if (le.target_id != ld.lordAgentId) continue;
            if (le.damage <= 0) continue;

            int rawDmg = le.damage;
            ld.totalDmgAbs += rawDmg;
            attackerDmg[le.caster_id] += rawDmg;
            hitTimes.push_back(le.time);
            ld.hits.push_back({ le.time, le.caster_id, rawDmg });

            int bucket = std::clamp((int)(le.time / 5.f), 0, bucketCount - 1);
            ld.damageBuckets[bucket] = true;
        }

        // Phases: 10+ second gap = new phase
        if (!hitTimes.empty())
        {
            std::sort(hitTimes.begin(), hitTimes.end());
            ld.phaseCount = 1;
            for (size_t i = 1; i < hitTimes.size(); ++i)
                if (hitTimes[i] - hitTimes[i - 1] >= 10.f)
                    ld.phaseCount++;
        }

        // Build attacker rows
        for (auto& [aid, dmg] : attackerDmg)
        {
            LordAttackerRow row;
            row.agentId = aid;
            row.totalDmg = dmg;
            row.pct = (ld.totalDmgAbs > 0) ? (float)dmg / (float)ld.totalDmgAbs : 0.f;
            auto ait = m_replayCtx.agents.find(aid);
            if (ait != m_replayCtx.agents.end())
            {
                row.name = ait->second.partyBarLabel.empty()
                    ? ait->second.playerName : ait->second.partyBarLabel;
                row.professionId = ait->second.primaryProf;
                row.teamId = ait->second.teamId;
            }
            ld.attackers.push_back(std::move(row));
        }
        std::sort(ld.attackers.begin(), ld.attackers.end(),
            [](const LordAttackerRow& a, const LordAttackerRow& b) { return a.totalDmg > b.totalDmg; });
        if (ld.attackers.size() > 8)
            ld.attackers.resize(8);
    }

    // Lord damage panel is toggled via menu, not auto-shown
}

void ReplayWindow::BuildTimelineData()
{
    if (m_timeline.computed) return;
    m_timeline.computed = true;

    float maxT = std::max(1.f, m_replayCtx.maxReplayTime);
    int totalSec = static_cast<int>(std::ceil(maxT));

    m_timeline.blueHealth.resize(totalSec + 1, 100.f);
    m_timeline.redHealth.resize(totalSec + 1, 100.f);

    auto sampleTeamHealth = [&](const std::vector<int>& ids, std::vector<float>& out) {
        for (int s = 0; s <= totalSec; ++s)
        {
            float t = static_cast<float>(s);
            float sumHp = 0.f, sumMaxHp = 0.f;
            for (int id : ids)
            {
                auto it = m_replayCtx.agents.find(id);
                if (it == m_replayCtx.agents.end()) continue;
                const auto& ard = it->second;
                if (ard.type != AgentType::Player) continue;
                const AgentSnapshot* snap = FindSnapshotAtTime(ard, t);
                if (!snap) continue;
                float mhp = static_cast<float>(snap->max_hp > 0 ? snap->max_hp : 480);
                sumMaxHp += mhp;
                if (snap->is_dead)
                    sumHp += 0.f;
                else
                    sumHp += snap->health_pct * mhp;
            }
            out[s] = (sumMaxHp > 0.f) ? (sumHp / sumMaxHp * 100.f) : 0.f;
        }
    };

    sampleTeamHealth(m_team1PlayerIds, m_timeline.blueHealth);
    sampleTeamHealth(m_team2PlayerIds, m_timeline.redHealth);

    auto teamForAgent = [&](int agentId) -> int {
        for (int id : m_team1PlayerIds) if (id == agentId) return 1;
        for (int id : m_team2PlayerIds) if (id == agentId) return 2;
        return 0;
    };

    // Deaths & resurrections from snapshot transitions
    for (auto& [agentId, ard] : m_replayCtx.agents)
    {
        if (ard.type != AgentType::Player) continue;
        int team = teamForAgent(agentId);
        for (size_t si = 1; si < ard.snapshots.size(); ++si)
        {
            const auto& prev = ard.snapshots[si - 1];
            const auto& cur  = ard.snapshots[si];
            if (cur.is_dead && !prev.is_dead)
            {
                TimelineEvent ev;
                ev.time = cur.time;
                ev.type = TimelineEventType::Death;
                ev.agentId = agentId;
                ev.teamId = team;
                ev.professionId = ard.primaryProf;
                ev.label = ard.playerName.empty() ? ard.partyBarLabel : ard.playerName;
                m_timeline.events.push_back(ev);
            }
            if (!cur.is_dead && prev.is_dead)
            {
                TimelineEvent ev;
                ev.time = cur.time;
                ev.type = TimelineEventType::Resurrection;
                ev.agentId = agentId;
                ev.teamId = team;
                ev.professionId = ard.primaryProf;
                ev.label = ard.playerName.empty() ? ard.partyBarLabel : ard.playerName;
                m_timeline.events.push_back(ev);
            }
        }
    }

    // Jumbo events
    auto jumboTeamId = [](int pv) -> int {
        return (pv == 1635021873) ? 1 : (pv == 1635021874) ? 2 : 0;
    };

    for (auto& ev : m_replayCtx.stocData.jumbo)
    {
        TimelineEvent te;
        te.time = ev.time;
        te.teamId = jumboTeamId(ev.party_value);

        if (ev.message == "CAPTURED_TOWER") {
            te.type = TimelineEventType::FlagCapture;
            te.label = (te.teamId == 1 ? "Blue" : "Red") + std::string(" captured tower");
        }
        else if (ev.message == "MORALE_BOOST") {
            te.type = TimelineEventType::MoraleBoost;
            te.label = (te.teamId == 1 ? "Blue" : "Red") + std::string(" morale boost");
        }
        else if (ev.message == "GUILD_LORD_UNDER_ATTACK" || ev.message == "BASE_UNDER_ATTACK") {
            te.type = TimelineEventType::LordAttacked;
            te.label = (te.teamId == 1 ? "Blue" : "Red") + std::string(" lord under attack");
        }
        else if (ev.message == "VICTORY" || ev.message == "FLAWLESS_VICTORY") {
            te.type = TimelineEventType::Victory;
            te.label = (te.teamId == 1 ? "Blue" : "Red") + std::string(" victory!");
        }
        else if (ev.message == "CAPTURED_SHRINE") {
            te.type = TimelineEventType::ShrineCaptured;
            te.label = (te.teamId == 1 ? "Blue" : "Red") + std::string(" captured shrine");
        }
        else if (ev.message == "NEUTRALIZED_SHRINE") {
            // party_value identifies the losing team — invert for display
            if (te.teamId > 0) te.teamId = (te.teamId == 1) ? 2 : 1;
            te.type = TimelineEventType::ShrineNeutralized;
            te.label = (te.teamId == 1 ? "Blue" : "Red") + std::string(" neutralized shrine");
        }
        else continue;

        m_timeline.events.push_back(te);
    }

    // Add flag return events from the flag timeline
    if (m_flagTimelineBuilt && m_flagTimeline.valid) {
        for (auto& ev : m_flagTimeline.allEvents) {
            if (ev.eventType != FlagTimelineEventType::Return) continue;
            TimelineEvent te;
            te.time = ev.time;
            te.type = TimelineEventType::FlagReturn;
            te.teamId = (ev.flagTeam == FlagTeam::Blue) ? 1 : 2;
            te.label = "Flag returned";
            m_timeline.events.push_back(std::move(te));
        }
    }

    std::sort(m_timeline.events.begin(), m_timeline.events.end(),
        [](const TimelineEvent& a, const TimelineEvent& b) { return a.time < b.time; });
}

// ---------------------------------------------------------------------------
// Timeline profession icon loader (Textures/professions/{id}.png — same as website)
// ---------------------------------------------------------------------------
static ImTextureID LoadProfIconTimeline(ID3D11Device* device, int profId)
{
    if (profId < 1 || profId > 10) return nullptr;

    static ID3D11Device* s_dev = nullptr;
    static std::unordered_map<int, ComPtr<ID3D11ShaderResourceView>> s_cache;
    if (device != s_dev) { s_cache.clear(); s_dev = device; }

    auto it = s_cache.find(profId);
    if (it != s_cache.end()) return (ImTextureID)it->second.Get();

    static std::filesystem::path basePath;
    if (basePath.empty())
    {
        wchar_t exePath[MAX_PATH];
        GetModuleFileNameW(nullptr, exePath, MAX_PATH);
        auto dir = std::filesystem::path(exePath).parent_path();
        for (int i = 0; i < 5; i++)
        {
            if (std::filesystem::exists(dir / "Textures" / "professions"))
            {
                basePath = dir / "Textures" / "professions";
                break;
            }
            if (!dir.has_parent_path() || dir == dir.parent_path()) break;
            dir = dir.parent_path();
        }
        if (basePath.empty())
            basePath = std::filesystem::path(exePath).parent_path() / "Textures" / "professions";
    }

    char fn[16]; snprintf(fn, sizeof(fn), "%d.png", profId);
    auto fullPath = basePath / fn;
    if (!std::filesystem::exists(fullPath)) return nullptr;

    DirectX::ScratchImage image;
    HRESULT hr = DirectX::LoadFromWICFile(fullPath.c_str(), DirectX::WIC_FLAGS_NONE, nullptr, image);
    if (FAILED(hr)) return nullptr;

    const auto& meta = image.GetMetadata();
    if (meta.width == 0 || meta.height == 0) return nullptr;

    DirectX::ScratchImage converted;
    if (meta.format != DXGI_FORMAT_R8G8B8A8_UNORM)
    {
        hr = DirectX::Convert(*image.GetImage(0, 0, 0), DXGI_FORMAT_R8G8B8A8_UNORM,
            DirectX::TEX_FILTER_DEFAULT, DirectX::TEX_THRESHOLD_DEFAULT, converted);
        if (FAILED(hr)) return nullptr;
    }
    const DirectX::ScratchImage& src = converted.GetImageCount() > 0 ? converted : image;
    const auto* img = src.GetImage(0, 0, 0);

    D3D11_TEXTURE2D_DESC texDesc = {};
    texDesc.Width = static_cast<UINT>(img->width);
    texDesc.Height = static_cast<UINT>(img->height);
    texDesc.MipLevels = 1;
    texDesc.ArraySize = 1;
    texDesc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
    texDesc.SampleDesc.Count = 1;
    texDesc.Usage = D3D11_USAGE_DEFAULT;
    texDesc.BindFlags = D3D11_BIND_SHADER_RESOURCE;

    D3D11_SUBRESOURCE_DATA initData = {};
    initData.pSysMem = img->pixels;
    initData.SysMemPitch = static_cast<UINT>(img->rowPitch);

    ComPtr<ID3D11Texture2D> tex;
    hr = device->CreateTexture2D(&texDesc, &initData, &tex);
    if (FAILED(hr)) return nullptr;

    ComPtr<ID3D11ShaderResourceView> srv;
    hr = device->CreateShaderResourceView(tex.Get(), nullptr, &srv);
    if (FAILED(hr)) return nullptr;

    s_cache[profId] = srv;
    return (ImTextureID)srv.Get();
}

// ---------------------------------------------------------------------------
// NPC icon loader (Textures/NPC subfolder)
// ---------------------------------------------------------------------------
static std::filesystem::path GetNPCIconBasePath()
{
    static std::filesystem::path cached;
    if (!cached.empty()) return cached;
    wchar_t exePath[MAX_PATH];
    GetModuleFileNameW(nullptr, exePath, MAX_PATH);
    auto dir = std::filesystem::path(exePath).parent_path();
    for (int i = 0; i < 5; i++)
    {
        if (std::filesystem::exists(dir / "Textures" / "NPC"))
        {
            cached = dir / "Textures" / "NPC";
            return cached;
        }
        if (!dir.has_parent_path() || dir == dir.parent_path()) break;
        dir = dir.parent_path();
    }
    cached = std::filesystem::path(exePath).parent_path() / "Textures" / "NPC";
    return cached;
}

static ImTextureID LoadNPCIcon(ID3D11Device* device, const char* filename)
{
    static ID3D11Device* s_cachedDevice = nullptr;
    static std::unordered_map<std::string, ComPtr<ID3D11ShaderResourceView>> s_cache;
    if (device != s_cachedDevice) { s_cache.clear(); s_cachedDevice = device; }

    auto it = s_cache.find(filename);
    if (it != s_cache.end()) return (ImTextureID)it->second.Get();

    auto fullPath = GetNPCIconBasePath() / std::filesystem::path(filename);
    if (!std::filesystem::exists(fullPath)) return nullptr;

    DirectX::ScratchImage image;
    HRESULT hr = DirectX::LoadFromWICFile(fullPath.c_str(), DirectX::WIC_FLAGS_NONE, nullptr, image);
    if (FAILED(hr)) return nullptr;

    const auto& meta = image.GetMetadata();
    if (meta.width == 0 || meta.height == 0) return nullptr;

    DirectX::ScratchImage converted;
    if (meta.format != DXGI_FORMAT_R8G8B8A8_UNORM)
    {
        hr = DirectX::Convert(*image.GetImage(0, 0, 0), DXGI_FORMAT_R8G8B8A8_UNORM,
            DirectX::TEX_FILTER_DEFAULT, DirectX::TEX_THRESHOLD_DEFAULT, converted);
        if (FAILED(hr)) return nullptr;
    }
    const DirectX::ScratchImage& src = converted.GetImageCount() > 0 ? converted : image;
    const auto* img = src.GetImage(0, 0, 0);

    D3D11_TEXTURE2D_DESC texDesc = {};
    texDesc.Width = static_cast<UINT>(img->width);
    texDesc.Height = static_cast<UINT>(img->height);
    texDesc.MipLevels = 1;
    texDesc.ArraySize = 1;
    texDesc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
    texDesc.SampleDesc.Count = 1;
    texDesc.Usage = D3D11_USAGE_DEFAULT;
    texDesc.BindFlags = D3D11_BIND_SHADER_RESOURCE;

    D3D11_SUBRESOURCE_DATA initData = {};
    initData.pSysMem = img->pixels;
    initData.SysMemPitch = static_cast<UINT>(img->rowPitch);

    ComPtr<ID3D11Texture2D> tex;
    hr = device->CreateTexture2D(&texDesc, &initData, &tex);
    if (FAILED(hr)) return nullptr;

    ComPtr<ID3D11ShaderResourceView> srv;
    hr = device->CreateShaderResourceView(tex.Get(), nullptr, &srv);
    if (FAILED(hr)) return nullptr;

    s_cache[filename] = srv;
    return (ImTextureID)srv.Get();
}

static std::filesystem::path GetSkillIconsBasePath();

static ImTextureID LoadSkillIconFile(ID3D11Device* device, const char* filename)
{
    static ID3D11Device* s_cachedDevice = nullptr;
    static std::unordered_map<std::string, ComPtr<ID3D11ShaderResourceView>> s_cache;
    if (device != s_cachedDevice) { s_cache.clear(); s_cachedDevice = device; }

    auto it = s_cache.find(filename);
    if (it != s_cache.end()) return (ImTextureID)it->second.Get();

    auto fullPath = GetSkillIconsBasePath() / std::filesystem::path(filename);
    if (!std::filesystem::exists(fullPath)) return nullptr;

    DirectX::ScratchImage image;
    HRESULT hr = DirectX::LoadFromWICFile(fullPath.c_str(), DirectX::WIC_FLAGS_NONE, nullptr, image);
    if (FAILED(hr)) return nullptr;

    const auto& meta = image.GetMetadata();
    if (meta.width == 0 || meta.height == 0) return nullptr;

    DirectX::ScratchImage converted;
    if (meta.format != DXGI_FORMAT_R8G8B8A8_UNORM)
    {
        hr = DirectX::Convert(*image.GetImage(0, 0, 0), DXGI_FORMAT_R8G8B8A8_UNORM,
            DirectX::TEX_FILTER_DEFAULT, DirectX::TEX_THRESHOLD_DEFAULT, converted);
        if (FAILED(hr)) return nullptr;
    }
    const DirectX::ScratchImage& src = converted.GetImageCount() > 0 ? converted : image;
    const auto* img = src.GetImage(0, 0, 0);

    D3D11_TEXTURE2D_DESC texDesc = {};
    texDesc.Width = static_cast<UINT>(img->width);
    texDesc.Height = static_cast<UINT>(img->height);
    texDesc.MipLevels = 1;
    texDesc.ArraySize = 1;
    texDesc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
    texDesc.SampleDesc.Count = 1;
    texDesc.Usage = D3D11_USAGE_DEFAULT;
    texDesc.BindFlags = D3D11_BIND_SHADER_RESOURCE;

    D3D11_SUBRESOURCE_DATA initData = {};
    initData.pSysMem = img->pixels;
    initData.SysMemPitch = static_cast<UINT>(img->rowPitch);

    ComPtr<ID3D11Texture2D> tex;
    hr = device->CreateTexture2D(&texDesc, &initData, &tex);
    if (FAILED(hr)) return nullptr;

    ComPtr<ID3D11ShaderResourceView> srv;
    hr = device->CreateShaderResourceView(tex.Get(), nullptr, &srv);
    if (FAILED(hr)) return nullptr;

    s_cache[filename] = srv;
    return (ImTextureID)srv.Get();
}

// ---------------------------------------------------------------------------
// DrawEventTimeline — full-width panel above playback bar
// ---------------------------------------------------------------------------
void ReplayWindow::DrawEventTimeline()
{
    if (!m_showEventTimeline || !m_timeline.computed) return;

    const ImGuiViewport* vp = ImGui::GetMainViewport();
    const float vpW = vp->Size.x;
    const float vpH = vp->Size.y;

    const float playbarH = 76.f;
    const float panelH   = 160.f;
    const float topPad   = 6.f;
    const float scrubH   = 16.f;
    const float chartH   = panelH - topPad - scrubH;

    // Match playback bar's internal layout for horizontal alignment
    const float PAD    = 12.f;
    const float timeW  = 80.f;
    const float badgeW = 64.f;

    float maxT = std::max(1.f, m_replayCtx.maxReplayTime);
    auto* dev = m_deviceResources->GetD3DDevice();

    ImVec2 panelPos(vp->Pos.x, vp->Pos.y + vpH - playbarH - panelH);
    ImGui::SetNextWindowPos(panelPos);
    ImGui::SetNextWindowSize(ImVec2(vpW, panelH));

    constexpr ImGuiWindowFlags kFlags =
        ImGuiWindowFlags_NoTitleBar      | ImGuiWindowFlags_NoResize       |
        ImGuiWindowFlags_NoMove          | ImGuiWindowFlags_NoScrollbar    |
        ImGuiWindowFlags_NoCollapse      | ImGuiWindowFlags_NoSavedSettings |
        ImGuiWindowFlags_NoBackground    | ImGuiWindowFlags_NoFocusOnAppearing;

    ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(0, 0));
    if (!ImGui::Begin("##EventTimeline", nullptr, kFlags))
    {
        ImGui::End();
        ImGui::PopStyleVar();
        return;
    }
    ImGui::PopStyleVar();

    ImDrawList* dl = ImGui::GetWindowDrawList();
    const ImVec2 O = ImGui::GetWindowPos();
    ImFont* font = ImGui::GetFont();
    const float fs = font->FontSize;

    // ── Palette ──────────────────────────────────────────────────────────
    const ImU32 cBg         = IM_COL32( 10,  14,  18, 166);
    const ImU32 cGlass      = IM_COL32( 18,  16,  10, 100);
    const ImU32 cBorderHi   = IM_COL32(200, 168,  75,  82);
    const ImU32 cText       = IM_COL32(232, 223, 200, 255);
    const ImU32 cTextDim    = IM_COL32(120, 108,  80, 255);
    const ImU32 cGrid       = IM_COL32(255, 255, 255,   8);
    const ImU32 cBlue       = IM_COL32( 74, 144, 216, 255);
    const ImU32 cBlueFill   = IM_COL32( 74, 144, 216,  18);
    const ImU32 cRed        = IM_COL32(208,  72,  72, 255);
    const ImU32 cRedFill    = IM_COL32(208,  72,  72,  18);
    const ImU32 cPlayhead   = IM_COL32(255, 215, 100, 200);

    // ── Background ──────────────────────────────────────────────────────
    dl->AddRectFilled(O, ImVec2(O.x + vpW, O.y + panelH), cBg, 0.f);
    {
        float px = O.x + 2.f, py = O.y + 2.f;
        float pw = vpW - 4.f, ph = panelH - 4.f;
        dl->AddRectFilled(ImVec2(px, py), ImVec2(px + pw, py + ph), cGlass, 6.f);
        dl->AddRect(ImVec2(px, py), ImVec2(px + pw, py + ph), cBorderHi, 6.f);
    }

    // ── Chart area — aligned to playback bar's scrubber track ───────────
    const float glassX = O.x + 2.f;
    const float glassW = vpW - 4.f;
    const float chartX0 = glassX + PAD + timeW + 6.f;
    const float chartX1 = glassX + glassW - PAD - badgeW - 6.f;
    const float chartY0 = O.y + topPad;
    const float chartY1 = chartY0 + chartH;
    const float chartW  = chartX1 - chartX0;
    const float scrubY0 = chartY1;
    const float scrubY1 = scrubY0 + scrubH;

    // ── Close button (top-right X) ──────────────────────────────────────
    {
        const float btnSz = 18.f;
        const float margin = 6.f;
        ImVec2 btnMin(O.x + vpW - margin - btnSz, O.y + margin);
        ImVec2 btnMax(btnMin.x + btnSz, btnMin.y + btnSz);
        ImVec2 center((btnMin.x + btnMax.x) * 0.5f, (btnMin.y + btnMax.y) * 0.5f);

        bool btnHov = ImGui::IsMouseHoveringRect(btnMin, btnMax);
        ImU32 btnBg  = btnHov ? IM_COL32(200, 60, 60, 200) : IM_COL32(255, 255, 255, 20);
        ImU32 xCol   = btnHov ? IM_COL32(255, 255, 255, 255) : IM_COL32(200, 168, 75, 180);

        dl->AddRectFilled(btnMin, btnMax, btnBg, 3.f);
        dl->AddRect(btnMin, btnMax, IM_COL32(200, 168, 75, 80), 3.f);
        float cr = 5.f;
        dl->AddLine(ImVec2(center.x - cr, center.y - cr),
                    ImVec2(center.x + cr, center.y + cr), xCol, 1.5f);
        dl->AddLine(ImVec2(center.x + cr, center.y - cr),
                    ImVec2(center.x - cr, center.y + cr), xCol, 1.5f);

        if (btnHov && ImGui::IsMouseClicked(0))
            m_showEventTimeline = false;
    }

    // ── Filter pills — vertical left column ─────────────────────────────
    {
        const float iconH   = 16.f;
        const float pillH   = 20.f;
        const float pillGap = 3.f;
        const float pillW   = chartX0 - O.x - 34.f;
        float lx = O.x + 6.f;
        float ly = O.y + 6.f;
        const float fsPill = fs * 1.0f;

        auto FilterPill = [&](const char* label, bool& active, ImTextureID miniTex, ImU32 fallbackCol) {
            ImVec2 p0(lx, ly);
            ImVec2 p1(lx + pillW, ly + pillH);

            bool hovered = ImGui::IsMouseHoveringRect(p0, p1);
            if (hovered && ImGui::IsMouseClicked(0))
                active = !active;

            ImU32 bg     = active ? IM_COL32(47, 36, 15, 220) : IM_COL32(20, 20, 20, 150);
            ImU32 border = active ? IM_COL32(255, 215, 100, 255) : IM_COL32(255, 255, 255, 30);
            ImU32 text   = active ? IM_COL32(255, 232, 176, 255) : IM_COL32(120, 120, 120, 255);

            if (hovered) bg = IM_COL32(60, 50, 20, 220);

            dl->AddRectFilled(p0, p1, bg, 4.f);
            dl->AddRect(p0, p1, border, 4.f);

            float iy = ly + (pillH - iconH) * 0.5f;
            if (miniTex)
                dl->AddImage(miniTex, ImVec2(lx + 5.f, iy), ImVec2(lx + 5.f + iconH, iy + iconH));
            else
                dl->AddCircleFilled(ImVec2(lx + 5.f + iconH * 0.5f, ly + pillH * 0.5f), 4.f, fallbackCol);

            dl->AddText(font, fsPill,
                ImVec2(lx + 5.f + iconH + 4.f, ly + (pillH - fsPill) * 0.5f), text, label);

            ly += pillH + pillGap;
        };

        ImTextureID deathTex  = LoadProfIcon(dev, 1);
        ImTextureID flagTex   = LoadFlagIcon(dev, "Blue_flag_waving.svg.png");
        ImTextureID moraleTex = LoadFlagIcon(dev, "bluemorale.png");
        ImTextureID lordTex   = LoadFlagIcon(dev, "blueguildlord.png");

        FilterPill("Death",   m_tlFilterDeath,  deathTex,  IM_COL32(208,  72,  72, 255));
        FilterPill("Flag",    m_tlFilterFlag,   flagTex,   IM_COL32(255, 200,  60, 255));
        FilterPill("Return",  m_tlFilterFlagReturn, flagTex, IM_COL32(40, 200, 40, 255));
        FilterPill("Morale",  m_tlFilterMorale, moraleTex, IM_COL32(212, 160,  32, 255));
        FilterPill("Lord",    m_tlFilterLord,   lordTex,   IM_COL32(255,  90,  90, 255));

        ImTextureID shrineTex = LoadFlagIcon(dev, "Health_Shrine_Bonus.jpg");
        FilterPill("Shrine",  m_tlFilterShrine, shrineTex, IM_COL32(220, 200, 120, 255));
    }

    // ── Clip to chart area ──────────────────────────────────────────────
    dl->PushClipRect(ImVec2(chartX0, chartY0), ImVec2(chartX1, chartY1), true);

    // ── Horizontal gridlines only (no vertical lines) ─────────────────
    for (int pct = 25; pct <= 100; pct += 25)
    {
        float y = chartY1 - (pct / 100.f) * chartH;
        dl->AddLine(ImVec2(chartX0, y), ImVec2(chartX1, y), cGrid);
    }

    float interval = maxT < 300.f ? 30.f : maxT < 600.f ? 60.f : 120.f;

    // ── Y-axis labels ───────────────────────────────────────────────────
    dl->PopClipRect();
    for (int pct = 25; pct <= 100; pct += 25)
    {
        float y = chartY1 - (pct / 100.f) * chartH;
        char buf[8]; snprintf(buf, sizeof(buf), "%d%%", pct);
        ImVec2 ts = font->CalcTextSizeA(fs * 0.72f, FLT_MAX, 0.f, buf);
        dl->AddText(font, fs * 0.72f,
            ImVec2(chartX0 - ts.x - 4.f, y - ts.y * 0.5f), cTextDim, buf);
    }

    // ── X-axis labels (placed below the scrubber) ───────────────────────
    for (float t = 0.f; t <= maxT; t += interval)
    {
        float x = chartX0 + (t / maxT) * chartW;
        float dispT = t - m_displayTimeOffset;
        int absSec = static_cast<int>(std::abs(dispT));
        int mins = absSec / 60;
        int secs = absSec % 60;
        char buf[16];
        if (dispT < 0.f)
            snprintf(buf, sizeof(buf), "-%d:%02d", mins, secs);
        else
            snprintf(buf, sizeof(buf), "%d:%02d", mins, secs);
        ImVec2 ts = font->CalcTextSizeA(fs * 0.72f, FLT_MAX, 0.f, buf);
        dl->AddText(font, fs * 0.72f,
            ImVec2(x - ts.x * 0.5f, scrubY1 + 1.f), cTextDim, buf);
    }

    dl->PushClipRect(ImVec2(chartX0, chartY0), ImVec2(chartX1, chartY1), true);

    // ── Health curves (smooth linear interpolation with fill) ───────────
    auto drawCurve = [&](const std::vector<float>& data, ImU32 lineCol, ImU32 fillCol) {
        if (data.size() < 2) return;
        int n = static_cast<int>(data.size());

        // Filled area: build triangle strip using AddConvexPoly in segments
        for (int i = 0; i < n - 1; ++i)
        {
            float t0 = static_cast<float>(i);
            float t1 = static_cast<float>(i + 1);
            float x0 = chartX0 + (t0 / maxT) * chartW;
            float x1 = chartX0 + (t1 / maxT) * chartW;
            float y0 = chartY1 - (data[i] / 100.f) * chartH;
            float y1 = chartY1 - (data[i + 1] / 100.f) * chartH;

            ImVec2 quad[4] = {
                ImVec2(x0, y0), ImVec2(x1, y1),
                ImVec2(x1, chartY1), ImVec2(x0, chartY1)
            };
            dl->AddConvexPolyFilled(quad, 4, fillCol);
        }

        // Smooth line
        for (int i = 0; i < n - 1; ++i)
        {
            float t0 = static_cast<float>(i);
            float t1 = static_cast<float>(i + 1);
            float x0 = chartX0 + (t0 / maxT) * chartW;
            float x1 = chartX0 + (t1 / maxT) * chartW;
            float y0 = chartY1 - (data[i] / 100.f) * chartH;
            float y1 = chartY1 - (data[i + 1] / 100.f) * chartH;
            dl->AddLine(ImVec2(x0, y0), ImVec2(x1, y1), lineCol, 1.f);
        }
    };

    drawCurve(m_timeline.blueHealth, cBlue, cBlueFill);
    drawCurve(m_timeline.redHealth,  cRed,  cRedFill);

    // ── Event markers ───────────────────────────────────────────────────
    auto isEventVisible = [&](const TimelineEvent& e) -> bool {
        switch (e.type) {
        case TimelineEventType::Death:        return m_tlFilterDeath;
        case TimelineEventType::Resurrection: return false;
        case TimelineEventType::FlagCapture:  return m_tlFilterFlag;
        case TimelineEventType::FlagReturn:   return m_tlFilterFlagReturn;
        case TimelineEventType::MoraleBoost:  return m_tlFilterMorale;
        case TimelineEventType::LordAttacked:      return m_tlFilterLord;
        case TimelineEventType::Victory:            return false;
        case TimelineEventType::ShrineCaptured:     return m_tlFilterShrine;
        case TimelineEventType::ShrineNeutralized:  return m_tlFilterShrine;
        }
        return true;
    };

    // Bottom event row: flags + morale pinned here, 20px from chart bottom
    const float iconSz       = 22.f;
    const float bottomRowY   = chartY1 - 10.f; // center of bottom row
    const float stackStep    = iconSz + 2.f;

    struct MarkerPos { float x, y; int idx; };
    std::vector<MarkerPos> markers;

    for (int i = 0; i < static_cast<int>(m_timeline.events.size()); ++i)
    {
        const auto& e = m_timeline.events[i];
        if (!isEventVisible(e)) continue;

        float ex = chartX0 + (e.time / maxT) * chartW;
        float ey;

        if (e.type == TimelineEventType::FlagCapture || e.type == TimelineEventType::FlagReturn
            || e.type == TimelineEventType::ShrineCaptured || e.type == TimelineEventType::ShrineNeutralized)
        {
            ey = bottomRowY;
        }
        else if (e.type == TimelineEventType::MoraleBoost)
        {
            ey = bottomRowY;
            // Collision avoidance: if a flag capture within 3s, offset morale 20px up
            for (const auto& other : m_timeline.events)
            {
                if ((other.type == TimelineEventType::FlagCapture
                     || other.type == TimelineEventType::ShrineCaptured
                     || other.type == TimelineEventType::ShrineNeutralized) &&
                    isEventVisible(other) &&
                    std::abs(e.time - other.time) <= 3.f)
                {
                    ey = bottomRowY - 20.f;
                    break;
                }
            }
        }
        else
        {
            int sec = std::clamp(static_cast<int>(e.time), 0,
                static_cast<int>(m_timeline.blueHealth.size()) - 1);
            const auto& curve = (e.teamId == 2) ? m_timeline.redHealth : m_timeline.blueHealth;
            float healthPct = (sec < static_cast<int>(curve.size())) ? curve[sec] : 50.f;
            ey = chartY1 - (healthPct / 100.f) * chartH;
            float minY = chartY0 + iconSz * 0.5f + 1.f;
            if (ey < minY) ey = minY;
        }

        markers.push_back({ ex, ey, i });
    }

    // Overlap stacking for curve-based markers (death, lord) — push downward
    auto isBottomRowEvent = [](TimelineEventType t) {
        return t == TimelineEventType::FlagCapture
            || t == TimelineEventType::FlagReturn
            || t == TimelineEventType::MoraleBoost
            || t == TimelineEventType::ShrineCaptured
            || t == TimelineEventType::ShrineNeutralized;
    };

    for (size_t mi = 0; mi < markers.size(); ++mi)
    {
        const auto& e = m_timeline.events[markers[mi].idx];
        if (isBottomRowEvent(e.type))
            continue;

        int stackCount = 0;
        for (size_t mj = 0; mj < mi; ++mj)
        {
            const auto& eo = m_timeline.events[markers[mj].idx];
            if (isBottomRowEvent(eo.type))
                continue;

            if (std::abs(markers[mi].x - markers[mj].x) < stackStep)
                stackCount++;
        }
        if (stackCount > 0)
        {
            markers[mi].y += stackCount * stackStep;
            if (markers[mi].y + iconSz * 0.5f > chartY1 - 22.f)
                markers[mi].y = chartY1 - 22.f - iconSz * 0.5f;
        }
    }

    // Draw markers with actual texture icons
    ImVec2 mousePos = ImGui::GetMousePos();
    int hoveredMarker = -1;

    for (auto& mp : markers)
    {
        const auto& e = m_timeline.events[mp.idx];
        float half = iconSz * 0.5f;
        ImVec2 iconMin(mp.x - half, mp.y - half);
        ImVec2 iconMax(mp.x + half, mp.y + half);

        bool mHovered = (mousePos.x >= iconMin.x - 2.f && mousePos.x <= iconMax.x + 2.f &&
                         mousePos.y >= iconMin.y - 2.f && mousePos.y <= iconMax.y + 2.f);
        if (mHovered) {
            hoveredMarker = mp.idx;
            iconMin = ImVec2(mp.x - half * 1.3f, mp.y - half * 1.3f);
            iconMax = ImVec2(mp.x + half * 1.3f, mp.y + half * 1.3f);
        }

        ImU32 teamBorderCol = (e.teamId == 2)
            ? IM_COL32(208, 72, 72, 255)   // #d04848
            : IM_COL32( 74,144,216, 255);   // #4a90d8

        switch (e.type) {
        case TimelineEventType::Death: {
            dl->AddRectFilled(iconMin, iconMax,
                              IM_COL32(10, 10, 10, 230), 2.f);
            dl->AddRect(iconMin, iconMax,
                        teamBorderCol, 2.f, 0, 2.f);
            ImTextureID profTex = LoadProfIcon(dev, e.professionId);
            if (profTex)
                dl->AddImage(profTex, iconMin, iconMax);
            else {
                dl->AddText(font, fs * 0.65f,
                    ImVec2(mp.x - 3.f, mp.y - fs * 0.35f),
                    IM_COL32(255, 255, 255, 255), "X");
            }
            // Subtle red cross overlay
            {
                const ImU32 crossCol = IM_COL32(220, 40, 40, 120);
                dl->AddLine(ImVec2(iconMin.x + 2.f, iconMin.y + 2.f),
                            ImVec2(iconMax.x - 2.f, iconMax.y - 2.f), crossCol, 1.5f);
                dl->AddLine(ImVec2(iconMax.x - 2.f, iconMin.y + 2.f),
                            ImVec2(iconMin.x + 2.f, iconMax.y - 2.f), crossCol, 1.5f);
            }
            break;
        }
        case TimelineEventType::FlagCapture: {
            const char* flagFile = (e.teamId == 2) ? "Red_flag_waving.svg.png" : "Blue_flag_waving.svg.png";
            ImTextureID tex = LoadFlagIcon(dev, flagFile);
            if (tex)
                dl->AddImage(tex, iconMin, iconMax);
            else {
                dl->AddText(font, fs * 0.65f,
                    ImVec2(mp.x - 3.f, mp.y - fs * 0.35f),
                    IM_COL32(255, 255, 255, 255), "F");
            }
            break;
        }
        case TimelineEventType::FlagReturn: {
            const char* flagFile = (e.teamId == 2) ? "Red_flag_waving.svg.png" : "Blue_flag_waving.svg.png";
            ImTextureID tex = LoadFlagIcon(dev, flagFile);
            if (tex)
                dl->AddImage(tex, iconMin, iconMax);
            else {
                dl->AddText(font, fs * 0.65f,
                    ImVec2(mp.x - 3.f, mp.y - fs * 0.35f),
                    IM_COL32(255, 255, 255, 255), "R");
            }
            // Green left-pointing arrow overlay
            float arrowX = iconMin.x - 2.f;
            float arrowCY = (iconMin.y + iconMax.y) * 0.5f;
            float arrowH = (iconMax.y - iconMin.y) * 0.35f;
            dl->AddTriangleFilled(
                ImVec2(arrowX - 6.f, arrowCY),
                ImVec2(arrowX, arrowCY - arrowH),
                ImVec2(arrowX, arrowCY + arrowH),
                IM_COL32(40, 200, 40, 220));
            dl->AddLine(ImVec2(arrowX, arrowCY), ImVec2(arrowX + 5.f, arrowCY),
                        IM_COL32(40, 200, 40, 220), 2.f);
            break;
        }
        case TimelineEventType::MoraleBoost: {
            const char* moraleFile = (e.teamId == 2) ? "redmorale.png" : "bluemorale.png";
            ImTextureID tex = LoadFlagIcon(dev, moraleFile);
            if (tex)
                dl->AddImage(tex, iconMin, iconMax);
            else {
                dl->AddText(font, fs * 0.65f,
                    ImVec2(mp.x - 3.f, mp.y - fs * 0.35f),
                    IM_COL32(255, 255, 255, 255), "M");
            }
            break;
        }
        case TimelineEventType::LordAttacked: {
            const char* lordFile = (e.teamId == 2) ? "redguildlord.png" : "blueguildlord.png";
            ImTextureID tex = LoadFlagIcon(dev, lordFile);
            if (tex)
                dl->AddImage(tex, iconMin, iconMax);
            else {
                dl->AddText(font, fs * 0.65f,
                    ImVec2(mp.x - 3.f, mp.y - fs * 0.35f),
                    IM_COL32(255, 255, 255, 255), "!");
            }
            break;
        }
        case TimelineEventType::ShrineCaptured: {
            ImTextureID tex = LoadFlagIcon(dev, "Health_Shrine_Bonus.jpg");
            ImU32 borderCol = (e.teamId == 2)
                ? IM_COL32(208, 72, 72, 255)
                : IM_COL32(74, 144, 216, 255);
            dl->AddRectFilled(iconMin, iconMax, IM_COL32(10, 10, 10, 200), 2.f);
            dl->AddRect(iconMin, iconMax, borderCol, 2.f, 0, 2.f);
            if (tex)
                dl->AddImage(tex, iconMin, iconMax);
            else
                dl->AddText(font, fs * 0.65f,
                    ImVec2(mp.x - 3.f, mp.y - fs * 0.35f),
                    IM_COL32(255, 255, 255, 255), "S");
            break;
        }
        case TimelineEventType::ShrineNeutralized: {
            ImTextureID tex = LoadFlagIcon(dev, "Health_Shrine_Bonus.jpg");
            dl->AddRectFilled(iconMin, iconMax, IM_COL32(10, 10, 10, 200), 2.f);
            dl->AddRect(iconMin, iconMax, IM_COL32(180, 180, 180, 200), 2.f, 0, 2.f);
            if (tex)
            {
                dl->AddImage(tex, iconMin, iconMax);
                // Grey desaturation overlay to visually distinguish from captured
                dl->AddRectFilled(iconMin, iconMax, IM_COL32(60, 60, 60, 120), 2.f);
            }
            else
                dl->AddText(font, fs * 0.65f,
                    ImVec2(mp.x - 3.f, mp.y - fs * 0.35f),
                    IM_COL32(180, 180, 180, 255), "N");
            break;
        }
        default: break;
        }
    }

    // ── Playhead (main chart) ───────────────────────────────────────────
    {
        float phX = chartX0 + (m_debugTimeline / maxT) * chartW;
        dl->AddLine(ImVec2(phX, chartY0), ImVec2(phX, chartY1), cPlayhead, 1.5f);
        dl->AddTriangleFilled(
            ImVec2(phX - 4.f, chartY0),
            ImVec2(phX + 4.f, chartY0),
            ImVec2(phX,       chartY0 + 6.f), cPlayhead);
    }

    // ── Hover crosshair + tooltip ───────────────────────────────────────
    bool chartHovered = (mousePos.x >= chartX0 && mousePos.x <= chartX1 &&
                         mousePos.y >= chartY0 && mousePos.y <= chartY1);
    if (chartHovered)
    {
        dl->AddLine(ImVec2(mousePos.x, chartY0), ImVec2(mousePos.x, chartY1),
            IM_COL32(255, 255, 255, 40), 1.f);

        float hoverT = ((mousePos.x - chartX0) / chartW) * maxT;
        int sec = std::clamp(static_cast<int>(hoverT), 0,
            static_cast<int>(m_timeline.blueHealth.size()) - 1);
        float bh = m_timeline.blueHealth[sec];
        float rh = m_timeline.redHealth[sec];
        float dispHT = hoverT - m_displayTimeOffset;
        int absHT = static_cast<int>(std::abs(dispHT));
        int mins = absHT / 60;
        int secs = absHT % 60;

        dl->PopClipRect();

        char ttBuf[128];
        if (dispHT < 0.f)
            snprintf(ttBuf, sizeof(ttBuf), "-%d:%02d  Blue: %.0f%%  Red: %.0f%%", mins, secs, bh, rh);
        else
            snprintf(ttBuf, sizeof(ttBuf), "%d:%02d  Blue: %.0f%%  Red: %.0f%%", mins, secs, bh, rh);
        ImVec2 ttSz = font->CalcTextSizeA(fs * 0.78f, FLT_MAX, 0.f, ttBuf);
        float ttX = std::clamp(mousePos.x - ttSz.x * 0.5f, chartX0, chartX1 - ttSz.x - 8.f);
        float ttY = mousePos.y - ttSz.y - 10.f;
        if (ttY < chartY0) ttY = mousePos.y + 14.f;

        dl->AddRectFilled(
            ImVec2(ttX - 4.f, ttY - 2.f),
            ImVec2(ttX + ttSz.x + 4.f, ttY + ttSz.y + 2.f),
            IM_COL32(14, 16, 20, 230), 4.f);
        dl->AddRect(
            ImVec2(ttX - 4.f, ttY - 2.f),
            ImVec2(ttX + ttSz.x + 4.f, ttY + ttSz.y + 2.f),
            IM_COL32(200, 168, 75, 80), 4.f);
        dl->AddText(font, fs * 0.78f, ImVec2(ttX, ttY), cText, ttBuf);

        dl->PushClipRect(ImVec2(chartX0, chartY0), ImVec2(chartX1, chartY1), true);
    }

    // ── Marker tooltip ──────────────────────────────────────────────────
    if (hoveredMarker >= 0)
    {
        const auto& e = m_timeline.events[hoveredMarker];
        dl->PopClipRect();

        const char* typeName = "";
        switch (e.type) {
        case TimelineEventType::Death:        typeName = "Death"; break;
        case TimelineEventType::FlagCapture:  typeName = "Flag Capture"; break;
        case TimelineEventType::FlagReturn:   typeName = "Flag Return"; break;
        case TimelineEventType::MoraleBoost:       typeName = "Morale Boost"; break;
        case TimelineEventType::LordAttacked:      typeName = "Lord Attacked"; break;
        case TimelineEventType::ShrineCaptured:    typeName = "Shrine Captured"; break;
        case TimelineEventType::ShrineNeutralized: typeName = "Shrine Neutralized"; break;
        default: break;
        }

        float dispET = e.time - m_displayTimeOffset;
        int absET = static_cast<int>(std::abs(dispET));
        int mins = absET / 60;
        int secs = absET % 60;
        const char* sign = (dispET < 0.f) ? "-" : "";
        char ttBuf[256];
        if (!e.label.empty())
            snprintf(ttBuf, sizeof(ttBuf), "[%s%d:%02d] %s - %s", sign, mins, secs, typeName, e.label.c_str());
        else
            snprintf(ttBuf, sizeof(ttBuf), "[%s%d:%02d] %s", sign, mins, secs, typeName);

        ImVec2 ttSz = font->CalcTextSizeA(fs * 0.78f, FLT_MAX, 0.f, ttBuf);
        float ttX = std::clamp(mousePos.x - ttSz.x * 0.5f, chartX0, chartX1 - ttSz.x - 8.f);
        float ttY = mousePos.y - ttSz.y - 22.f;
        if (ttY < chartY0) ttY = mousePos.y + 14.f;

        dl->AddRectFilled(
            ImVec2(ttX - 4.f, ttY - 2.f),
            ImVec2(ttX + ttSz.x + 4.f, ttY + ttSz.y + 2.f),
            IM_COL32(14, 16, 20, 240), 4.f);
        dl->AddRect(
            ImVec2(ttX - 4.f, ttY - 2.f),
            ImVec2(ttX + ttSz.x + 4.f, ttY + ttSz.y + 2.f),
            IM_COL32(200, 168, 75, 100), 4.f);
        dl->AddText(font, fs * 0.78f, ImVec2(ttX, ttY), cText, ttBuf);

        if (ImGui::IsMouseClicked(0))
            m_debugTimeline = std::clamp(e.time, 0.f, maxT);

        dl->PushClipRect(ImVec2(chartX0, chartY0), ImVec2(chartX1, chartY1), true);
    }

    dl->PopClipRect();

    // ── Scrubber strip ──────────────────────────────────────────────────
    dl->AddLine(ImVec2(chartX0, scrubY0), ImVec2(chartX1, scrubY0),
        IM_COL32(200, 168, 75, 40), 1.f);
    dl->PushClipRect(ImVec2(chartX0, scrubY0 + 1.f), ImVec2(chartX1, scrubY1), true);
    dl->AddRectFilled(ImVec2(chartX0, scrubY0 + 1.f), ImVec2(chartX1, scrubY1),
        IM_COL32(255, 255, 255, 6));

    // Mini health curves in scrubber (smooth)
    {
        int n = static_cast<int>(m_timeline.blueHealth.size());
        for (int i = 0; i < n - 1; ++i)
        {
            float t0 = static_cast<float>(i);
            float t1 = static_cast<float>(i + 1);
            float x0 = chartX0 + (t0 / maxT) * chartW;
            float x1 = chartX0 + (t1 / maxT) * chartW;

            float by0 = scrubY1 - (m_timeline.blueHealth[i] / 100.f) * scrubH;
            float by1 = scrubY1 - (m_timeline.blueHealth[i + 1] / 100.f) * scrubH;
            dl->AddLine(ImVec2(x0, by0), ImVec2(x1, by1), IM_COL32(74, 200, 255, 100), 1.f);

            float ry0 = scrubY1 - (m_timeline.redHealth[i] / 100.f) * scrubH;
            float ry1 = scrubY1 - (m_timeline.redHealth[i + 1] / 100.f) * scrubH;
            dl->AddLine(ImVec2(x0, ry0), ImVec2(x1, ry1), IM_COL32(255, 107, 107, 100), 1.f);
        }
    }

    // Scrubber playhead
    {
        float phX = chartX0 + (m_debugTimeline / maxT) * chartW;
        dl->AddLine(ImVec2(phX, scrubY0), ImVec2(phX, scrubY1), cPlayhead, 2.f);
    }

    dl->PopClipRect();

    // Unified click-drag scrubbing for both chart and scrubber areas
    bool anyTimelineHovered = (mousePos.x >= chartX0 && mousePos.x <= chartX1 &&
                               mousePos.y >= chartY0 && mousePos.y <= scrubY1);
    static bool timelineDragging = false;
    if (anyTimelineHovered && ImGui::IsMouseClicked(0) && hoveredMarker < 0)
        timelineDragging = true;
    if (!ImGui::IsMouseDown(0))
        timelineDragging = false;
    if (timelineDragging)
    {
        float t = ((mousePos.x - chartX0) / chartW) * maxT;
        m_debugTimeline = std::clamp(t, 0.f, maxT);
    }

    // ── Bottom border shimmer ───────────────────────────────────────────
    {
        float sx = O.x + 12.f, sw = vpW - 24.f;
        float sy = O.y + panelH - 1.f;
        float mx = sx + sw * 0.5f;
        dl->AddRectFilledMultiColor(
            ImVec2(sx, sy), ImVec2(mx, sy + 1.f),
            IM_COL32(200,168,75, 0), IM_COL32(200,168,75,100),
            IM_COL32(200,168,75,100), IM_COL32(200,168,75, 0));
        dl->AddRectFilledMultiColor(
            ImVec2(mx, sy), ImVec2(sx + sw, sy + 1.f),
            IM_COL32(200,168,75,100), IM_COL32(200,168,75, 0),
            IM_COL32(200,168,75, 0), IM_COL32(200,168,75,100));
    }

    ImGui::End();
}

void ReplayWindow::DrawMatchTimer()
{
    ImFont* font = m_latoRegular ? m_latoRegular : ImGui::GetFont();
    float fontSize = font->FontSize;

    float curTime = m_debugTimeline;
    float matchTime = curTime - m_matchStartOffset;

    bool isCountdown = matchTime < 0.f;
    float absTime = fabsf(matchTime);
    FormatMMSS(m_timerBuf, sizeof(m_timerBuf), absTime);

    const char* label = isCountdown ? "Time to start:" : "Time Elapsed:";

    float labelFs = fontSize;
    float timeFs  = fontSize;

    ImVec2 labelSize = font->CalcTextSizeA(labelFs, FLT_MAX, 0.f, label);
    ImVec2 timeSize  = font->CalcTextSizeA(timeFs, FLT_MAX, 0.f, m_timerBuf);
    float boxW = std::max(labelSize.x, timeSize.x);
    float lineH = labelFs + 2.f;
    float boxH = lineH * 2.f;

    const ImGuiViewport* vp = ImGui::GetMainViewport();
    float posX = m_uiLayout.useCustom ? m_uiLayout.timerX : 0.50f;
    float posY = m_uiLayout.useCustom ? m_uiLayout.timerY : 0.12f;
    float cx   = vp->Pos.x + vp->Size.x * posX;
    float topY = vp->Pos.y + vp->Size.y * posY;

    float padX, padY;
    if (isCountdown) { padX = 12.f; padY = 10.f; }
    else             { padX = 8.f;  padY = 4.f; }

    ImVec2 boxTL(cx - boxW * 0.5f - padX, topY);
    ImVec2 boxBR(cx + boxW * 0.5f + padX, topY + boxH + padY * 2.f);

    ImDrawList* dl = ImGui::GetForegroundDrawList();

    if (isCountdown)
    {
        dl->AddRectFilled(boxTL, boxBR, IM_COL32(0, 0, 0, 204), 8.f);
        dl->AddRect(boxTL, boxBR, IM_COL32(0xB7, 0xB8, 0xB3, 0xFF), 8.f, 0, 1.f);
    }

    ImU32 goldCol = IM_COL32(0xF5, 0xE4, 0xB4, 0xFF);
    ImU32 shA     = IM_COL32(0, 0, 0, 204);
    ImU32 shB     = IM_COL32(0, 0, 0, 230);

    auto drawShadowedText = [&](ImFont* f, float fs, ImVec2 pos, ImU32 col, const char* txt)
    {
        dl->AddText(f, fs, ImVec2(pos.x, pos.y + 1), shA, txt);
        dl->AddText(f, fs, ImVec2(pos.x, pos.y + 1), shB, txt);
        dl->AddText(f, fs, pos, col, txt);
    };

    float labelX = cx - labelSize.x * 0.5f;
    float labelY = boxTL.y + padY;
    drawShadowedText(font, labelFs, ImVec2(labelX, labelY), goldCol, label);

    float timeX = cx - timeSize.x * 0.5f;
    float timeY = labelY + lineH;
    drawShadowedText(font, timeFs, ImVec2(timeX, timeY), goldCol, m_timerBuf);

    HandleOverlayDrag(3, &m_uiLayout.timerX, &m_uiLayout.timerY, boxTL, boxBR);
}

// ---------------------------------------------------------------------------
// Flag event messages — displayed below the Time Elapsed counter
// ---------------------------------------------------------------------------

void ReplayWindow::DrawFlagEventMessages()
{
    if (m_flagMessages.empty()) return;

    float curTime = m_debugTimeline;

    constexpr float kDisplayDuration = 5.0f;
    constexpr float kFadeStart      = 4.0f;
    constexpr int   kMaxVisible     = 2;

    // Collect up to kMaxVisible active messages (most recent first)
    struct ActiveMsg { const FlagEventMessage* msg; float age; };
    std::vector<ActiveMsg> actives;
    for (auto& msg : m_flagMessages)
    {
        float age = curTime - msg.time;
        if (age < 0.f || age > kDisplayDuration) continue;
        actives.push_back({ &msg, age });
    }
    if (actives.empty()) return;

    // Sort by time descending (newest first), keep up to kMaxVisible
    std::sort(actives.begin(), actives.end(),
        [](const ActiveMsg& a, const ActiveMsg& b) { return a.msg->time > b.msg->time; });
    if (static_cast<int>(actives.size()) > kMaxVisible)
        actives.resize(kMaxVisible);
    // Reverse so oldest draws on top, newest on bottom (chat order)
    std::reverse(actives.begin(), actives.end());

    ImFont* font = m_latoRegular ? m_latoRegular : ImGui::GetFont();
    float fontSize = font->FontSize;
    float lineH = fontSize + 6.f;
    ImDrawList* dl = ImGui::GetForegroundDrawList();

    const ImGuiViewport* vp = ImGui::GetMainViewport();
    float posX = m_uiLayout.useCustom ? m_uiLayout.timerX : 0.50f;
    float posY = m_uiLayout.useCustom ? m_uiLayout.timerY : 0.12f;
    float cx = vp->Pos.x + vp->Size.x * posX;
    float baseY = vp->Pos.y + vp->Size.y * posY;
    float msgStartY = baseY + fontSize * 2.f + 30.f;

    struct Segment { std::string text; ImU32 color; };

    auto drawSegmentsCentered = [&](const std::vector<Segment>& segs, float y, float alpha)
    {
        int a = static_cast<int>(alpha * 255);
        ImU32 shadow = IM_COL32(0, 0, 0, static_cast<int>(alpha * 230));
        float totalW = 0.f;
        for (auto& s : segs)
            totalW += font->CalcTextSizeA(fontSize, FLT_MAX, 0.f, s.text.c_str()).x;
        float x = cx - totalW * 0.5f;
        for (auto& s : segs) {
            ImU32 col = (s.color & 0x00FFFFFF) | (static_cast<ImU32>(a) << 24);
            dl->AddText(font, fontSize, ImVec2(x, y + 1), shadow, s.text.c_str());
            dl->AddText(font, fontSize, ImVec2(x, y), col, s.text.c_str());
            x += font->CalcTextSizeA(fontSize, FLT_MAX, 0.f, s.text.c_str()).x;
        }
        return totalW;
    };

    float curY = msgStartY;

    for (auto& am : actives)
    {
        const auto* active = am.msg;
        float alpha = 1.f;
        if (am.age > kFadeStart)
            alpha = std::clamp(kDisplayDuration - am.age, 0.f, 1.f) / (kDisplayDuration - kFadeStart);
        if (alpha <= 0.f) continue;

        ImU32 whiteCol = IM_COL32(255, 255, 255, 255);
        ImU32 blueCol  = IM_COL32(0x99, 0xCB, 0xFD, 255);
        ImU32 redCol   = IM_COL32(0xFF, 0x99, 0x9A, 255);

        ImU32 playerCol = (active->playerTeam == 0) ? blueCol : redCol;
        ImU32 flagCol   = (active->flagTeam == 0)   ? blueCol : redCol;
        const char* flagTeamName = (active->flagTeam == 0) ? "blue" : "red";

        std::vector<Segment> line1, line2;

        switch (active->eventType)
        {
        case FlagTimelineEventType::Pickup:
            line1.push_back({ active->playerName, playerCol });
            line1.push_back({ " picked up ", whiteCol });
            line1.push_back({ flagTeamName, flagCol });
            line1.push_back({ "'s team flag!", whiteCol });
            break;
        case FlagTimelineEventType::Drop:
            line1.push_back({ active->playerName, playerCol });
            line1.push_back({ " has dropped ", whiteCol });
            line1.push_back({ flagTeamName, flagCol });
            line1.push_back({ "'s team flag!", whiteCol });
            break;
        case FlagTimelineEventType::Return:
            if (!active->playerName.empty()) {
                line1.push_back({ active->playerName, playerCol });
                line1.push_back({ " has returned ", whiteCol });
            } else {
                const char* returnTeamName = (active->flagTeam == 0) ? "Red" : "Blue";
                ImU32 returnTeamCol = (active->flagTeam == 0) ? redCol : blueCol;
                line1.push_back({ returnTeamName, returnTeamCol });
                line1.push_back({ " team has returned ", whiteCol });
            }
            line1.push_back({ flagTeamName, flagCol });
            line1.push_back({ "'s team flag!", whiteCol });
            break;
        case FlagTimelineEventType::Stick:
        {
            const char* teamName = (active->flagTeam == 0) ? "Blue" : "Red";
            line1.push_back({ active->playerName, playerCol });
            line1.push_back({ " has taken control of the watchtower!", whiteCol });
            line2.push_back({ teamName, flagCol });
            line2.push_back({ " team will earn a morale boost every two minutes they hold the watchtower.", whiteCol });
            break;
        }
        default:
            continue;
        }

        drawSegmentsCentered(line1, curY, alpha);
        curY += lineH;

        if (!line2.empty()) {
            drawSegmentsCentered(line2, curY, alpha);
            curY += lineH;
        }
    }
}

void ReplayWindow::DrawJumboMessages()
{
    const ImGuiViewport* vp = ImGui::GetMainViewport();
    float posX = m_uiLayout.useCustom ? m_uiLayout.jumboX : 0.50f;
    float posY = m_uiLayout.useCustom ? m_uiLayout.jumboY : 0.30f;

    // Show drag preview even without an active jumbo message
    if (m_draggingUIElement == 0)
    {
        ImFont* font = m_latoBoldBig ? m_latoBoldBig : ImGui::GetFont();
        float fontSize = font->FontSize;
        const char* preview = "Blue Captured Tower";
        ImVec2 textSize = font->CalcTextSizeA(fontSize, FLT_MAX, 0.f, preview);

        float cx = vp->Pos.x + vp->Size.x * posX;
        float ty = vp->Pos.y + vp->Size.y * posY;
        float tx = cx - textSize.x * 0.5f;

        ImDrawList* dl = ImGui::GetForegroundDrawList();
        dl->AddText(font, fontSize, ImVec2(tx, ty + 1), IM_COL32(0, 0, 0, 150), preview);
        dl->AddText(font, fontSize, ImVec2(tx, ty), IM_COL32(0x99, 0xCB, 0xFD, 180), preview);

        ImVec2 boxTL(tx - 4, ty - 4);
        ImVec2 boxBR(tx + textSize.x + 4, ty + textSize.y + 4);
        HandleOverlayDrag(0, &m_uiLayout.jumboX, &m_uiLayout.jumboY, boxTL, boxBR);
        return;
    }

    if (!m_replayCtx.stocLoaded) return;

    const auto& jumbos = m_replayCtx.stocData.jumbo;
    if (jumbos.empty()) return;

    float curTime = m_debugTimeline;

    const JumboMessageEvent* best = nullptr;
    float bestAge = 999.f;
    for (auto& ev : jumbos)
    {
        float age = curTime - ev.time;
        if (age < 0.f || age > 6.f) continue;
        if (!best || ev.time > best->time)
        {
            best = &ev;
            bestAge = age;
        }
    }

    if (!best) return;

    float alpha = 1.f;
    if (bestAge > 5.f)
        alpha = std::clamp(6.f - bestAge, 0.f, 1.f);
    if (alpha <= 0.f) return;

    int team = JumboPartyToTeam(best->party_value);
    const bool isNeutralizedShrine = (best->message == "NEUTRALIZED_SHRINE");
    // NEUTRALIZED_SHRINE party_value identifies the losing team — invert for display
    if (isNeutralizedShrine && team > 0)
        team = (team == 1) ? 2 : 1;
    const char* text = JumboMessageDisplayText(best->message, team);

    int a = static_cast<int>(alpha * 255);
    ImU32 teamCol;
    if (isNeutralizedShrine)    teamCol = IM_COL32(0xBB, 0xBB, 0xBB, a);
    else if (team == 1)         teamCol = IM_COL32(0x99, 0xCB, 0xFD, a);
    else if (team == 2)         teamCol = IM_COL32(0xFF, 0x99, 0x9A, a);
    else                        teamCol = IM_COL32(0xFF, 0xFF, 0xFF, a);

    ImFont* font = m_latoBoldBig ? m_latoBoldBig : ImGui::GetFont();
    float fontSize = font->FontSize;
    ImVec2 textSize = font->CalcTextSizeA(fontSize, FLT_MAX, 0.f, text);

    float cx = vp->Pos.x + vp->Size.x * posX;
    float topY = vp->Pos.y + vp->Size.y * posY;

    float tx = cx - textSize.x * 0.5f;
    float ty = topY;

    ImDrawList* dl = ImGui::GetForegroundDrawList();
    ImU32 shadow = IM_COL32(0, 0, 0, static_cast<int>(alpha * 230));
    dl->AddText(font, fontSize, ImVec2(tx, ty + 1), shadow, text);
    dl->AddText(font, fontSize, ImVec2(tx, ty), teamCol, text);
}

void ReplayWindow::DrawMoraleBoostTimers()
{
    auto& standEvents = m_flagTimeline.stand.events;
    if (standEvents.empty() && m_draggingUIElement != 1 && m_draggingUIElement != 2)
        return;

    float curTime = m_debugTimeline;

    float lastCapTime[2] = { -1.f, -1.f };
    int   lastCapTeam = -1;

    for (auto& sc : standEvents)
    {
        if (sc.time > curTime) break;
        if (sc.owner == StandOwner::Blue)        { lastCapTime[0] = sc.time; lastCapTeam = 0; }
        else if (sc.owner == StandOwner::Red)     { lastCapTime[1] = sc.time; lastCapTeam = 1; }
        else if (sc.owner == StandOwner::Neutral) { lastCapTeam = -1; }
    }

    ImFont* font = m_latoBold ? m_latoBold : ImGui::GetFont();
    float fontSize = font->FontSize;
    const ImGuiViewport* vp = ImGui::GetMainViewport();

    ImU32 shA     = IM_COL32(0, 0, 0, 204);
    ImU32 shB     = IM_COL32(0, 0, 0, 230);

    auto drawShadowed = [&](ImVec2 pos, ImU32 col, const char* txt)
    {
        ImDrawList* dl = ImGui::GetForegroundDrawList();
        dl->AddText(font, fontSize, ImVec2(pos.x, pos.y + 2), shA, txt);
        dl->AddText(font, fontSize, ImVec2(pos.x, pos.y + 1), shB, txt);
        dl->AddText(font, fontSize, pos, col, txt);
    };

    auto DrawOneMorale = [&](int teamIdx01, int dragIdx, float* fracX, float* fracY,
                             float defaultX, float defaultY)
    {
        int team = teamIdx01 + 1;
        float px = m_uiLayout.useCustom ? *fracX : defaultX;
        float py = m_uiLayout.useCustom ? *fracY : defaultY;

        bool hasCap = (lastCapTeam >= 0 && lastCapTeam == teamIdx01);

        if (!hasCap && m_draggingUIElement != dragIdx)
            return;

        const char* teamLabel = (team == 1) ? "Blue Morale Boost" : "Red Morale Boost";
        char buf[32] = "02:00";

        if (hasCap)
        {
            float secondsSince = curTime - lastCapTime[teamIdx01];
            if (secondsSince < 0.f && m_draggingUIElement != dragIdx) return;
            int cyclePos = static_cast<int>(floorf(std::max(0.f, secondsSince))) % 120;
            int remaining = 120 - cyclePos;
            FormatMMSS(buf, sizeof(buf), static_cast<float>(remaining));
        }

        ImVec2 labelSize = font->CalcTextSizeA(fontSize, FLT_MAX, 0.f, teamLabel);
        ImVec2 timerSize = font->CalcTextSizeA(fontSize, FLT_MAX, 0.f, buf);
        float blockW = std::max(labelSize.x, timerSize.x);
        float lineH = fontSize + 4.f;

        float anchorX = vp->Pos.x + vp->Size.x * px;
        float anchorY = vp->Pos.y + vp->Size.y * py;
        float x = anchorX - blockW * 0.5f;

        ImU32 teamCol = (team == 1) ? IM_COL32(0x99, 0xCB, 0xFD, 0xFF)
                                    : IM_COL32(0xFF, 0x99, 0x9A, 0xFF);
        ImU32 goldCol = IM_COL32(0xF5, 0xE4, 0xB4, 0xFF);

        float labelX = x + (blockW - labelSize.x) * 0.5f;
        float timerX = x + (blockW - timerSize.x) * 0.5f;

        drawShadowed(ImVec2(labelX, anchorY), teamCol, teamLabel);
        drawShadowed(ImVec2(timerX, anchorY + lineH), goldCol, buf);

        ImVec2 boxTL(x - 2, anchorY - 2);
        ImVec2 boxBR(x + blockW + 2, anchorY + lineH * 2 + 2);
        HandleOverlayDrag(dragIdx, fracX, fracY, boxTL, boxBR);
    };

    DrawOneMorale(0, 1, &m_uiLayout.moBlueX, &m_uiLayout.moBlueY, 0.65f, 0.22f);
    DrawOneMorale(1, 2, &m_uiLayout.moRedX,  &m_uiLayout.moRedY,  0.35f, 0.22f);
}

// ---------------------------------------------------------------------------
// Follow-agent camera
// ---------------------------------------------------------------------------

void ReplayWindow::EnterFollowMode(int agentId)
{
    auto it = m_replayCtx.agents.find(agentId);
    if (it == m_replayCtx.agents.end()) return;

    const auto& ard = it->second;
    if (ard.snapshots.empty()) return;

    bool wasFollowing = (m_cameraMode == CameraMode::FollowAgent && m_followedAgentId >= 0);

    if (wasFollowing && m_followedAgentId != agentId)
    {
        // Switching targets: pan the orbit center from old agent to new.
        // Orbit distance, yaw, and pitch stay exactly as the user set them.
        m_followTransFromAgentId = m_followedAgentId;
        m_followTransActive      = true;
        m_followTransElapsed     = 0.f;
    }
    else if (!wasFollowing)
    {
        // Entering follow mode from Free camera: adopt current distance.
        Camera* cam = m_mapRenderer->GetCamera();
        XMFLOAT3 camPos = cam->GetPosition3f();

        float sx, sy, sz;
        InterpolateAgentPosition(ard, m_debugTimeline, m_replayCtx.interpSettings, sx, sy, sz);
        XMFLOAT3 agentWorld = ApplyMapTransformToPos(sx, sy, sz, m_replayCtx.mapTransform);

        float dx = camPos.x - agentWorld.x;
        float dy = camPos.y - agentWorld.y;
        float dz = camPos.z - agentWorld.z;
        float distToAgent = sqrtf(dx * dx + dy * dy + dz * dz);

        m_followDist       = distToAgent;
        m_followDistTarget = distToAgent;
        m_followYaw        = atan2f(dx, dz);
        m_followPitch      = (distToAgent > 0.001f)
            ? asinf(std::clamp(dy / distToAgent, -1.f, 1.f)) : 0.3f;

        m_followTransActive = false;
    }

    m_followedAgentId = agentId;
    m_cameraMode = CameraMode::FollowAgent;
    m_mapRenderer->m_disableMovementInput = true;
    m_leftClickPending = false;
}

void ReplayWindow::ExitFollowMode()
{
    m_cameraMode = CameraMode::Free;
    m_followedAgentId = -1;
    m_followTransActive = false;
    m_mapRenderer->m_disableMovementInput = false;
}

// ---------------------------------------------------------------------------
// Top View mode
// ---------------------------------------------------------------------------

XMFLOAT3 ReplayWindow::ComputeTopViewPosition() const
{
    Terrain* terrain = m_mapRenderer ? m_mapRenderer->GetTerrain() : nullptr;
    if (!terrain)
        return XMFLOAT3(0.f, 5000.f, 0.f);

    const auto& b = terrain->m_bounds;
    float cx = (b.map_min_x + b.map_max_x) * 0.5f;
    float cz = (b.map_min_z + b.map_max_z) * 0.5f;

    float mapW = b.map_max_x - b.map_min_x;
    float mapH = b.map_max_z - b.map_min_z;
    if (mapW < 1.f) mapW = 10000.f;
    if (mapH < 1.f) mapH = 10000.f;

    // Add 5% padding
    mapW *= 1.10f;
    mapH *= 1.10f;

    Camera* cam = m_mapRenderer->GetCamera();
    float fovY  = cam->GetFovY();
    float aspect = cam->GetAspectRatio();
    if (fovY <= 0.f)  fovY  = 50.f * XM_PI / 180.f;
    if (aspect <= 0.f) aspect = 16.f / 9.f;

    float halfFovY = fovY * 0.5f;
    float halfFovX = atanf(tanf(halfFovY) * aspect);

    float hFromW = (mapW * 0.5f) / tanf(halfFovX);
    float hFromH = (mapH * 0.5f) / tanf(halfFovY);
    float height = std::max(hFromW, hFromH);

    // Ensure minimum height and add vertical offset above terrain
    float maxTerrainY = std::max(std::abs(b.map_min_y), std::abs(b.map_max_y));
    height = std::max(height, 2000.f) + maxTerrainY;

    return XMFLOAT3(cx, height, cz);
}

void ReplayWindow::EnterTopView()
{
    if (m_topViewActive) return;

    Camera* cam = m_mapRenderer->GetCamera();

    // Save current camera state
    m_tvSavedPos   = cam->GetPosition3f();
    m_tvSavedYaw   = cam->GetYaw();
    m_tvSavedPitch = cam->GetPitch();
    m_tvSavedCamMode     = m_cameraMode;
    m_tvSavedFollowId    = m_followedAgentId;
    m_tvSavedFollowDist  = m_followDist;
    m_tvSavedFollowYaw   = m_followYaw;
    m_tvSavedFollowPitch = m_followPitch;
    m_tvSavedFogPerspective = m_fogPerspective;
    m_tvSavedSkillIcons   = m_showSkillIcons;
    m_tvSavedSkillLasers  = m_showSkillLasers;
    m_tvSavedLodEnabled   = m_uiLayout.lodEnabled;
    m_tvSavedShow3DLabels = m_show3DLabels;
    m_tvSavedNamePanel    = m_showNameFilterPanel;

    // Pause auto camera if active
    m_tvSavedAutoCam = m_autoCameraEnabled;
    if (m_autoCameraEnabled)
        m_autoCameraEnabled = false;

    // Exit follow mode so we have direct camera control
    if (m_cameraMode == CameraMode::FollowAgent)
        ExitFollowMode();

    m_topViewActive = true;
    m_mapRenderer->m_disableMovementInput = true;

    // Suppress fog
    if (m_fogPerspective > 0)
    {
        m_fogLastActive = m_fogPerspective;
        m_fogPerspective = 0;
    }

    // Override display settings for top view
    m_showSkillIcons      = false;
    m_showSkillLasers     = false;
    m_uiLayout.lodEnabled = true;
    m_show3DLabels        = false;
    m_showNameFilterPanel = true;

    // Set up transition
    m_topViewTransitioning = true;
    m_topViewTransTimer    = 0.f;
    m_tvTransFrom      = cam->GetPosition3f();
    m_tvTransFromYaw   = cam->GetYaw();
    m_tvTransFromPitch = cam->GetPitch();
    m_tvTransTo        = ComputeTopViewPosition();
    m_tvTransToYaw     = 0.f;
    m_tvTransToPitch   = -XM_PIDIV2 + 0.001f;  // Looking straight down
}

void ReplayWindow::ExitTopView()
{
    if (!m_topViewActive) return;

    Camera* cam = m_mapRenderer->GetCamera();

    // Set up transition from current position back to saved
    m_topViewTransitioning = true;
    m_topViewTransTimer    = 0.f;
    m_tvTransFrom      = cam->GetPosition3f();
    m_tvTransFromYaw   = cam->GetYaw();
    m_tvTransFromPitch = cam->GetPitch();
    m_tvTransTo        = m_tvSavedPos;
    m_tvTransToYaw     = m_tvSavedYaw;
    m_tvTransToPitch   = m_tvSavedPitch;

    m_topViewActive = false;
    m_mapRenderer->m_disableMovementInput = false;

    // Restore display settings
    m_fogPerspective      = m_tvSavedFogPerspective;
    m_showSkillIcons      = m_tvSavedSkillIcons;
    m_showSkillLasers     = m_tvSavedSkillLasers;
    m_uiLayout.lodEnabled = m_tvSavedLodEnabled;
    m_show3DLabels        = m_tvSavedShow3DLabels;
    m_showNameFilterPanel = m_tvSavedNamePanel;

    // Restore follow mode if was active
    if (m_tvSavedCamMode == CameraMode::FollowAgent && m_tvSavedFollowId >= 0)
    {
        EnterFollowMode(m_tvSavedFollowId);
        m_followDist       = m_tvSavedFollowDist;
        m_followDistTarget = m_tvSavedFollowDist;
        m_followYaw        = m_tvSavedFollowYaw;
        m_followPitch      = m_tvSavedFollowPitch;
    }

    // Restore auto camera
    if (m_tvSavedAutoCam)
    {
        m_autoCameraEnabled = true;
        m_autoCamState = AutoCameraState{};
    }
}

void ReplayWindow::UpdateTopViewTransition(float dt)
{
    if (!m_topViewTransitioning) return;

    m_topViewTransTimer += dt;
    float t = std::clamp(m_topViewTransTimer / m_topViewTransDuration, 0.f, 1.f);

    // Ease-in-out cubic
    float ease = t < 0.5f
        ? 4.f * t * t * t
        : 1.f - 0.5f * powf(-2.f * t + 2.f, 3.f);

    Camera* cam = m_mapRenderer->GetCamera();

    // Lerp position
    float lx = m_tvTransFrom.x + (m_tvTransTo.x - m_tvTransFrom.x) * ease;
    float ly = m_tvTransFrom.y + (m_tvTransTo.y - m_tvTransFrom.y) * ease;
    float lz = m_tvTransFrom.z + (m_tvTransTo.z - m_tvTransFrom.z) * ease;
    cam->SetPosition(lx, ly, lz);

    // Lerp orientation (short-path yaw interpolation)
    float dyaw = m_tvTransToYaw - m_tvTransFromYaw;
    while (dyaw >  XM_PI) dyaw -= XM_2PI;
    while (dyaw < -XM_PI) dyaw += XM_2PI;
    float curYaw   = m_tvTransFromYaw + dyaw * ease;
    float curPitch = m_tvTransFromPitch + (m_tvTransToPitch - m_tvTransFromPitch) * ease;
    cam->SetOrientation(curPitch, curYaw);

    if (t >= 1.f)
    {
        m_topViewTransitioning = false;
        // Snap to exact target values
        cam->SetPosition(m_tvTransTo.x, m_tvTransTo.y, m_tvTransTo.z);
        cam->SetOrientation(m_tvTransToPitch, m_tvTransToYaw);
    }
}

void ReplayWindow::UpdateFollowCamera(float dt)
{
    if (m_cameraMode != CameraMode::FollowAgent) return;

    auto it = m_replayCtx.agents.find(m_followedAgentId);
    if (it == m_replayCtx.agents.end()) { ExitFollowMode(); return; }

    const auto& ard = it->second;
    if (ard.snapshots.empty()) { ExitFollowMode(); return; }

    if (ard.isDeadAtTime(m_debugTimeline) &&
        m_debugTimeline > ard.snapshots.back().time)
    {
        ExitFollowMode();
        return;
    }

    // Smooth zoom toward target distance
    float t = 1.0f - expf(-kFollowLerpSpeed * dt);
    m_followDist += (m_followDistTarget - m_followDist) * t;
    m_followDist = std::clamp(m_followDist, kFollowMinDist, kFollowMaxDist);

    // New agent (target) world position
    float sx, sy, sz;
    InterpolateAgentPosition(ard, m_debugTimeline, m_replayCtx.interpSettings, sx, sy, sz);
    XMFLOAT3 newCenter = ApplyMapTransformToPos(sx, sy, sz, m_replayCtx.mapTransform);

    // Orbit center: blend from old agent to new agent during transition
    XMFLOAT3 center = newCenter;

    if (m_followTransActive)
    {
        m_followTransElapsed += dt;
        float u = std::clamp(m_followTransElapsed / kFollowTransDuration, 0.f, 1.f);

        // Smooth-step (cubic Hermite) for a gentle, broadcast-camera pan
        float ease = u * u * (3.f - 2.f * u);

        if (u >= 1.f)
        {
            m_followTransActive = false;
        }
        else
        {
            auto itOld = m_replayCtx.agents.find(m_followTransFromAgentId);
            if (itOld != m_replayCtx.agents.end() && !itOld->second.snapshots.empty())
            {
                float ox, oy, oz;
                InterpolateAgentPosition(itOld->second, m_debugTimeline,
                    m_replayCtx.interpSettings, ox, oy, oz);
                XMFLOAT3 oldCenter = ApplyMapTransformToPos(ox, oy, oz, m_replayCtx.mapTransform);

                center.x = oldCenter.x + (newCenter.x - oldCenter.x) * ease;
                center.y = oldCenter.y + (newCenter.y - oldCenter.y) * ease;
                center.z = oldCenter.z + (newCenter.z - oldCenter.z) * ease;
            }
        }
    }

    // Spherical offset from orbit center
    float cosP = cosf(m_followPitch);
    float offX = m_followDist * sinf(m_followYaw) * cosP;
    float offY = m_followDist * sinf(m_followPitch);
    float offZ = m_followDist * cosf(m_followYaw) * cosP;

    Camera* cam = m_mapRenderer->GetCamera();
    cam->SetPosition(center.x + offX, center.y + offY, center.z + offZ);
    cam->SetOrientation(-m_followPitch, m_followYaw + XM_PI);
}

// ---------------------------------------------------------------------------
// Auto Camera system
// ---------------------------------------------------------------------------

static const int kRezSkillIds[] = { 2, 305, 306, 314, 315, 791, 1263, 1481, 1778 };

// Returns projected HP as fraction 0.0–1.0, and optionally the damage rate
float ReplayWindow::EstimateProjectedHp(const AgentReplayData& ard, float time, float lookahead) const
{
    return EstimateProjectedHpEx(ard, time, lookahead, nullptr);
}

float ReplayWindow::EstimateProjectedHpEx(const AgentReplayData& ard, float time, float lookahead, float* outDmgRate) const
{
    const auto& combatEvents = m_replayCtx.stocData.combat;
    float totalDmgFrac = 0.f;
    const float window = 3.f;
    for (const auto& ce : combatEvents)
    {
        if (ce.target_id != ard.agent_id) continue;
        if (ce.type != "DAMAGE") continue;
        if (ce.time > time || ce.time < time - window) continue;
        if (ce.value < 0.f)
            totalDmgFrac += -ce.value;
    }
    float dmgRate = totalDmgFrac / window;
    if (outDmgRate) *outDmgRate = dmgRate;

    const AgentSnapshot* snap = FindSnapshotAtTime(ard, time);
    if (!snap) return 1.f;

    float projected = snap->health_pct - dmgRate * lookahead;
    return std::clamp(projected, 0.f, 1.f);
}

bool ReplayWindow::WillAgentDie(const AgentReplayData& ard, float time, float lookahead) const
{
    const auto& snaps = ard.snapshots;
    if (snaps.empty()) return false;

    // Binary search to find the first snapshot at or after 'time'
    auto it = std::lower_bound(snaps.begin(), snaps.end(), time,
        [](const AgentSnapshot& s, float t) { return s.time < t; });

    float deadline = time + lookahead;
    for (; it != snaps.end() && it->time <= deadline; ++it)
    {
        if (it->is_dead) return true;
    }
    return false;
}


bool ReplayWindow::IsAgentTakingDamage(int agentId, float time, float window) const
{
    for (const auto& ce : m_replayCtx.stocData.combat)
    {
        if (ce.target_id != agentId) continue;
        if (ce.type != "DAMAGE") continue;
        if (ce.time <= time && ce.time >= time - window)
            return true;
    }
    return false;
}

bool ReplayWindow::IsAgentIsolated(const AgentReplayData& ard, float time, float radius) const
{
    const AgentSnapshot* snap = FindSnapshotAtTime(ard, time);
    if (!snap) return false;

    float ax = snap->x, ay = snap->y;
    float radiusSq = radius * radius;
    const auto& teammates = (ard.teamId == 1) ? m_team1PlayerIds : m_team2PlayerIds;

    int nearbyCount = 0;
    for (int pid : teammates)
    {
        if (pid == ard.agent_id) continue;
        auto it = m_replayCtx.agents.find(pid);
        if (it == m_replayCtx.agents.end()) continue;
        const AgentSnapshot* ps = FindSnapshotAtTime(it->second, time);
        if (!ps || ps->is_dead) continue;
        float dx = ps->x - ax, dy = ps->y - ay;
        if (dx * dx + dy * dy < radiusSq) nearbyCount++;
    }
    return nearbyCount == 0;
}

bool ReplayWindow::IsAgentCastingRez(const AgentReplayData& ard, float time) const
{
    for (const auto& su : ard.skillUseHistory)
    {
        if (su.wasCancelled) continue;
        if (time < su.startTime || time > su.endTime) continue;
        for (int rid : kRezSkillIds)
        {
            if (su.skillId == rid) return true;
        }
    }
    return false;
}

void ReplayWindow::UpdateAutoCamera(float dt)
{
    if (!m_autoCameraEnabled) return;
    if (!m_agentsClassified) return;

    auto& st = m_autoCamState;
    auto& cfg = m_autoCamCfg;

    // Only advance timers while the replay is playing
    if (m_replayCtx.isPlaying)
    {
        st.dwellTimer += dt;
        st.switchCooldown = std::max(0.f, st.switchCooldown - dt);
    }

    float now = m_debugTimeline;

    m_autoCamDebug.clear();

    int bestAgent = -1;
    int bestScore = 0;
    std::string bestReason;

    // Re-score the current target so hysteresis uses live score, not stale priority
    int currentTargetLiveScore = 0;

    auto scoreAgent = [&](int pid, const AgentReplayData& ard) {
        const AgentSnapshot* snap = FindSnapshotAtTime(ard, now);

        AutoCamDebugEntry dbg;
        dbg.agentId = pid;
        dbg.name = ard.partyBarLabel.empty() ? std::to_string(pid) : ard.partyBarLabel;

        if (!snap) {
            dbg.disqualified = true;
            dbg.disqualReason = "No snapshot";
            m_autoCamDebug.push_back(std::move(dbg));
            return;
        }
        if (snap->is_dead) {
            dbg.hpPct = 0.f;
            dbg.disqualified = true;
            dbg.disqualReason = "Dead";
            m_autoCamDebug.push_back(std::move(dbg));
            return;
        }

        dbg.hpPct = snap->health_pct;

        int score = 0;
        std::string reason;

        // Use actual future snapshot for projected HP
        const AgentSnapshot* futureSnap = FindSnapshotAtTime(ard, now + cfg.lookaheadSec);
        float futureHp = futureSnap ? futureSnap->health_pct : snap->health_pct;
        dbg.projectedHp = futureHp;
        dbg.dmgRate = (futureSnap && futureSnap->time > snap->time)
            ? std::max(0.f, snap->health_pct - futureHp) / (futureSnap->time - snap->time)
            : 0.f;

        // Death imminent: check actual future snapshots for a real death
        if (cfg.focusDeath && WillAgentDie(ard, now, cfg.lookaheadSec))
        {
            score = std::max(score, 1000);
            reason = std::format("Death imminent (HP {:.0f}%)", snap->health_pct * 100.f);
        }

        // Low HP: use actual future HP from replay data
        if (cfg.focusLowHp && futureHp < cfg.hpThreshold &&
            futureHp < snap->health_pct)
        {
            score = std::max(score, 700);
            if (reason.empty()) reason = std::format("Low HP ({:.0f}% -> {:.0f}%)", snap->health_pct * 100.f, futureHp * 100.f);
        }

        if (cfg.focusRez && IsAgentCastingRez(ard, now))
        {
            score = std::max(score, 500);
            if (reason.empty()) reason = "Casting resurrection";
        }

        if (cfg.focusIsolated && IsAgentIsolated(ard, now) && IsAgentTakingDamage(pid, now))
        {
            score = std::max(score, 400);
            if (reason.empty()) reason = "Isolated + taking damage";
        }

        if (cfg.focusFlagCarry && snap->weapon_type == 0)
        {
            BundleType bt = GetPlayerBundleType(pid, now);
            if (bt == BundleType::Flag || bt == BundleType::Unknown)
            {
                score = std::max(score, 200);
                if (reason.empty()) reason = "Carrying flag";
            }
        }

        dbg.score = score;
        dbg.reason = reason;
        m_autoCamDebug.push_back(std::move(dbg));

        if (pid == st.currentTarget)
            currentTargetLiveScore = score;

        if (score > bestScore)
        {
            bestScore = score;
            bestAgent = pid;
            bestReason = reason;
        }
    };

    for (int pid : m_team1PlayerIds)
    {
        auto it = m_replayCtx.agents.find(pid);
        if (it != m_replayCtx.agents.end())
            scoreAgent(pid, it->second);
    }
    for (int pid : m_team2PlayerIds)
    {
        auto it = m_replayCtx.agents.find(pid);
        if (it != m_replayCtx.agents.end())
            scoreAgent(pid, it->second);
    }

    // Score guild lords
    if (cfg.focusLord)
    {
        for (int nid : m_npcIds)
        {
            auto it = m_replayCtx.agents.find(nid);
            if (it == m_replayCtx.agents.end()) continue;
            if (it->second.categoryName != "Guild Lord") continue;
            const AgentSnapshot* snap = FindSnapshotAtTime(it->second, now);
            if (!snap || snap->is_dead) continue;
            if (IsAgentTakingDamage(nid, now))
            {
                int lordScore = 700;
                AutoCamDebugEntry dbg;
                dbg.agentId = nid;
                dbg.name = "Guild Lord";
                dbg.hpPct = snap->health_pct;
                dbg.score = lordScore;
                dbg.reason = "Guild Lord under attack";
                m_autoCamDebug.push_back(std::move(dbg));

                if (nid == st.currentTarget)
                    currentTargetLiveScore = lordScore;

                if (lordScore > bestScore)
                {
                    bestScore = lordScore;
                    bestAgent = nid;
                    bestReason = "Guild Lord under attack";
                }
            }
        }
    }

    // Score flag pickup
    if (cfg.focusFlag && m_flagTimelineBuilt && m_flagTimeline.valid)
    {
        for (int ti = 0; ti < 2; ++ti)
        {
            for (const auto& fe : m_flagTimeline.teams[ti].events)
            {
                if (fe.newLocation == FlagLocation::Carried &&
                    fe.carrierAgentId >= 0 &&
                    std::abs(fe.time - now) < 2.f)
                {
                    if (500 > bestScore)
                    {
                        bestScore = 500;
                        bestAgent = fe.carrierAgentId;
                        bestReason = "Flag pickup";
                    }
                }
            }
        }
    }

    if (bestAgent < 0) return;

    // Switch decision — use live score for current target (not stale priority)
    bool shouldSwitch = false;
    if (st.currentTarget < 0)
    {
        shouldSwitch = true;
    }
    else if (bestScore >= 900 && bestAgent != st.currentTarget)
    {
        // Priority 1 events bypass both dwell and hysteresis
        shouldSwitch = true;
    }
    else if (st.dwellTimer < cfg.minDwellTime)
    {
        // Still dwelling, no switch for non-P1
    }
    else if (st.switchCooldown <= 0.f && bestAgent != st.currentTarget)
    {
        float refScore = static_cast<float>(std::max(currentTargetLiveScore, 1));
        if (static_cast<float>(bestScore) > refScore * 1.10f)
            shouldSwitch = true;
    }

    if (shouldSwitch && bestAgent != st.currentTarget)
    {
        Camera* cam = m_mapRenderer->GetCamera();
        st.lerpFrom = cam->GetPosition3f();
        st.lerpActive = true;
        st.lerpElapsed = 0.f;
        st.lerpDuration = (bestScore >= 900) ? 1.2f : 2.5f;

        st.currentTarget = bestAgent;
        st.currentPriority = bestScore;
        st.currentReason = bestReason;
        st.dwellTimer = 0.f;
        st.switchCooldown = 1.f;

        if (m_cameraMode != CameraMode::FollowAgent || m_followedAgentId != bestAgent)
        {
            EnterFollowMode(bestAgent);
        }
    }

    // Smooth camera lerp transition
    if (st.lerpActive && m_cameraMode == CameraMode::FollowAgent)
    {
        if (m_replayCtx.isPlaying)
            st.lerpElapsed += dt;
        float t = std::clamp(st.lerpElapsed / st.lerpDuration, 0.f, 1.f);
        // Ease-in-out quintic for a smoother, more cinematic camera glide
        float ease = t < 0.5f
            ? 16.f * t * t * t * t * t
            : 1.f - 0.5f * powf(-2.f * t + 2.f, 5.f);

        if (t >= 1.f)
        {
            st.lerpActive = false;
        }
        else
        {
            auto it = m_replayCtx.agents.find(m_followedAgentId);
            if (it != m_replayCtx.agents.end())
            {
                float sx, sy, sz;
                InterpolateAgentPosition(it->second, m_debugTimeline,
                    m_replayCtx.interpSettings, sx, sy, sz);
                XMFLOAT3 agentWorld = ApplyMapTransformToPos(sx, sy, sz, m_replayCtx.mapTransform);

                float cosP = cosf(m_followPitch);
                float offX = m_followDist * sinf(m_followYaw) * cosP;
                float offY = m_followDist * sinf(m_followPitch);
                float offZ = m_followDist * cosf(m_followYaw) * cosP;

                XMFLOAT3 targetPos(agentWorld.x + offX, agentWorld.y + offY, agentWorld.z + offZ);

                float lx = st.lerpFrom.x + (targetPos.x - st.lerpFrom.x) * ease;
                float ly = st.lerpFrom.y + (targetPos.y - st.lerpFrom.y) * ease;
                float lz = st.lerpFrom.z + (targetPos.z - st.lerpFrom.z) * ease;

                Camera* cam = m_mapRenderer->GetCamera();
                cam->SetPosition(lx, ly, lz);
            }
        }
    }
}

void ReplayWindow::LoadAutoCamSettings()
{
    auto& cfg = m_autoCamCfg;
    cfg.lookaheadSec = GuiGlobalConstants::autocam_lookahead;
    cfg.hpThreshold  = GuiGlobalConstants::autocam_hp_thresh / 100.f;
    cfg.minDwellTime = GuiGlobalConstants::autocam_dwell;
    cfg.focusDeath     = GuiGlobalConstants::autocam_death;
    cfg.focusLowHp     = GuiGlobalConstants::autocam_low_hp;
    cfg.focusLord      = GuiGlobalConstants::autocam_lord;
    cfg.focusFlag      = GuiGlobalConstants::autocam_flag;
    cfg.focusRez       = GuiGlobalConstants::autocam_rez;
    cfg.focusIsolated  = GuiGlobalConstants::autocam_isolated;
    cfg.focusFlagCarry = GuiGlobalConstants::autocam_flag_carry;
}

void ReplayWindow::SaveAutoCamSettings()
{
    auto& cfg = m_autoCamCfg;
    GuiGlobalConstants::autocam_lookahead  = cfg.lookaheadSec;
    GuiGlobalConstants::autocam_hp_thresh  = static_cast<int>(cfg.hpThreshold * 100.f);
    GuiGlobalConstants::autocam_dwell      = cfg.minDwellTime;
    GuiGlobalConstants::autocam_death      = cfg.focusDeath;
    GuiGlobalConstants::autocam_low_hp     = cfg.focusLowHp;
    GuiGlobalConstants::autocam_lord       = cfg.focusLord;
    GuiGlobalConstants::autocam_flag       = cfg.focusFlag;
    GuiGlobalConstants::autocam_rez        = cfg.focusRez;
    GuiGlobalConstants::autocam_isolated   = cfg.focusIsolated;
    GuiGlobalConstants::autocam_flag_carry = cfg.focusFlagCarry;
    GuiGlobalConstants::SaveSettings();
}

void ReplayWindow::DrawAutoCameraPanel()
{
    if (!m_showAutoCameraPanel) return;

    auto& cfg = m_autoCamCfg;
    auto& st  = m_autoCamState;

    ImGui::PushStyleColor(ImGuiCol_WindowBg,       ImVec4(0.055f, 0.063f, 0.078f, 0.94f));
    ImGui::PushStyleColor(ImGuiCol_TitleBg,        ImVec4(0.07f, 0.08f, 0.10f, 1.f));
    ImGui::PushStyleColor(ImGuiCol_TitleBgActive,  ImVec4(0.10f, 0.09f, 0.06f, 1.f));
    ImGui::PushStyleColor(ImGuiCol_Border,         ImVec4(0.16f, 0.12f, 0.06f, 0.85f));
    ImGui::PushStyleColor(ImGuiCol_Separator,      ImVec4(0.40f, 0.33f, 0.15f, 0.40f));
    ImGui::PushStyleColor(ImGuiCol_FrameBg,        ImVec4(0.10f, 0.10f, 0.12f, 1.f));
    ImGui::PushStyleColor(ImGuiCol_FrameBgHovered, ImVec4(0.15f, 0.14f, 0.12f, 1.f));
    ImGui::PushStyleColor(ImGuiCol_SliderGrab,     ImVec4(0.78f, 0.65f, 0.29f, 0.85f));
    ImGui::PushStyleColor(ImGuiCol_CheckMark,      ImVec4(1.f, 0.84f, 0.39f, 1.f));
    ImGui::PushStyleColor(ImGuiCol_Header,         ImVec4(0.18f, 0.14f, 0.05f, 1.f));
    ImGui::PushStyleColor(ImGuiCol_HeaderHovered,  ImVec4(0.23f, 0.19f, 0.08f, 1.f));
    ImGui::PushStyleVar(ImGuiStyleVar_WindowRounding, 6.f);
    ImGui::PushStyleVar(ImGuiStyleVar_WindowBorderSize, 1.f);
    ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(10, 8));
    ImGui::PushStyleVar(ImGuiStyleVar_FrameRounding, 4.f);

    auto* vp = ImGui::GetMainViewport();
    ImGui::SetNextWindowSizeConstraints(ImVec2(300.f, 0.f), ImVec2(vp->Size.x, vp->Size.y));
    ImGui::SetNextWindowSize(ImVec2(0, 0), ImGuiCond_Always);
    m_panelLayout.ApplyPosition("auto_camera");

    if (!ImGui::Begin("Auto Camera", &m_showAutoCameraPanel,
        ImGuiWindowFlags_AlwaysAutoResize))
    {
        m_panelLayout.TrackWindow("auto_camera");
        ImGui::End();
        ImGui::PopStyleVar(4);
        ImGui::PopStyleColor(11);
        return;
    }

    m_panelLayout.TrackWindow("auto_camera");

    {
        ImVec2 pos = ImGui::GetWindowPos();
        ImVec2 sz  = ImGui::GetWindowSize();
        float cx = std::clamp(pos.x, vp->Pos.x, vp->Pos.x + vp->Size.x - sz.x);
        float cy = std::clamp(pos.y, vp->Pos.y, vp->Pos.y + vp->Size.y - sz.y);
        if (cx != pos.x || cy != pos.y)
            ImGui::SetWindowPos(ImVec2(cx, cy));
    }

    const ImVec4 goldText(0.78f, 0.72f, 0.55f, 1.f);
    const ImVec4 accentText(1.f, 0.91f, 0.69f, 1.f);
    const ImVec4 dimText(0.60f, 0.64f, 0.69f, 1.f);

    bool wasEnabled = m_autoCameraEnabled;
    ImGui::Checkbox("Enable Auto Camera (A)", &m_autoCameraEnabled);
    if (m_autoCameraEnabled && !wasEnabled)
        st = AutoCameraState{};
    if (!m_autoCameraEnabled && wasEnabled)
        ExitFollowMode();

    if (m_topViewActive && m_tvSavedAutoCam)
        ImGui::TextColored(ImVec4(1.f, 0.7f, 0.3f, 1.f), "Paused (Top View active)");

    // ── Focus pills ──────────────────────────────────────────────────────
    ImGui::Separator();
    ImGui::TextColored(goldText, "Focus");

    auto FocusPill = [&](const char* label, bool& active) {
        ImVec4 bg, tx, hov, bdr;
        if (active) {
            bg  = ImVec4(0.18f, 0.14f, 0.05f, 1.f);
            tx  = ImVec4(1.f, 0.91f, 0.69f, 1.f);
            hov = ImVec4(0.23f, 0.19f, 0.08f, 1.f);
            bdr = ImVec4(1.f, 0.84f, 0.39f, 0.85f);
        } else {
            bg  = ImVec4(1.f, 1.f, 1.f, 0.05f);
            tx  = ImVec4(0.60f, 0.64f, 0.69f, 1.f);
            hov = ImVec4(1.f, 1.f, 1.f, 0.12f);
            bdr = ImVec4(1.f, 1.f, 1.f, 0.08f);
        }
        ImGui::PushStyleColor(ImGuiCol_Button, bg);
        ImGui::PushStyleColor(ImGuiCol_Text, tx);
        ImGui::PushStyleColor(ImGuiCol_ButtonHovered, hov);
        ImGui::PushStyleColor(ImGuiCol_ButtonActive,
            ImVec4(bg.x * 0.85f, bg.y * 0.85f, bg.z * 0.85f, 1.f));
        ImGui::PushStyleColor(ImGuiCol_Border, bdr);
        ImGui::PushStyleVar(ImGuiStyleVar_FrameRounding, 10.f);
        ImGui::PushStyleVar(ImGuiStyleVar_FramePadding, ImVec2(6, 3));
        ImGui::PushStyleVar(ImGuiStyleVar_FrameBorderSize, 1.f);
        if (ImGui::Button(label))
            active = !active;
        ImGui::PopStyleVar(3);
        ImGui::PopStyleColor(5);
    };

    FocusPill("Death", cfg.focusDeath);
    ImGui::SameLine();
    FocusPill("Low HP", cfg.focusLowHp);
    ImGui::SameLine();
    FocusPill("Guild Lord", cfg.focusLord);
    ImGui::SameLine();
    FocusPill("Flag", cfg.focusFlag);

    FocusPill("Resurrection", cfg.focusRez);
    ImGui::SameLine();
    FocusPill("Isolated", cfg.focusIsolated);
    ImGui::SameLine();
    FocusPill("Flag Carrier", cfg.focusFlagCarry);

    // ── Settings (collapsible) ───────────────────────────────────────────
    ImGui::Separator();
    if (ImGui::CollapsingHeader("Settings"))
    {
        const char* lookaheadLabels[] = { "2s", "3s", "5s", "10s" };
        const float lookaheadValues[] = { 2.f, 3.f, 5.f, 10.f };
        int lookaheadIdx = 1;
        for (int i = 0; i < 4; ++i) if (cfg.lookaheadSec == lookaheadValues[i]) lookaheadIdx = i;
        if (ImGui::Combo("Lookahead", &lookaheadIdx, lookaheadLabels, 4))
            cfg.lookaheadSec = lookaheadValues[lookaheadIdx];

        float hpPct = cfg.hpThreshold * 100.f;
        if (ImGui::SliderFloat("HP Threshold", &hpPct, 10.f, 80.f, "%.0f%%"))
            cfg.hpThreshold = hpPct / 100.f;

        ImGui::SliderFloat("Min Dwell", &cfg.minDwellTime, 1.f, 8.f, "%.1fs");
    }

    (void)accentText;
    (void)dimText;

    ImGui::End();
    ImGui::PopStyleVar(4);
    ImGui::PopStyleColor(11);
}

void ReplayWindow::DrawAutoCameraDebugPanel()
{
    if (!m_autoCamShowDebug) return;

    auto& st = m_autoCamState;

    ImGui::PushStyleColor(ImGuiCol_WindowBg, ImVec4(0.055f, 0.063f, 0.078f, 0.94f));
    ImGui::PushStyleColor(ImGuiCol_TitleBg,        ImVec4(0.07f, 0.08f, 0.10f, 1.f));
    ImGui::PushStyleColor(ImGuiCol_TitleBgActive,  ImVec4(0.10f, 0.09f, 0.06f, 1.f));
    ImGui::PushStyleColor(ImGuiCol_Border,         ImVec4(0.16f, 0.12f, 0.06f, 0.85f));
    ImGui::PushStyleVar(ImGuiStyleVar_WindowRounding, 6.f);
    ImGui::PushStyleVar(ImGuiStyleVar_WindowBorderSize, 1.f);
    ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(10, 8));

    ImGui::SetNextWindowSize(ImVec2(520, 340), ImGuiCond_FirstUseEver);
    if (!ImGui::Begin("Auto Camera Debug", &m_autoCamShowDebug))
    {
        ImGui::End();
        ImGui::PopStyleVar(3);
        ImGui::PopStyleColor(4);
        return;
    }

    auto& cfg = m_autoCamCfg;
    const ImVec4 accentText(1.f, 0.91f, 0.69f, 1.f);
    const ImVec4 dimText(0.60f, 0.64f, 0.69f, 1.f);
    const ImVec4 goldText(0.78f, 0.72f, 0.55f, 1.f);

    // ── Status ──────────────────────────────────────────────────────────
    ImGui::TextColored(goldText, "Status");
    if (m_autoCameraEnabled && st.currentTarget >= 0)
    {
        auto it = m_replayCtx.agents.find(st.currentTarget);
        if (it != m_replayCtx.agents.end())
        {
            const auto& ard = it->second;
            const AgentSnapshot* snap = FindSnapshotAtTime(ard, m_debugTimeline);
            std::string name = ard.partyBarLabel.empty() ? ard.playerName : ard.partyBarLabel;
            ImGui::TextColored(accentText, "Watching: %s", name.c_str());
            if (snap)
            {
                float pct = snap->health_pct;
                ImGui::ProgressBar(pct, ImVec2(-1, 14),
                    std::format("{:.0f}%", pct * 100.f).c_str());
            }
            ImGui::TextColored(ImVec4(0.8f, 0.7f, 0.3f, 1.f), "Reason: %s", st.currentReason.c_str());
            float remaining = std::max(0.f, cfg.minDwellTime - st.dwellTimer);
            ImGui::TextColored(dimText, "Next switch: in %.1fs", remaining);
        }
    }
    else if (m_autoCameraEnabled)
        ImGui::TextDisabled("No target selected");
    else
        ImGui::TextDisabled("Auto camera OFF");

    ImGui::Separator();
    ImGui::TextColored(accentText, "Agent Scores (%d agents)", (int)m_autoCamDebug.size());

    if (ImGui::BeginTable("##acdbg", 6,
        ImGuiTableFlags_Borders | ImGuiTableFlags_RowBg | ImGuiTableFlags_SizingFixedFit | ImGuiTableFlags_ScrollY,
        ImVec2(0, -ImGui::GetFrameHeightWithSpacing() * 2.f)))
    {
        ImGui::TableSetupColumn("Agent", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("HP%",   ImGuiTableColumnFlags_WidthFixed, 44.f);
        ImGui::TableSetupColumn("Dmg/s", ImGuiTableColumnFlags_WidthFixed, 50.f);
        ImGui::TableSetupColumn("Proj",  ImGuiTableColumnFlags_WidthFixed, 44.f);
        ImGui::TableSetupColumn("Score", ImGuiTableColumnFlags_WidthFixed, 44.f);
        ImGui::TableSetupColumn("Info",  ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableHeadersRow();

        auto sorted = m_autoCamDebug;
        std::sort(sorted.begin(), sorted.end(),
            [](const AutoCamDebugEntry& a, const AutoCamDebugEntry& b) { return a.score > b.score; });

        for (const auto& e : sorted)
        {
            ImGui::TableNextRow();

            bool isCurrent = (e.agentId == st.currentTarget);
            if (isCurrent)
                ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.3f, 1.f, 0.3f, 1.f));

            ImGui::TableSetColumnIndex(0);
            ImGui::TextUnformatted(e.name.c_str());

            ImGui::TableSetColumnIndex(1);
            if (e.disqualified)
                ImGui::TextDisabled("--");
            else
                ImGui::Text("%.0f", e.hpPct * 100.f);

            ImGui::TableSetColumnIndex(2);
            if (e.disqualified)
                ImGui::TextDisabled("--");
            else
                ImGui::Text("%.1f%%", e.dmgRate * 100.f);

            ImGui::TableSetColumnIndex(3);
            if (e.disqualified)
                ImGui::TextDisabled("--");
            else
            {
                if (e.score >= 1000)
                    ImGui::TextColored(ImVec4(1.f, 0.2f, 0.2f, 1.f), "DIES");
                else
                    ImGui::Text("%.0f%%", e.projectedHp * 100.f);
            }

            ImGui::TableSetColumnIndex(4);
            if (e.score >= 900)
                ImGui::TextColored(ImVec4(1.f, 0.3f, 0.3f, 1.f), "%d", e.score);
            else if (e.score > 0)
                ImGui::TextColored(ImVec4(1.f, 0.8f, 0.2f, 1.f), "%d", e.score);
            else
                ImGui::TextDisabled("0");

            ImGui::TableSetColumnIndex(5);
            if (e.disqualified)
                ImGui::TextDisabled("%s", e.disqualReason.c_str());
            else if (!e.reason.empty())
                ImGui::TextUnformatted(e.reason.c_str());

            if (isCurrent)
                ImGui::PopStyleColor();
        }
        ImGui::EndTable();
    }

    ImGui::TextColored(dimText,
        "Dwell: %.2f  Cooldown: %.2f  Hysteresis: 1.10x",
        st.dwellTimer, st.switchCooldown);

    ImGui::End();
    ImGui::PopStyleVar(3);
    ImGui::PopStyleColor(4);
}

